def multisets(m, n, start=0):
    if n == 0:
        yield ()
        return
    for i in range(start, m):
        for rest in multisets(m, n - 1, i):
            yield (i,) + rest


RMAT = [[1, 0, 2, -1, 0, 1], [0, 3, -1, 0, 1, 0], [2, 1, 0, 1, -2, 1], [0, -1, 1, 2, 0, 3], [1, 0, 0, -1, 2, 1], [-1, 2, 1, 0, 1, 1]]


