                          S = -(m'/r^2) w^2 and c = L/6 - e2/(2 r^4); P(k, e_x) = P(k, e_y) = 0.
  check_inner_horizon:    RN (m = 5/4, e2 = 1: r_- = 1/2, r_+ = 2) and RNdS (L = 3/25, m = 6/5, e2 = 36/25, kappa_- = 7/25:
                          roots 1, 2, 3, -6): f(r_-) = 0, kappa_- := -f_r(r_-)/2 > 0 equals (r_+ - r_-)/(2 r_-^2)
                          for RN; the outgoing-ray flow r' = f/2 has derivative -kappa_- at r_- (attracting).
  check_threshold_bookkeeping: in units with kappa_- = kappa and the model w = exp(kappa v):
                          for m' = exp(-2 alpha v) the L^1 integrand m' w is exp((kappa - 2 alpha) v) and the
                          Tipler integrand (lambda_c - lambda) w m' equals m'/kappa exactly; in affine distance
                          t = exp(-kappa v)/kappa, |S| = m' w^2 r^-2 is a constant times t^(2 beta - 2) with
                          beta = alpha/kappa; tail integrals int_V^oo are finite exactly when 2 alpha > kappa.
"""
from fractions import Fraction as F
import itertools
import GA
from tp_premise import premise

NV = 4
ORDER = 2
ZERO_E = (0,) * NV


class J(object):
    """Taylor jet of total order <= 2 in four variables, exact coefficients."""
    __slots__ = ("c",)

    def __init__(self, c=None):
        self.c = {k: v for k, v in (c or {}).items() if v != 0}

    @staticmethod
    def const(a):
        return J({ZERO_E: F(a)})

    @staticmethod
    def coord(i, base):
        e = [0] * NV
        e[i] = 1
        return J({ZERO_E: F(base), tuple(e): F(1)})

    def _lift(self, o):
        return o if isinstance(o, J) else J.const(o)

    def __add__(self, o):
        o = self._lift(o)
        d = dict(self.c)
        for k, v in o.c.items():
            d[k] = d.get(k, F(0)) + v
        return J(d)

    __radd__ = __add__

    def __neg__(self):
        return J({k: -v for k, v in self.c.items()})

    def __sub__(self, o):
        return self + (-self._lift(o))

    def __rsub__(self, o):
        return self._lift(o) - self

    def __mul__(self, o):
        o = self._lift(o)
        d = {}
        for k1, v1 in self.c.items():
            for k2, v2 in o.c.items():
                k = tuple(a + b for a, b in zip(k1, k2))
                if sum(k) <= ORDER:
                    d[k] = d.get(k, F(0)) + v1 * v2
        return J(d)

    __rmul__ = __mul__

    def c0(self):
        return self.c.get(ZERO_E, F(0))

    def inv(self):
        a0 = self.c0()
        assert a0 != 0
        h = (self - a0) * (F(1) / a0)
        out = J.const(1)
        p = J.const(1)
        for _ in range(ORDER):
            p = p * (-h)
            out = out + p
        return out * (F(1) / a0)

    def over(self, o):
        return self * self._lift(o).inv()

    def d(self, i):
        d = {}
        for k, v in self.c.items():
            if k[i] > 0:
                kk = list(k)
                kk[i] -= 1
                d[tuple(kk)] = d.get(tuple(kk), F(0)) + v * k[i]
        return J(d)

    def lower(self):
        return J({k: v for k, v in self.c.items() if sum(k) < ORDER})


def mat_inv(M):
    n = len(M)
    A = [[M[i][j] for j in range(n)] + [J.const(int(i == j)) for j in range(n)] for i in range(n)]
    for c in range(n):
        p = next(i for i in range(c, n) if A[i][c].c0() != 0)
        A[c], A[p] = A[p], A[c]
        piv = A[c][c].inv()
        A[c] = [x * piv for x in A[c]]
        for i in range(n):
            if i != c and A[i][c].c:
                fct = A[i][c]
                A[i] = [x - fct * y for x, y in zip(A[i], A[c])]
    return [row[n:] for row in A]


def curvature(g):
    n = NV
    ginv = mat_inv(g)
    dg = [[[g[i][j].d(k) for k in range(n)] for j in range(n)] for i in range(n)]
    Gam = [[[None] * n for _ in range(n)] for _ in range(n)]
    for a in range(n):
        for b in range(n):
            for c in range(n):
                s = J()
                for d in range(n):
                    s = s + ginv[a][d] * (dg[d][c][b] + dg[d][b][c] - dg[b][c][d])
                Gam[a][b][c] = (s * F(1, 2)).lower()
    Riem = {}
    for a, b, c, d in itertools.product(range(n), repeat=4):
        s = Gam[a][d][b].d(c).c0() - Gam[a][c][b].d(d).c0()
        for e in range(n):
            s += Gam[a][c][e].c0() * Gam[e][d][b].c0() - Gam[a][d][e].c0() * Gam[e][c][b].c0()
        Riem[(a, b, c, d)] = s
    Ric = [[sum(Riem[(a, b, a, d)] for a in range(n)) for d in range(n)] for b in range(n)]
    g0inv = [[ginv[i][j].c0() for j in range(n)] for i in range(n)]
    G0 = [[[Gam[a][b][c].c0() for c in range(n)] for b in range(n)] for a in range(n)]
    return g0inv, G0, Ric


def vaidya(pt, mj, e2, L):
    v0, r0, x0, y0 = pt
    v = J.coord(0, v0)
    r = J.coord(1, r0)
    x = J.coord(2, x0)
    y = J.coord(3, y0)
    dv = v - v0
    m = J.const(mj[0]) + dv * mj[1] + dv * dv * (F(mj[2]) * F(1, 2))
    f = 1 - (2 * m).over(r) + J.const(e2).over(r * r) - r * r * (F(L) * F(1, 3))
    s = 1 + x * x + y * y
    q = J.const(4).over(s * s)
    z = J()
    g = [[f, J.const(-1), z, z], [J.const(-1), z, z, z], [z, z, -(r * r * q), z], [z, z, z, -(r * r * q)]]
    return g, f


def store_schouten(g):
    g0inv, G0, Ric = curvature(g)
    Rs = [[-Ric[i][j] for j in range(NV)] for i in range(NV)]
    g0 = [[g[i][j].c0() for j in range(NV)] for i in range(NV)]
    R = sum(g0inv[i][j] * Rs[i][j] for i in range(NV) for j in range(NV))
    P = [[(Rs[i][j] - R * g0[i][j] * F(1, 6)) * F(1, 2) for j in range(NV)] for i in range(NV)]
    return P, R, Rs, g0, G0


POINTS = [((F(1, 3), F(3, 2), F(1, 5), F(-2, 7)), (F(5, 4), F(2, 9), F(-1, 3)), F(1), F(3, 25)),
          ((F(2), F(3, 4), F(0), F(1, 2)), (F(6, 5), F(1, 7), F(4)), F(36, 25), F(3, 25)),
          ((F(-1, 2), F(5, 7), F(3, 4), F(1, 3)), (F(5, 4), F(3), F(-2)), F(1), F(0)),
          ((F(7), F(2, 5), F(-1), F(-1)), (F(1), F(1, 11), F(1, 2)), F(1, 4), F(-1, 3))]


def check_store_sign():
    premise("interior.imported-tractor-connection")
    # tabulated store-sign values Ric_vv = L f = L (1 - L r^2/3) and Ric_xx = -L r^2 q at the sample points
    table = {(F(3), F(1, 2)): (F(9, 4), F(-3)), (F(3), F(1, 4)): (F(45, 16), F(-1500625, 2517168)),
             (F(3), F(1, 7)): (F(144, 49), F(-1, 147)), (F(3, 25), F(1, 2)): (F(297, 2500), F(-3, 25)),
             (F(3, 25), F(1, 4)): (F(1197, 10000), F(-60025, 2517168)),
             (F(3, 25), F(1, 7)): (F(3672, 30625), F(-1, 3675))}
    for L in (F(3), F(3, 25)):
        for pt in ((F(0), F(1, 2), F(0), F(0)), (F(1, 3), F(1, 4), F(1, 5), F(-2, 7)), (F(2), F(1, 7), F(1), F(2))):
            g, _ = vaidya(pt, (F(0), F(0), F(0)), F(0), L)
            P, R, Rs, g0, _ = store_schouten(g)
            for i in range(NV):
                for j in range(NV):
                    assert Rs[i][j] == L * g0[i][j]
            assert R == 4 * L
            assert (Rs[0][0], Rs[2][2]) == table[(L, pt[1])]
            # the formula convention itself gives the opposite sign (Ric_formula = -L g)
            assert -Rs[0][0] == -L * g0[0][0]
    # control: a nonzero m' breaks Ric = L g
    g, _ = vaidya((F(0), F(1, 2), F(0), F(0)), (F(0), F(1), F(0)), F(0), F(3))
    P, R, Rs, g0, _ = store_schouten(g)
    assert Rs[0][0] != F(3) * g0[0][0]
    return True


def check_vaidya_schouten():
    premise("interior.imported-tractor-connection")
    premise("synthesis.tractor-transport-weak-null-crossing")
    for pt, mj, e2, L in POINTS:
        g, f = vaidya(pt, mj, e2, L)
        P, R, Rs, g0, _ = store_schouten(g)
        r0 = pt[1]
        assert R == 4 * L
        h2 = [[g0[i][j] if (i < 2 and j < 2) else F(0) for j in range(NV)] for i in range(NV)]
        hS = [[g0[i][j] if (i >= 2 and j >= 2) else F(0) for j in range(NV)] for i in range(NV)]
        for i in range(NV):
            for j in range(NV):
                dust = -mj[1] / (r0 * r0) if (i, j) == (0, 0) else F(0)
                maxw = e2 / (2 * r0 ** 4) * (-h2[i][j] + hS[i][j])
                assert P[i][j] == L * F(1, 6) * g0[i][j] + dust + maxw
    return True


def check_crossing_ray():
    premise("interior.imported-tractor-connection")
    premise("synthesis.tractor-transport-weak-null-crossing")
    for pt, mj, e2, L in POINTS:
        g, f = vaidya(pt, mj, e2, L)
        P, R, Rs, g0, G0 = store_schouten(g)
        r0 = pt[1]
        f0, fv, fr = f.c0(), f.d(0).c0(), f.d(1).c0()
        xi = [F(1), f0 * F(1, 2), F(0), F(0)]
        assert sum(g0[a][b] * xi[a] * xi[b] for a in range(NV) for b in range(NV)) == 0     # null

        def Gxx(a):
            return sum(G0[a][b][c] * xi[b] * xi[c] for b in range(NV) for c in range(NV))
        assert Gxx(0) == fr * F(1, 2)
        lw = -Gxx(0)                                                    # w'/w along the ray (d/dv)
        # r-equation: d(w f/2)/dlambda + Gamma^r(k,k) = 0, divided by w^2, with d f/dv = f_v + f_r f/2
        assert lw * f0 * F(1, 2) + (fv + fr * f0 * F(1, 2)) * F(1, 2) + Gxx(1) == 0
        assert Gxx(2) == 0 and Gxx(3) == 0
        for w in (F(1), F(7, 3), F(40)):
            k = [w * c for c in xi]
            # n = dv / w is parallel: (nabla_k n)_a = k(1/w) delta_a^v - Gamma^v_{ba} k^b / w, k(1/w) = -lw
            for a in range(NV):
                assert -lw * (1 if a == 0 else 0) - sum(G0[0][b][a] * xi[b] for b in range(NV)) == 0
            n = [F(1) / w, F(0), F(0), F(0)]
            assert sum(n[a] * k[a] for a in range(NV)) == 1                                      # nu = 1
            kflat = [sum(g0[a][b] * k[b] for b in range(NV)) for a in range(NV)]
            # k^flat parallel: d/dlambda (k_a) - Gamma^c_{ba} k^b k_c, with k_a = w * xi_a(v, r):
            # d/dlambda xi_v = w (d/dv along ray of f/2) = w (fv + fr f/2)/2 ; xi_r = -1 constant
            xflat = [sum(g0[a][b] * xi[b] for b in range(NV)) for a in range(NV)]
            assert xflat == [f0 * F(1, 2), F(-1), F(0), F(0)]
            dxi = [(fv + fr * f0 * F(1, 2)) * F(1, 2), F(0), F(0), F(0)]
            for a in range(NV):
                lhs = lw * xflat[a] + dxi[a] - sum(G0[c][b][a] * xi[b] * xflat[c] for b in range(NV) for c in range(NV))
                assert lhs == 0
            Pk = [sum(P[a][b] * k[b] for b in range(NV)) for a in range(NV)]
            S = -mj[1] / (r0 * r0) * w * w
            c = L * F(1, 6) - e2 / (2 * r0 ** 4)
            assert Pk == [S * n[a] + c * kflat[a] for a in range(NV)]
            assert Pk[2] == 0 and Pk[3] == 0
    return True


def check_inner_horizon():
    premise("synthesis.tractor-transport-weak-null-crossing")
    # f as a Laurent polynomial in r: coefficients of r^-2, r^-1, r^0, r^2
    def fpoly(m, e2, L):
        return {-2: F(e2), -1: -2 * F(m), 0: F(1), 2: -F(L) * F(1, 3)}

    def ev(p, r):
        return sum(c * F(r) ** e for e, c in p.items())

    def dr(p):
        return {e - 1: c * e for e, c in p.items() if e != 0}
    rn = fpoly(F(5, 4), F(1), F(0))
    assert ev(rn, F(1, 2)) == 0 and ev(rn, F(2)) == 0
    kap = -ev(dr(rn), F(1, 2)) * F(1, 2)
    assert kap == F(3) and kap == (F(2) - F(1, 2)) / (2 * F(1, 2) ** 2)
    assert ev(rn, F(1)) < 0                                      # f < 0 between the horizons (region II)
    # outgoing-ray flow r' = f/2: derivative at r_- is f_r/2 = -kappa < 0, so r_- attracts
    assert ev(dr(rn), F(1, 2)) * F(1, 2) == -kap
    ds = fpoly(F(6, 5), F(36, 25), F(3, 25))
    for root in (F(1), F(2), F(3), F(-6)):
        assert ev(ds, root) == 0
    kap2 = -ev(dr(ds), F(1)) * F(1, 2)
    assert kap2 == F(7, 25) and kap2 > 0
    assert ev(ds, F(3, 2)) < 0                                   # region II between r_- = 1 and r_+ = 2
    return True


# generalised exponentials: dict a -> coefficient, standing for sum c exp(a v)
def ex_mul(p, q):
    out = {}
    for a1, c1 in p.items():
        for a2, c2 in q.items():
            out[a1 + a2] = out.get(a1 + a2, F(0)) + c1 * c2
    return {a: c for a, c in out.items() if c != 0}


def ex_tail(p):
    """int_V^oo of sum c exp(a v) dv, as a generalised exponential in V; None if some a >= 0 (divergent)."""
    if any(a >= 0 for a in p):
        return None
    return {a: -c / a for a, c in p.items()}


def check_threshold_bookkeeping():
    premise("synthesis.crossing-transport-tipler-threshold-sharp")
    premise("synthesis.tractor-transport-weak-null-crossing")
    for kap in (F(1), F(3), F(2, 5)):
        w = {kap: F(1)}
        winv = {-kap: F(1)}
        lam_gap = ex_tail(winv)                                 # lambda_c - lambda = int_v^oo dv/w
        assert lam_gap == {-kap: F(1) / kap}
        for alpha in (kap / 4, kap / 2, kap * F(3, 5), kap * 2):
            mp = {-2 * alpha: F(1)}
            l1 = ex_tail(ex_mul(mp, w))                          # int |S| dlambda = int m' w dv / r^2
            assert (l1 is not None) == (2 * alpha > kap)
            beta = alpha / kap
            assert (l1 is not None) == (beta > F(1, 2))
            tip = ex_mul(ex_mul(lam_gap, w), mp)                 # (lambda_c - lambda) w m'
            assert tip == {-2 * alpha: F(1) / kap}
            assert ex_tail(tip) == {-2 * alpha: 1 / (kap * 2 * alpha)}   # finite: total mass / kappa
            # |S| = m' w^2 as a power of t = exp(-kappa v)/kappa: exponent of exp(v) is kappa (2 - 2 beta)
            Sx = ex_mul(mp, ex_mul(w, w))
            (a_S, c_S), = Sx.items()
            assert a_S == -kap * (2 * beta - 2)
    return True

synthesis.cohomology-of-the-quarter-turn:
"""synthesis.cohomology-of-the-quarter-turn-lens-spaces-from-the-equivariant-cell-structure: exact checks.

The sphere S^{2n+1} with the free action of Z_m (m = 4: the quarter turn J(v) = v . B in every coordinate plane)
has one free cell e_k in each dimension, with boundary (g - 1) e_{k-1} for k odd and N e_{k-1} for k even,
N = 1 + g + ... + g^{m-1}. Chains are dicts {(k, a): n} for n g^a e_k; tensors {(p, a, q, b): n}. Checks:
  (1) the quarter turn in GA (Cl(6,0)): J^2 = -1, orthogonal, free on the sphere, J(v) tangent at v;
  (2) the cell complex: d^2 = 0 and exactness in the middle degrees (ranks of g - 1 and N on the group ring);
  (3) the diagonal approximation is an equivariant chain map that preserves the augmentation; the four
      group-ring identities that prove it for every degree;
  (4) cup products and Bocksteins read from it: integral, mod 2 and mod 4; the m = 2 control (projective space);
  (5) the sections that compute the Euler classes of the quarter-turn and half-turn plane bundles;
  (6) the presented ring Z[s]/((1+s)^4 - 1, s^{n+1}): order 4^n of its augmentation ideal and the order of
      1 - (1+s)^2.
"""
from fractions import Fraction as F
import GA

M4 = 4
ORDERS = (2, 3, 4)        # group orders for which the diagonal is tested
TOP = 9                   # highest cell dimension tested
ID = 0                    # the identity translate g^0
MORE_ORDERS = (2, 3, 4, 5, 6, 8)   # group orders for the four group-ring identities


def bd(k, a, m):
    """Boundary of g^a e_k."""
    out = {}
    if k == 0:
        return out
    if k % 2 == 1:
        out[(k - 1, (a + 1) % m)] = out.get((k - 1, (a + 1) % m), 0) + 1
        out[(k - 1, a)] = out.get((k - 1, a), 0) - 1
    else:
        for c in range(m):
            out[(k - 1, (a + c) % m)] = out.get((k - 1, (a + c) % m), 0) + 1
    return {x: v for x, v in out.items() if v}


def acc(A, B, s=1):
    C = dict(A)
    for x, v in B.items():
        C[x] = C.get(x, 0) + s * v
        if not C[x]:
            del C[x]
    return C


def bd_chain(ch, m):
    out = {}
    for (k, a), c in ch.items():
        out = acc(out, bd(k, a, m), c)
    return out


def delta(k, a, m, twist=1):
    """Delta(g^a e_k) = sum over p + q = k of: e_p (x) e_q (p even); e_p (x) g e_q (p odd, q even);
    sum_{i<j} g^i e_p (x) g^j e_q (p, q odd); all translated by g^a (diagonal action)."""
    out = {}
    for p in range(k + 1):
        q = k - p
        if p % 2 == 0:
            terms = [(0, 0)]
        elif q % 2 == 0:
            terms = [(0, twist)]
        else:
            terms = [(i, j) for i in range(m) for j in range(i + 1, m)]
        for (i, j) in terms:
            out[(p, (a + i) % m, q, (a + j) % m)] = 1
    return out


def bd_tensor(T, m):
    out = {}
    for (p, a, q, b), v in T.items():
        for (pp, aa), c in bd(p, a, m).items():
            out = acc(out, {(pp, aa, q, b): v * c})
        for (qq, bb), c in bd(q, b, m).items():
            out = acc(out, {(p, a, qq, bb): v * c * (-1) ** p})
    return out


def delta_chain(ch, m, twist=1):
    out = {}
    for (k, a), c in ch.items():
        out = acc(out, delta(k, a, m, twist), c)
    return out


def cup_coefficient(p, q, m):
    """(eps_p cup eps_q)(e_{p+q}) for the invariant cochains eps_k (value 1 on every g^a e_k)."""
    return sum(v for (pp, a, qq, b), v in delta(p + q, 0, m).items() if pp == p)


def check_quarter_turn_in_the_algebra():
    sq = GA.sig(6, 0)
    B = GA.add(GA.mul(GA.gen(0), GA.gen(1), sq), GA.mul(GA.gen(2), GA.gen(3), sq), GA.mul(GA.gen(4), GA.gen(5), sq))

    def J(v):
        w = GA.mul(v, B, sq)
        return {k: c for k, c in w.items() if len(k) == 1}
    vs = [GA.add(GA.scal(F(1 + i), GA.gen(i)), GA.scal(F(2 - i), GA.gen((i + 3) % 6)), GA.gen((i + 1) % 6))
          for i in range(6)]
    for v in vs:
        assert GA.eq(J(J(v)), GA.neg(v))                                     # J^2 = -1, so J^4 = 1
        assert GA.mul(J(v), J(v), sq) == GA.mul(v, v, sq)                    # Q(Jv) = Q(v)
        assert GA.dot(v, J(v), sq) == 0 and GA.dot(v, v, sq) != 0             # Jv tangent at v
        for a in (1, 2, 3):
            w = v
            for _ in range(a):
                w = J(w)
            assert not GA.eq(w, v)                                           # free on nonzero vectors
    # J^a - 1 is invertible on vectors for a = 1, 2, 3: rank 6
    for a in (1, 2, 3):
        rows = []
        for i in range(6):
            w = GA.gen(i)
            for _ in range(a):
                w = J(w)
            d = GA.sub(w, GA.gen(i))
            rows.append([d.get((j,), F(0)) for j in range(6)])
        assert GA.field_rank(rows) == 6


def check_cell_complex():
    for m in (2, 4):
        for k in range(2, 12):
            assert bd_chain(bd(k, 0, m), m) == {}
        # on the group ring: g - 1 has rank m - 1 and N has rank 1, so ker(g - 1) = im N and ker N = im(g - 1)
        gm1 = [[F(bd(1, a, m).get((0, b), 0)) for b in range(m)] for a in range(m)]
        nn = [[F(bd(2, a, m).get((1, b), 0)) for b in range(m)] for a in range(m)]
        assert GA.field_rank(gm1) == m - 1 and GA.field_rank(nn) == 1
        assert all(sum(row) == 0 for row in gm1) and all(row == nn[0] for row in nn)
    assert bd(2, 0, M4) == {(1, 0): 1, (1, 1): 1, (1, 2): 1, (1, 3): 1}
    assert bd(3, 1, M4) == {(2, 2): 1, (2, 1): -1}


def check_diagonal_approximation_is_a_chain_map():
    for m in ORDERS:
        for k in range(TOP + 1):
            assert bd_tensor(delta(k, ID, m), m) == delta_chain(bd(k, ID, m), m)
        assert delta(ID, ID, m) == {(ID, ID, ID, ID): 1}                    # augmentation preserved
    # term counts: e_4 has 3 even-even terms and 2 * 6 odd-odd ones; e_5 has 6 terms; e_9 has 10
    assert len(delta(4, ID, M4)) == 15 and len(delta(5, ID, M4)) == 6 and len(delta(TOP, ID, M4)) == 10
    assert sum(bd_tensor(delta(4, ID, M4), M4).values()) == 16 and len(bd_tensor(delta(3, ID, M4), M4)) == 10
    # the formula without the twist by g (e_p (x) e_q for p odd, q even), or with g^2, is not a chain map
    assert bd_tensor(delta(3, ID, M4, twist=ID), M4) != delta_chain(bd(3, ID, M4), M4, twist=ID)
    assert bd_tensor(delta(3, ID, M4, twist=2), M4) != delta_chain(bd(3, ID, M4), M4, twist=2)


def gg_mul(x, y, m):
    """Product in the group ring Z[G x G]: dicts {(a, b): n} for n g^a (x) g^b."""
    out = {}
    for (a1, b1), u in x.items():
        for (a2, b2), v in y.items():
            k = ((a1 + a2) % m, (b1 + b2) % m)
            out[k] = out.get(k, 0) + u * v
            if not out[k]:
                del out[k]
    return out


def gg_add(*xs):
    out = {}
    for sgn, x in xs:
        out = acc(out, x, sgn)
    return out


def check_four_group_ring_identities():
    """The chain-map condition in bidegree (p, q) depends on parities only: four identities in Z[G x G]."""
    for m in MORE_ORDERS:
        one = {(ID, ID): 1}
        g1 = {(1, ID): 1}                                   # g (x) 1
        g2 = {(ID, 1): 1}                                   # 1 (x) g
        gg = {(1, 1): 1}                                    # g (x) g
        N1 = {(a, ID): 1 for a in range(m)}                 # N (x) 1
        N2 = {(ID, a): 1 for a in range(m)}                 # 1 (x) N
        diag = {(a, a): 1 for a in range(m)}
        T = {(r, j): 1 for r in range(m) for j in range(r + 1, m)}
        assert len(T) == m * (m - 1) // 2
        # (even, even)
        assert gg_add((1, gg_mul(g2, gg_add((1, g1), (-1, one)), m)), (1, g2), (-1, one)) == gg_add((1, gg), (-1, one))
        # (odd, even): N (x) 1 - T (1 (x) g - 1) = diag (1 (x) g)
        assert gg_add((1, N1), (-1, gg_mul(T, gg_add((1, g2), (-1, one)), m))) == gg_mul(diag, g2, m)
        # (even, odd): T (g (x) 1 - 1) + 1 (x) N = diag
        assert gg_add((1, gg_mul(T, gg_add((1, g1), (-1, one)), m)), (1, N2)) == diag
        # (odd, odd): N (x) 1 - 1 (x) N = (g (x) g - 1) T
        assert gg_add((1, N1), (-1, N2)) == gg_mul(gg_add((1, gg), (-1, one)), T, m)
        # the form with N (x) g - 1 (x) N on the right is false
        if m > 2:
            assert gg_mul(gg_add((1, gg), (-1, one)), T, m) != gg_add((1, gg_mul(N1, g2, m)), (-1, N2))


def check_cup_products_and_bocksteins():
    m = M4
    n = 4                                                                    # L^9(4): cells e_0 .. e_9
    for p in range(0, 2 * n + 2):
        for q in range(0, 2 * n + 2 - p):
            c = cup_coefficient(p, q, m)
            assert c == (6 if (p % 2 and q % 2) else 1)
    # integral cochains: (delta eps_{2i-1})(e_{2i}) = eps_{2i-1}(N e_{2i-1}) = 4, delta eps_{2i} = 0
    for i in range(1, n + 1):
        assert sum(bd(2 * i, 0, m).values()) == 4 and sum(bd(2 * i + 1, 0, m).values()) == 0
    # H^{2i}(Z) = Z_4 generated by y^i = eps_{2i}: products of even cochains have coefficient 1
    assert all(cup_coefficient(2, 2 * i, m) == 1 for i in range(1, n))
    # mod 2: x = eps_1, x^2 = 6 eps_2 = 0; x u^i = eps_{2i+1} with coefficient 1
    assert cup_coefficient(1, 1, m) % 2 == 0
    assert all(cup_coefficient(1, 2 * i, m) % 2 == 1 for i in range(0, n + 1))
    # mod 4: the square of the degree-one generator is 2 eps_2, nonzero
    assert cup_coefficient(1, 1, m) % 4 == 2
    # Bocksteins: the integral Bockstein of x is (delta eps_1)/2 = 2 eps_2, of order two in Z_4;
    # the Bockstein of Z_2 -> Z_4 -> Z_2 is (delta eps_odd)/2 mod 2 = 0 in every degree
    d = sum(bd(2, 0, m).values())
    assert d // 2 == 2 and (d // 2) % 4 != 0 and (2 * (d // 2)) % 4 == 0
    assert (d // 2) % 2 == 0
    # control: m = 2 is real projective space, where x^2 = eps_2 is not zero and the Bockstein is not zero
    assert cup_coefficient(1, 1, 2) % 2 == 1 and (sum(bd(2, 0, 2).values()) // 2) % 2 == 1


def check_euler_class_sections():
    sq = GA.sig(2, 0)
    e1, e2 = GA.gen(0), GA.gen(1)
    B = GA.mul(e1, e2, sq)
    for (c, s) in ((F(3, 5), F(4, 5)), (F(5, 13), F(12, 13)), (F(-8, 17), F(15, 17))):
        v = GA.add(GA.scal(c, e1), GA.scal(s, e2))
        Jv = {k: x for k, x in GA.mul(v, B, sq).items() if len(k) == 1}
        assert GA.eq(Jv, GA.add(GA.scal(-s, e1), GA.scal(c, e2)))               # the quarter turn of the plane
        # s1(v) = v: s1(Jv) = J s1(v), one turn around the circle (the identity map): Euler number 1
        # s2(v) = v e1 v: s2(Jv) = -s2(v), and it is the double-angle map: two turns, Euler number 2
        s2 = GA.mul(GA.mul(v, e1, sq), v, sq)
        s2J = GA.mul(GA.mul(Jv, e1, sq), Jv, sq)
        assert GA.eq(s2J, GA.neg(s2))
        assert GA.eq(s2, GA.add(GA.scal(c * c - s * s, e1), GA.scal(2 * c * s, e2)))
        assert GA.mul(s2, s2, sq) == GA.mul(v, v, sq)                         # nowhere zero on the circle


def ideal_orders(n):
    """Augmentation ideal of Z[s]/((1+s)^4 - 1, s^{n+1}) on the basis s, ..., s^n: relation rows s^j R,
    R = 4s + 6s^2 + 4s^3 + s^4. Returns (order of the ideal, order of the element -(2s + s^2))."""
    R = [4, 6, 4, 1]
    T = [[R[c - j] if 0 <= c - j < 4 else 0 for c in range(n)] for j in range(n)]
    det = 1
    for j in range(n):
        det *= T[j][j]
    v = [F(-2) if c == 0 else (F(-1) if c == 1 else F(0)) for c in range(n)]
    w = []                                                                   # v = w T, T upper triangular
    for c in range(n):
        w.append((v[c] - sum(w[j] * T[j][c] for j in range(c))) / T[c][c])
    order = 1
    for x in w:
        den = x.denominator
        g, a, b = order, order, den
        while b:
            a, b = b, a % b
        order = g * den // a
    return det, order


def check_presented_ring_orders():
    want = {1: 2, 2: 2, 3: 4, 4: 4, 5: 8, 6: 8, 7: 16, 8: 16, 9: 32, 10: 32, 11: 64, 12: 64, 13: 128, 14: 128}
    for n in range(1, 15):
        det, order = ideal_orders(n)
        assert det == 4 ** n
        assert order == want[n] == 2 ** ((n + 1) // 2)
    # so 2(1 - xi) is zero in the presented ring for n = 1, 2 and not for n = 3
    assert ideal_orders(2)[1] == 2 and ideal_orders(3)[1] == 4

synthesis.collar-isotropy-selects-t-boos:
"""synthesis.collar-isotropy-selects-t-boost: exact checks in the basis-blade engine of GA.py.

Cl(1,3) with e0^2 = 1, e1^2 = e2^2 = e3^2 = -1 (e0 the Hubble-normal direction, e1 the t-direction,
e2, e3 the sphere directions, as in the collar's adapted frame). Boost bivectors B_i = e0 e_i
(square +1), rotation bivectors R_ij = e_i e_j (square -1). For K = B/2 with K^2 = 1/4,
exp(-beta K) = cosh(beta/2) - 2 sinh(beta/2) K; rational (cosh, sinh) on the hyperbola.
Checked:
  (a) B_i^2 = 1, R_ij^2 = -1, [B_1, B_2] = -2 R_12 (nonzero): the three boosts do not commute;
  (b) the bivectors commuting with R_23 are exactly span{B_1, R_23} (kernel of a 6x6 rational system);
      the bivectors commuting with all three R_ij: only 0;
  (c) the B_1-Gibbs element rho_1 = c - s B_1 is invariant under every rational R_23 rotor; the
      B_2-Gibbs element rho_2 = c - s B_2 is not (for s != 0 and a rotation angle with sin != 0), and the
      R_23 rotation by a right angle carries rho_2 to the B_3-Gibbs element;
  (d) the Kasner rate tensor diag(-1/3, 2/3, 2/3) on (e1, e2, e3) is fixed by the rotations of the
      (e2, e3) plane and by no rotation of the (e1, e2) plane with nonzero sine; the same at first order
      in R with the collar's rates (-1/3 - 4R/15, 2/3 - 2R/15, 2/3 - 2R/15).
"""
import GA
from fractions import Fraction as F
from tp_premise import premise

SQ = (1, -1, -1, -1)


def m(*xs):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, SQ)
    return out


e = [GA.gen(i) for i in range(4)]
B = {1: m(e[0], e[1]), 2: m(e[0], e[2]), 3: m(e[0], e[3])}
R = {(1, 2): m(e[1], e[2]), (1, 3): m(e[1], e[3]), (2, 3): m(e[2], e[3])}
BIV = [B[1], B[2], B[3], R[(1, 2)], R[(1, 3)], R[(2, 3)]]


def comm(x, y):
    return GA.sub(GA.mul(x, y, SQ), GA.mul(y, x, SQ))


def rotor(c, s, biv):
    """c + s biv, with c^2 + s^2 = 1 for a rotation bivector (square -1); inverse c - s biv"""
    return GA.add(GA.sc(c), GA.scal(s, biv)), GA.add(GA.sc(c), GA.scal(-s, biv))


def conj(r, ri, x):
    return GA.mul(GA.mul(r, x, SQ), ri, SQ)


def centraliser_dim(gens):
    """dimension of {sum_k x_k BIV_k : [g, .] = 0 for g in gens}, by exact rank"""
    blades = GA.all_blades(4)
    rows = []
    for g in gens:
        cols = [comm(g, bv) for bv in BIV]
        for bl in blades:
            rows.append([c.get(bl, F(0)) for c in cols])
    return len(BIV) - GA.mat_rank(rows)


def check_boost_algebra_and_isotropy_centraliser():
    premise("singularity.imported-interior-collar-kasner-form")
    premise("singularity.modular-flow-boundary-modes-holonomy-universal")
    premise("synthesis.phase-flow-is-time-rotor-flow-kms-continuation")
    # frame *-structure: x* = x for Q(x) = 1, x* = -x for Q(x) = -1, antiautomorphism
    star = {0: GA.sc(1), 1: GA.sc(-1), 2: GA.sc(-1), 3: GA.sc(-1)}

    def star_biv(i, j):
        return m(GA.scal(star[j][()], e[j]), GA.scal(star[i][()], e[i]))
    for i in (1, 2, 3):
        assert GA.eq(star_biv(0, i), B[i])                     # boosts are *-symmetric
    for (i, j) in R:
        assert GA.eq(star_biv(i, j), GA.neg(R[(i, j)]))        # rotations are *-antisymmetric
    for i in (1, 2, 3):
        assert GA.eq(m(B[i], B[i]), GA.sc(1))
    for k in R:
        assert GA.eq(m(R[k], R[k]), GA.sc(-1))
    assert GA.eq(comm(B[1], B[2]), GA.scal(-2, R[(1, 2)])) and not GA.is_zero(comm(B[1], B[2]))
    assert not GA.is_zero(comm(B[1], B[3])) and not GA.is_zero(comm(B[2], B[3]))
    # centraliser of R_23 among bivectors: span{B_1, R_23}
    assert centraliser_dim([R[(2, 3)]]) == 2
    assert GA.is_zero(comm(R[(2, 3)], B[1])) and GA.is_zero(comm(R[(2, 3)], R[(2, 3)]))
    assert not GA.is_zero(comm(R[(2, 3)], B[2])) and not GA.is_zero(comm(R[(2, 3)], B[3]))
    # centraliser of the whole frame so(3): zero
    assert centraliser_dim([R[(1, 2)], R[(1, 3)], R[(2, 3)]]) == 0
    GA.check("the bivectors commuting with the isotropy rotation R_23 are span{B_1, R_23}; "
             "nothing nonzero commutes with all frame rotations", True)


def check_isotropy_invariant_kms_is_t_boost_only():
    premise("singularity.kms-uniqueness-factor")
    premise("singularity.modular-flow-boundary-modes-holonomy-universal")
    for (c, s) in [(F(5, 4), F(3, 4)), (F(13, 5), F(-12, 5)), (F(17, 8), F(15, 8))]:
        assert c * c - s * s == 1
        rho1 = GA.add(GA.sc(c), GA.scal(-s, B[1]))          # e^{-beta K_1}, K_1 = B_1/2, beta = 2 artanh(s/c)
        rho2 = GA.add(GA.sc(c), GA.scal(-s, B[2]))
        rho3 = GA.add(GA.sc(c), GA.scal(-s, B[3]))
        # rho_1 is a positive invertible element: rho_1 (c + s B_1) = c^2 - s^2 = 1
        assert GA.eq(m(rho1, GA.add(GA.sc(c), GA.scal(s, B[1]))), GA.sc(1))
        for (ct, st) in [(F(3, 5), F(4, 5)), (F(5, 13), F(-12, 13)), (F(8, 17), F(15, 17))]:
            r, ri = rotor(ct, st, R[(2, 3)])
            assert GA.eq(m(r, ri), GA.sc(1))
            assert GA.eq(conj(r, ri, rho1), rho1)              # B_1-Gibbs: isotropy-invariant
            assert not GA.eq(conj(r, ri, rho2), rho2)          # B_2-Gibbs: not invariant
            assert not GA.eq(conj(r, ri, rho3), rho3)
        # the right-angle isotropy rotation (half-angle c = s = 1/sqrt 2) squared away: use the
        # rotor e2 e3 itself (a rotation by pi in the plane, up to sign) and the generator form:
        # [R_23, B_2] = 2 B_3, so the isotropy flow mixes B_2 into B_3
        assert GA.eq(comm(R[(2, 3)], B[2]), GA.scal(2, B[3]))
        assert not GA.eq(rho2, rho3)
    GA.check("for every rational beta the B_1-Gibbs element commutes with the isotropy rotations and "
             "the B_2-, B_3-Gibbs elements do not; the isotropy flow mixes B_2 into B_3", True)


def check_kasner_rates_fix_isotropy_only():
    premise("singularity.imported-interior-collar-kasner-form")

    def rot3(i, j, c, s):
        M = [[F(int(a == b)) for b in range(3)] for a in range(3)]
        M[i][i], M[j][j], M[i][j], M[j][i] = c, c, -s, s
        return M

    def tr3(M):
        return [[M[b][a] for b in range(3)] for a in range(3)]

    def conj3(M, P):
        return GA.mat_mul(GA.mat_mul(M, P), tr3(M))

    P0 = [[F(-1, 3), 0, 0], [0, F(2, 3), 0], [0, 0, F(2, 3)]]
    P0 = [[F(x) for x in row] for row in P0]
    assert P0[0][0] + P0[1][1] + P0[2][2] == 1                 # sum p_i = 1
    assert P0[0][0] ** 2 + P0[1][1] ** 2 + P0[2][2] ** 2 == 1  # sum p_i^2 = 1
    for Rr in [F(1, 10), F(1, 4)]:
        P1 = [[F(-1, 3) - F(4, 15) * Rr, 0, 0], [0, F(2, 3) - F(2, 15) * Rr, 0], [0, 0, F(2, 3) - F(2, 15) * Rr]]
        P1 = [[F(x) for x in row] for row in P1]
        for P in (P0, P1):
            for (c, s) in [(F(3, 5), F(4, 5)), (F(5, 13), F(12, 13))]:
                assert GA.mat_eq(conj3(rot3(1, 2, c, s), P), P)        # (e2, e3) rotations: symmetries
                assert not GA.mat_eq(conj3(rot3(0, 1, c, s), P), P)    # (e1, e2) rotations: not
    GA.check("the Kasner rate tensor (and the collar's first-order rates) is fixed by the (e2,e3) "
             "rotations and by no (e1,e2) rotation", True)

synthesis.colour-centre-flux-bounds-poly:
"""synthesis.colour-centre-flux-bounds-polyakov-lines-and-the-leading-glueball-tube: exact checks.

The colour factor su(3) as the eight traceless bivectors of the block e3..e8 of Cl(9,0) commuting with
J = e34 + e56 + e78 (the realisation of the stored field-level BRST result). I = e345678, P_k = e34, e56, e78,
the pure-spinor idempotent E = prod_k (1 + I P_k)/2, and the trivectors Re Omega = e357 - e368 - e458 - e467,
Im Omega = e457 + e367 + e358 - e468 (the J-complex volume form on the frame e3, e5, e7 with J-partners
e4, e6, e8; the complex structure on vectors is v -> v.J, e3 -> e4). A colour rotor is a rotor R of
the block (even, R rev(R) = 1, R v rev(R) a vector for every vector v) with R E = E; f_R(v) = R v rev(R) is its vector action.
Products in the 32-dimensional even subalgebra of the block use a blade table built from GA.blade_mul and are
checked against GA.mul on all basis pairs. The finite group G (order 96) is generated by four rational
rotors (two quarter-turn tori and two J-commuting signed permutations), each with the sign fixed by R E = E.
Haar averages on SU(3) are not imported: for a compact group the average of a representation is the
orthogonal projector onto its invariants, and the checks show that the G-invariants of the vector action in
degrees 1, 2, 3 (and of left multiplication on the even subalgebra) are spanned by tensors that every colour
rotor fixes, so G-averages equal Haar averages there (the argument is in the proof).
The centre rotor needs sqrt(3): it is computed in Q(sqrt 3) with a two-component exact number class.
Lattice integrals: tree gauge with the multiplication table of G, and, independently, closed-surface tensor
contraction with the degree-2 moment int f_ab f_cd = (delta delta + J J)/6.
"""
from fractions import Fraction as F
from itertools import combinations, product

import GA
from tp_premise import premise

E9 = GA.sig(9, 0)
IDX = tuple(range(3, 9))
EVEN = [b for k in (0, 2, 4, 6) for b in combinations(IDX, k)]
POS = {b: i for i, b in enumerate(EVEN)}
TAB = []
for _a in EVEN:
    _row = []
    for _b in EVEN:
        _s, _c = GA.blade_mul(_a, _b, E9)
        _row.append((int(_s), POS[_c]))
    TAB.append(_row)


def m(x, y):
    out = [F(0)] * 32
    for i, a in enumerate(x):
        if a:
            row = TAB[i]
            for j, b in enumerate(y):
                if b:
                    s, k = row[j]
                    out[k] = out[k] + s * a * b
    return tuple(out)


def arr(mv):
    a = [F(0)] * 32
    for b, c in mv.items():
        a[POS[b]] += c
    return tuple(a)


def mvec(x):
    return {EVEN[i]: c for i, c in enumerate(x) if c}


def rev(x):
    return tuple(c if len(EVEN[i]) % 4 == 0 else -c for i, c in enumerate(x))


def add(*xs):
    return tuple(sum(c, F(0)) for c in zip(*xs))


def sca(c, x):
    return tuple(c * v for v in x)


def blade(*ix):
    r = GA.sc(1)
    for i in ix:
        r = GA.mul(r, GA.gen(i), E9)
    return r


ONE = arr(GA.sc(1))
I6 = arr(blade(*IDX))
P34, P56, P78 = arr(blade(3, 4)), arr(blade(5, 6)), arr(blade(7, 8))
JB = add(P34, P56, P78)
HALF = F(1, 2)
E = ONE
for _p in (P34, P56, P78):
    E = m(E, sca(HALF, add(ONE, m(I6, _p))))
JMV = mvec(JB)
RE_OM = GA.add(blade(3, 5, 7), GA.scal(-1, blade(3, 6, 8)), GA.scal(-1, blade(4, 5, 8)), GA.scal(-1, blade(4, 6, 7)))
IM_OM = GA.add(blade(4, 5, 7), blade(3, 6, 7), blade(3, 5, 8), GA.scal(-1, blade(4, 6, 8)))


def gcomm(x, y):
    return GA.sub(GA.mul(x, y, E9), GA.mul(y, x, E9))


def su3_basis():
    so6 = [blade(i, j) for i, j in combinations(IDX, 2)]
    rows = sorted({b for x in so6 for b in gcomm(x, JMV)})
    M = [[gcomm(x, JMV).get(r, F(0)) for x in so6] for r in rows]
    u3 = [GA.add(*[GA.scal(v[i], so6[i]) for i in range(len(so6)) if v[i] != 0]) for v in GA.field_kernel(M)]
    jj = GA.mul(JMV, JMV, E9).get((), F(0))
    out = []
    for x in u3:
        y = GA.sub(x, GA.scal(GA.mul(x, JMV, E9).get((), F(0)) / jj, JMV))
        trial = out + [y]
        keys = sorted({b for z in trial for b in z})
        if y and GA.field_rank([[z.get(k, F(0)) for k in keys] for z in trial]) == len(trial):
            out.append(y)
    return out


def sandwich(R, v):
    return GA.mul(GA.mul(mvec(R), v, E9), mvec(rev(R)), E9)


def vec_action(R):
    """integer matrix M[a][b] = e_a . f_R(e_b)"""
    cols = []
    for k in IDX:
        y = sandwich(R, GA.gen(k))
        assert all(len(b) == 1 for b in y)
        cols.append([y.get((t,), F(0)) for t in IDX])
    return tuple(tuple(int(cols[b][a]) for b in range(6)) for a in range(6))


def jmat():
    out = [[0] * 6 for _ in range(6)]
    for b, k in enumerate(IDX):
        y = GA.mul(GA.gen(k), JMV, E9)
        for a, t in enumerate(IDX):
            out[a][b] = int(y.get((t,), F(0)))
    return out


def lift(R):
    RE = m(R, E)
    return R if RE == E else sca(-1, R)


def pair_rotor(a, b, c, d):
    x = GA.sub(GA.gen(a), GA.gen(b))
    y = GA.sub(GA.gen(c), GA.gen(d))
    return arr(GA.scal(HALF, GA.mul(x, y, E9)))


GENS = [lift(sca(HALF, m(add(ONE, sca(-1, P34)), add(ONE, P56)))),
        lift(sca(HALF, m(add(ONE, sca(-1, P56)), add(ONE, P78)))),
        lift(m(pair_rotor(5, 7, 6, 8), pair_rotor(3, 5, 4, 6))),
        lift(m(pair_rotor(3, 5, 4, 6), P78))]


def closure(gens):
    elems = {ONE: None}
    frontier = [ONE]
    while frontier:
        new = []
        for x in frontier:
            for g in gens:
                y = m(x, g)
                if y not in elems:
                    elems[y] = None
                    new.append(y)
        frontier = new
    return list(elems)


G = closure(GENS)
_CACHE = {}


def table():
    if 'mul' not in _CACHE:
        idx = {R: i for i, R in enumerate(G)}
        _CACHE['mul'] = [[idx[m(a, b)] for b in G] for a in G]
        _CACHE['inv'] = [idx[rev(a)] for a in G]
        _CACHE['id'] = idx[ONE]
    return _CACHE['mul'], _CACHE['inv'], _CACHE['id']


def chi(R):
    """fundamental character as (Re, Im): 4(<R>_0 + <R>_6) - 1 with I standing for i"""
    return (4 * R[0] - 1, 4 * R[POS[IDX]])


def w(R):
    return (4 * R[0] - 1) / 3


def cm(a, b):
    return (a[0] * b[0] - a[1] * b[1], a[0] * b[1] + a[1] * b[0])


def cbar(a):
    return (a[0], -a[1])


def avg(vals):
    vals = list(vals)
    return (sum((v[0] for v in vals), F(0)) / len(vals), sum((v[1] for v in vals), F(0)) / len(vals))


def tensor_of(T):
    """totally antisymmetric 6x6x6 array of a trivector"""
    out = {}
    for b, c in T.items():
        for perm in __import__('itertools').permutations(range(3)):
            sgn = 1
            p = list(perm)
            for i in range(3):
                for j in range(i + 1, 3):
                    if p[i] > p[j]:
                        sgn = -sgn
            out[tuple(IDX.index(b[q]) for q in perm)] = sgn * int(c)
    return out


def outer3(M, T):
    """outermorphism of the vector map M on a trivector T"""
    out = {}
    for b, c in T.items():
        vs = [{(IDX[a],): F(M[a][IDX.index(k)]) for a in range(6) if M[a][IDX.index(k)]} for k in b]
        x = GA.mul(GA.mul(vs[0], vs[1], E9), vs[2], E9)
        x = {bb: cc for bb, cc in x.items() if len(bb) == 3}
        out = GA.add(out, GA.scal(c, x))
    return out


class Q3(object):
    """exact a + b sqrt(3), a, b rational"""

    def __init__(self, a, b=0):
        self.a, self.b = F(a), F(b)

    def _c(self, o):
        return o if isinstance(o, Q3) else Q3(o)

    def __add__(self, o):
        o = self._c(o)
        return Q3(self.a + o.a, self.b + o.b)
    __radd__ = __add__

    def __neg__(self):
        return Q3(-self.a, -self.b)

    def __sub__(self, o):
        return self + (-self._c(o))

    def __mul__(self, o):
        o = self._c(o)
        return Q3(self.a * o.a + 3 * self.b * o.b, self.a * o.b + self.b * o.a)
    __rmul__ = __mul__

    def __eq__(self, o):
        o = self._c(o)
        return self.a == o.a and self.b == o.b

    def __hash__(self):
        return hash((self.a, self.b))

    def __bool__(self):
        return self.a != 0 or self.b != 0


# ---------------------------------------------------------------- tensor contraction on closed surfaces
def surface_integral(faces):
    """int prod_f w(U_f) over all links, each link in exactly two faces, by int f_ab f_cd = (dd + JJ)/6."""
    occ = {}
    for f, face in enumerate(faces):
        L = len(face)
        for k, (l, d) in enumerate(face):
            occ.setdefault(l, []).append(((f, k), (f, (k + 1) % L)) if d > 0 else ((f, (k + 1) % L), (f, k)))
    links = sorted(occ)
    adj = {}
    for li, l in enumerate(links):
        assert len(occ[l]) == 2
        (r1, c1), (r2, c2) = occ[l]
        for a, b in ((r1, r2), (c1, c2)):
            adj.setdefault(a, []).append((b, li, 1))
            adj.setdefault(b, []).append((a, li, -1))
    used, cycles, seen = set(), [], set()
    for start in adj:
        if start in seen:
            continue
        cyc, node = [], start
        while True:
            seen.add(node)
            for e in adj[node]:
                key = (min(node, e[0]), max(node, e[0]), e[1])
                if key not in used:
                    used.add(key)
                    cyc.append((e[1], e[2]))
                    node = e[0]
                    break
            if node == start:
                break
        cycles.append(cyc)
    total = F(0)
    for sig in product((0, 1), repeat=len(links)):
        val = 1
        for cyc in cycles:
            k, sgn = 0, 1
            for li, d in cyc:
                if sig[li]:
                    k += 1
                    sgn = -sgn if d < 0 else sgn
            if k % 2:
                val = 0
                break
            val *= sgn * (6 if k % 4 == 0 else -6)
        total += val
    return total / F(6) ** len(links) / F(6) ** len(faces)


def _link(a, b):
    return ((a, b) if a < b else (b, a)), (1 if a < b else -1)


def _loop(cs):
    return [_link(a, b) for a, b in zip(cs, cs[1:] + cs[:1])]


def disc_faces(R, T):
    faces = [_loop([(x, y), (x + 1, y), (x + 1, y + 1), (x, y + 1)]) for x in range(R) for y in range(T)]
    bd = [(x, 0) for x in range(R + 1)] + [(R, y) for y in range(1, T + 1)]
    bd += [(x, T) for x in range(R - 1, -1, -1)] + [(0, y) for y in range(T - 1, 0, -1)]
    return faces + [_loop(bd)]


def tube_faces(t):
    sq = [(0, 0), (1, 0), (1, 1), (0, 1)]
    faces = [_loop([(x, y, 0) for x, y in sq]), _loop([(x, y, t) for x, y in sq])]
    for tau in range(t):
        for (x, y), (x2, y2) in zip(sq, sq[1:] + sq[:1]):
            faces.append(_loop([(x, y, tau), (x2, y2, tau), (x2, y2, tau + 1), (x, y, tau + 1)]))
    return faces


