    # N_t = 1: P(x) P(y) (N-ality 2) has no term at this order
    lead2 = avg((cm(CH[a], CH[b])[0] * W[MUL[a][INV[b]]], cm(CH[a], CH[b])[1] * W[MUL[a][INV[b]]])
                for a in range(n) for b in range(n))
