                tot[0] += v[0] * f
                tot[1] += v[1] * f
    assert (tot[0] / n ** 3 / 9, tot[1] / n ** 3 / 9) == (F(1, 9) * F(1, 18) ** 2, 0)
    # three lines at the three neighbours of a site, N_t = 1: each sheet reduces to chi(U_o)/54
    Fu = []
    for u in range(n):
