    assert (I_EH_S4, I_GB_S4, I_EH_N, I_GB_N) == (-3, 3, -2, 6)
    assert I_EH_S4 == -S_dS_EH and I_EH_S4 + I_GB_S4 == -(S_dS_EH + shift)
    assert I_EH_N == -S_N_EH and I_EH_N + I_GB_N == -S_N_MM
    # nucleation exponents S_N - S_dS: Einstein-Hilbert -1, series' action -4, ratio 4
    assert S_N_EH - S_dS_EH == -1 and S_N_MM - (S_dS_EH + shift) == -4
    # anti-de Sitter branch: the shift is positive
    assert 2 * (-3 / (4 * F(-1))) * 2 > 0
    # SdS: h(r) = r f(r) = r - 2M - Lambda r^3/3 increases on (0, 1/sqrt(Lambda)) (h' = 1 - Lambda r^2),
    # h(0) = -2M < 0, so the smaller root r_b lies below 1/sqrt(Lambda): A_b/4G < pi/(Lambda G), and
    # S_MM(r_b) < 1 + shift = -2 in units pi/(Lambda G)
    for M in (F(1, 10), F(1, 6), F(19, 100)):     # 27 M^2 Lambda < 1 for two horizons
        h = lambda r: r - 2 * M - Lam * r ** 3 / 3
        assert h(F(0)) < 0 and 27 * M * M * Lam < 1 and h(F(1)) > 0
        lo, hi = F(0), F(1)
        for _ in range(40):
            mid = (lo + hi) / 2
            lo, hi = (mid, hi) if h(mid) < 0 else (lo, mid)
        assert hi < 1 and hi * hi + shift < -2 + F(1, 10)
    assert 1 + shift == -2
    return True

synthesis.even-composite-doublet-needs-a:
"""synthesis.even-composite-doublet-needs-a-singlet-constituent-and-its-pair-modes-are-quasi-spins: exact checks.

(i)  Selection rule, in the full Clifford algebra of the tower planes (GA's blade engine): plane j has generators
     e_j, f_j (squares +1, -1), v_j = (e_j + f_j)/2 = a_j*, w_j = (e_j - f_j)/2 = a_j. Planes 0, 1 are a doublet
     (up, down), the rest singlets. Isospin T_+ = v_0 w_1, T_- = v_1 w_0, T_3 = (v_0 w_0 - v_1 w_1)/2; the Casimir
     of ad is C = ad(T_3)^2 + (ad T_+ ad T_- + ad T_- ad T_+)/2. On the span A^(pD, pS) of the blades with doublet
     parity pD and singlet parity pS: C = 3/4 exactly when pD = 1, and C(C - 2) = 0 with the eigenvalue 2 of fixed
     multiplicity when pD = 0. One and two singlet planes; with no singlet plane every even element has integer
     isospin (the stored rung case). Hypercharge weights of the doublet-singlet bilinears.
(ii) Charged pair modes on a window k in {-2, -1, 0, 1} with channels (up, down, s), each mode a tower plane in GA's
     exterior model of the CAR: hypercharge weights (Y_d, Y_d, Y_s), M_up = E_{up, s}; [W, M] = (Y_d - Y_s) M, M^2 = 0,
     M not normal; the commutator on edge-clean vectors takes the two values q + 1 and q - 1; on the chiral sea
     B = rho_q(M)* has |B^p Omega|^2 = (p!)^2 C(q, p), B^(q+1) Omega = 0; the mutual commutator of the two components
     on an edge-clean vector is the isospin raising density.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from tp_premise import premise

YD, YS = F(1, 6), F(-1, 3)          # sample weights with Y_d - Y_s = 1/2


def _squares(m):
    return [F(1), F(-1)] * m           # generator 2j = e_j, 2j + 1 = f_j


def _v(j):
    return {(2 * j,): F(1, 2), (2 * j + 1,): F(1, 2)}


def _w(j):
    return {(2 * j,): F(1, 2), (2 * j + 1,): F(-1, 2)}


def _comm(x, y, sq):
    return GA.sub(GA.mul(x, y, sq), GA.mul(y, x, sq))


def _iso(sq):
    tp = GA.mul(_v(0), _w(1), sq)
    tm = GA.mul(_v(1), _w(0), sq)
    t3 = GA.scal(F(1, 2), GA.sub(GA.mul(_v(0), _w(0), sq), GA.mul(_v(1), _w(1), sq)))
    return tp, tm, t3


def _casimir_on(blade, ops, sq):
    tp, tm, t3 = ops
    x = {blade: F(1)}
    a = _comm(t3, _comm(t3, x, sq), sq)
    b = _comm(tp, _comm(tm, x, sq), sq)
    c = _comm(tm, _comm(tp, x, sq), sq)
    return GA.add(a, GA.scal(F(1, 2), GA.add(b, c)))


def _blocks(m):
    """Casimir matrices of ad on the spans A^(pD, pS) of blades, m planes (planes 0, 1 doublet)."""
    sq = _squares(m)
    ops = _iso(sq)
    blades = GA.all_blades(2 * m)
    out = {}
    for pd in (0, 1):
        for ps in (0, 1):
            sub = [b for b in blades if sum(1 for g in b if g < 4) % 2 == pd and sum(1 for g in b if g >= 4) % 2 == ps]
            idx = {b: i for i, b in enumerate(sub)}
            M = [[F(0)] * len(sub) for _ in sub]
            closed = True
            for j, b in enumerate(sub):
                for t, cf in _casimir_on(b, ops, sq).items():
                    if t not in idx:
                        closed = closed and cf == 0
                        continue
                    M[idx[t]][j] += cf
            out[(pd, ps)] = (M, closed)
    return out


def _shift(M, e):
    return [[M[i][j] - (e if i == j else 0) for j in range(len(M))] for i in range(len(M))]


def _zero(M):
    return all(x == 0 for r in M for x in r)


def check_doublets_are_odd_in_the_doublet_modes():
    premise("synthesis.rung-field-is-odd-in-the-tower-and-its-modes-carry-no-even-doublet")
    premise("tower.structure-tower-c-norms")
    premise("tower.ladder-pairs-satisfy-car-vectors")
    ok = True
    found = []
    for m in (2, 3, 4):
        for (pd, ps), (M, closed) in _blocks(m).items():
            n = len(M)
            ok = ok and closed
            if pd == 1:
                ok = ok and _zero(_shift(M, F(3, 4)))
                found.append((m, pd, ps, n, n))
            else:
                ok = ok and (n == 0 or _zero(GA.mat_mul(M, _shift(M, F(2)))))
                found.append((m, pd, ps, n, n - GA.mat_rank(_shift(M, F(2)))))
    # (planes, pD, pS, dimension, multiplicity of the eigenvalue 3/4 (pD = 1) or 2 (pD = 0))
    ok = ok and found[:4] == [(2, 0, 0, 8, 3), (2, 0, 1, 0, 0), (2, 1, 0, 8, 8), (2, 1, 1, 0, 0)]
    ok = ok and found[4:] == [(3, 0, 0, 16, 6), (3, 0, 1, 16, 6), (3, 1, 0, 16, 16), (3, 1, 1, 16, 16),
                          (4, 0, 0, 64, 24), (4, 0, 1, 64, 24), (4, 1, 0, 64, 64), (4, 1, 1, 64, 64)]
    GA.check("ad-isospin on one or two singlet planes beside a doublet: C = 3/4 on the doublet-odd part, C in {0, 2} "
             "on the doublet-even part; with no singlet plane no even doublet; the even doublets are A^(1,1), of dimension 16 and 64", ok)
    return ok


def check_bilinear_doublets_and_their_hypercharge():
    premise("synthesis.rung-field-is-odd-in-the-tower-and-its-modes-carry-no-even-doublet")
    ok = True
    sq = _squares(3)
    tp, tm, t3 = _iso(sq)
    y = GA.add(GA.scal(YD, GA.add(GA.mul(_v(0), _w(0), sq), GA.mul(_v(1), _w(1), sq))),
               GA.scal(YS, GA.mul(_v(2), _w(2), sq)))
    # the four bilinear doublets (upper component, lower component, expected hypercharge)
    cases = [(GA.mul(_v(0), _w(2), sq), GA.mul(_v(1), _w(2), sq), YD - YS),
             (GA.mul(_v(2), _w(1), sq), GA.neg(GA.mul(_v(2), _w(0), sq)), YS - YD),
             (GA.mul(_w(1), _w(2), sq), GA.neg(GA.mul(_w(0), _w(2), sq)), -YD - YS),
             (GA.mul(_v(2), _v(0), sq), GA.mul(_v(2), _v(1), sq), YD + YS)]
    for (up, dn, h) in cases:
        ok = ok and GA.is_zero(_comm(tp, up, sq)) and GA.eq(_comm(tm, up, sq), dn) and GA.eq(_comm(tp, dn, sq), up)
        ok = ok and GA.eq(_comm(t3, up, sq), GA.scal(F(1, 2), up)) and GA.eq(_comm(t3, dn, sq), GA.scal(F(-1, 2), dn))
        ok = ok and GA.eq(_comm(y, up, sq), GA.scal(h, up)) and GA.eq(_comm(y, dn, sq), GA.scal(h, dn))
    ok = ok and [h for (_, _, h) in cases] == [F(1, 2), F(-1, 2), F(1, 6), F(-1, 6)]
    GA.check("the doublet-singlet bilinears are even doublets; with Y_d - Y_s = 1/2 the hoppings carry +-1/2, the "
             "pairs -+(Y_d + Y_s)", ok)
    return ok


# ---------- (ii) window, exterior model ----------
KS = (-2, -1, 0, 1)
CH = 3                                  # channels 0 = up, 1 = down, 2 = s
WEIGHTS = (YD, YD, YS)


def _mode(k, a):
    return (k + 2) * CH + a


def _ann(i, st):
    return GA.ext_contract([F(1) if j == i else F(0) for j in range(len(KS) * CH)], st)


def _cre(i, st):
    return GA.ext_wedge(i, st)


def _acc(out, x, c):
    for k, v in x.items():
        out[k] = out.get(k, F(0)) + c * v


def _clean(x):
    return {k: v for k, v in x.items() if v != 0}


def _rho(q, M, st):
    """rho_q(M) = sum_{k, k+q} sum_{a, b} M_ab a*_{k,a} a_{k+q,b}."""
    out = {}
    for k in KS:
        if k + q not in KS:
            continue
        for a in range(CH):
            for b in range(CH):
                if M[a][b] != 0:
                    _acc(out, _cre(_mode(k, a), _ann(_mode(k + q, b), st)), M[a][b])
    return _clean(out)


def _rho_star(q, M, st):
    Ms = [[M[b][a] for b in range(CH)] for a in range(CH)]
    out = {}
    for k in KS:
        if k + q not in KS:
            continue
        for a in range(CH):
            for b in range(CH):
                if Ms[a][b] != 0:
                    _acc(out, _cre(_mode(k + q, a), _ann(_mode(k, b), st)), Ms[a][b])
    return _clean(out)


def _unit(a, b):
    return [[F(1) if (i, j) == (a, b) else F(0) for j in range(CH)] for i in range(CH)]


def _matmul(A, B):
    return [[sum(A[i][l] * B[l][j] for l in range(CH)) for j in range(CH)] for i in range(CH)]


def _ip(x, y):
    return sum(c * y.get(S, F(0)) for S, c in x.items())


def _sea():
    return {frozenset(_mode(k, a) for k in KS if k < 0 for a in range(CH)): F(1)}


def check_charged_pair_modes_are_quasi_spins():
    premise("synthesis.helicity-one-pair-modes-on-a-null-generator-are-quasi-spins")
    premise("tower.ladder-pairs-satisfy-car-vectors")
    ok = True
    W = [[WEIGHTS[i] if i == j else F(0) for j in range(CH)] for i in range(CH)]
    M = _unit(0, 2)
    Md = _unit(1, 2)
    WM = _matmul(W, M)
    MW = _matmul(M, W)
    ok = ok and all(WM[i][j] - MW[i][j] == F(1, 2) * M[i][j] for i in range(CH) for j in range(CH))
    ok = ok and all(x == 0 for r in _matmul(M, M) for x in r)
    # the same components are charged under the channel isospin weights (1/2, -1/2, 0), whatever the hypercharge
    W3 = [[F(1, 2), F(0), F(0)], [F(0), F(-1, 2), F(0)], [F(0), F(0), F(0)]]
    for (X, t) in ((M, F(1, 2)), (Md, F(-1, 2))):
        A, B = _matmul(W3, X), _matmul(X, W3)
        ok = ok and all(A[i][j] - B[i][j] == t * X[i][j] for i in range(CH) for j in range(CH))
    MMs = _matmul(M, [[M[j][i] for j in range(CH)] for i in range(CH)])
    MsM = _matmul([[M[j][i] for j in range(CH)] for i in range(CH)], M)
    ok = ok and MMs != MsM
    q = 1
    # edge-clean vectors at depth 1: k = -2 filled in every channel, k = 1 empty; one extra particle at k = -1
    base = frozenset(_mode(-2, a) for a in range(CH))
    vals = []
    for a in (0, 2):
        x = {base | {_mode(-1, a)}: F(1)}
        c = dict(_rho(q, M, _rho_star(q, M, x)))
        _acc(c, _rho_star(q, M, _rho(q, M, x)), F(-1))
        c = _clean(c)
        vals.append(_ip(x, c))
        ok = ok and GA.ext_state_eq(c, {S: vals[-1] * v for S, v in x.items()})
    ok = ok and vals == [q + 1, q - 1]
    # mutual commutator of the two components on the edge-clean vector with a bulk down particle: the raising density
    x = {base | {_mode(-1, 1)}: F(1)}
    c = dict(_rho(q, M, _rho_star(q, Md, x)))
    _acc(c, _rho_star(q, Md, _rho(q, M, x)), F(-1))
    ok = ok and GA.ext_state_eq(_clean(c), {base | {_mode(-1, 0)}: F(1)})
    # quasi-spin on the chiral sea: |B^p Omega|^2 = (p!)^2 C(q, p), B = rho_q(M)*, for q = 1, 2
    norms = []
    for qq in (1, 2):
        st = _sea()
        row = []
        for p in range(qq + 2):
            row.append(_ip(st, st))
            st = _rho_star(qq, M, st)
        norms.append(row)
        ok = ok and _rho(qq, M, _sea()) == {}
    ok = ok and norms == [[1, 1, 0], [1, 2, 4, 0]]
    # without M^2 = 0 the count fails: M2 = E_{up,s} + E_{s,down} has T_3 weight +1/2, M2^2 = E_{up,down} != 0,
    # and at q = 1 the norms 1, 2, 6, 18 exceed q rank(M2) = 2 quanta
    M2 = [[F(0), F(0), F(1)], [F(0), F(0), F(0)], [F(0), F(1), F(0)]]
    A2, B2 = _matmul(W3, M2), _matmul(M2, W3)
    ok = ok and all(A2[i][j] - B2[i][j] == F(1, 2) * M2[i][j] for i in range(CH) for j in range(CH))
    ok = ok and _matmul(M2, M2) == _unit(0, 1)
    st, row = _sea(), []
    for p in range(4):
        row.append(_ip(st, st))
        st = _rho_star(1, M2, st)
    ok = ok and row == [1, 2, 6, 18]
    GA.check("a doublet-singlet hopping of hypercharge 1/2 is nilpotent and not normal: commutator q +- 1 on two "
             "edge-clean vectors, quasi-spin norms 1, 1, 0 (q = 1) and 1, 2, 4, 0 (q = 2) on the sea", ok)
    return ok


if __name__ == "__main__":
    check_doublets_are_odd_in_the_doublet_modes()
    check_bilinear_doublets_and_their_hypercharge()
    check_charged_pair_modes_are_quasi_spins()

synthesis.face-mass-form-unit-plus-gram:
"""synthesis.face-mass-form-unit-plus-gram: exact checks.

Six bosonic modes p = (i, A), i in {0,1,2} (family), A in {0,1} (spinor slot). States are finite
combinations of unnormalised monomials (a^dag)^m |0>, with <m|m'> = delta_{m m'} prod_p m_p!, so
a_p (a^dag)^m|0> = m_p (a^dag)^{m - e_p}|0> and every amplitude stays rational (complex
rationals as pairs of Fractions). Theta_k[(i,A),(j,B)] = (1/2) eps_{kij} eps_{AB}, and
Omega_k = sum_{pq} Theta_k[p,q] a_p a_q, as in the skeleton theorem.
"""
from fractions import Fraction as F
from itertools import product
from tp_premise import premise
from GA import mul, gen, sig


def factorial(n):
    out = 1
    for j in range(2, n + 1):
        out *= j
    return out

MODES = [(i, A) for i in range(3) for A in range(2)]


CL3 = sig(3, 0)                          # Cl(3,0): e_k e_i e_j = eps_kij e_1 e_2 e_3 for distinct k, i, j


def eps3(k, i, j):
    """Levi-Civita symbol read off the Clifford product in Cl(3,0): the coefficient of the
    pseudoscalar in e_k e_i e_j when k, i, j are distinct, zero otherwise."""
    if len({k, i, j}) < 3:
        return 0
    prod = mul(mul(gen(k), gen(i), CL3), gen(j), CL3)
    return int(prod.get((0, 1, 2), 0))


def eps2(A, B):
    return 0 if A == B else (1 if (A, B) == (0, 1) else -1)


THETA = [[[F(1, 2) * eps3(k, p[0], q[0]) * eps2(p[1], q[1]) for q in MODES] for p in MODES] for k in range(3)]


# complex rationals
def cadd(x, y): return (x[0] + y[0], x[1] + y[1])
def cmul(x, y): return (x[0] * y[0] - x[1] * y[1], x[0] * y[1] + x[1] * y[0])
def cconj(x): return (x[0], -x[1])
Z = (F(0), F(0))


def sadd(s, m, c):
    s[m] = cadd(s.get(m, Z), c)
    if s[m] == Z:
        del s[m]


def ann(p, st):                          # a_p
    out = {}
    for m, c in st.items():
        if m[p]:
            mm = list(m); mm[p] -= 1
            sadd(out, tuple(mm), cmul((F(m[p]), F(0)), c))
    return out


def cre(p, st):                          # a_p^dag
    out = {}
    for m, c in st.items():
        mm = list(m); mm[p] += 1
        sadd(out, tuple(mm), c)
    return out


def lin(terms):                          # sum of (coefficient, state)
    out = {}
    for coef, st in terms:
        for m, c in st.items():
            sadd(out, m, cmul(coef, c))
    return out


def inner(s, t):                         # <s|t>
    tot = Z
    for m, c in s.items():
        if m in t:
            w = 1
            for x in m:
                w *= factorial(x)
            tot = cadd(tot, cmul(cconj(c), cmul((F(w), F(0)), t[m])))
    return tot


def omega(k, st):
    return lin([((THETA[k][p][q], F(0)), ann(p, ann(q, st))) for p in range(6) for q in range(6) if THETA[k][p][q]])


def omega_dag(k, st):
    return lin([((THETA[k][p][q], F(0)), cre(q, cre(p, st))) for p in range(6) for q in range(6) if THETA[k][p][q]])


def theta_a(k, st):                      # the 6-vector of operators (Theta_k a)_p applied to st
    return [lin([((THETA[k][p][q], F(0)), ann(q, st)) for q in range(6) if THETA[k][p][q]]) for p in range(6)]


def states():
    vac = tuple([0] * 6)
    def mono(*m): return tuple(m)
    yield {vac: (F(1), F(0))}
    yield {vac: (F(1), F(0)), mono(1, 0, 0, 1, 0, 0): (F(2), F(-1)), mono(0, 1, 1, 0, 0, 0): (F(0), F(3, 2))}
    yield {mono(1, 0, 0, 0, 0, 0): (F(1), F(1)), mono(0, 0, 1, 1, 1, 0): (F(-2, 3), F(0)),
           mono(2, 1, 0, 0, 0, 1): (F(1, 5), F(-1, 7)), mono(0, 0, 0, 0, 2, 0): (F(4), F(1))}
    yield {mono(1, 1, 1, 1, 0, 0): (F(1), F(0)), mono(0, 0, 1, 1, 1, 1): (F(-1), F(2)),
           mono(1, 0, 0, 0, 0, 1): (F(3, 4), F(0)), vac: (F(0), F(-5, 2)), mono(0, 2, 0, 1, 0, 0): (F(1), F(1))}


def check_theta_normalisation():
    premise("families.skeleton-rank-one-plus-ordering-shift")
    for k in range(3):
        for l in range(3):
            t = sum(THETA[k][p][q] * THETA[l][q][p] for p in range(6) for q in range(6))
            assert t == (1 if k == l else 0)
            for p in range(6):
                for q in range(6):
                    assert THETA[k][p][q] == THETA[k][q][p]


def check_unit_plus_gram():
    """For every state psi: H_kl = (1/2)<Omega_k^dag Omega_l + Omega_l Omega_k^dag>
    equals <psi|psi> delta_kl + <Omega_k psi, Omega_l psi> + 2 sum_p <(Theta_k a)_p psi, (Theta_l a)_p psi>."""
    premise("families.skeleton-rank-one-plus-ordering-shift")
    premise("families.imported-squeezed-vacuum-bosonic-pairing")
    for psi in states():
        n2 = inner(psi, psi)
        Om = [omega(k, psi) for k in range(3)]
        Od = [omega_dag(k, psi) for k in range(3)]
        Ta = [theta_a(k, psi) for k in range(3)]
        for k in range(3):
            for l in range(3):
                H = cmul((F(1, 2), F(0)), cadd(inner(Om[k], Om[l]), inner(Od[l], Od[k])))
                G = inner(Om[k], Om[l])
                for p in range(6):
                    G = cadd(G, cmul((F(2), F(0)), inner(Ta[k][p], Ta[l][p])))
                rhs = cadd(G, n2 if k == l else Z)
                assert H == rhs, (k, l)


EXPORTS = {}

synthesis.field-level-brst-differential-:
"""The field-level BRST differential of the gauge fields of the minimal massive composite: exact checks.

Fields at a point and all their derivatives (the jet algebra): A^a_mu, B^a even, ghosts c^a and antighosts cb^a odd,
the odd ones generators of a Grassmann algebra (the degenerate Clifford algebra, every generator of square 0, in
GA's blade engine); the coupling g and the gauge parameter xi formal even constants. The gauge algebra
su(2) + su(3) + u(1) of the minimal massive composite is realised, up to isomorphism, by bivectors of Cl(9,0): T_1..T_3 = (1/2) e_ij in Cl(3,0) on e_0, e_1, e_2; the eight
traceless bivectors of so(6) on e_3..e_8 commuting with J = e_34 + e_56 + e_78; T_12 = J/2; [T_a, T_b] = f_ab^c T_c.
s A^a_mu = d_mu c^a + g f_bc^a A^b_mu c^c, s c^a = -(g/2) f_bc^a c^b c^c, s cb^a = B^a, s B^a = 0, s(x_J) = d_J(s x),
s an odd derivation acting from the left. A^a = A^a_mu g^mu is a GA vector field (signature +,-,-,-),
nabla = g^mu d_mu, F^a = nabla^A^a + (g/2) f_bc^a A^b^A^c a bivector field.
(1) The bivectors close into su(2) + su(3) + u(1): 12 independent generators, 58 nonzero f; the Cl(3,0) block and
    the 8-block are ideals, J spans the centre, the derived algebra has dimension 11, kappa_ab = -<T_a T_b>_0 is positive
    definite and ad-invariant, the 8-block's adjoint commutant is one-dimensional (simple, so su(3)).
(2) s^2 = 0 on every generator with at most one derivative (300 generators), as a polynomial identity in g.
(3) Without the term g[A, c] in s A, with s c = -g f c c (no 1/2), or with one antisymmetric pair of structure
    constants perturbed (Jacobi broken), s^2 != 0.
(4) s F^a = g f_bc^a F^b c^c for all twelve a; a non-invariant kappa fails ad-invariance.
(5) On the su(2) + u(1) block: s <kappa F F>_0 = 0 and s <kappa F F>_4 = 0; a non-invariant kappa gives s <F F>_0 != 0.
(6) Psi = kappa_ab cb^a (nabla.A^b + (xi/2) B^b): s Psi = kappa_ab (B^a nabla.A^b + (xi/2) B^a B^b - cb^a nabla.(D c)^b)
    with (D c)^b = nabla c^b + g f_cd^b A^c c^d, and s(s Psi) = 0, for the full algebra.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise


class _Zero(object):
    def __getitem__(self, k):
        return F(0)


ZSQ = _Zero()          # Grassmann generators: degenerate Clifford generators of square 0
G4 = (1, -1, -1, -1)   # spacetime signature of the store

# ---------------------------------------------------------------- the gauge algebra as bivectors
E9 = GA.sig(9, 0)


def _bv(i, j):
    return GA.mul(GA.gen(i), GA.gen(j), E9)


def _comm(x, y):
    return GA.sub(GA.mul(x, y, E9), GA.mul(y, x, E9))


def gauge_bivectors():
    half = lambda x: GA.scal(F(1, 2), x)
    su2 = [half(_bv(1, 2)), half(_bv(2, 0)), half(_bv(0, 1))]
    J = GA.add(_bv(3, 4), _bv(5, 6), _bv(7, 8))
    so6 = [_bv(i, j) for i in range(3, 9) for j in range(i + 1, 9)]
    # commutant of J in so(6): kernel of B -> [B, J]
    rows = sorted({b for x in so6 for b in _comm(x, J)})
    M = [[_comm(x, J).get(r, F(0)) for x in so6] for r in rows]
    ker = GA.field_kernel(M) if rows else None
    u3 = [GA.add(*[GA.scal(v[i], so6[i]) for i in range(len(so6)) if v[i] != 0]) for v in ker]
    # traceless part: orthogonal to J for <X Y>_0
    ip = lambda x, y: GA.mul(x, y, E9).get((), F(0))
    jj = ip(J, J)
    su3 = []
    for x in u3:
        y = GA.sub(x, GA.scal(ip(x, J) / jj, J))
        if not GA.is_zero(y):
            su3.append(y)
    # independent 8
    basis = []
    for y in su3:
        trial = basis + [y]
        keys = sorted({b for z in trial for b in z})
        if GA.field_rank([[z.get(k, F(0)) for k in keys] for z in trial]) == len(trial):
            basis.append(y)
    return su2 + basis + [half(J)]


def structure_constants(gens):
    keys = sorted({b for z in gens for b in z})
    n = len(gens)
    fs = {}
    for a in range(n):
        for b in range(n):
            cm = _comm(gens[a], gens[b])
            if GA.is_zero(cm):
                continue
            ks = sorted(set(keys) | set(cm))
            M = [[gens[c].get(k, F(0)) for c in range(n)] for k in ks]
            rhs = [cm.get(k, F(0)) for k in ks]
            ker = GA.field_kernel([M[i] + [rhs[i]] for i in range(len(ks))])
            pick = [v for v in ker if v[n] != 0]
            if len(pick) != 1:
                raise ValueError("commutator leaves the span")
            sol = [-x / pick[0][n] for x in pick[0][:n]]
            for c in range(n):
                if sol[c] != 0:
                    fs[(a, b, c)] = sol[c]
    return fs


# ---------------------------------------------------------------- superpolynomials on jets
_ODD = {}
_ODDK = []


def oid(key):
    if key not in _ODD:
        _ODD[key] = len(_ODDK)
        _ODDK.append(key)
    return _ODD[key]


def _odd_sort(lst):
    return GA.blade_mul(tuple(lst), (), ZSQ) if lst else (F(1), ())


def P_even(key):
    return {((key,), ()): F(1)}


def P_odd(key):
    return {((), (oid(key),)): F(1)}


def P_const(c):
    return {((), ()): F(c)} if c != 0 else {}


def padd(*ps):
    out = {}
    for p in ps:
        for k, v in p.items():
            out[k] = out.get(k, F(0)) + v
    return {k: v for k, v in out.items() if v != 0}


def psc(c, p):
    c = F(c)
    return {k: c * v for k, v in p.items()} if c != 0 else {}


def pmul(p, q):
    out = {}
    for (e1, o1), v1 in p.items():
        for (e2, o2), v2 in q.items():
            s, o = GA.blade_mul(o1, o2, ZSQ)
            if s == 0:
                continue
            e = tuple(sorted(e1 + e2))
            k = (e, o)
            out[k] = out.get(k, F(0)) + s * v1 * v2
    return {k: v for k, v in out.items() if v != 0}


def _shift(key, mu):
    J = list(key[-1])
    J[mu] += 1
    return key[:-1] + (tuple(J),)


def _is_jet(key):
    return key[0] in ('A', 'B', 'c', 'cb')


def D(mu, p):
    """Total derivative d_mu (even derivation; the coupling and gauge parameters are constants)."""
    out = {}
    for (e, o), v in p.items():
        for i, x in enumerate(e):
            if not _is_jet(x):
                continue
            e2 = tuple(sorted(e[:i] + e[i + 1:] + (_shift(x, mu),)))
            out[(e2, o)] = out.get((e2, o), F(0)) + v
        for j, y in enumerate(o):
            lst = list(o)
            lst[j] = oid(_shift(_ODDK[y], mu))
            s, o2 = _odd_sort(lst)
            if s == 0:
                continue
            out[(e, o2)] = out.get((e, o2), F(0)) + s * v
    return {k: v for k, v in out.items() if v != 0}


def DJ(J, p):
    for mu in range(4):
        for _ in range(J[mu]):
            p = D(mu, p)
    return p


Z4 = (0, 0, 0, 0)


def unit(mu):
    return tuple(1 if i == mu else 0 for i in range(4))


class BRST(object):
    """s on generators: s A^a_mu = d_mu c^a + g f_bc^a A^b_mu c^c, s c^a = -(g/2) f_bc^a c^b c^c,
    s cb^a = B^a, s B^a = 0; s(x_J) = d_J (s x); s an odd derivation from the left."""

    def __init__(self, fs, n, half=F(1, 2), cov=True):
        self.fs, self.n, self.half, self.cov = fs, n, half, cov
        self.memo = {}
        self.g = P_even(('g',))

    def gen(self, key):
        if key in self.memo:
            return self.memo[key]
        kind, J = key[0], key[-1]
        if J != Z4:
            base = list(key[:-1]) + [Z4]
            r = DJ(J, self.gen(tuple(base)))
        elif kind == 'A':
            a, mu = key[1], key[2]
            r = D(mu, P_odd(('c', a, Z4)))
            if self.cov:
                for (b, c, aa), v in self.fs.items():
                    if aa == a:
                        r = padd(r, psc(v, pmul(self.g, pmul(P_even(('A', b, mu, Z4)), P_odd(('c', c, Z4))))))
        elif kind == 'c':
            a = key[1]
            r = {}
            for (b, c, aa), v in self.fs.items():
                if aa == a:
                    r = padd(r, psc(-self.half * v, pmul(self.g, pmul(P_odd(('c', b, Z4)), P_odd(('c', c, Z4))))))
        elif kind == 'cb':
            r = P_even(('B', key[1], Z4))
        else:
            r = {}
        self.memo[key] = r
        return r

    def __call__(self, p):
        out = {}
        for (e, o), v in p.items():
            evenpart = {(e, ()): F(1)}
            for i, x in enumerate(e):
                if not _is_jet(x):
                    continue
                rest = {(e[:i] + e[i + 1:], o): v}
                out = padd(out, pmul(self.gen(x), rest))
            for j, y in enumerate(o):
                sign = (-1) ** j
                left = {(e, o[:j]): v * sign}
                right = {((), o[j + 1:]): F(1)}
                out = padd(out, pmul(pmul(left, self.gen(_ODDK[y])), right))
        return out


def jets(order):
    out = [Z4]
    if order >= 1:
        out += [unit(m) for m in range(4)]
    if order >= 2:
        for m in range(4):
            for n in range(m, 4):
                J = [0] * 4
                J[m] += 1
                J[n] += 1
                out.append(tuple(J))
    return out


def s2_zero_on_generators(s, n, order):
    for J in jets(order):
        for a in range(n):
            for mu in range(4):
                if s(s.gen(('A', a, mu, J))):
                    return False
            if s(s.gen(('c', a, J))):
                return False
    return True


# ---------------------------------------------------------------- GA multivectors with polynomial coefficients
def mv_mul(X, Y):
    out = {}
    for b1, p in X.items():
        for b2, q in Y.items():
            sg, b = GA.blade_mul(b1, b2, G4)
            if sg == 0:
                continue
            out[b] = padd(out.get(b, {}), psc(sg, pmul(p, q)))
    return {b: p for b, p in out.items() if p}


def grade(X, r):
    return {b: p for b, p in X.items() if len(b) == r}


def mv_add(*Xs):
    out = {}
    for X in Xs:
        for b, p in X.items():
            out[b] = padd(out.get(b, {}), p)
    return {b: p for b, p in out.items() if p}


def mv_sc(c, X):
    return {b: psc(c, p) for b, p in X.items() if c != 0}


def mv_s(s, X):
    return {b: q for b, q in ((b, s(p)) for b, p in X.items()) if q}


def vecfield(a):
    # A^a = A^a_mu g^mu, g^mu = g^{mu mu} g_mu
    return {(mu,): psc(G4[mu], P_even(('A', a, mu, Z4))) for mu in range(4)}


def nabla(X):
    out = {}
    for mu in range(4):
        dX = {b: D(mu, p) for b, p in X.items()}
        out = mv_add(out, mv_mul({(mu,): P_const(G4[mu])}, dX))
    return out


def field_strength(fs, n, a):
    Fa = grade(nabla(vecfield(a)), 2)
    g = P_even(('g',))
    for (b, c, aa), v in fs.items():
        if aa == a:
            Fa = mv_add(Fa, mv_sc(F(1, 2) * v, mv_mul({(): g}, grade(mv_mul(vecfield(b), vecfield(c)), 2))))
    return Fa




# ---------------------------------------------------------------- cached data
_CACHE = {}


def _algebra():
    if 'g' not in _CACHE:
        gens = gauge_bivectors()
        _CACHE['g'] = gens
        _CACHE['f'] = structure_constants(gens)
    return _CACHE['g'], _CACHE['f']


def _ip(x, y):
    return GA.mul(x, y, E9).get((), F(0))


def _kappa(gens):
    return [[-_ip(x, y) for y in gens] for x in gens]


def _ad_invariant(fs, kap, n):
    # kappa([T_a, T_b], T_c) + kappa(T_b, [T_a, T_c]) = 0
    for a in range(n):
        for b in range(n):
            for c in range(n):
                v = sum((fs.get((a, b, d), F(0)) * kap[d][c] + fs.get((a, c, d), F(0)) * kap[b][d]
                         for d in range(n)), F(0))
                if v != 0:
                    return False
    return True


def _closed(fs, idx):
    return all(c in idx for (a, b, c) in fs if a in idx and b in idx)


def check_gauge_algebra_as_bivectors():
    premise("standard-model.gauge-algebra-minimal-massive-composite")
    gens, fs = _algebra()
    n = len(gens)
    ok = n == 12 and len(fs) == 58
    keys = sorted({b for z in gens for b in z})
    ok = ok and GA.field_rank([[z.get(k, F(0)) for k in keys] for z in gens]) == 12
    ok = ok and all(len(b) == 2 for z in gens for b in z)
    s2, s3 = set(range(0, 3)), set(range(3, 11))
    ok = ok and _closed(fs, s2) and _closed(fs, s3)
    ok = ok and not any((a, b, c) for (a, b, c) in fs if (a in s2 and b in s3) or (a in s3 and b in s2))
    # centre: kernel of x -> [x, T_b] for all b
    rows = [[fs.get((a, b, c), F(0)) for a in range(n)] for b in range(n) for c in range(n)]
    ok = ok and len(GA.field_kernel(rows)) == 1 and not any(k[0] == 11 or k[1] == 11 for k in fs)
    # derived algebra [g, g] has dimension 11
    ok = ok and GA.field_rank([[fs.get((a, b, c), F(0)) for c in range(n)]
                               for a in range(n) for b in range(n)]) == 11
    kap = _kappa(gens)
    ok = ok and GA.congruence_signature(kap) == (12, 0, 0) and _ad_invariant(fs, kap, n)
    # Schur: the commutant of ad(su(3)) in gl(8) is one-dimensional, so the 8-block is simple
    idx = sorted(s3)
    ad = [[[fs.get((a, b, c), F(0)) for b in idx] for c in idx] for a in idx]
    eqs = []
    for A in ad:
        for i in range(8):
            for j in range(8):
                row = [F(0)] * 64
                for k in range(8):
                    row[i * 8 + k] += A[k][j]
                    row[k * 8 + j] -= A[i][k]
                eqs.append(row)
    ok = ok and len(GA.field_kernel(eqs)) == 1
    GA.check("bivectors of Cl(9,0) realise su(2) + su(3) + u(1): 12 generators, 58 structure constants, centre J,"
             " derived algebra of dimension 11, invariant positive kappa, simple 8-block", ok)
    return ok


def check_brst_differential_is_nilpotent():
    premise("standard-model.gauge-algebra-minimal-massive-composite")
    premise("synthesis.imported-brst-kugo-ojima-strocchi-and-gribov")
    gens, fs = _algebra()
    n = len(gens)
    s = BRST(fs, n)
    count = 0
    ok = True
    for J in jets(1):
        for a in range(n):
            for mu in range(4):
                ok = ok and not s(s.gen(('A', a, mu, J)))
                count += 1
            ok = ok and not s(s.gen(('c', a, J)))
            ok = ok and not s(s.gen(('cb', a, J))) and s.gen(('cb', a, J)) == P_even(('B', a, J))
            count += 1
    # the differential is not trivial: s A carries the ghost's covariant derivative
    ok = ok and len(s.gen(('A', 3, 2, Z4))) == 1 + len([k for k in fs if k[2] == 3])
    ok = ok and count == 300
    GA.check("s^2 = 0 on all 300 generators A^a_mu, c^a with at most one derivative, for every g", ok)
    return ok


def _cov_der(fs, mu, a, Y):
    """(D_mu Y)^a = d_mu Y^a + g f_bc^a A^b_mu Y^c for a Lie-algebra-valued polynomial Y."""
    out = D(mu, Y[a])
    g = P_even(('g',))
    for (b, c, aa), v in fs.items():
        if aa == a:
            out = padd(out, psc(v, pmul(g, pmul(P_even(('A', b, mu, Z4)), Y[c]))))
    return out


def _bad_count(s, n):
    k = 0
    for a in range(n):
        for mu in range(4):
            k += 1 if s(s.gen(('A', a, mu, Z4))) else 0
        k += 1 if s(s.gen(('c', a, Z4))) else 0
    return k


def check_nilpotency_needs_jacobi_the_half_and_the_covariant_term():
    premise("standard-model.gauge-algebra-minimal-massive-composite")
    gens, fs = _algebra()
    n = len(gens)
    good = BRST(fs, n)
    Y = [good.gen(('c', a, Z4)) for a in range(n)]
    ok = _bad_count(good, n) == 0
    # s c = -2 g f c c / 2 (factor 2 instead of 1/2): s^2 A = 3 D Y, Y = s c with the factor 1/2; s^2 c = 0
    s2 = BRST(fs, n, half=F(2))
    for a in range(n):
        ok = ok and not s2(s2.gen(('c', a, Z4)))
        for mu in range(4):
            ok = ok and s2(s2.gen(('A', a, mu, Z4))) == psc(3, _cov_der(fs, mu, a, Y))
    # without the covariant term: s^2 A^a_mu = d_mu (s c^a), nonzero on the 11 non-abelian generators
    s0 = BRST(fs, n, cov=False)
    for a in range(n):
        for mu in range(4):
            ok = ok and s0(s0.gen(('A', a, mu, Z4))) == D(mu, Y[a])
    ok = ok and _bad_count(s0, n) == 44
    # Jacobi broken: one antisymmetric pair of su(3) structure constants shifted
    key = sorted(k for k in fs if 3 <= k[0] < 11 and 3 <= k[1] < 11)[0]
    bad = dict(fs)
    a, b, c = key
    bad[(a, b, c)] = bad[(a, b, c)] + 1
    bad[(b, a, c)] = bad.get((b, a, c), F(0)) - 1
    ok = ok and key == (3, 4, 5) and _bad_count(BRST(bad, n), n) == 30
    GA.check("s^2 = 3 D(s c) with the factor 2 for 1/2, s^2 A = d(s c) without g[A, c] (44 generators), Jacobi broken"
             " gives 30 failing generators; s^2 = 0 as stated", ok)
    return ok


def check_field_strength_is_covariant():
    premise("standard-model.gauge-algebra-minimal-massive-composite")
    gens, fs = _algebra()
    n = len(gens)
    s = BRST(fs, n)
    g = P_even(('g',))
    Fs = [field_strength(fs, n, a) for a in range(n)]
    ok = all(set(len(b) for b in X) == {2} for X in Fs)
    ok = ok and sum(len(X) for X in Fs) == 72 and sum(len(q) for X in Fs for q in X.values()) == 492
    for a in range(n):
        rhs = {}
        for (b, c, aa), v in fs.items():
            if aa == a:
                rhs = mv_add(rhs, mv_sc(v, mv_mul(Fs[b], {(): pmul(g, P_odd(('c', c, Z4)))})))
        ok = ok and not mv_add(mv_s(s, Fs[a]), mv_sc(-1, rhs))
    kap = _kappa(gens)
    bad = [r[:] for r in kap]
    bad[0][0] = bad[0][0] + 1
    ok = ok and _ad_invariant(fs, kap, n) and not _ad_invariant(fs, bad, n)
    ok = ok and kap[0][0] == F(1, 4) and kap[3][3] == F(2, 3) and kap[11][11] == F(3, 4)
    GA.check("s F^a = g f_bc^a F^b c^c for the bivector field strength; kappa ad-invariant, a perturbed one not", ok)
    return ok


def check_yang_mills_density_is_invariant_on_the_weak_block():
    premise("standard-model.gauge-algebra-minimal-massive-composite")
    gens, fs = _algebra()
    sub = [0, 1, 2, 11]
    m = len(sub)
    fsub = {(sub.index(a), sub.index(b), sub.index(c)): v for (a, b, c), v in fs.items()
            if a in sub and b in sub and c in sub}
    s = BRST(fsub, m)
    Fs = [field_strength(fsub, m, a) for a in range(m)]
    kap = [[-_ip(gens[i], gens[j]) for j in sub] for i in sub]

    def dens(kp, r, blade):
        out = {}
        for i in range(m):
            for j in range(m):
                if kp[i][j]:
                    out = padd(out, psc(kp[i][j], grade(mv_mul(Fs[i], Fs[j]), r).get(blade, {})))
        return out
    L0 = dens(kap, 0, ())
    L4 = dens(kap, 4, (0, 1, 2, 3))
    ok = len(fsub) == 6 and bool(L0) and bool(L4) and not s(L0) and not s(L4)
    bad = [r[:] for r in kap]
    bad[0][0] = bad[0][0] + 1
    ok = ok and bool(s(dens(bad, 0, ())))
    GA.check("on su(2) + u(1): s <kappa F F>_0 = 0 and s <kappa F F>_4 = 0; a non-invariant kappa breaks it", ok)
    return ok


def check_gauge_fixing_term_is_exact_with_the_faddeev_popov_operator():
    premise("standard-model.gauge-algebra-minimal-massive-composite")
    premise("synthesis.imported-brst-kugo-ojima-strocchi-and-gribov")
    gens, fs = _algebra()
    n = len(gens)
    s = BRST(fs, n)
    kap = _kappa(gens)
    g = P_even(('g',))
    xi = P_even(('xi',))

    def div(vec):
        # nabla . V for V = sum_mu V_mu g^mu given lower components V_mu
        return padd(*[psc(G4[mu], D(mu, vec[mu])) for mu in range(4)])
    Psi, expect = {}, {}
    for a in range(n):
        for b in range(n):
            if kap[a][b] == 0:
                continue
            divA = div([P_even(('A', b, mu, Z4)) for mu in range(4)])
            Psi = padd(Psi, psc(kap[a][b], pmul(P_odd(('cb', a, Z4)),
                                                padd(divA, pmul(psc(F(1, 2), xi), P_even(('B', b, Z4)))))))
            Dc = []
            for mu in range(4):
                t = D(mu, P_odd(('c', b, Z4)))
                for (c, d, bb), v in fs.items():
                    if bb == b:
                        t = padd(t, psc(v, pmul(g, pmul(P_even(('A', c, mu, Z4)), P_odd(('c', d, Z4))))))
                Dc.append(t)
            e = padd(pmul(P_even(('B', a, Z4)), divA),
                     pmul(psc(F(1, 2), xi), pmul(P_even(('B', a, Z4)), P_even(('B', b, Z4)))),
                     psc(-1, pmul(P_odd(('cb', a, Z4)), div(Dc))))
            expect = padd(expect, psc(kap[a][b], e))
    sPsi = s(Psi)
    ok = bool(sPsi) and not padd(sPsi, psc(-1, expect)) and not s(sPsi)
    ok = ok and len([k for k in sPsi if len(k[1]) == 2]) > 0 and n == 12
    GA.check("s Psi = kappa(B, nabla.A) + (xi/2) kappa(B, B) - kappa(cb, nabla.(D c)) and s(s Psi) = 0", ok)
    return ok


if __name__ == "__main__":
    check_gauge_algebra_as_bivectors()
    check_brst_differential_is_nilpotent()
    check_nilpotency_needs_jacobi_the_half_and_the_covariant_term()
    check_field_strength_is_covariant()
    check_yang_mills_density_is_invariant_on_the_weak_block()
    check_gauge_fixing_term_is_exact_with_the_faddeev_popov_operator()

synthesis.field-level-brst-of-the-two-do:
