def class_orbits_of_bivector_turns(m):
    full = (1 << (2 * m)) - 1
    pairs = [x for x in range(1, full + 1) if wt(x) == 2]
    reps = {min(x, x ^ full) for x in range(1, full) if wt(x) % 2 == 0}
    seen = set()
    sizes = []
    for c in sorted(reps):
        if c in seen:
            continue
        comp = {c}
        todo = [c]
        while todo:
            x = todo.pop()
            for w in pairs:
                y = x ^ w if bform(x, w) else x
                y = min(y, y ^ full)
                if y not in comp:
                    comp.add(y)
                    todo.append(y)
        seen |= comp
        sizes.append(len(comp))
    return sorted(sizes)


