    ok_id = True
    for dv in (1, 2, 3):
        for dw in (1, 2, 3):
            lhs = _ext_weights(dv, dw, 2)
            rhs = _add(_tensor(_sym_weights(dv, 2), _alt_weights(dw, 2)),
