def data(lam):
    I = GA.add(NI, GA.scal(lam / 6, N0))
    V = GA.sub(N0, GA.scal(Fr(3) / lam, I))
    return I, N0, V


def eps_gram(lam):
    I, X, V = data(lam)
    IV = wedge(I, V, 1, 1)
    return [[-sc(mul(wedge(wedge(a, b, 2, 2), IV, 4, 2), I6)) for b in L2W] for a in L2W]


EPS = {}
for _p in permutations(range(4)):
    _s = 1
    for _i in range(4):
        for _j in range(_i + 1, 4):
