def matmul(A, B):
    m, p = len(B), len(B[0])
    return [[sum((A[i][k] * B[k][j] for k in range(m) if A[i][k] and B[k][j]), Fr(0))
             for j in range(p)] for i in range(len(A))]


def tr(A):
    return [list(r) for r in zip(*A)]


def inverse(M):
    n = len(M)
    A = [list(M[i]) + [Fr(1) if i == j else Fr(0) for j in range(n)] for i in range(n)]
    for c in range(n):
        p = next(r for r in range(c, n) if A[r][c] != 0)
        A[c], A[p] = A[p], A[c]
        pv = A[c][c]
        A[c] = [x / pv for x in A[c]]
        for r in range(n):
            if r != c and A[r][c] != 0:
                f = A[r][c]
                A[r] = [x - f * y for x, y in zip(A[r], A[c])]
    return [row[n:] for row in A]


def nullspace(rows, n):
    piv = {}
    for r in rows:
        r = list(r)
        for c, pr in piv.items():
            if r[c] != 0:
                f = r[c]
                r = [a - f * b for a, b in zip(r, pr)]
        c0 = next((c for c in range(n) if r[c] != 0), None)
        if c0 is None:
            continue
        pv = r[c0]
        r = [a / pv for a in r]
        for c, pr in list(piv.items()):
            if pr[c0] != 0:
                f = pr[c0]
                piv[c] = [a - f * b for a, b in zip(pr, r)]
        piv[c0] = r
    out = []
    for fc in [c for c in range(n) if c not in piv]:
        x = [Fr(0)] * n
        x[fc] = Fr(1)
        for c, pr in piv.items():
            x[c] = -pr[fc]
        out.append(x)
    return out


def rd_of(x):
    Rd = {(r, r): {} for r in range(4)}
    for k, (r, s) in enumerate(PAIRS):
        b = fromL(x[6 * k:6 * k + 6])
        Rd[(r, s)] = b
        Rd[(s, r)] = GA.neg(b)
