    Ric = ricci(x)
    R = sum(Ric[k][k] for k in range(4))
    tf = [[Ric[k][m] - (R / 4 if k == m else 0) for m in range(4)] for k in range(4)]
    r2 = sum(tf[k][m] * tf[m][k] for k in range(4) for m in range(4))
    return [w2, wd, r2, R * R], R


def svec(M):
