def _deg(x):
    return max((len(b) for b in x), default=0)


def _wedge(*xs):
    out = xs[0]
    g = _deg(out)
    for y in xs[1:]:
        g += _deg(y)
        out = _grade(_m(out, y), g)
    return out


def _cp(x, y):
