def _sign(p):
    s = 1
    for i in range(len(p)):
        for j in range(i + 1, len(p)):
            if p[i] > p[j]:
                s = -s
    return s


def _form(Fc, Gc, pair):
    tot = Fr(0)
    for p in permutations(range(4)):
        tot += _sign(p) * pair(Fc(p[0], p[1]), Gc(p[2], p[3]))
