    def Fc(p, q):
        if p == q:
            return {}
        if p > q:
            return GA.neg(Fc(q, p))
        out = {}
        for k, bl in enumerate(_BLADES6):
            c = T[4 * p + q][k]
            if c:
                out = GA.add(out, GA.scal(Fr(c), _wedge(E[bl[0]], E[bl[1]])))
        return out
    return Fc


def _on(Fc, B):
