            # g^mu p_mu with g^mu = sum_a Hi[mu][a] gamma^a, gamma^a = S[a] gamma_a
            gp = [lseries(pscal(S[a], padd(*[pmul(pat1(Hi[mu][a]), p[mu]) for mu in range(4)])))
                  for a in range(4)]
            ok &= gp == v
