        for s, (A, B) in zip(signs, CONJ_PAIRS):
            Vp += component(A if s == 0 else B)
        ch = [charges(S) for S in Vp]
        tr = sum(y for *_, y in ch)
        traces[signs] = tr
        anomalies = (tr, sum(y ** 3 for *_, y in ch), sum(y * t3 * t3 for t3, _, _, y in ch),
                     sum(y * h3 * h3 for _, h3, _, y in ch))
        if tr == 0:
            zero.append(signs)
        if all(a == 0 for a in anomalies):
            free.append(signs)
    ok = ok and set(traces.values()) == {-6, -4, -2, 0, 2, 4, 6}
    ok = ok and len(zero) == 8 and len(traces) - len(zero) == 24
    ok = ok and len(free) == 2 and all(f in zero for f in free)
    # the constant L tr_C Y of the reversal is the difference of the seas' hypercharges (L / 2) tr Y
    L = 2
    for signs, tr in traces.items():
        for i, (A, B) in enumerate(CONJ_PAIRS):
            other = tuple(1 - s if j == i else s for j, s in enumerate(signs))
            Cc = A if signs[i] == 0 else B
            ok = ok and F(L, 2) * tr - F(L, 2) * traces[other] == L * dimy[Cc]
    # (b) on a window L = 2 with the channels of V_{1,0} and V_{2,0}: the sea's hypercharge and the Y-N central term
    chans = component((1, 0)) + component((2, 0))
    n = len(chans)
    sq, pos = window(n, L)
    J = GA.mul(GA.gen(0), GA.gen(1), sq)
    MY = induced(gauge_generators(sq)[11], chans, chans, sq)
    one = {(x, x): GA.sc(1) for x in range(n)}
    sea = GA.sc(1)
    for x in range(n):
        sea = GA.mul(sea, GA.mul(cr(pos, (x, 0)), an(pos, (x, 0)), sq), sq)
        sea = GA.mul(sea, GA.mul(an(pos, (x, 1)), cr(pos, (x, 1)), sq), sq)
    trY = sum(hyper(S) for S in chans)
    ok = ok and n == 3 and trY == 2
    charge = GA.mul(rho(0, MY, pos, L, sq), sea, sq)
    ok = ok and GA.eq(charge, GA.mul(GA.scal(F(L, 2) * trY, J), sea, sq))
    r1 = rho(1, MY, pos, L, sq)
    r1n = adjoint(rho(1, one, pos, L, sq), sq)
    mixed = GA.sub(GA.mul(r1, r1n, sq), GA.mul(r1n, r1, sq))
    ok = ok and GA.eq(GA.mul(mixed, sea, sq), GA.mul(GA.scal(trY, J), sea, sq))
    ok = ok and not GA.is_zero(GA.mul(mixed, sea, sq))
    GA.check("tr Y: values 0, +-2, +-4, +-6, zero on 8 of 32, the 2 anomaly-free among them; sea charge and Y-N term", ok)
    return ok


if __name__ == "__main__":
    for fn in (check_partner_blocks_are_minus_transposes,
               check_particle_hole_reversal_intertwines_window_currents,
               check_trace_form_is_halving_independent_and_anomalies_are_not,
               check_abelian_level_depends_on_the_scale_of_y,
               check_hypercharge_constant_is_the_linear_anomaly_coefficient):
        fn()

synthesis.loc-independent-of-clausius-an:
"""synthesis.loc-independent-of-clausius-and-killing-data: exact checks.

A model of every premise except (Loc): the local-horizon entropy density 1/4 (1 + c S_ab S^ab), S the
tracefree Ricci tensor. Curvatures are computed from the metrics with exact truncated Taylor jets.
(1) On Schwarzschild-de Sitter and de Sitter (Lambda-vacuum) S = 0, so the density is 1/4: every Killing-horizon
datum is the general-relativistic one. (2) The Einstein static universe with dust, metric
-dt^2 + 4a^2 |dx|^2/(1 + |x|^2)^2: Ric(e_t, e_t) = 0, Ric(e_i, e_j) = (2/a^2) delta_ij, S_ab S^ab = 3/a^4 at two
points; for several rational null k the Clausius defect T(k,k) - (eta/2 pi) Ric(k,k) of the stored theorem
vanishes with eta = 1/4 (1 + 3c/a^4) and 8 pi rho = 2(1 + 3c/a^4)/a^2; the dust is conserved (Gamma^b_tt = 0,
Gamma^a_at = 0) and the integration constant is Lambda_J = 1/a^2. (3) eta differs between the two spacetimes,
so it depends on the curvature at the point. pi is carried as a formal factor (mu = 8 pi rho is rational).
"""
from fractions import Fraction as F
from itertools import product
import GA
from tp_premise import premise

NV = 4
D = 3
SQ = [-1, 1, 1, 1]          # orthonormal frame (t, r, theta, phi), signature (-,+,+,+)


# ---- exact truncated Taylor jets in the four coordinate displacements --------------------------
def jconst(c):
    return {(0, 0, 0, 0): F(c)} if c != 0 else {}


def jvar(i):
    e = [0, 0, 0, 0]
    e[i] = 1
    return {tuple(e): F(1)}


def jadd(a, b, s=1):
    out = dict(a)
    for e, v in b.items():
        out[e] = out.get(e, F(0)) + s * v
    return {e: v for e, v in out.items() if v != 0}


def jscal(c, a):
    return {e: c * v for e, v in a.items() if c * v != 0}


def jmul(a, b, d):
    out = {}
    for e1, v1 in a.items():
        for e2, v2 in b.items():
            e = tuple(x + y for x, y in zip(e1, e2))
            if sum(e) <= d:
                out[e] = out.get(e, F(0)) + v1 * v2
    return {e: v for e, v in out.items() if v != 0}


def jinv(a, d):
    c0 = a.get((0, 0, 0, 0), F(0))
    assert c0 != 0
    x = jscal(-1 / c0, jadd(a, jconst(c0), -1))
    term, out = jconst(1), jconst(1)
    for _ in range(d):
        term = jmul(term, x, d)
        out = jadd(out, term)
    return jscal(1 / c0, out)


def jderiv(a, i):
    out = {}
    for e, v in a.items():
        if e[i] > 0:
            ee = list(e)
            ee[i] -= 1
            out[tuple(ee)] = out.get(tuple(ee), F(0)) + v * e[i]
    return out


def jval(a):
    return a.get((0, 0, 0, 0), F(0))


def jdr(a):
    return a.get((0, 1, 0, 0), F(0))


def christoffel(g):
    ginv = [jinv(g[a], D) for a in range(NV)]
    G = {}
    for a, b, c in product(range(NV), repeat=3):
        s = {}
        if a == c:
            s = jadd(s, jderiv(g[a], b))
        if a == b:
            s = jadd(s, jderiv(g[a], c))
        if b == c:
            s = jadd(s, jderiv(g[b], a), -1)
        if s:
            G[(a, b, c)] = jscal(F(1, 2), jmul(ginv[a], s, D - 1))
    return G


def riemann(g):
    """lowered R_{abcd} = g_aa (d_c G^a_db - d_d G^a_cb + G^a_ce G^e_db - G^a_de G^e_cb)"""
    G = christoffel(g)
    Rl = {}
    for a, b, c, d in product(range(NV), repeat=4):
        if c >= d:
            continue
        s = jadd(jderiv(G.get((a, d, b), {}), c), jderiv(G.get((a, c, b), {}), d), -1)
        for e in range(NV):
            s = jadd(s, jmul(G.get((a, c, e), {}), G.get((e, d, b), {}), D - 2))
            s = jadd(s, jmul(G.get((a, d, e), {}), G.get((e, c, b), {}), D - 2), -1)
        low = jmul(g[a], s, D - 2)
        if low:
            Rl[(a, b, c, d)] = low
            Rl[(a, b, d, c)] = jscal(-1, low)
    return Rl, G


def R4(Rl, a, b, c, d):
    return jval(Rl.get((a, b, c, d), {}))


def ricci(g, Rl):
    return {(b, d): sum(R4(Rl, a, b, a, d) / jval(g[a]) for a in range(NV)) for b in range(NV) for d in range(NV)}


def tracefree_square(g, Ric):
    """S_ab S^ab for a diagonal metric, S = Ric - (R/4) g"""
    gi = [1 / jval(g[a]) for a in range(NV)]
    Rs = sum(gi[a] * Ric[(a, a)] for a in range(NV))
    S = {(a, b): Ric[(a, b)] - (Rs / 4 * jval(g[a]) if a == b else 0) for a in range(NV) for b in range(NV)}
    return sum(gi[a] * gi[b] * S[(a, b)] ** 2 for a in range(NV) for b in range(NV)), Rs


def sds(M, Lam, r0):
    r = jadd(jconst(r0), jvar(1))
    r2 = jmul(r, r, D)
    f = jadd(jadd(jconst(1), jscal(-2 * M, jinv(r, D))), jscal(-Lam / 3, r2))
    z = jvar(2)
    omz = jadd(jconst(1), jmul(z, z, D), -1)
    return [jscal(-1, f), jinv(f, D), jmul(r2, jinv(omz, D), D), jmul(r2, omz, D)]


def esu(a, x0):
    """-dt^2 + A (dx^2 + dy^2 + dz^2), A = 4 a^2 / (1 + |x|^2)^2, about (0, x0)"""
    rho2 = jconst(0)
    for i in range(3):
        xi = jadd(jconst(x0[i]), jvar(i + 1))
        rho2 = jadd(rho2, jmul(xi, xi, D))
    den = jadd(jconst(1), rho2)
    A = jscal(4 * a * a, jinv(jmul(den, den, D), D))
    return [jconst(-1), A, A, A]


def eta_model(c, S2):
    return F(1, 4) * (1 + c * S2)


C_MODEL = F(5, 3)
SQ = [-1, 1, 1, 1]


def check_vacuum_density_is_one_quarter():
    premise("synthesis.black-hole-data-do-not-fix-field-equations")
    premise("synthesis.c-loc-entropy-clause-curvature-independent-density")
    premise("synthesis.sds-clausius-fixes-area-constant")
    for (M, Lam, r0) in ((F(1), F(3, 100), F(3)), (F(1, 2), F(1, 10), F(7, 5)), (F(0), F(1, 10), F(2))):
        g = sds(M, Lam, r0)
        Rl, G = riemann(g)
        Ric = ricci(g, Rl)
        S2, Rs = tracefree_square(g, Ric)
        GA.check("Lambda-vacuum: R = 4 Lambda, S = 0", Rs == 4 * Lam and S2 == 0)
        GA.check("model density 1/4 on vacuum patches", eta_model(C_MODEL, S2) == F(1, 4))
        anchors = {F(3): (F(3, 25), F(227, 2700)), F(7, 5): (F(2, 5), F(4093, 10290)), F(2): (F(2, 5), F(1, 30))}
        K = R4(Rl, 2, 3, 2, 3) / (jval(g[2]) * jval(g[3]))
        GA.check("anchor R and K_edge", (Rs, K) == anchors[r0])


def check_einstein_static_universe_model():
    premise("synthesis.einstein-equations-from-c-loc-and-clausius")
    premise("synthesis.c-loc-entropy-clause-curvature-independent-density")
    for a in (F(2), F(3, 2)):
        Ge = 1 / (1 + 3 * C_MODEL / a ** 4)                 # Newton coupling of the model in ESU
        eta = eta_model(C_MODEL, 3 / a ** 4)
        GA.check("eta = 1/(4 G_e) != 1/4", eta == 1 / (4 * Ge) and eta != F(1, 4))
        mu = 2 / (Ge * a ** 2)                              # mu = 8 pi rho
        anchors = {F(2): (F(21, 64), F(21, 32)), F(3, 2): (F(161, 324), F(1288, 729))}
        GA.check("anchor eta, 8 pi rho", (eta, mu) == anchors[a])
        for x0 in ((F(0), F(0), F(0)), (F(1, 2), F(1, 3), F(-1, 5))):
            g = esu(a, x0)
            Rl, G = riemann(g)
            Ric = ricci(g, Rl)
            S2, Rs = tracefree_square(g, Ric)
            A0 = jval(g[1])
            GA.check("Ric(e_t, e_t) = 0, Ric(e_i, e_j) = (2/a^2) delta_ij",
                     Ric[(0, 0)] == 0 and all(Ric[(i, j)] == (2 / a ** 2 * A0 if i == j else 0)
                                              for i in range(1, 4) for j in range(1, 4))
                     and all(Ric[(0, i)] == 0 for i in range(1, 4)))
            GA.check("S_ab S^ab = 3/a^4, R = 6/a^2", S2 == 3 / a ** 4 and Rs == 6 / a ** 2)
            GA.check("model density uses the computed curvature", eta_model(C_MODEL, S2) == eta)
            # dust at rest is conserved: Gamma^b_tt = 0 and Gamma^a_at = 0
            GA.check("u = d_t geodesic and expansion-free",
                     all(jval(G.get((b, 0, 0), {})) == 0 for b in range(NV))
                     and sum(jval(G.get((b, b, 0), {})) for b in range(NV)) == 0)
            for n in ((F(1), F(0), F(0)), (F(3, 5), F(4, 5), F(0)), (F(2, 7), F(3, 7), F(6, 7)), (F(1, 3), F(-2, 3), F(2, 3))):
                kon = {(0,): F(1)}
                for i in range(3):
                    if n[i]:
                        kon[(i + 1,)] = n[i]
                GA.check("k null (GA)", GA.dot(kon, kon, SQ) == 0)
                # coordinate components: k = e_t + n^i e_i, e_i = d_i / sqrt(A0); Ric(k,k) via the orthonormal frame
                ric_kk = Ric[(0, 0)] + sum(n[i] * n[j] * Ric[(i + 1, j + 1)] / A0 for i in range(3) for j in range(3))
                T_kk_8pi = mu                                   # 8 pi T(k,k) = 8 pi rho (u.k)^2, u.k = -1
                # stored defect: T(k,k) - (eta/2 pi) Ric(k,k) = 0  <=>  8 pi T(k,k) = 4 eta Ric(k,k)
                GA.check("Clausius balance with the model density", T_kk_8pi == 4 * eta * ric_kk)
                GA.check("same balance fails with eta = 1/4", T_kk_8pi != 4 * F(1, 4) * ric_kk)
            # integration constant: G_tt + Lambda_J g_tt = 8 pi G_e T_tt
            G_tt = Ric[(0, 0)] - Rs / 2 * jval(g[0])
            Lam_J = G_tt - Ge * mu
            GA.check("Lambda_J = 1/a^2", Lam_J == 1 / a ** 2)
            G_xx = Ric[(1, 1)] - Rs / 2 * A0
            GA.check("spatial equations: G_ij + Lambda_J g_ij = 0", G_xx + Lam_J * A0 == 0)

synthesis.locality-of-the-attached-free-:
"""Locality of the attached free fields fixes their statistics: exact checks.

Spacetime algebra Cl(1,3), gamma_0^2 = +1, gamma_i^2 = -1, I4 = gamma_0 gamma_1 gamma_2 gamma_3.
Polarisation sums (the numerators of the positive-energy two-point functions), on rational null k:
  scalar   P_0(k) = 1                                   (degree 0)
  spinor   P_1(k) = k gamma_0 = 2 k_0 Lambda(k)          (degree 1; Lambda the stored projector)
  photon   P_2(k)[A, B] = sum over transverse eps of <A, k^eps><B, k^eps>, <X, Y> = <XY>_0 for
           bivectors; equal on the cone to the polynomial -<A, k^g_0><B, k^g_0> + sum_i <A, k^g_i><B, k^g_i>
           (degree 2), with k^eps in the stored mode space {f : k f = 0}.
Locality: with D_+ the massless Wightman function, equal on the open spacelike set to -1/(4 pi^2 Q(xi))
(imported, standard; the constant is kept symbolic), the bracket of a free field whose particle and
antiparticle parts carry the polarisation sum P with weights 1 and c > 0 is, at spacelike xi,
  i^d (-1/(4 pi^2)) [ P(d) f (xi) + eta c P(-d)[f(-.)](xi) ],   f = 1/Q,
eta = +1 for the CAR (anticommutator), -1 for the CCR (commutator).  The script evaluates both terms
from exact derivatives of 1/Q at rational spacelike points and finds the bracket zero exactly when
c = 1 and eta = -(-1)^d (positive norm), and P(d) f nonzero (so the other choice is non-local); with a
negative-norm antiparticle term, c = -1 (indefinite form), exactly when eta = (-1)^d (ghosts).
Storeys: a tower plane (Q(v) = Q(w) = 0, {v, w} = 1) has eta = +1; the palatial polynomial pair
(a = d/dz, a* = z) has [a, a*] = 1, eta = -1.
"""
from fractions import Fraction as F
from itertools import product
import GA
from tp_premise import premise

SQ = GA.sig(1, 3)
G = [1, -1, -1, -1]  # diagonal metric


def g(i):
    return GA.gen(i)


def mm(*xs):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, SQ)
    return out


def vec(c):
    return {(i,): F(x) for i, x in enumerate(c) if x != 0}


def wedge(a, b):
    return GA.scal(F(1, 2), GA.sub(mm(a, b), mm(b, a)))


def sp(x, y):
    return mm(x, y).get((), F(0))


I4 = mm(g(0), g(1), g(2), g(3))
NULLS = [(5, 3, 4, 0), (3, 1, 2, 2), (9, 4, 4, 7), (7, 2, 3, 6), (-5, 3, 0, 4)]
SPACELIKE = [(0, 1, 2, 3), (1, 3, 1, 2), (F(1, 2), 2, -1, F(3, 2)), (-2, 1, 4, -3)]
BIV = [(0, 1), (0, 2), (0, 3), (1, 2), (1, 3), (2, 3)]


def Q(x):
    return sum(G[m] * F(x[m]) ** 2 for m in range(4))


# ---------------------------------------------------------------- polarisation sums
def P1(k):
    return mm(vec(k), g(0))


def P2(k, A, B):
    kv = vec(k)
    out = -sp(A, wedge(kv, g(0))) * sp(B, wedge(kv, g(0)))
    for i in (1, 2, 3):
        out += sp(A, wedge(kv, g(i))) * sp(B, wedge(kv, g(i)))
    return out


def P2_phys(k, A, B):
    """Sum over the transverse spatial polarisations: projector delta_ij - k_i k_j / |k|^2."""
    kv = vec(k)
    kk = sum(F(k[i]) ** 2 for i in (1, 2, 3))
    out = F(0)
    for i in (1, 2, 3):
        for j in (1, 2, 3):
            T = (F(1) if i == j else F(0)) - F(k[i]) * F(k[j]) / kk
            out += T * sp(A, wedge(kv, g(i))) * sp(B, wedge(kv, g(j)))
    return out


def blade(b):
    return {b: F(1)}


def check_polarisation_sums_have_degree_two_s():
    premise("field-theory.second-quantisation")
    premise("field-theory.fock-space-maxwell-modes")
    ok = True
    for k in NULLS:
        kv = vec(k)
        ok = ok and Q(k) == 0
        lam = GA.scal(F(1, 2 * k[0]), P1(k))
        ok = ok and GA.eq(mm(lam, lam), lam) and GA.is_zero(mm(kv, lam))
        mk = tuple(-x for x in k)
        k2 = tuple(2 * x for x in k)
        ok = ok and GA.eq(P1(mk), GA.neg(P1(k))) and GA.eq(P1(k2), GA.scal(2, P1(k)))
        # transverse polarisations give modes of the stored space {f : k f = 0}
        eps1 = vec((0, k[2], -k[1], 0))
        eps2 = vec((0, k[3] * k[1], k[3] * k[2], -(k[1] ** 2 + k[2] ** 2)))
        for eps in (eps1, eps2):
            if eps:
                f = wedge(kv, eps)
                ok = ok and GA.dot(kv, eps, SQ) == 0 and GA.is_zero(mm(kv, f)) and not GA.is_zero(f)
        for a, b in product(BIV, BIV):
            A, B = blade(a), blade(b)
            ok = ok and P2(k, A, B) == P2_phys(k, A, B)
            ok = ok and P2(mk, A, B) == P2(k, A, B) and P2(k2, A, B) == 4 * P2(k, A, B)
    # the photon sum is not identically zero and not odd
    ok = ok and any(P2(NULLS[0], blade(a), blade(b)) != 0 for a, b in product(BIV, BIV))
    GA.check("polarisation sums: spinor odd of degree 1 (2 k0 Lambda), photon even of degree 2", ok)
    return ok


# ---------------------------------------------------------------- derivatives of f = 1/Q
def d0(x):
    return F(1) / Q(x)


def d1(x, m):  # d f / d x^m
    return F(-2 * G[m]) * F(x[m]) / Q(x) ** 2


def d2(x, m, n):
    return F(-2 * (G[m] if m == n else 0)) / Q(x) ** 2 + F(8 * G[m] * G[n]) * F(x[m]) * F(x[n]) / Q(x) ** 3


def up(m):  # raising: d^m = g^{mm} d_m on the diagonal metric
    return G[m]


def quad_coeffs(A, B):
    """Coefficients M[m][n] of the quadratic polynomial P2(k) = sum M k^m k^n."""
    def P(k):
        return P2(k, A, B)
    e = [tuple(1 if i == m else 0 for i in range(4)) for m in range(4)]
    M = [[F(0)] * 4 for _ in range(4)]
    for m in range(4):
        M[m][m] = P(e[m])
    for m in range(4):
        for n in range(m + 1, 4):
            s = tuple(e[m][i] + e[n][i] for i in range(4))
            M[m][n] = M[n][m] = F(1, 2) * (P(s) - P(e[m]) - P(e[n]))
    return M


def Pd_f(d, x, sign, extra=None):
    """P(sign * d) applied to f at x, by degree d (0 scalar, 1 spinor, 2 photon component)."""
    if d == 0:
        return GA.sc(d0(x))
    if d == 1:
        out = {}
        for m in range(4):
            out = GA.add(out, GA.scal(sign * up(m) * d1(x, m), mm(g(m), g(0))))
        return out
    M = extra
    tot = F(0)
    for m in range(4):
        for n in range(4):
            tot += M[m][n] * up(m) * up(n) * d2(x, m, n)
    return GA.sc(sign * sign * tot)


def reflected(d, x, M):
    """P(-d)[f(-.)](x): derivatives of y -> f(-y) are (-1)^order f-derivatives at -x."""
    mx = tuple(-F(c) for c in x)
    if d == 0:
        return GA.sc(d0(mx))
    if d == 1:
        out = {}
        for m in range(4):
            out = GA.add(out, GA.scal(-1 * up(m) * (-1) * d1(mx, m), mm(g(m), g(0))))
        return out
    tot = F(0)
    for m in range(4):
        for n in range(4):
            tot += M[m][n] * up(m) * up(n) * d2(mx, m, n)  # (-1)^2 from P(-d), (-1)^2 from f(-.)
    return GA.sc(tot)


def check_locality_selects_the_statistics():
    premise("field-theory.second-quantisation")
    premise("field-theory.fock-space-maxwell-modes")
    premise("field-theory.twistor-attachment")
    A, B = blade((0, 1)), blade((0, 1))
    M = quad_coeffs(A, B)
    ok = True
    for x in SPACELIKE:
        ok = ok and Q(x) < 0
        # box (1/Q) = 0 off the cone: the quadratic extension is unique up to Q(k) R, R constant
        ok = ok and sum(up(m) * d2(x, m, m) for m in range(4)) == 0
        # spinor term is -2 xi gamma_0 / Q^2, nonzero
        ok = ok and GA.eq(Pd_f(1, x, 1), GA.scal(F(-2) / Q(x) ** 2, mm(vec(x), g(0))))
        for d in (0, 1, 2):
            t1 = Pd_f(d, x, 1, M)
            t2 = reflected(d, x, M)
            ok = ok and not GA.is_zero(t1)
