    """3 int_0^1 t^{2k} dt for the RR, RK (with its multiplicity 2) and KK terms of (R + t^2 K)^2."""
    polys = ([Fr(1)], [Fr(0), Fr(0), Fr(2)], [Fr(0), Fr(0), Fr(0), Fr(0), Fr(1)])
    return [3 * GA.peval(GA.ps_int(p), 1) for p in polys]


