def is_weyl(W):
    tf = all(not grade(GA.add(*[cross(ER[m], W(cross(E6[m], E6[b]))) for m in range(4)]), 1) for b in range(4))
    bi = all(not grade(GA.add(*[mul(ER[m], W(cross(E6[m], E6[b]))) for m in range(4)]), 3) for b in range(4))
