synthesis.many-twistor-join:
"""synthesis.many-twistor-join: exact checks.

Gaussian rationals (pairs of Fractions) stand for the chart's I6-complex components. The grip of
N conformal spinors is assembled three ways and compared exactly, for N = 2..5 and several lambda:
  route A: from the definition <P,U> = M_{U ^ I}, with the matrices A(U ^ V) of the chart lemma,
           the moment M_A = i sum_i bar Z^i . A Z^i, and a generic exact inverse of the ambient Gram
           matrix (no use of G^2 = 1);
  route B: 2 sum_{i<l} |B^{il}|^2 + 2 lambda C_N, with B^{il} = eps(I ^ Z^i ^ Z^l) as 4x4 determinants
           and C_N = tr h^2 / 2 - (tr h)^2 / 4 from the Gram matrix;
  route C: the component formulas p.p, k.k, p.k, d in closed form.
Then U(N) invariance (exact Cayley unitaries), the positivity bound, the antilinear map J of the
massless-locus argument, and the de Sitter Casimir corollary.
"""
import GA  # noqa: F401  (house rule; the computation below is in Gaussian rationals)
from tp_premise import premise


class _Rng:
    """Deterministic integer generator (Lehmer, modulus 2^31 - 1) giving a fixed, reproducible list
    of rational test points; no floats and no random module."""

    def __init__(self, seed):
        self.s = seed % 2147483647 or 1

    def _next(self):
        self.s = (self.s * 48271) % 2147483647
        return self.s

    def randint(self, a, b):
        return a + self._next() % (b - a + 1)

    def randrange(self, n):
        return self._next() % n
from fractions import Fraction as F


class C:
    """Gaussian rational a + i b, i the chart's complex unit (I6)."""
    __slots__ = ("re", "im")

    def __init__(self, re=0, im=0):
        self.re, self.im = F(re), F(im)

    def __add__(s, o):
        o = cc(o); return C(s.re + o.re, s.im + o.im)
    __radd__ = __add__

    def __sub__(s, o):
        o = cc(o); return C(s.re - o.re, s.im - o.im)

    def __rsub__(s, o):
        return cc(o) - s

    def __neg__(s):
        return C(-s.re, -s.im)

    def __mul__(s, o):
        o = cc(o); return C(s.re * o.re - s.im * o.im, s.re * o.im + s.im * o.re)
    __rmul__ = __mul__

    def __truediv__(s, o):
        o = cc(o); n = o.re * o.re + o.im * o.im
        return s * C(o.re / n, -o.im / n)

    def conj(s):
        return C(s.re, -s.im)

    def abs2(s):
        return s.re * s.re + s.im * s.im

    def __eq__(s, o):
        o = cc(o); return s.re == o.re and s.im == o.im

    def __repr__(s):
        return f"({s.re}+{s.im}i)"


def cc(x):
    return x if isinstance(x, C) else C(x)


I = C(0, 1)
EPS = [[0, 1], [-1, 0]]          # eps_12 = 1: eps^T eps = 1, eps^2 = -1, det = 1


def rnd(rng, k=3):
    return C(F(rng.randint(-k, k), rng.randint(1, 3)), F(rng.randint(-k, k), rng.randint(1, 3)))


def herm(Z, W):
    """bar Z . W = conj(pi_Z).omega_W + conj(omega_Z).pi_W  (Sigma pairs e1<->e3, e2<->e4)."""
    return sum((Z[2 + a].conj() * W[a] + Z[a].conj() * W[2 + a] for a in range(2)), C())


def matvec(A, Z):
    return [sum((cc(A[r][c]) * Z[c] for c in range(4)), C()) for r in range(4)]


def moment(A, Zs):
    """M_A = i sum_i bar Z^i . A Z^i."""
    return I * sum((herm(Z, matvec(A, Z)) for Z in Zs), C())


def A_grading():          # A(n_inf ^ n_0)
    h = F(1, 2)
    return [[-h, 0, 0, 0], [0, -h, 0, 0], [0, 0, h, 0], [0, 0, 0, h]]


def A_trans(x):           # A(x ^ n_inf): omega-block <- b_x pi, (b_x pi)^a = x^{aa'} eps_{a'b'} pi^{b'}
    A = [[0] * 4 for _ in range(4)]
    for a in range(2):
        for bp in range(2):
            A[a][2 + bp] = sum(x[a][ap] * EPS[ap][bp] for ap in range(2))
    return A


def A_spec(x):            # A(x ^ n_0): pi-block <- c_x omega, (c_x w)^{a'} = -x^{ba'} eps_{ba} w^a
    A = [[0] * 4 for _ in range(4)]
    for ap in range(2):
        for a in range(2):
            A[2 + ap][a] = -sum(x[b][ap] * EPS[b][a] for b in range(2))
    return A


def unit_x(a, ap):
    x = [[0, 0], [0, 0]]
    x[a][ap] = 1
    return x


# ambient basis: n_inf, n_0, E_{aa'} (a, a' in 0..1 standing for 1,2 and 3,4)
XS = [(a, ap) for a in range(2) for ap in range(2)]


def gram():
    G = [[F(0)] * 6 for _ in range(6)]
    G[0][1] = G[1][0] = F(1)
    for r, (a, ap) in enumerate(XS):
        for s, (b, bp) in enumerate(XS):
            G[2 + r][2 + s] = F(-EPS[a][b] * EPS[ap][bp])
    return G


def inverse(G):
    n = len(G)
    M = [[cc(G[r][c]) for c in range(n)] + [C(1 if r == c else 0) for c in range(n)] for r in range(n)]
    for col in range(n):
        piv = next(r for r in range(col, n) if not (M[r][col] == 0))
        M[col], M[piv] = M[piv], M[col]
        p = M[col][col]
        M[col] = [v / p for v in M[col]]
        for r in range(n):
            if r != col and not (M[r][col] == 0):
                f = M[r][col]
                M[r] = [M[r][c] - f * M[col][c] for c in range(2 * n)]
    return [row[n:] for row in M]


GI = inverse(gram())


def bil(u, v):
    return sum((GI[r][s] * u[r] * v[s] for r in range(6) for s in range(6)), C())


def grip_values(Zs, lam):
    """<P, U_j> = M_{U_j ^ I}, I = n_inf + lam n_0, by bilinearity of U ^ V -> A(U ^ V)."""
    d = moment(A_grading(), Zs)                     # M_{n_inf ^ n_0}
    v = [lam * d, -d]                               # M_{n_inf ^ I} = lam d ; M_{n_0 ^ I} = -d
    for (a, ap) in XS:
        x = unit_x(a, ap)
        v.append(moment(A_trans(x), Zs) + lam * moment(A_spec(x), Zs))
    return v


def PP_routeA(Zs, lam):
    v = grip_values(Zs, lam)
    return bil(v, v)


def br(u, w):            # eps_{ab} u^a w^b
    return u[0] * w[1] - u[1] * w[0]


def B(Zi, Zl, lam):      # B^{il} = <pi^i pi^l> + lam [omega^i omega^l]
    return br(Zi[2:], Zl[2:]) + lam * br(Zi[:2], Zl[:2])


def det4(M):
    if len(M) == 1:
        return M[0][0]
    return sum(((-1) ** c * M[0][c] * det4([row[:c] + row[c + 1:] for row in M[1:]]) for c in range(len(M))), C())


def B_eps(Zi, Zl, lam):
    """B^{il} = eps(I ^ Z^i ^ Z^l) with eps(e1 e2 e3 e4) = 1, n_inf = e1^e2, n_0 = e3^e4: a 4x4
    determinant route independent of the bracket formula."""
    def e(k):
        return [C(1 if j == k else 0) for j in range(4)]
    t1 = det4([e(0), e(1), Zi, Zl])          # eps(e1 ^ e2 ^ Zi ^ Zl), as columns (det of transpose)
    t2 = det4([e(2), e(3), Zi, Zl])
    return t1 + lam * t2


def gram_h(Zs):
    return [[herm(Zi, Zl) for Zl in Zs] for Zi in Zs]


def trace(M):
    return sum((M[k][k] for k in range(len(M))), C())


def mm(X, Y):
    n = len(X)
    return [[sum((X[r][k] * Y[k][c] for k in range(n)), C()) for c in range(n)] for r in range(n)]


def C_N(h):
    t1 = trace(mm(h, h)); t0 = trace(h)
    return t1 * F(1, 2) - t0 * t0 * F(1, 4)


def PP_routeB(Zs, lam):
    N = len(Zs)
    s = sum((B_eps(Zs[i], Zs[l], lam).abs2() for i in range(N) for l in range(i + 1, N)), F(0))
    return 2 * s + 2 * lam * C_N(gram_h(Zs)).re


def components(Zs):
    N = len(Zs)
    pp = 2 * sum((br(Zs[i][2:], Zs[l][2:]).abs2() for i in range(N) for l in range(i + 1, N)), F(0))
    kk = 2 * sum((br(Zs[i][:2], Zs[l][:2]).abs2() for i in range(N) for l in range(i + 1, N)), F(0))
    t = [[sum((Zs[i][2 + a].conj() * Zs[l][a] for a in range(2)), C()) for l in range(N)] for i in range(N)]
    pk = sum((t[i][l].abs2() for i in range(N) for l in range(N)), F(0))
    d = trace(t).im
    return pp, kk, pk, d, t


def PP_routeC(Zs, lam):
    pp, kk, pk, d, _ = components(Zs)
    return -2 * lam * d * d + pp + 2 * lam * pk + lam * lam * kk


def forms(Zs):
    """p, k as linear forms on the x-slot (components on E_{aa'}), d, all from the A-matrices."""
    p = [moment(A_trans(unit_x(a, ap)), Zs) for (a, ap) in XS]
    k = [moment(A_spec(unit_x(a, ap)), Zs) for (a, ap) in XS]
    d = moment(A_grading(), Zs)
    return p, k, d


def xdot(f, g):
    return sum((GI[2 + r][2 + s] * f[r] * g[s] for r in range(4) for s in range(4)), C())




# ---------------------------------------------------------------- further constructions

def cayley_unitary(rng, N):
    """U = (1 - K)(1 + K)^{-1} for an anti-Hermitian K with Gaussian-rational entries: exactly unitary."""
    K = [[C() for _ in range(N)] for _ in range(N)]
    for r in range(N):
        K[r][r] = C(0, F(rng.randint(-3, 3), 2))
        for c in range(r + 1, N):
            z = rnd(rng, 2)
            K[r][c] = z
            K[c][r] = -z.conj()
    one = [[C(1 if r == c else 0) for c in range(N)] for r in range(N)]
    Am = [[one[r][c] - K[r][c] for c in range(N)] for r in range(N)]
    Bm = [[one[r][c] + K[r][c] for c in range(N)] for r in range(N)]
    Binv = inverse(Bm)
    return mm(Am, Binv)


def apply_U(Zs, U):
    """Z^i -> sum_j Z^j U_{ji}."""
    N = len(Zs)
    return [[sum((Zs[j][a] * U[j][i] for j in range(N)), C()) for a in range(4)] for i in range(N)]


def J(Z, lam):
    """The antilinear map with bar(JZ).W = B_lam(Z, W): JZ = S Omega^T conj(Z), S the block swap."""
    cz = [z.conj() for z in Z]
    OT = [[0] * 4 for _ in range(4)]
    for a in range(2):
        for b in range(2):
            OT[a][b] = lam * EPS[b][a]
            OT[2 + a][2 + b] = EPS[b][a]
    y = matvec(OT, cz)
    return [y[2], y[3], y[0], y[1]]


def check_many_twistor_join():
    premise("mass.exact-join")
    premise("mass.chart-form-spin-isomorphism")
    premise("mass.de-sitter-scale-frozen-point")
    premise("mass.imported-flat-model-twistor-chart-infinity")
    premise("mass.casimir-form-join")
    rng = _Rng(20261022)
    # the ambient Gram matrix: <n_inf, n_0> = 1 (de-sitter-scale-frozen-point (3) uses it),
    # <x, x> = -2 det x on the mixed slot (imported chart fact)
    G = gram()
    for (a, ap), (b, bp) in [((0, 0), (1, 1)), ((0, 1), (1, 0))]:
        x = [[F(0)] * 2 for _ in range(2)]
        x[a][ap] += 1
        x[b][bp] += 1
        r, s = XS.index((a, ap)), XS.index((b, bp))
        quad = G[2 + r][2 + r] + G[2 + s][2 + s] + 2 * G[2 + r][2 + s]
        assert quad == -2 * (x[0][0] * x[1][1] - x[0][1] * x[1][0])
    for lam in (F(1, 6), F(1), F(-2, 3)):
        Iv = [C(1), C(lam), C(), C(), C(), C()]          # coordinates of I = n_inf + lam n_0
        Gc = [[cc(v) for v in row] for row in G]
        II = sum((Gc[r][s] * Iv[r] * Iv[s] for r in range(6) for s in range(6)), C())
        assert II == C(2 * lam)                          # <I,I> = 2 lambda = Lambda/3
    for N in range(2, 6):
        for trial in range(3):
            Zs = [[rnd(rng) for _ in range(4)] for _ in range(N)]
            h = gram_h(Zs)
            # (i) component formulas: forms built from the chart matrices, paired by the inverse Gram
            p, k, d = forms(Zs)
            pp, kk, pk, dd, t = components(Zs)
            assert xdot(p, p) == pp and xdot(k, k) == kk and xdot(p, k) == pk
            assert d == C(dd)
            for i in range(N):
                for l in range(N):
                    assert h[i][l] == t[i][l] + t[l][i].conj()     # h = t + t^dagger
            for lam in (F(0), F(1), F(-2, 3), F(5, 7)):
                # B by the bracket formula equals eps(I ^ Z^i ^ Z^l)
                for i in range(N):
                    for l in range(i + 1, N):
                        assert B(Zs[i], Zs[l], lam) == B_eps(Zs[i], Zs[l], lam)
                # (ii) three routes to <P,P>
                a, b, c = PP_routeA(Zs, lam), PP_routeB(Zs, lam), PP_routeC(Zs, lam)
                assert a.im == 0 and a.re == b == c
            # (ii) at N = 2 the remainder is T11's C = (h11 - h22)^2/4 + |h12|^2
            cN = C_N(h)
            assert cN.im == 0
            if N == 2:
                assert cN.re == (h[0][0].re - h[1][1].re) ** 2 / 4 + h[0][1].abs2()
            # C_N = (1/2) tr h0^2 - (N-2)/(4N) (tr h)^2
            th = trace(h)
            h0 = [[h[r][s] - (th * F(1, N) if r == s else C()) for s in range(N)] for r in range(N)]
            assert cN == trace(mm(h0, h0)) * F(1, 2) - th * th * F(N - 2, 4 * N)
            # (iii) U(N) invariance of <P,P>, of sum |B|^2 and of C_N, with h -> U^dag h U
            U = cayley_unitary(rng, N)
            Zu = apply_U(Zs, U)
            hu = gram_h(Zu)
            Ud = [[U[c][r].conj() for c in range(N)] for r in range(N)]
            assert hu == mm(mm(Ud, h), U)
            assert C_N(hu) == cN
            for lam in (F(1), F(-3, 4)):
                assert PP_routeA(Zu, lam) == PP_routeA(Zs, lam)
                sB = sum((B(Zs[i], Zs[l], lam).abs2() for i in range(N) for l in range(i + 1, N)), F(0))
                sBu = sum((B(Zu[i], Zu[l], lam).abs2() for i in range(N) for l in range(i + 1, N)), F(0))
                assert sB == sBu
            # (iv) C_N >= 0 on realised Gram matrices
            assert cN.re >= 0
            # (vi) de Sitter Casimir: C2(Lambda^2 CS) - <P,P>/<I,I> = (1/2) tr h^2 - sum|B|^2 / lambda
            for lam in (F(1, 6), F(2)):
                sB = sum((B(Zs[i], Zs[l], lam).abs2() for i in range(N) for l in range(i + 1, N)), F(0))
                conf = trace(mm(h, h)).re - th.re * th.re / 4
                assert conf - PP_routeB(Zs, lam) / (2 * lam) == trace(mm(h, h)).re / 2 - sB / lam
    # (iv) the bound uses the signature: an abstract Hermitian h = 1_N has C_N = N(2 - N)/4 < 0 for N >= 3,
    # so 1_N is not the Gram matrix of N >= 3 conformal spinors; and 4 C_N = (a1-a2)^2 + (b1-b2)^2 + 2AB
    for N in range(3, 7):
        one = [[C(1 if r == c else 0) for c in range(N)] for r in range(N)]
        assert C_N(one) == C(F(N * (2 - N), 4)) and F(N * (2 - N), 4) < 0
    for (a1, a2, b1, b2) in [(F(3), F(1), F(2), F(0)), (F(1, 2), F(1, 2), F(0), F(0)), (F(5), F(0), F(1), F(1))]:
        mus = [a1, a2, -b1, -b2, F(0)]
        h = [[C(mus[r] if r == c else 0) for c in range(5)] for r in range(5)]
        assert 4 * C_N(h).re == (a1 - a2) ** 2 + (b1 - b2) ** 2 + 2 * (a1 + a2) * (b1 + b2)
    # (v) the antilinear map J: bar(JZ).W = B_lam(Z,W), J^2 = -lam, bar(JZ).(JW) = lam conj(bar Z.W)
    for lam in (F(1, 6), F(1), F(-3, 5)):
        for _ in range(4):
            Z = [rnd(rng) for _ in range(4)]
            W = [rnd(rng) for _ in range(4)]
            assert herm(J(Z, lam), W) == B(Z, W, lam)
            JJ = J(J(Z, lam), lam)
            assert all(JJ[q] == -lam * Z[q] for q in range(4))
            assert herm(J(Z, lam), J(W, lam)) == lam * herm(Z, W).conj()
    # (v) massless examples: B = 0 and h = 0, for N = 2 (T11's) and N = 3, at Lambda > 0
    for lam in (F(1, 6), F(3)):
        for coeffs in ([(C(1), C(1)), (C(2), C(0, 1))], [(C(1), C(1)), (C(-1), C(2)), (C(0, 1), C(1, -1))]):
            Zs = [[a, C(), C(), b] for (a, b) in coeffs]      # Z = a e1 + b e4
            assert all(B(Zs[i], Zs[l], lam) == 0 for i in range(len(Zs)) for l in range(len(Zs)))
            assert all(v == 0 for row in gram_h(Zs) for v in row)
            assert PP_routeA(Zs, lam) == 0
    return True

synthesis.massive-dirac-instantaneous-va:
"""synthesis.massive-dirac-instantaneous-vacuum-and-non-smooth-descents-are-not-hadamard: exact checks.

One momentum-helicity sector of the Dirac field on a spatially flat Robertson-Walker field, in conformal
time, is the two-level system i u' = H u with H = M s3 + k s1, M = m a(eta) (s_j the Pauli vectors, i the
Pauli pseudoscalar I = s1 s2 s3). For a pure state rho = (1 + s)/2 with Bloch vector s this is
s' = 2 h x s, h = (k, 0, M).

Jets: M_j = d^j M / d eta^j are independent polynomial variables; D(M_j) = M_{j+1}; eps = 1/k.
(1) Pauli algebra: H^2 = k^2 + M^2, I^2 = -1, I central, (a b - b a)/2 = I (a x b) on all basis pairs.
(2) The all-order adiabatic Bloch series s_ad = sum_j eps^j c_j: recursion e1 x c_{n+1} = (D c_n - 2 M e3 x c_n)/2
    with the e1-part fixed by |s| = 1; solvability, unit norm, the equation residual and weight homogeneity
    (weight(M_j) = j + 1, c_j of weight j) are checked to order NMAX; c_1 = M e3, c_2 = -M^2/2 e1 + M_1/2 e2.
(3) The instantaneous eigenvector h/|h| as a series; 1 - s_ad . h/|h| = M_1^2/8 eps^4 + c6 eps^6 + ...,
    odd orders zero; |beta|^2 = (1 - s.s')/2 = M_1^2/(16 k^4) + O(k^-6).
(3b) A gauge-invariant deposit diagonal over the instantaneous vacuum has one-particle Bloch part t h/|h|; its
    sigma_2 gap to the adiabatic state's density (1 - s_ad)/2 is s_ad.s2/2 = M_1/(4 k^2) + O(k^-4) for every t.
(4) Jump law: the only monomial of c_{n+1} containing M_n is lambda_n M_n v_n, lambda_n v_n = -(1/2) lambda_{n-1}
    e1 x v_{n-1}, |lambda_n| = 2^-n; M_n is absent from c_j for j <= n; shifting M_n by D changes s through
    order n + 1 only by D lambda_n v_n eps^(n+1), and 1 - s_L . s_R = D^2 4^-n / 2 eps^(2n+2) + O(eps^(2n+3)).
"""
from fractions import Fraction as Fr
import GA
from tp_premise import premise

NMAX = 9          # series order computed
NJ = NMAX + 3     # jet variables M_0 .. M_{NJ-2}, plus the shift variable D in the last slot
DSLOT = NJ - 1


# ---- polynomials in the jet variables: {exponent tuple: Fraction} ----
def padd(p, q, c=1):
    out = dict(p)
    for m, v in q.items():
        out[m] = out.get(m, 0) + c * v
        if out[m] == 0:
            del out[m]
    return out


def pmul(p, q):
    out = {}
    for a, x in p.items():
        for b, y in q.items():
            m = tuple(i + j for i, j in zip(a, b))
            out[m] = out.get(m, 0) + x * y
            if out[m] == 0:
                del out[m]
    return out


def pscale(p, c):
    return {m: v * c for m, v in p.items() if v * c != 0}


def mono(j, e=1):
    t = [0] * NJ
    t[j] = e
    return {tuple(t): Fr(1)}


ONE = {tuple([0] * NJ): Fr(1)}
M = mono(0)


def pder(p):
    """Total eta-derivative: D M_j = M_{j+1}; the shift variable D is a constant."""
    out = {}
    for m, v in p.items():
        for j, e in enumerate(m[:DSLOT]):
            if e:
                t = list(m)
                t[j] -= 1
                t[j + 1] += 1
                assert j + 1 < DSLOT
                t = tuple(t)
                out[t] = out.get(t, 0) + v * e
                if out[t] == 0:
                    del out[t]
    return out


def subst(p, j, q):
    """Substitute M_j -> q in p."""
    out = {}
    for m, v in p.items():
        e = m[j]
        base = list(m)
        base[j] = 0
        term = {tuple(base): v}
        for _ in range(e):
            term = pmul(term, q)
        out = padd(out, term)
    return out


# ---- 3-vectors of polynomials ----
def vadd(a, b, c=1):
    return [padd(a[i], b[i], c) for i in range(3)]


def vder(a):
    return [pder(x) for x in a]


def vsc(a, p):
    return [pmul(x, p) for x in a]


def cross(a, b):
    return [padd(pmul(a[1], b[2]), pmul(a[2], b[1]), -1),
            padd(pmul(a[2], b[0]), pmul(a[0], b[2]), -1),
            padd(pmul(a[0], b[1]), pmul(a[1], b[0]), -1)]


def vdot(a, b):
    return padd(padd(pmul(a[0], b[0]), pmul(a[1], b[1])), pmul(a[2], b[2]))


E1 = [ONE, {}, {}]
E2 = [{}, ONE, {}]
E3 = [{}, {}, ONE]
ZERO = [{}, {}, {}]


def adiabatic_series(N):
    c = [E1]
    for n in range(N):
        rhs = vadd(vder(c[n]), vsc(cross(E3, c[n]), pscale(M, 2)), -1)
        rhs = [pscale(x, Fr(1, 2)) for x in rhs]
        assert rhs[0] == {}, ("solvability fails", n)
        nxt = [pscale(x, -1) for x in cross(E1, rhs)]
        s = {}
        for a in range(1, n + 1):
            s = padd(s, vdot(c[a], c[n + 1 - a]))
        nxt[0] = pscale(s, Fr(-1, 2))
        c.append(nxt)
    return c


def inst_series(N):
    """h/|h| = (1, 0, eps M) (1 + eps^2 M^2)^(-1/2) via GA's exact power series."""
    coeffs = GA.ps_pow_rat([Fr(1), Fr(1)], Fr(-1, 2), N // 2 + 1)   # (1 + x)^(-1/2)
    out = [[{}, {}, {}] for _ in range(N + 1)]
    m2 = ONE
    for j, cj in enumerate(coeffs):
        if 2 * j <= N:
            out[2 * j][0] = padd(out[2 * j][0], pscale(m2, cj))
        if 2 * j + 1 <= N:
            out[2 * j + 1][2] = padd(out[2 * j + 1][2], pmul(pscale(m2, cj), M))
        m2 = pmul(m2, pmul(M, M))
    return out


def series_dot(a, b, N):
    out = []
    for n in range(N + 1):
        tot = {}
        for i in range(n + 1):
            tot = padd(tot, vdot(a[i], b[n - i]))
        out.append(tot)
    return out


C = adiabatic_series(NMAX)
CI = inst_series(NMAX)


def check_pauli_two_level_bloch_form():
    sq = (1, 1, 1)
    e = [GA.gen(i) for i in range(3)]
    I = GA.mul(GA.mul(e[0], e[1], sq), e[2], sq)
    assert GA.eq(GA.mul(I, I, sq), GA.sc(-1))
    for v in e:
        assert GA.commutes(I, v, sq)
    # (a b - b a)/2 = I (a x b) on all basis pairs, so on all vectors by bilinearity
    for i in range(3):
        for j in range(3):
            lhs = GA.scal(Fr(1, 2), GA.sub(GA.mul(e[i], e[j], sq), GA.mul(e[j], e[i], sq)))
            cr = [0, 0, 0]
            k = 3 - i - j
            if i != j:
                sgn = 1 if (i, j) in ((0, 1), (1, 2), (2, 0)) else -1
                cr[k] = sgn
            rhs = GA.mul(I, GA.add(*[GA.scal(Fr(cr[t]), e[t]) for t in range(3)]), sq)
            assert GA.eq(lhs, rhs)
    # H = M s3 + k s1 squares to k^2 + M^2 at sample rational points
    for Mv, kv in ((Fr(3, 7), Fr(5)), (Fr(-2), Fr(1, 3)), (Fr(0), Fr(11, 4))):
        H = GA.add(GA.scal(Mv, e[2]), GA.scal(kv, e[0]))
        assert GA.eq(GA.mul(H, H, sq), GA.sc(kv * kv + Mv * Mv))
    return True


def check_adiabatic_series_solves_the_bloch_equation():
    assert C[1] == [{}, {}, M]
    assert C[2] == [pscale(pmul(M, M), Fr(-1, 2)), pscale(mono(1), Fr(1, 2)), {}]
    for n in range(NMAX + 1):
        # unit norm order by order: sum_{a+b=n} c_a . c_b = delta_{n0}
        tot = {}
        for a in range(n + 1):
            tot = padd(tot, vdot(C[a], C[n - a]))
        assert tot == (ONE if n == 0 else {}), n
        # weight homogeneity
        for comp in C[n]:
            for m in comp:
                assert sum((j + 1) * e for j, e in enumerate(m)) == n
        # residual of s' = 2 h x s at order eps^n (n < NMAX): D c_n - 2 e1 x c_{n+1} - 2 M e3 x c_n = 0
        if n < NMAX:
            res = vadd(vadd(vder(C[n]), vsc(cross(E1, C[n + 1]), pscale(ONE, 2)), -1),
                       vsc(cross(E3, C[n]), pscale(M, 2)), -1)
            assert res == ZERO, n
    # parity: c_j lies along e1, e2 for even j and along e3 for odd j
    for n in range(NMAX + 1):
        if n % 2:
            assert C[n][0] == {} and C[n][1] == {}
        else:
            assert C[n][2] == {}
    return True


def check_instantaneous_vacuum_differs_at_order_k_minus_two():
    premise("synthesis.imported-microlocal-hadamard-condition")
    # the instantaneous series is a unit vector along h
    tot = series_dot(CI, CI, NMAX)
    assert tot[0] == ONE and all(t == {} for t in tot[1:])
    assert cross(E1, CI[1]) == vsc(cross(E1, E3), M)
    # agreement through order 1, first difference at order 2 along e2 with coefficient M_1/2
    for n in range(2):
        assert C[n] == CI[n]
    d2 = vadd(C[2], CI[2], -1)
    assert d2 == [{}, pscale(mono(1), Fr(1, 2)), {}]
    # 1 - s_ad . s_inst
    sd = series_dot(C, CI, NMAX)
    one_minus = [padd(ONE if n == 0 else {}, sd[n], -1) for n in range(NMAX + 1)]
    for n in range(4):
        assert one_minus[n] == {}
    assert one_minus[4] == pscale(pmul(mono(1), mono(1)), Fr(1, 8))
    assert one_minus[5] == {} and one_minus[7] == {}
    six = padd(padd(pscale(pmul(pmul(M, M), pmul(mono(1), mono(1))), Fr(-3, 8)),
                    pscale(pmul(mono(1), mono(3)), Fr(-1, 16))), pscale(pmul(mono(2), mono(2)), Fr(1, 32)))
    assert one_minus[6] == six
    # |beta|^2 = (1 - s.s')/2 at order k^-4 is M_1^2/16; the energy moment k^2 * k * |beta|^2 has
    # leading term (M_1^2/16) / k, so each dyadic shell [K, 2K] contributes at least M_1^2/32 at
    # leading order (1/k >= 1/(2K) on the shell, shell length K)
    beta2_4 = pscale(one_minus[4], Fr(1, 2))
    assert beta2_4 == pscale(pmul(mono(1), mono(1)), Fr(1, 16))
    shell = pscale(beta2_4, Fr(1, 2))          # K * (1/(2K)) * M_1^2/16
    assert shell == pscale(pmul(mono(1), mono(1)), Fr(1, 32))
    # the number moment k^2 |beta|^2 ~ k^-2 is integrable at infinity; the energy moment ~ k^-1 is not
    num_power, energy_power = 2 - 4, 2 + 1 - 4
    assert num_power < -1 and energy_power == -1
    # massless field: every correction vanishes at M = 0 (conformal vacuum exact)
    for n in range(1, NMAX + 1):
        for comp in C[n]:
            for m in comp:
                assert any(m[j] for j in range(DSLOT))
    return True


def check_deposits_diagonal_over_the_instantaneous_vacuum_keep_the_gap():
    premise("synthesis.imported-microlocal-hadamard-condition")
    # h/|h| has no sigma_2 part at any order
    for n in range(NMAX + 1):
        assert CI[n][1] == {}
    for t in (Fr(-1), Fr(-1, 3), Fr(0), Fr(1, 2), Fr(1)):
        # Bloch part of the difference of densities: (t h_hat - (-s_ad))/2
        diff = [vadd(vsc(CI[n], pscale(ONE, t)), C[n]) for n in range(NMAX + 1)]
        half2 = [pscale(diff[n][1], Fr(1, 2)) for n in range(NMAX + 1)]
        assert half2[0] == {} and half2[1] == {}
        assert half2[2] == pscale(mono(1), Fr(1, 4))
        assert half2[3] == {}
        assert half2[4] == padd(pscale(mono(3), Fr(-1, 16)), pscale(pmul(pmul(M, M), mono(1)), Fr(-3, 8)))
        # the gap does not depend on t: identical to the t = 0 value at every order
        assert half2 == [pscale(C[n][1], Fr(1, 2)) for n in range(NMAX + 1)]
    return True


def check_jump_law():
    premise("synthesis.imported-microlocal-hadamard-condition")
    lam_v = None
    for n in range(NMAX):
        key = list(mono(n))[0]
        coeff = [comp.get(key, Fr(0)) for comp in C[n + 1]]
        # only one monomial of c_{n+1} contains M_n: M_n itself
        for comp in C[n + 1]:
            for m in comp:
                if m[n]:
                    assert m == key
        # absent below
        for j in range(n + 1):
            for comp in C[j]:
                for m in comp:
                    assert m[n] == 0
        mag = sum(x * x for x in coeff)
        assert mag == Fr(1, 4 ** n)
        expected_axis = 2 if n % 2 == 0 else 1
        assert [i for i in range(3) if coeff[i] != 0] == [expected_axis]
        if lam_v is not None:
            prev = [{key0: lam_v[i]} if lam_v[i] else {} for i in range(3)]
            rec = [pscale(x, Fr(-1, 2)) for x in cross(E1, prev)]
            assert [x.get(key0, Fr(0)) for x in rec] == coeff
        lam_v = coeff
        key0 = key
        # shift M_n -> M_n + D: s changes through order n + 1 only by D lambda_n v_n
        shifted = [[subst(comp, n, padd(mono(n), mono(DSLOT))) for comp in C[j]] for j in range(NMAX + 1)]
        for j in range(n + 1):
            assert shifted[j] == C[j]
        diff = vadd(shifted[n + 1], C[n + 1], -1)
        assert diff == [{list(mono(DSLOT))[0]: coeff[i]} if coeff[i] else {} for i in range(3)]
        if 2 * n + 2 <= NMAX:
            sd = series_dot(shifted, C, NMAX)
            om = [padd(ONE if t == 0 else {}, sd[t], -1) for t in range(NMAX + 1)]
            for t in range(2 * n + 2):
                assert om[t] == {}
            assert om[2 * n + 2] == pscale(mono(DSLOT, 2), Fr(1, 2 * 4 ** n))
    return True


def check_stored_sudden_start_differs_from_bunch_davies_unboundedly():
    premise("synthesis.sudden-descent-feature-not-tilt")
    premise("synthesis.imported-microlocal-hadamard-condition")
    I = GA.QI(0, 1)
    # u = E (1 - i/z), u_z = E (-i - 1/z + i/z^2), E = e^{-iz} of modulus one; instantaneous data f = 1, f_z = -i.
    # The identities below are Laurent polynomials in 1/z of degree at most 8, so nine distinct sample
    # points determine them; eleven are used.
    samples = [Fr(-1, 3), Fr(-1, 2), Fr(-1), Fr(-3, 2), Fr(-2), Fr(-5, 2), Fr(-3), Fr(-7), Fr(-10), Fr(-40), Fr(-101, 3)]
    for z in samples:
        p = GA.QI(1) - I * GA.QI(Fr(1) / z)                       # u / E
        q = GA.QI(0, -1) - GA.QI(Fr(1) / z) + I * GA.QI(Fr(1) / (z * z))  # u_z / E
        u2 = (p * p.conj()).re
        uz2 = (q * q.conj()).re
        e_u = Fr(1, 2) * (uz2 + u2)
        e_f = Fr(1, 2) * (1 + 1)
        assert z * z * (u2 - 1) == 1                               # <chi^2> deficit 1/z^2 per mode
        assert z ** 4 * (e_u - e_f) == Fr(1, 2)                    # energy deficit 1/(2 z^4) per mode
        # Bogoliubov coefficient of the instantaneous data against u, |beta|^2 = 1/(4 z^4)
        W = GA.QI(0, 2)
        beta = GA.QI(-1) * (q + I * p) / W                       # -(u' + i u)/W up to the phase E
        assert z ** 4 * (beta * beta.conj()).re == Fr(1, 4)
    # in physical units chi = f/sqrt(2k), d/deta = k d/dz: per-mode deficits (1/(2k)) (k eta_d)^-2 and
    # (k/2) (1/2)(k eta_d)^-4; with the measure k^2 dk both are (const)/k: logarithmically divergent
    chi_power = -1 - 2 + 2      # k^-1 (1/(2k)) * k^-2 * k^2
    energy_power = 1 - 4 + 2    # k (k/2) * k^-4 * k^2
    assert chi_power == -1 and energy_power == -1
    return True

synthesis.massless-composites-de-sitter-:
"""synthesis.massless-composites-de-sitter-conformal-boundary: exact checks.

Gaussian rationals (GA.QI) stand for the chart's I6-complex components; Z = (omega^1, omega^2, pi^1, pi^2).
The squared grip is computed from its definition, <P,U> = M_{U ^ I_Lambda} with the chart matrices
A(U ^ V), the moment M_A = i sum_i bar Z^i . A Z^i and an exact inverse of the ambient Gram matrix
(route A, independent of the join formula). On it:
  (1) lines omega = mu pi: h = pi^dag (mu + mu^dag) pi, B_Lambda = (1 + lambda det mu) <pi pi>,
      [omega omega] = det mu <pi pi>; on mu + mu^dag = 0, m^2 = 2 sigma^2 |<pi pi>|^2 with sigma = 1 + lambda det mu;
  (2a) samples with det mu = -1/lambda are massless, and moving det mu makes them massive;
  (2b) the planes {(omega,0),(0,pi)} with bar omega . pi = 0 are massless; the plane pi = 0 is not;
  (3) the source term (2 Lambda/3) Re(bar b Omega) is -4 |b|^2 on (2a) and 0 on (2b);
  (4) a third constituent in the plane keeps the composite massless.
"""
import GA
from GA import QI
import gtg
from tp_premise import premise
from fractions import Fraction as F


def C(re=0, im=0):
    return QI(re, im)


def cc(x):
    return x if isinstance(x, QI) else QI(x)


def abs2(z):
    return z.re * z.re + z.im * z.im



I = C(0, 1)
EPS = [[0, 1], [-1, 0]]          # eps_12 = 1: eps^T eps = 1, eps^2 = -1, det = 1


# bar Z . W = conj(pi_Z).omega_W + conj(omega_Z).pi_W (Sigma pairs e1<->e3, e2<->e4): gtg.tw_herm;
# the moment M_A = i sum_i bar Z^i . A Z^i and the Gram matrix h_il = bar Z^i . Z^l
moment, gram_h = gtg.tw_moment, gtg.tw_gram_h


def A_grading():          # A(n_inf ^ n_0)
    h = F(1, 2)
    return [[-h, 0, 0, 0], [0, -h, 0, 0], [0, 0, h, 0], [0, 0, 0, h]]


def A_trans(x):           # A(x ^ n_inf): omega-block <- b_x pi, (b_x pi)^a = x^{aa'} eps_{a'b'} pi^{b'}
    A = [[0] * 4 for _ in range(4)]
    for a in range(2):
        for bp in range(2):
            A[a][2 + bp] = sum(x[a][ap] * EPS[ap][bp] for ap in range(2))
    return A


def A_spec(x):            # A(x ^ n_0): pi-block <- c_x omega, (c_x w)^{a'} = -x^{ba'} eps_{ba} w^a
    A = [[0] * 4 for _ in range(4)]
    for ap in range(2):
        for a in range(2):
            A[2 + ap][a] = -sum(x[b][ap] * EPS[b][a] for b in range(2))
    return A


def unit_x(a, ap):
    x = [[0, 0], [0, 0]]
    x[a][ap] = 1
    return x


# ambient basis: n_inf, n_0, E_{aa'} (a, a' in 0..1 standing for 1,2 and 3,4)
XS = [(a, ap) for a in range(2) for ap in range(2)]


def gram():
    G = [[F(0)] * 6 for _ in range(6)]
    G[0][1] = G[1][0] = F(1)
    for r, (a, ap) in enumerate(XS):
        for s, (b, bp) in enumerate(XS):
            G[2 + r][2 + s] = F(-EPS[a][b] * EPS[ap][bp])
    return G


def inverse(G):
    n = len(G)
    M = [[cc(G[r][c]) for c in range(n)] + [C(1 if r == c else 0) for c in range(n)] for r in range(n)]
    for col in range(n):
        piv = next(r for r in range(col, n) if not (M[r][col] == 0))
        M[col], M[piv] = M[piv], M[col]
        p = M[col][col]
        M[col] = [v / p for v in M[col]]
        for r in range(n):
            if r != col and not (M[r][col] == 0):
                f = M[r][col]
                M[r] = [M[r][c] - f * M[col][c] for c in range(2 * n)]
    return [row[n:] for row in M]


GI = inverse(gram())


def bil(u, v):
    return sum((GI[r][s] * u[r] * v[s] for r in range(6) for s in range(6)), C())


def grip_values(Zs, lam):
    """<P, U_j> = M_{U_j ^ I}, I = n_inf + lam n_0, by bilinearity of U ^ V -> A(U ^ V)."""
    d = moment(A_grading(), Zs)                     # M_{n_inf ^ n_0}
    v = [lam * d, -d]                               # M_{n_inf ^ I} = lam d ; M_{n_0 ^ I} = -d
    for (a, ap) in XS:
        x = unit_x(a, ap)
        v.append(moment(A_trans(x), Zs) + lam * moment(A_spec(x), Zs))
    return v


def PP_routeA(Zs, lam):
    v = grip_values(Zs, lam)
    return bil(v, v)


def br(u, w):            # eps_{ab} u^a w^b
    return u[0] * w[1] - u[1] * w[0]


def B(Zi, Zl, lam):      # B^{il} = <pi^i pi^l> + lam [omega^i omega^l]
    return br(Zi[2:], Zl[2:]) + lam * br(Zi[:2], Zl[:2])


def det4(M):
    if len(M) == 1:
        return M[0][0]
    return sum(((-1) ** c * M[0][c] * det4([row[:c] + row[c + 1:] for row in M[1:]]) for c in range(len(M))), C())


def B_eps(Zi, Zl, lam):
    """B^{il} = eps(I ^ Z^i ^ Z^l) with eps(e1 e2 e3 e4) = 1, n_inf = e1^e2, n_0 = e3^e4: a 4x4
    determinant route independent of the bracket formula."""
    def e(k):
        return [C(1 if j == k else 0) for j in range(4)]
    t1 = det4([e(0), e(1), Zi, Zl])          # eps(e1 ^ e2 ^ Zi ^ Zl), as columns (det of transpose)
    t2 = det4([e(2), e(3), Zi, Zl])
    return t1 + lam * t2


def trace(M):
    return sum((M[k][k] for k in range(len(M))), C())


def mm(X, Y):
    n = len(X)
    return [[sum((X[r][k] * Y[k][c] for k in range(n)), C()) for c in range(n)] for r in range(n)]


def C_N(h):
    t1 = trace(mm(h, h)); t0 = trace(h)
    return t1 * F(1, 2) - t0 * t0 * F(1, 4)



def det2(M):
    return M[0][0] * M[1][1] - M[0][1] * M[1][0]


def adj(M):
    return [[M[c][r].conj() for c in range(2)] for r in range(2)]


def line(mu, p):
    """The conformal spinor mu pi + pi of the plane omega = mu pi."""
    return [mu[0][0] * p[0] + mu[0][1] * p[1], mu[1][0] * p[0] + mu[1][1] * p[1], p[0], p[1]]


def mu_of_x(x):
    """mu_x of the exact join (4): (mu_x pi)^a = x^{aa'} eps_{b'a'} pi^{b'}."""
    return [[sum((cc(x[a][ap]) * EPS[bp][ap] for ap in range(2)), C()) for bp in range(2)] for a in range(2)]


def Q_of_x(x):
    G = gram()
    v = [cc(x[a][ap]) for (a, ap) in XS]
    return sum((G[2 + r][2 + s] * v[r] * v[s] for r in range(4) for s in range(4)), C())


def source(b, Om, lam):
    """(2 Lambda / 3) Re(conj(b) Omega) with Lambda = 6 lam."""
    return 4 * lam * (b.conj() * Om).re


def check_massless_composites():
    premise("mass.exact-join")
    premise("mass.de-sitter-scale-frozen-point")
    premise("families.source-term-linear-tilt-mass-functional")
    premise("synthesis.many-twistor-join")
    pis = [([C(1), C(2, 1)], [C(0, 1), C(-1, 3)]), ([C(1, 2), C(0)], [C(2), C(1, -1)])]
    # (1) generic lines omega = mu pi (mu not anti-Hermitian): Gram, brackets, join from the definition
    for lam in (F(1, 6), F(2, 3)):
        for mu in ([[C(1, 1), C(2)], [C(0, -1), C(3, 1)]], [[C(0, 2), C(1, -1)], [C(2, 1), C(-1)]]):
            for (p1, p2) in pis:
                Zs = [line(mu, p1), line(mu, p2)]
                b = br(p1, p2)
                h = gram_h(Zs)
                S = [[mu[r][c] + adj(mu)[r][c] for c in range(2)] for r in range(2)]
                for i, pi in enumerate((p1, p2)):
                    for l, pl in enumerate((p1, p2)):
                        Sp = [S[0][0] * pl[0] + S[0][1] * pl[1], S[1][0] * pl[0] + S[1][1] * pl[1]]
                        assert h[i][l] == pi[0].conj() * Sp[0] + pi[1].conj() * Sp[1]
                assert br(Zs[0][:2], Zs[1][:2]) == det2(mu) * b
                assert B(Zs[0], Zs[1], lam) == (1 + lam * det2(mu)) * b == B_eps(Zs[0], Zs[1], lam)
                assert PP_routeA(Zs, lam) == C(2 * abs2(B(Zs[0], Zs[1], lam)) + 2 * lam * C_N(h).re)
    # mu_x is the chart's line of x and 1 + lam det mu_x = sigma(x) = 1 - lam Q(x) / 2
    for x in ([[1, 2], [3, 5]], [[F(1, 2), 0], [1, -3]]):
        mux = mu_of_x(x)
        assert det2(mux) == Q_of_x(x) * F(-1, 2)
        for (p1, p2) in pis:
            Zs = [line(mux, p1), line(mux, p2)]
            assert B_eps(Zs[0], Zs[1], F(1, 6)) == (1 - F(1, 6) * Q_of_x(x) * F(1, 2)) * br(p1, p2)
    # (1)-(2a) real points: mu = i Y, Y Hermitian; h = 0 and m^2 = 2 sigma^2 |<pi pi>|^2;
    # massless exactly at det Y = 1/lam, i.e. sigma = 0
    for lam, Y in ((F(1, 2), [[C(2), C(1, 1)], [C(1, -1), C(2)]]),
                   (F(1, 6), [[C(3), C(1, 1)], [C(1, -1), C(F(8, 3))]]),
                   (F(3), [[C(1), C(F(1, 3), F(1, 3))], [C(F(1, 3), F(-1, 3)), C(F(5, 9))]])):
        assert det2(Y) == C(1 / lam)
        for shift in (0, 1, -2):
            Ys = [[Y[0][0] + shift, Y[0][1]], [Y[1][0], Y[1][1]]]
            mu = [[I * Ys[r][c] for c in range(2)] for r in range(2)]
            assert all(mu[r][c] + adj(mu)[r][c] == 0 for r in range(2) for c in range(2))
            sig = 1 + lam * det2(mu)
            assert sig.im == 0
            for (p1, p2) in pis:
                Zs = [line(mu, p1), line(mu, p2)]
                b = br(p1, p2)
                Om = br(Zs[0][:2], Zs[1][:2])
                assert all(v == 0 for row in gram_h(Zs) for v in row)
                m2 = PP_routeA(Zs, lam)
                assert m2 == C(2 * sig.re * sig.re * abs2(b))
                if shift == 0:
                    # massless, and (3): Omega = -b / lam, source derivative -4 b, source term -4 |b|^2
                    assert sig == 0 and m2 == 0 and B(Zs[0], Zs[1], lam) == 0
                    assert Om == b * (-1 / lam)
                    assert Om * (4 * lam) == b * (-4)
                    assert source(b, Om, lam) == -4 * abs2(b)
                    # (4) a third constituent in the plane keeps it massless
                    Z3 = [Zs[0][q] * C(2, -1) + Zs[1][q] * C(F(1, 3)) for q in range(4)]
                    assert PP_routeA(Zs + [Z3], lam) == 0
                else:
                    assert m2 != 0
    # (2b) the sphere at infinity: span{(omega, 0), (0, pi)} with conj(omega) . pi = 0
    for lam in (F(1, 6), F(2)):
        for w0 in ([C(1), C(2, -1)], [C(0, 1), C(3)], [C(1), C(0)]):
            p = [w0[1].conj(), -w0[0].conj()]
            Zs = [[w0[0], w0[1], C(), C()], [C(), C(), p[0], p[1]]]
            assert all(v == 0 for row in gram_h(Zs) for v in row)
            b, Om = br(Zs[0][2:], Zs[1][2:]), br(Zs[0][:2], Zs[1][:2])
            assert b == 0 and Om == 0 and source(b, Om, lam) == 0
            # on the boundary at the chart's infinity: <n_inf, X> = <n_0, X> = 0, so <I_Lambda, X> = 0 for every lambda
            assert B_eps(Zs[0], Zs[1], F(0)) == 0 and B_eps(Zs[0], Zs[1], F(1)) == 0
            assert PP_routeA(Zs, lam) == 0
            # tilting pi off the orthogonal line leaves the locus
            Zt = [Zs[0], [C(), C(), p[0] + w0[0], p[1] + w0[1]]]
            assert PP_routeA(Zt, lam) != 0
        # the plane pi = 0 itself is massive: m^2 = 2 lam^2 |[omega omega]|^2
        Zs = [[C(1), C(2), C(), C()], [C(0, 1), C(-1), C(), C()]]
        Om = br(Zs[0][:2], Zs[1][:2])
        assert PP_routeA(Zs, lam) == C(2 * lam * lam * abs2(Om)) and Om != 0
    return True

synthesis.massless-frequency-sign-relati:
"""Frequency sign relative to I4 against the chirality of massless even spinors: exact checks.

Conventions of the store: Cl(1,3), g0^2 = +1, g1^2 = g2^2 = g3^2 = -1, I4 = g0 g1 g2 g3, spinors are even
multivectors, the field theory's unit is I4 (central in the even algebra, so L_I4 = R_I4 on spinors),
I sigma3 = I4 g3 g0 = g2 g1. For a future null k = w (g0 + n), n spatial with Q(n) = -1, B_k = g0 n (for
k = g0 + g1 this is the stored wedge boost B = g0 g1) and D_k = I4 B_k (the stored identity I4 B = D = g2 g3).
S_k = {psi even : k psi = 0}; a mode is exp(-s I4 k.x) psi0 with psi0 in S_k and s = +1 or -1.
Gamma(psi) = I4 psi I sigma3 is the chirality; the store's projectors chi_e (field-theory.fock-space-maxwell-
modes) project onto Gamma = -e.

(i)  On S_k: dim 4, L_{B_k} = -1, L_{D_k} = -L_I4; the right-handed rotor about n, cos - sin I sigma_n with
     I sigma_n = -D_k, acts as cos - sin I4 (helicity +1/2 along n relative to I4); a Lorentz rotor R carries
     S_k onto S_{R k R~}. Samples: k = g0 + g1 and its images under rational rotors (rotations and a boost).
(ii) Gamma^2 = 1, L_I4 = -Gamma R_{I sigma3} on all of Cl+(1,3), Gamma commutes with the left bivector action,
     preserves S_k with 2-dimensional eigenspaces there, and Gamma = -e on the store's chi_e.
(iii) The real-linear maps of Cl+(1,3) commuting with left multiplication by the six bivectors form an
     8-dimensional space containing the 8 right multiplications by even blades, and every one commutes with L_I4.
(iv) For psi(x) -> a psi(Lambda^{-1} x) b, a, b blades of the same parity, Lambda in {1, P, T, PT}: the
     massless equation is preserved on the samples exactly for a in {1, I4} (Lambda = 1, PT) and a in
     {g0, g0 I4} (Lambda = P, T); for those, s' = s (-1)^{|a|} sgn(g0 . Lambda k), flipped exactly for P and PT;
     Gamma' = Gamma (-1)^{|a|} c(b), c(b) = +1 or -1 as b commutes or anticommutes with I sigma3; Hestenes
     C (b = sigma1) flips Gamma and not s, a CP map (a = g0, b = g0 sigma1) flips s and not Gamma.
Exact arithmetic only.
"""
from fractions import Fraction as F
import GA
from tp_premise import premise

SQ = GA.sig(1, 3)
G = [GA.gen(i) for i in range(4)]
BL = GA.all_blades(4)
EVEN = [b for b in BL if len(b) % 2 == 0]


def _m(*xs):
    r = GA.sc(1)
    for x in xs:
        r = GA.mul(r, x, SQ)
    return r


I4 = _m(*G)
ISIG3 = _m(I4, G[3], G[0])
SIG1 = _m(G[1], G[0])


def _bl(b):
    return {tuple(b): F(1)}


def _vec(x):
    return [x.get(b, F(0)) for b in EVEN]


def _unvec(v):
    return {b: c for b, c in zip(EVEN, v) if c != 0}


def _L(a):
    return lambda x: GA.mul(a, x, SQ)


def _R(b):
    return lambda x: GA.mul(x, b, SQ)


def _gamma(x):
    return GA.mul(GA.mul(I4, x, SQ), ISIG3, SQ)


def _mat(f):
    cols = [_vec(f(_bl(b))) for b in EVEN]
    return [[cols[j][i] for j in range(len(EVEN))] for i in range(len(EVEN))]


def _ident():
    n = len(EVEN)
    return [[F(1) if i == j else F(0) for j in range(n)] for i in range(n)]


def _null_kernel(k):
    """Basis of S_k: even psi with k psi = 0 (k psi is odd, all coordinates kept)."""
    cols = [[GA.mul(k, _bl(b), SQ).get(c, F(0)) for c in BL] for b in EVEN]
    M = [[cols[j][i] for j in range(len(EVEN))] for i in range(len(BL))]
    return [_unvec(v) for v in GA.field_kernel(M)]


def _cayley(biv, t):
    return GA.add(GA.sc(1), GA.scal(t, biv))


def _sandwich(R, x):
    nrm = GA.mul(R, GA.reverse(R), SQ).get((), F(0))
    return GA.scal(F(1) / nrm, _m(R, x, GA.reverse(R)))


K0 = GA.add(G[0], G[1])
ROTORS = [_cayley(_m(G[1], G[3]), F(1, 2)), _cayley(_m(G[1], G[2]), F(2, 3)),
          _cayley(_m(G[2], G[3]), F(3, 5)), _cayley(_m(G[0], G[1]), F(1, 3))]
KS = [K0] + [_sandwich(R, K0) for R in ROTORS[:3]]
BOOSTED = _sandwich(ROTORS[3], K0)


def _time(k):
    return k.get((0,), F(0))


def _bk(k):
    n = GA.scal(F(1) / _time(k), {b: c for b, c in k.items() if b != (0,)})
    return _m(G[0], n)


def _modes(k):
    """Gamma eigenvectors in S_k, one per eigenvalue."""
    out = {}
    for psi in _null_kernel(k):
        for gm in (1, -1):
            p = GA.scal(F(1, 2), GA.add(psi, GA.scal(F(gm), _gamma(psi))))
            if not GA.is_zero(p) and gm not in out:
                out[gm] = p
    return out


def check_null_kernel_locks_helicity_to_the_frequency_sign():
    premise("field-theory.fock-space-maxwell-modes")
    ok_dim = ok_b = ok_d = ok_rot = ok_cov = True
    c, s = F(4, 5), F(3, 5)
    for k in KS + [BOOSTED]:
        Sk = _null_kernel(k)
        Bk = _bk(k)
        Dk = _m(I4, Bk)
        isn = GA.neg(Dk)
        ok_dim = ok_dim and len(Sk) == 4
        for psi in Sk:
            ok_b = ok_b and GA.eq(_m(Bk, psi), GA.neg(psi))
            ok_d = ok_d and GA.eq(_m(Dk, psi), GA.neg(_m(I4, psi)))
            rot = GA.sub(GA.sc(c), GA.scal(s, isn))
            ok_rot = ok_rot and GA.eq(_m(rot, psi), GA.sub(GA.scal(c, psi), GA.scal(s, _m(I4, psi))))
            for R in ROTORS:
                ok_cov = ok_cov and GA.is_zero(_m(_sandwich(R, k), R, psi))
    GA.check("(i) dim S_k = 4 on every sample", ok_dim)
    GA.check("(i) L_{B_k} = -1 on S_k", ok_b)
    GA.check("(i) L_{D_k} = -L_I4 on S_k, D_k = I4 B_k", ok_d)
    GA.check("(i) right-handed rotor about n acts as cos - sin I4: helicity +1/2 along n", ok_rot)
    GA.check("(i) a rotor R carries S_k into S_{R k R~}", ok_cov)
    GA.check("(i) stored identity: I4 g0 g1 = g2 g3", GA.eq(_m(I4, G[0], G[1]), _m(G[2], G[3])))
    GA.check("(i) B_k of g0 + g1 is g0 g1", GA.eq(_bk(K0), _m(G[0], G[1])))
    GA.check("(i) Q(I sigma_n) = -1 for k = g0 + g1", GA.eq(_m(_m(G[3], G[2]), _m(G[3], G[2])), GA.sc(-1)))
    # the rotor cos + sin D_k (half angle 4/5, 3/5) turns g2 towards g3 about n = g1: right-handed for
    # the spatial orientation I3 = g1 g2 g3 = g0 I4 (cos = 7/25, sin = 24/25)
    rot = GA.add(GA.sc(c), GA.scal(s, _m(G[2], G[3])))
    img = _sandwich(rot, G[2])
    GA.check("(i) the rotor is right-handed about g1 for I3 = g0 I4",
             GA.eq(img, GA.add(GA.scal(F(7, 25), G[2]), GA.scal(F(24, 25), G[3])))
             and GA.eq(_m(G[1], G[2], G[3]), _m(G[0], I4)))


def check_the_unit_is_minus_chirality_times_the_charge_rotation():
    premise("field-theory.fock-space-maxwell-modes")
    Gm = _mat(_gamma)
    LI = _mat(_L(I4))
    RH = _mat(_R(ISIG3))
    GA.check("(ii) Gamma^2 = 1", GA.mat_eq(GA.mat_mul(Gm, Gm), _ident()))
    GA.check("(ii) L_I4 = -Gamma R_{I sigma3}",
             GA.mat_eq(LI, [[-x for x in r] for r in GA.mat_mul(Gm, RH)]))
    GA.check("(ii) L_I4 = R_I4 on even spinors", GA.mat_eq(LI, _mat(_R(I4))))
    ok = all(GA.mat_eq(GA.mat_mul(Gm, _mat(_L(_m(G[i], G[j])))), GA.mat_mul(_mat(_L(_m(G[i], G[j]))), Gm))
             for i in range(4) for j in range(i + 1, 4))
