def _vdot(a, b):
    return _grade(_m4(a, b), 0).get((), F(0))


def _padd(*fs):
    out = {}
    for f in fs:
        for e, mv in f.items():
            out[e] = GA.add(out.get(e, {}), mv)
    return {e: mv for e, mv in out.items() if mv}


def _pneg(f):
    return {e: GA.neg(mv) for e, mv in f.items()}


def _pmul(f, h):
    out = {}
    for e1, m1 in f.items():
        for e2, m2 in h.items():
