def check_flip_defect_and_the_generator_bound():
    premise("field-theory.imported-tower-limit")
    premise("synthesis.null-vacuum-on-a-horizon-generator")
    premise("synthesis.fluctuation-forms-of-the-tower-and-density-wave-bosons-of-the-null-vacuum")
    premise("synthesis.bulk-hadamard-states-restrict-to-the-generator-condition-on-flat-null-planes")
    # one copy, L = 3, bottom level filled
    L = 3
    T = _Tower(2 * L)
    idx = lambda a, k: a * L + (k - 1)
    Jc = lambda a, b, m: _current(T, idx, L, a, b, m)
    P = T.proj([1, 0, 0, 1, 0, 0])
    X = T.comm(Jc(0, 1, 0), Jc(1, 0, -1))
    GA.check("[J^{+-}_0, J^{-+}_-1] = J^{++}_-1 - J^{--}_-1 = 2 J^3_-1", GA.eq(X, GA.sub(Jc(0, 0, -1), Jc(1, 1, -1))))
    GA.check("one copy: ||[J^+_0, J^-_-1] Omega||^2 = 2", T.omega(P, T.m(T.star(X), X)) == 2)
    L4 = 4
    T4 = _Tower(2 * L4)
    i4 = lambda a, k: a * L4 + (k - 1)
    J4 = lambda a, b, m: _current(T4, i4, L4, a, b, m)
    P4 = T4.proj([1, 1, 0, 0, 1, 1, 0, 0])
    nr = []
    for m, n in ((1, -2), (0, -2), (-1, -1)):
        X2 = T4.comm(J4(0, 1, m), J4(1, 0, n))
        nr.append(T4.omega(P4, T4.m(T4.star(X2), X2)))
    GA.check("one copy, L = 4, depth 2: ||[J^+_m, J^-_n] Omega||^2 = 2|m + n| = 2, 4, 4", nr == [2, 4, 4])
    # N generators, L = 2: modes (g, a, k); M[g][h] weights c*_{g,+,k} c_{h,-,k+m}
    def run(Nf, Ms):
        L2 = 2
        T2 = _Tower(Nf * 2 * L2)
        ix = lambda f, a, k: (f * 2 + a) * L2 + (k - 1)
        P2 = T2.proj([1 if k == 1 else 0 for f in range(Nf) for a in (0, 1) for k in range(1, L2 + 1)])

        def flip(M, a, b, m):
            out = {}
            for f in range(Nf):
                for g in range(Nf):
                    if M[f][g]:
                        for k in range(1, L2 + 1):
                            if 1 <= k + m <= L2:
                                out = GA.add(out, GA.scal(M[f][g], T2.bil(ix(f, a, k), ix(g, b, k + m))))
            return out
        res = []
        for M in Ms:
            Mt = [[M[g][f] for g in range(Nf)] for f in range(Nf)]
            MMt = [[sum(M[f][h] * M[g][h] for h in range(Nf)) for g in range(Nf)] for f in range(Nf)]
            tr = sum(MMt[f][f] for f in range(Nf))
            fro = sum(MMt[f][g] ** 2 for f in range(Nf) for g in range(Nf))
            D = T2.comm(flip(M, 0, 1, 0), flip(Mt, 1, 0, -1))
            nrm = T2.omega(P2, T2.m(T2.star(D), D))
            cen = T2.omega(P2, T2.comm(flip(M, 0, 1, 1), flip(Mt, 1, 0, -1)))
            ident = all(M[f][g] == (1 if f == g else 0) for f in range(Nf) for g in range(Nf))
            res.append((nrm, fro, tr, cen, ident))
        return res
    r2 = run(2, ([[1, 0], [0, 1]], [[1, 1], [0, 1]], [[2, 0], [1, 1]]))
    GA.check("two generators: ||D Omega||^2 = 2 ||M M*||_F^2, central value tr(M M*), bound 2 tr^2 / 2 attained only at M = 1",
             all(n == 2 * fr and c == t and n * 2 >= 2 * t * t and ((n * 2 == 2 * t * t) == i) for n, fr, t, c, i in r2)
             and [x[0] for x in r2] == [4, 14, 56])
    # a J-valued weight matrix on two generators: M = [[1, J], [2, -J]], M* its conjugate transpose
    L2 = 2
    T2 = _Tower(2 * 2 * L2)
    ix = lambda f, a, k: (f * 2 + a) * L2 + (k - 1)
    P2 = T2.proj([1 if k == 1 else 0 for f in range(2) for a in (0, 1) for k in range(1, L2 + 1)])
    one, Jt = GA.sc(1), T2.J
    Mc = [[one, Jt], [GA.scal(2, one), GA.neg(Jt)]]

    def cflip(M, a, b, m):
        out = {}
        for f in range(2):
            for g in range(2):
                for k in range(1, L2 + 1):
                    if 1 <= k + m <= L2:
                        out = GA.add(out, T2.m(M[f][g], T2.bil(ix(f, a, k), ix(g, b, k + m))))
        return out
    Mh = [[T2.star(Mc[g][f]) for g in range(2)] for f in range(2)]
    Dc = T2.comm(cflip(Mc, 0, 1, 0), cflip(Mh, 1, 0, -1))
    GA.check("J-valued M = [[1, J], [2, -J]]: ||D Omega||^2 = 2 * 31 = 62 and central value tr M M* = 7",
             T2.omega(P2, T2.m(T2.star(Dc), Dc)) == 62 and T2.omega(P2, T2.comm(cflip(Mc, 0, 1, 1), cflip(Mh, 1, 0, -1))) == 7)
    r3 = run(3, ([[1, 0, 0], [0, 1, 0], [0, 0, 1]],))
    GA.check("three generators, uniform: ||D Omega||^2 = 6, central value 3: normalised defect 2/3", r3[0][0] == 6 and r3[0][3] == 3)
    # null translations along the generator: H = sum_k k n_{a,k}
    H = {}
    for a in (0, 1):
        for k in range(1, L + 1):
            H = GA.add(H, GA.scal(k, T.num(idx(a, k))))
    GA.check("[H, J^ab_m] = -m J^ab_m for all a, b and m = -2..2 (linear dispersion along the generator)",
             all(GA.eq(T.comm(H, Jc(a, b, m)), GA.scal(-m, Jc(a, b, m))) for a in (0, 1) for b in (0, 1) for m in range(-2, 3)))
    return True

synthesis.number-diagonal-dynamics-sprea:
"""synthesis.number-diagonal-dynamics-spreads-nothing: exact checks.

Four CAR modes in Cl(4,4): v_k = (e_k + e_{4+k})/2, v_k^* = (e_k - e_{4+k})/2, sigma_k = e_k e_{4+k}.
check_diagonal_support_never_grows: for number-diagonal H (chain couplings sigma_j sigma_{j+1},
a field on mode 0, and a three-body term sigma_0 sigma_1 sigma_2) the nested commutators
ad_H^n(v_0), n = 1..5, equal v_0 (-2 H_1)^n with H = H_0 + sigma_0 H_1, and never involve mode 3
(nor mode 2 when the three-body term is absent); adding a hop between modes 1, 2 and 2, 3 makes
ad^2 reach mode 2 and ad^3 reach mode 3.
check_real_time_dressing_exact: with all-to-all couplings and cos = 3/5, sin = 4/5, the exact unitary
U = prod_k (cos + i sin sigma_0 sigma_k) gives U v_0 U^{-1} = v_0 prod_k (cos 2 - i sin 2 sigma_k) with
(cos 2, sin 2) = (-7/25, 24/25), whose size distribution is binomial with mean 3 (24/25)^2; and the
evolved v_0 anticommutes with v_3, v_3^* on the chain (no out-of-time-order growth outside N(0)).
"""
from fractions import Fraction as F
import GA
from tp_premise import premise

SQ = GA.sig(4, 4)
NM = 4


def v(k):
    return GA.scal(F(1, 2), GA.add(GA.gen(k), GA.gen(NM + k)))


def vs(k):
    return GA.scal(F(1, 2), GA.sub(GA.gen(k), GA.gen(NM + k)))


def m(*xs):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, SQ)
    return out


def sig(k):
    return GA.sub(m(vs(k), v(k)), m(v(k), vs(k)))


def ad(H, X):
    return GA.sub(m(H, X), m(X, H))


def support(X):
    s = set()
    for b in X:
        for g in b:
            s.add(g % NM)
    return s


def check_diagonal_support_never_grows():
    premise("singularity.modular-structure-completed-pair")
    premise("singularity.number-diagonal-dynamics-models-scrambling-derived")
    for k in range(NM):
        assert GA.eq(sig(k), GA.mul(GA.gen(k), GA.gen(NM + k), SQ))
        assert GA.eq(m(v(k), sig(k)), v(k))                         # v sigma = v
        assert GA.eq(m(sig(k), v(k)), GA.neg(v(k)))                 # sigma v = -v
    s0, s1, s2, s3 = sig(0), sig(1), sig(2), sig(3)
    for three in (0, 5):
        H1 = GA.add(GA.sc(F(1, 3)), GA.scal(2, s1), GA.scal(three, m(s1, s2)))
        H = GA.add(m(s0, H1), GA.scal(F(-1, 2), m(s1, s2)), GA.scal(7, m(s2, s3)), GA.scal(F(5, 4), s3))
        X, P = v(0), GA.sc(1)
        for n in range(1, 6):
            X = ad(H, X)
            P = m(P, GA.scal(-2, H1))
            assert GA.eq(X, m(v(0), P))                             # ad^n v0 = v0 (-2 H_1)^n
            assert 3 not in support(X)
            assert (2 in support(X)) == (three != 0)
            assert support(X) <= {0, 1, 2}
            if three == 0:
                # (-2 H_1)^n = ((a+b)^n + (a-b)^n)/2 + sigma_1 ((a+b)^n - (a-b)^n)/2, a + b = -14/3, a - b = 10/3
                p_, q_ = F(-14, 3) ** n, F(10, 3) ** n
                assert GA.eq(X, GA.add(GA.scal((p_ + q_) / 2, v(0)), GA.scal((p_ - q_) / 2, m(v(0), s1))))
    # a hop (outside the diagonal algebra) propagates along the chain
    hop = GA.add(m(vs(1), v(2)), m(vs(2), v(1)), m(vs(2), v(3)), m(vs(3), v(2)))
    Hh = GA.add(GA.scal(2, m(s0, s1)), hop)
    X = v(0)
    reach = []
    for n in range(1, 4):
        X = ad(Hh, X)
        reach.append(max(support(X)))
    assert reach == [1, 2, 3]
    return True


def qmul(x, y):
    # Clifford product with Gaussian-rational coefficients
    out = {}
    for b1, c1 in x.items():
        for b2, c2 in y.items():
            s, b = GA.blade_mul(b1, b2, SQ)
            c = c1 * c2 * s
            if c != 0:
                out[b] = out.get(b, GA.QI(0)) + c
    return {b: c for b, c in out.items() if c != 0}


def qadd(*xs):
    out = {}
    for x in xs:
        for b, c in x.items():
            out[b] = out.get(b, GA.QI(0)) + c
    return {b: c for b, c in out.items() if c != 0}


def q(x, c=1):
    return {b: GA.QI(cc) * c for b, cc in x.items()}


def check_real_time_dressing_exact():
    premise("singularity.number-diagonal-dynamics-models-scrambling-derived")
    premise("synthesis.phase-flow-is-time-rotor-flow-kms-continuation")
    c, s = F(3, 5), F(4, 5)
    assert c * c + s * s == 1
    I = GA.QI(0, 1)
    one = q(GA.sc(1))
    U, Ui = one, one
    for k in (1, 2, 3):
        Z = q(m(sig(0), sig(k)))
        U = qmul(U, qadd(q(GA.sc(c)), {b: z * I * s for b, z in Z.items()}))
        Ui = qmul(Ui, qadd(q(GA.sc(c)), {b: z * I * (-s) for b, z in Z.items()}))
    assert qmul(U, Ui) == one                                       # unitary, exactly
    ev = qmul(U, qmul(q(v(0)), Ui))
    c2, s2 = c * c - s * s, 2 * s * c
    assert (c2, s2) == (F(-7, 25), F(24, 25))
    D = one
    for k in (1, 2, 3):
        D = qmul(D, qadd(q(GA.sc(c2)), {b: z * I * (-s2) for b, z in q(sig(k)).items()}))
    assert qadd(ev, q(qmul(q(v(0)), D), -1)) == {}                  # v0(t) = v0 prod_k (c2 - i s2 sigma_k)
    # size distribution: weight of |S| = j in the product is C(3, j) s2^{2j} c2^{2(3-j)}; mean 3 s2^2
    w = [1 * c2 ** 6, 3 * s2 ** 2 * c2 ** 4, 3 * s2 ** 4 * c2 ** 2, s2 ** 6]
    assert sum(w) == 1
    assert sum(j * w[j] for j in range(4)) == 3 * s2 ** 2 == F(1728, 625)
    # chain dressing: v0 evolved under J sigma_0 sigma_1 only anticommutes with v3, v3^*
    Uc = qadd(q(GA.sc(c)), {b: z * I * s for b, z in q(m(sig(0), sig(1))).items()})
    Uci = qadd(q(GA.sc(c)), {b: z * I * (-s) for b, z in q(m(sig(0), sig(1))).items()})
    evc = qmul(Uc, qmul(q(v(0)), Uci))
    for w3 in (v(3), vs(3)):
        assert qadd(qmul(evc, q(w3)), qmul(q(w3), evc)) == {}
    assert qadd(qmul(evc, q(v(1))), qmul(q(v(1)), evc)) != {}       # mode 1 is reached
    return True

synthesis.one-loop-self-energy-and-verte:
"""Exact checks: the one-loop electron self-energy and vertex extended across coincident points with the
Ward-Takahashi identity holding for the pair of extensions at one common cut-off length (Euclidean section, Cl(4,0),
units hbar = c = 1; method and conventions of the stored vacuum polarisation result).

Notation: w a vector of Cl(4,0), s = Q(w), L = ln s (the scale mu = 1 throughout; a scale M enters as ln(M^2 s) =
L + ln M^2). Propagators S0(w) = w/(2 pi^2 s^2), photon D_ab(w) = ((1 + xi)/2 delta_ab + (1 - xi) w_a w_b / s)/(4 pi^2 s)
with gauge parameter xi (xi = 1 Feynman, xi = 0 Landau).

Two exact calculi are used.
(A) Off the origin: polynomials in the four components times s^a L^k, differentiated exactly
    (dict {(e0, e1, e2, e3, a, k): Fraction}).
(B) Pairings with test functions g = P(w) (1 - s)^N on the unit ball (zero outside; C^(N-1), so they pair with the
    distributions of order at most 3 that occur for N = 5). Integrals over the ball of w^e s^a L^k are exact
    rationals times pi^2: angular average of a monomial over the 3-sphere times |S^3| = 2 pi^2 times a radial
    integral int_0^1 t^p (ln t)^k dt = (-1)^k k!/(p + 1)^(k + 1). A distributional derivative of a locally
    integrable function is paired by moving the derivatives to g. Every pairing below is returned in units of pi^2.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

SIG4 = (1, 1, 1, 1)
E = [GA.gen(i) for i in range(4)]


def _m(x, y):
    return GA.mul(x, y, SIG4)


def _vec(c):
    return {(i,): F(v) for i, v in enumerate(c) if v != 0}


# ------------------------------------------------------------------ calculus (A) and (B)
def padd(*ps):
    out = {}
    for p in ps:
        for k, v in p.items():
            out[k] = out.get(k, F(0)) + v
    return {k: v for k, v in out.items() if v != 0}


def pscl(c, p):
    c = F(c)
    return {k: c * v for k, v in p.items() if c * v != 0}


def pmul(p, q):
    out = {}
    for k1, v1 in p.items():
        for k2, v2 in q.items():
            k = tuple(x + y for x, y in zip(k1, k2))
            out[k] = out.get(k, F(0)) + v1 * v2
    return {k: v for k, v in out.items() if v != 0}


def mono(e=(0, 0, 0, 0), a=0, k=0, c=1):
    return {tuple(e) + (a, k): F(c)}


def comp(i):
    e = [0, 0, 0, 0]
    e[i] = 1
    return mono(e)


def d(i, p):
    """Partial derivative d/dw_i of sum c w^e s^a L^k (off the origin for singular terms)."""
    out = {}

    def put(key, v):
        out[key] = out.get(key, F(0)) + v

    for key, v in p.items():
        e, a, k = list(key[:4]), key[4], key[5]
        if e[i]:
            e2 = list(e)
            e2[i] -= 1
            put(tuple(e2) + (a, k), v * e[i])
        e2 = list(e)
        e2[i] += 1
        if a:
            put(tuple(e2) + (a - 1, k), v * 2 * a)
        if k:
            put(tuple(e2) + (a - 1, k - 1), v * 2 * k)
    return {k: v for k, v in out.items() if v != 0}


def lap(p):
    return padd(*[d(i, d(i, p)) for i in range(4)])


def normal(p):
    """Canonical form: trade w_3^2 = s - w_0^2 - w_1^2 - w_2^2 so that equal functions have equal dicts."""
    out = dict(p)
    changed = True
    while changed:
        changed = False
        new = {}
        for key, v in out.items():
            e, a, k = list(key[:4]), key[4], key[5]
            if e[3] >= 2:
                changed = True
                e[3] -= 2
                kk = tuple(e) + (a + 1, k)
                new[kk] = new.get(kk, F(0)) + v
                for j in range(3):
                    e2 = list(e)
                    e2[j] += 2
                    kk = tuple(e2) + (a, k)
                    new[kk] = new.get(kk, F(0)) - v
            else:
                new[key] = new.get(key, F(0)) + v
        out = {k: v for k, v in new.items() if v != 0}
    return out


def same(p, q):
    return normal(padd(p, pscl(-1, q))) == {}


def factorial(k):
    out = 1
    for j in range(2, k + 1):
        out *= j
    return out


def sphere_average(e):
    """Average of w^e / |w|^|e| over the unit 3-sphere: prod (e_i - 1)!! / (4 * 6 * ... ) for even exponents."""
    if any(x % 2 for x in e):
        return F(0)
    num = 1
    for x in e:
        for j in range(x - 1, 0, -2):
            num *= j
    den = 1
    for j in range(sum(e) // 2):
        den *= 4 + 2 * j
    return F(num, den)


def ball(p):
    """Integral over the unit ball of sum c w^e s^a L^k, in units of pi^2. Raises if a term is not integrable."""
    tot = F(0)
    for key, v in p.items():
        e, a, k = key[:4], key[4], key[5]
        av = sphere_average(e)
        if av == 0:
            continue
        # d^4w = |S^3| r^3 dr = pi^2 t dt (t = s); integrand t^(|e|/2 + a) (ln t)^k
        pw = F(sum(e), 2) + a + 1
        if pw <= -1:
            raise ValueError("not locally integrable")
        tot += v * av * (-1) ** k * factorial(k) / (pw + 1) ** (k + 1)
    return tot


def bump(poly, n=5):
    """g = poly(w) (1 - s)^n as a polynomial dict (support the unit ball)."""
    one_minus_s = {(0, 0, 0, 0, 0, 0): F(1), (0, 0, 0, 0, 1, 0): F(-1)}
    g = {(0, 0, 0, 0, 0, 0): F(1)}
    for _ in range(n):
        g = pmul(g, one_minus_s)
    return expand_s(pmul(poly, g))


def expand_s(p):
    """Write s^a (a >= 0) as a polynomial in the components (test functions only)."""
    ssum = padd(*[mono([2 if j == i else 0 for j in range(4)]) for i in range(4)])
    out = {}
    for key, v in p.items():
        e, a, k = key[:4], key[4], key[5]
        assert a >= 0 and k == 0
        term = {tuple(e) + (0, 0): v}
        for _ in range(a):
            term = pmul(term, ssum)
        out = padd(out, term)
    return out


def at0(p):
    return p.get((0, 0, 0, 0, 0, 0), F(0))


def taylor1(g):
    """g(0) + w . grad g(0)."""
    out = {}
    for key, v in g.items():
        if sum(key[:4]) <= 1:
            out[key] = v
    return out


TESTS = None


def tests():
    global TESTS
    if TESTS is None:
        p1 = padd(mono(c=1), comp(0), pscl(2, comp(1)), pscl(-1, pmul(comp(0), comp(2))), pscl(3, pmul(comp(1), comp(1))))
        p2 = padd(mono(c=2), pscl(-3, comp(2)), comp(3), pmul(comp(0), comp(0)), pscl(5, pmul(comp(2), comp(3))),
                  pmul(comp(1), pmul(comp(1), comp(3))))
        TESTS = [bump(p1), bump(p2)]
    return TESTS


LS = mono(a=-1, k=1)          # L / s
INV_S = mono(a=-1)            # 1 / s


# ------------------------------------------------------------------ check 1: the kernels in Cl(4,0)
def check_kernels_in_the_euclidean_algebra_and_their_gauge_dependence():
    premise("field-theory.second-quantisation")
    premise("field-theory.coupled-system-tree-level")
    premise("synthesis.one-loop-vacuum-polarisation-extends-without-a-regulator-and-ward-preserving-extensions-differ-only-by-the-renormalisation-constants")
    ok = True
    for c in ([1, 0, 0, 0], [1, 2, 0, 0], [3, -2, 5, 7], [1, 1, -4, 2]):
        w = _vec(c)
        s = sum(F(x) * x for x in c)
        for xi in (F(1), F(0), F(3), F(-2, 5)):
            # sum_ab e_a w e_b ((1 + xi)/2 delta_ab s + (1 - xi) w_a w_b) = -2 xi s w
            tot = {}
            mass = {}
            for a in range(4):
                for b in range(4):
                    coef = (1 - xi) * c[a] * c[b] + ((1 + xi) / 2 * s if a == b else 0)
                    if coef:
                        tot = GA.add(tot, GA.scal(coef, _m(_m(E[a], w), E[b])))
                        mass = GA.add(mass, GA.scal(coef, _m(E[a], E[b])))
            ok = ok and GA.eq(tot, GA.scal(-2 * xi * s, w))
            ok = ok and GA.eq(mass, {(): (3 + xi) * s})
    # coefficients: Sigma = e^2 e_a S0 e_b D_ab = -xi e^2 w/(4 pi^4 s^3); order m: (3 + xi) e^2 m/(16 pi^4 s^2)
    c_sigma = lambda xi: F(1, 2) * F(1, 4) * (-2 * xi)      # units e^2 pi^-4, times w/s^3
    c_mass = lambda xi: F(1, 4) * F(1, 4) * (3 + xi)        # units e^2 m pi^-4, times 1/s^2
    ok = ok and c_sigma(F(1)) == F(-1, 4) and c_sigma(F(0)) == 0 and c_mass(F(1)) == F(1, 4) and c_mass(F(0)) == F(3, 16)
    # sphere average of w_nu w = e_nu s/4 (the trace part of the zero-transfer vertex)
    for nu in range(4):
        for a in range(4):
            e = [0, 0, 0, 0]
            e[nu] += 1
            e[a] += 1
            ok = ok and sphere_average(e) == (F(1, 4) if a == nu else 0)
    GA.check("kernels: sandwich -2 xi w, mass part 3 + xi, sphere average e_nu s/4", ok)
    return ok


# ------------------------------------------------------------------ check 2: identities off the origin
def check_identities_off_the_origin():
    premise("field-theory.second-quantisation")
    premise("synthesis.imported-epstein-glaser-extension-theorem-and-ward-preserving-time-ordered-products")
    ok = True
    # S0 = w/s^2 (times 1/(2 pi^2)) is monogenic off the origin: d_i (w_j/s^2) symmetric and traceless
    s0 = [pmul(comp(j), mono(a=-2)) for j in range(4)]
    tr = {}
    for i in range(4):
        tr = padd(tr, d(i, s0[i]))
        for j in range(4):
            ok = ok and same(d(i, s0[j]), d(j, s0[i]))
    ok = ok and normal(tr) == {}
    # flux of S0 through the sphere: (w/s^2) . (w/r) r^3 |S^3| / (2 pi^2) = 1, so dslash S0 = delta
    ok = ok and F(1, 2) * 2 * sphere_average((0, 0, 0, 0)) == 1
    # dslash (w_nu S0) = e_nu S0 off the origin: d_i (w_nu w_j / s^2) - delta_(i nu) w_j/s^2 = w_nu d_i (w_j/s^2)
    for nu in range(4):
        tr = {}
        for i in range(4):
            lhs = d(i, pmul(comp(nu), s0[i]))
            tr = padd(tr, lhs)
        ok = ok and same(tr, s0[nu])                      # scalar part: e_nu . S0
        for i in range(4):
            for j in range(i + 1, 4):                     # bivector part: (e_nu ^ S0)_(ij)
                curl = padd(d(i, pmul(comp(nu), s0[j])), pscl(-1, d(j, pmul(comp(nu), s0[i]))))
                want = padd(s0[j] if i == nu else {}, pscl(-1, s0[i]) if j == nu else {})
                ok = ok and same(curl, want)
    # w_nu S0 is of degree -2: no delta at the origin (flux through a sphere of radius r scales as r)
    ok = ok and (-2 + 3) > 0
    # w/s^3 = (1/16) dslash box (L/s); 1/s^2 = -(1/4) box(L/s); box(1/s) = 0
    for a in range(4):
        ok = ok and same(pscl(F(1, 16), d(a, lap(LS))), pmul(comp(a), mono(a=-3)))
    ok = ok and same(pscl(F(-1, 4), lap(LS)), mono(a=-2)) and normal(lap(INV_S)) == {}
    # traceless part: (d_a d_nu - (1/4) delta box)(1/(8 s)) = (w_a w_nu - delta s/4)/s^3
    for a in range(4):
        for nu in range(4):
            lhs = pscl(F(1, 8), d(a, d(nu, INV_S)))
            rhs = pmul(pmul(comp(a), comp(nu)), mono(a=-3))
            if a == nu:
                rhs = padd(rhs, mono(a=-2, c=F(-1, 4)))
            ok = ok and same(lhs, rhs)
    # box(w_nu L/s) = 2 d_nu((L + 1)/s) off the origin (used for the product w_nu Sigma-bar)
    for nu in range(4):
        ok = ok and same(lap(pmul(comp(nu), LS)), pscl(2, d(nu, padd(LS, INV_S))))
    GA.check("off the origin: S0 monogenic with unit flux, dslash(w_nu S0) = e_nu S0, differential forms of "
             "w/s^3, 1/s^2 and the traceless part", ok)
    return ok


# ------------------------------------------------------------------ pairings
def pair_dist(F_loc, derivs, g):
    """< d_(i1) ... d_(ik) F_loc, g > = (-1)^k int F_loc d_(i1) ... d_(ik) g, units pi^2."""
    h = g
    for i in derivs:
        h = d(i, h)
    return (-1) ** len(derivs) * ball(pmul(F_loc, h))


def pair_lap(F_loc, g, extra=()):
    h = lap(g)
    for i in extra:
        h = d(i, h)
    return (-1) ** len(extra) * ball(pmul(F_loc, h))


def check_cut_off_extensions_against_the_logarithmic_forms():
    """[1/s^2]_1 = -(1/4) box(L/s) + pi^2 delta; [w/s^3]_1 = (1/16) dslash box(L/s) - (3 pi^2/8) dslash delta;
    [w_nu w_a/s^3]_1 = (d_a d_nu - delta box/4)(1/(8 s)) + (delta/4)(-(1/4) box(L/s) + pi^2 delta)."""
    premise("synthesis.imported-epstein-glaser-extension-theorem-and-ward-preserving-time-ordered-products")
    premise("synthesis.one-loop-vacuum-polarisation-extends-without-a-regulator-and-ward-preserving-extensions-differ-only-by-the-renormalisation-constants")
    ok = True
    consts = set()
    seen_gradient = False
    for g in tests():
        g0 = at0(g)
        # zero-order cut-off extension of 1/s^2 at radius 1
        cut = ball(pmul(mono(a=-2), padd(g, mono(c=-g0))))
        diff = cut - F(-1, 4) * pair_lap(LS, g)
        ok = ok and g0 != 0 and diff == 1 * g0                       # pi^2 delta
        consts.add(diff / g0)
        for a in range(4):
            # first-order cut-off extension of w_a/s^3 at radius 1
            cut = ball(pmul(pmul(comp(a), mono(a=-3)), padd(g, pscl(-1, taylor1(g)))))
            log_form = F(1, 16) * pair_lap(LS, g, extra=(a,))
            dg0 = at0(d(a, g))
            seen_gradient = seen_gradient or dg0 != 0
            # <dslash delta, g> = -dslash g(0): the difference is -(3 pi^2/8) dslash delta
            ok = ok and cut - log_form == F(3, 8) * dg0
            for nu in range(4):
                cutv = ball(pmul(pmul(pmul(comp(a), comp(nu)), mono(a=-3)), padd(g, mono(c=-g0))))
                trl = F(1, 8) * (pair_dist(INV_S, (a, nu), g) - (F(1, 4) * pair_lap(INV_S, g) if a == nu else 0))
                trc = (F(1, 4) * (F(-1, 4) * pair_lap(LS, g) + g0)) if a == nu else F(0)
                ok = ok and cutv == trl + trc
    ok = ok and consts == {F(1)} and seen_gradient
    # scales: -(1/4) box(ln(M^2 s)/s) = -(1/4) box(L/s) + pi^2 ln(M^2) delta, so [1/s^2]_1 has ln M_V^2 = 1;
    # (1/16) dslash box(ln(M^2 s)/s) = (1/16) dslash box(L/s) - (pi^2/4) ln(M^2) dslash delta, so [w/s^3]_1 has
    # ln M_Sigma^2 = 3/2
    g = tests()[0]
    box_inv_s = pair_lap(INV_S, g) / at0(g)
    ok = ok and box_inv_s == -4                                       # box(1/s) = -4 pi^2 delta
    per_log_zero = F(-1, 4) * box_inv_s                               # pairing shift per unit ln M^2, against g(0)
    per_log_one = F(1, 16) * pair_lap(INV_S, g, extra=(0,)) / at0(d(0, g))   # against d_0 g(0)
    ln_mv2 = F(1) / per_log_zero
    ln_ms2 = F(3, 8) / per_log_one
    ok = ok and per_log_zero == 1 and per_log_one == F(1, 4)
    ok = ok and ln_mv2 == 1 and ln_ms2 == F(3, 2) and ln_ms2 - ln_mv2 == F(1, 2)
    GA.check("cut-off extensions at radius 1 equal the logarithmic forms with ln M^2 = 1 (order zero) and 3/2 "
             "(order one); the difference of the logarithms is 1/2", ok)
    return ok


def check_product_of_the_extended_self_energy_with_a_coordinate():
    """w_nu (1/16) d_a box(ln(M^2 s)/s) = (d_a d_nu - delta box/4)(1/(8 s)) - (delta/16) box(ln(M'^2 s)/s)
    exactly when ln(M^2/M'^2) = 1/2: the pairing of the left side at M = 1 against the right side at M' = 1 leaves
    -(pi^2/8) delta_(a nu) g(0), which the shift ln M^2 = 1/2 removes."""
    premise("synthesis.imported-epstein-glaser-extension-theorem-and-ward-preserving-time-ordered-products")
    ok = True
    for g in tests():
        g0 = at0(g)
        for a in range(4):
            for nu in range(4):
                left = F(1, 16) * pair_lap(LS, pmul(comp(nu), g), extra=(a,))
                per_log = F(1, 16) * pair_lap(INV_S, pmul(comp(nu), g), extra=(a,))
                right = F(1, 8) * (pair_dist(INV_S, (a, nu), g) - (F(1, 4) * pair_lap(INV_S, g) if a == nu else 0))
                if a == nu:
                    right += F(-1, 16) * pair_lap(LS, g)
                    ok = ok and per_log == F(1, 4) * g0 and left + F(1, 2) * per_log == right
                    ok = ok and left != right
                else:
                    ok = ok and per_log == 0 and left == right
    GA.check("w_nu times the extended self-energy is the zero-transfer vertex form exactly at ln(M_Sigma^2/M_V^2) = 1/2", ok)
    return ok


def check_ward_matching_of_subtractions_and_scale_coefficients():
    """The subtraction of the vertex pairing against d_t f is the first-order Taylor term of
    F(w) = f(u = w, v = 0) - f(u = 0, v = w); and the scale derivatives of the two extensions are opposite."""
    premise("synthesis.one-loop-vacuum-polarisation-extends-without-a-regulator-and-ward-preserving-extensions-differ-only-by-the-renormalisation-constants")
