    d_sigma = c_s * (-shell)                     # coefficient of dslash delta, units xi e^2 pi^-2
    d_vertex = c_s * shell                       # coefficient of e_nu delta(u) delta(v)
    ok = ok and c_s == F(-1, 4) and d_sigma == F(1, 8) and d_vertex == F(-1, 8) and d_sigma == -d_vertex
    # the same from the logarithmic form: mu d/dmu of (1/16) dslash box(ln(mu^2 s)/s) is (1/8) dslash box(1/s)
    g = tests()[1]
    for a in range(4):
        dg0 = at0(d(a, g))
        ok = ok and F(1, 8) * pair_lap(INV_S, g, extra=(a,)) == shell * dg0
    GA.check("the vertex subtraction is the first-order Taylor term of the self-energy pairing; scale derivatives "
             "xi e^2/(8 pi^2) (self-energy) and its negative (vertex)", ok)
    return ok

synthesis.one-loop-vacuum-polarisation-e:
"""Exact checks: the one-loop vacuum polarisation extended without a regulator, and the difference spaces of
Ward-preserving covariant one-loop extensions, in the spacetime algebra (standard method: Epstein and Glaser;
Freedman, Johnson and Latorre). Numbering below is the check's own; the formal clauses are (i) traces, (ii)
vacuum polarisation, (iii) difference spaces, (vi) scalar bubble, (vii) floors (closure beyond the stored commutant).

Units hbar = c = 1; Euclidean section; s = Q(x) the square of the vector x; L = ln(mu^2 s). Off the origin a radial
expression is a dict {(a, k): Fraction} for sum c s^a L^k; a symmetric tensor is (A, B) for A g + B x x; a vector
field C x is the dict C. Powers of pi are carried as an explicit integer exponent next to a Fraction. Rules used
(signature-free, from d_mu s = 2 x_mu and d_mu x^mu = 4): d_mu d_nu f = 2 f' g + 4 f'' x x, box f = 8 f' + 4 s f'',
dslash f = 2 f' x, div(A g + B x x) = (2 A' + 2 s B' + 5 B) x, mu d/dmu (s^a L^k) = 2 k s^a L^(k-1).
(1) Spin traces in Cl(4,0) and Cl(1,3): <e_mu x e_nu x>_0 = 2 x_mu x_nu - g_mu_nu Q(x), <e_mu x e_nu>_0 = 0,
    e^mu x e_mu = -2 x, e^mu e_mu = 4 (complete by polarisation); the real trace of left multiplication on the algebra
    is 16 <X>_0 (complete over blades); the massless propagator x / (2 pi^2 s^2) is homogeneous of degree -3.
(2) The vacuum polarisation: with S(x) = alpha x + beta, alpha = 1/(2 pi^2 s^2) - m^2/(8 pi^2 s), beta = m/(4 pi^2 s)
    (the m^2 coefficient from the Klein-Gordon recursion), -e^2 tr(g_mu S(x) g_nu S(-x)) has scaling-degree-6 part
    (e^2/pi^4)(2xx - g s)/s^4 = (e^2/(12 pi^4))(dd - g box) s^-2 and scaling-degree-4 part
    -(e^2 m^2/(8 pi^4))(dd - g box)(1/s); both divergence-free; s^-2 = -(1/4) box(L/s) off the origin; with
    box(1/s) = -4 pi^2 delta (flux of grad(1/s) through the 3-sphere of area 2 pi^2 r^3) the extension's mu-derivative
    is (e^2/(6 pi^2))(dd - g box) delta, giving the log coefficient e^2/(12 pi^2) per Dirac fermion.
(3) Covariant local differences between extensions (existence of Ward-preserving ones is not checked) in Cl(1,3) (polynomials in the components of the momenta and polarisations, Lorentz
    covariance under the six bivector generators, exact sparse rank): photon two-point (omega 2) 3, transverse 1;
    self-energy (omega 1) 4, with the reflection 2; vertex (omega 0) 2, with the reflection 1; self-energy and vertex
    under the Ward-Takahashi identity 2 (with the reflection), 4 (without), and c_V = -c_2 forced; three-current
    (omega 1) 8, transverse on any two legs 0; four-photon (omega 0) 4, transverse on one leg 0.
(4) The scalar bubble Delta_0^2 = 1/(16 pi^4 s^2): extension mu-derivative delta/(8 pi^2); three channels with
    symmetry factor 1/2 give the quartic coefficient 3/(16 pi^2).
(5) Cl(2,4): the commutant k of the conformal Hamiltonian gamma_0 e_+ among the 15 bivectors is 7-dimensional and
    k together with any one boost, translation, special conformal generator or the dilation generates all 15.
(6) Scaling degrees (homogeneity) of the one-loop kernels: 6, 4 (vacuum polarisation), 5 (self-energy numerator
    structure x/s^3), 4 (scalar bubble); omega = sd - 4.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise


# ---------------------------------------------------------------- radial algebra off the origin
def radd(*fs):
    out = {}
    for f in fs:
        for k, v in f.items():
            out[k] = out.get(k, F(0)) + v
    return {k: v for k, v in out.items() if v != 0}


def rscl(c, f):
    return {k: c * v for k, v in f.items() if c * v != 0}


def rmul(f, g):
    out = {}
    for (a, k), v in f.items():
        for (b, l), w in g.items():
            out[(a + b, k + l)] = out.get((a + b, k + l), F(0)) + v * w
    return {k: v for k, v in out.items() if v != 0}


def dds(f):
    out = {}
    for (a, k), v in f.items():
        if a != 0:
            out[(a - 1, k)] = out.get((a - 1, k), F(0)) + a * v
        if k != 0:
            out[(a - 1, k - 1)] = out.get((a - 1, k - 1), F(0)) + k * v
    return {k: v for k, v in out.items() if v != 0}


S1 = {(1, 0): F(1)}


def box(f):
    return radd(rscl(F(8), dds(f)), rscl(F(4), rmul(S1, dds(dds(f)))))


def trans_t(f):
    """(d_mu d_nu - g box) f as (A, B)."""
    return (radd(rscl(F(2), dds(f)), rscl(F(-1), box(f))), rscl(F(4), dds(dds(f))))


def div_t(t):
    a, b = t
    return radd(rscl(F(2), dds(a)), rscl(F(2), rmul(S1, dds(b))), rscl(F(5), b))


def dslash(f):
    return rscl(F(2), dds(f))


def mu_dmu(f):
    out = {}
    for (a, k), v in f.items():
        if k:
            out[(a, k - 1)] = out.get((a, k - 1), F(0)) + 2 * k * v
    return {k: v for k, v in out.items() if v != 0}


def teq(t, u):
    return t[0] == u[0] and t[1] == u[1]


def tscl(c, t):
    return (rscl(c, t[0]), rscl(c, t[1]))


def sd_of(f, xdeg=0):
    """Scaling degree of sum c s^a L^k (x-degree xdeg): -2a - xdeg for the most singular term (logs do not count)."""
    return max(-2 * a - xdeg for (a, k) in f)


def delta_coefficient_of_box_inv_s():
    """box(1/s) = c pi^2 delta: c = (d/dr r^-2) r^3 times the 3-sphere area 2 pi^2 r^3 / r^3, read at any r."""
    radial_derivative = {(-3,): F(-2)}            # d/dr r^-2 = -2 r^-3
    area = {(3,): F(2)}                            # |S^3| r^3 = 2 pi^2 r^3 (pi^2 carried)
    prod = {}
    for (p,), v in radial_derivative.items():
        for (q,), w in area.items():
            prod[(p + q,)] = prod.get((p + q,), F(0)) + v * w
    assert list(prod) == [(0,)]                    # independent of r
    return prod[(0,)]


# ---------------------------------------------------------------- spin traces
def _vec(c):
    return {(i,): F(v) for i, v in enumerate(c) if v != 0}


def _trace_identities(sig):
    m = lambda x, y: GA.mul(x, y, sig)
    g = [GA.gen(i) for i in range(4)]
    up = [GA.scal(F(sig[i]), g[i]) for i in range(4)]       # reciprocal frame
    xs = []
    for i in range(4):
        xs.append([1 if k == i else 0 for k in range(4)])
        for j in range(i + 1, 4):
            xs.append([1 if k in (i, j) else 0 for k in range(4)])
    xs.append([3, -2, 5, 7])
    ok = True
    for c in xs:
        x = _vec(c)
        q = sum(F(sig[i]) * c[i] * c[i] for i in range(4))
        xlow = [F(sig[i]) * c[i] for i in range(4)]
        for mu in range(4):
            for nu in range(4):
                lhs = m(m(m(g[mu], x), g[nu]), x).get((), F(0))
                rhs = 2 * xlow[mu] * xlow[nu] - (F(sig[mu]) if mu == nu else F(0)) * q
                ok = ok and lhs == rhs
                ok = ok and m(m(g[mu], x), g[nu]).get((), F(0)) == 0
        sw = GA.add(*[m(m(up[k], x), g[k]) for k in range(4)])
        ok = ok and GA.eq(sw, GA.scal(F(-2), x))
    ok = ok and GA.eq(GA.add(*[m(up[k], g[k]) for k in range(4)]), {(): F(4)})
    return ok


def check_spin_traces_and_homogeneity_in_the_spacetime_algebra():
    premise("field-theory.second-quantisation")
    premise("field-theory.coupled-system-tree-level")
    ok = _trace_identities((1, 1, 1, 1)) and _trace_identities((1, -1, -1, -1))
    sig = (1, -1, -1, -1)
    blades = GA.all_blades(4)
    for bl in blades:
        tr = F(0)
        for b2 in blades:
            tr += GA.mul({bl: F(1)}, {b2: F(1)}, sig).get(b2, F(0))
        ok = ok and tr == (F(16) if bl == () else F(0))
    # homogeneity of the massless propagator x / (2 pi^2 Q(x)^2): S(l x) = l^-3 S(x)
    for c in ([1, 2, 0, 3], [2, -1, 1, 1]):
        x = _vec(c)
        q = sum(F(s) * v * v for s, v in zip(sig, c))
        for lam in (F(2), F(1, 3), F(-5, 2)):
            xl = GA.scal(lam, x)
            s_l = GA.scal(F(1, 2) / (lam * lam * q) ** 2, xl)
            s_1 = GA.scal(F(1, 2) / q ** 2, x)
            ok = ok and GA.eq(s_l, GA.scal(lam ** -3, s_1))
    GA.check("spin traces <g x g x>_0 = 2xx - gQ, sandwich -2x, trace 4<X>_0 (16 on the algebra); propagator degree -3", ok)
    return ok


# ---------------------------------------------------------------- vacuum polarisation
def _vacuum_polarisation_parts():
    """Return (sd6 part, sd4 part) of -tr(g S(x) g S(-x)) / (e^2 / pi^4) with S = alpha x + beta.
    Trace: 4[-alpha^2 (2xx - g s) + beta^2 g] (from the spin traces). alpha, beta in units pi^-2."""
    # Klein-Gordon recursion on the flat field: Delta = 1/(4 pi^2 s) + A m^2 ln s + ...; -box(A ln s) + 1/(4 s) = 0
    box_ln = box({(0, 1): F(1)})                     # = 4/s (L and ln s differ by a constant)
    A = F(1, 4) / box_ln[(-1, 0)]                    # in units pi^-2
    alpha0 = F(1, 2)                                  # -dslash(1/(4 pi^2 s)) = x/(2 pi^2 s^2)
    alpha2 = -2 * A                                   # -dslash(A m^2 ln s) = -2 A m^2 x / s
    beta1 = F(1, 4)                                   # m Delta_0
    # alpha^2 = alpha0^2 s^-4 + 2 alpha0 alpha2 m^2 s^-3 ; beta^2 = beta1^2 m^2 s^-2
    # -tr = -4[-alpha^2 (2xx - g s) + beta^2 g] = 4 alpha^2 (2xx - g s) - 4 beta^2 g
    lead = (rscl(F(4) * alpha0 ** 2, {(-3, 0): F(-1)}), rscl(F(4) * alpha0 ** 2, {(-4, 0): F(2)}))
    a2 = 2 * alpha0 * alpha2
    m2 = (radd(rscl(F(4) * a2, {(-2, 0): F(-1)}), rscl(F(-4) * beta1 ** 2, {(-2, 0): F(1)})),
          rscl(F(4) * a2, {(-3, 0): F(2)}))
    return A, lead, m2


def check_vacuum_polarisation_extension_is_transverse_and_gives_the_log_coefficient():
    premise("field-theory.second-quantisation")
    premise("field-theory.coupled-system-tree-level")
    premise("synthesis.imported-hadamard-parametrix-of-the-squared-dirac-operator-leads-with-van-vleck-root-times-spin-transport")
    A, lead, m2 = _vacuum_polarisation_parts()
    ok = A == F(1, 16)                                                # m^2 ln s coefficient 1/(16 pi^2)
    ok = ok and lead == ({(-3, 0): F(-1)}, {(-4, 0): F(2)})          # (e^2/pi^4)(2xx - g s)/s^4
    inv_s2, inv_s, ls = {(-2, 0): F(1)}, {(-1, 0): F(1)}, {(-1, 1): F(1)}
    ok = ok and teq(lead, tscl(F(1, 12), trans_t(inv_s2)))           # = (1/12)(dd - g box) s^-2
    ok = ok and teq(m2, tscl(F(-1, 8), trans_t(inv_s)))              # = -(m^2/8)(dd - g box)(1/s)
    ok = ok and div_t(lead) == {} and div_t(m2) == {}
    ok = ok and rscl(F(-1, 4), box(ls)) == inv_s2 and box(inv_s) == {}
    # extension: lead = (1/12)(dd - g box)(-1/4) box(L/s); mu d/dmu acts on L/s only
    c_ext = F(1, 12) * F(-1, 4)
    mu_ls = mu_dmu(ls)                                               # = 2/s
    ok = ok and mu_ls == {(-1, 0): F(2)}
    dbox = delta_coefficient_of_box_inv_s()                          # box(1/s) = -4 pi^2 delta
    ok = ok and dbox == F(-4)
    coef_delta = c_ext * mu_ls[(-1, 0)] * dbox                        # times pi^-4 pi^2 = pi^-2
    ok = ok and coef_delta == F(1, 6)                                # (e^2/(6 pi^2))(dd - g box) delta
    # Fourier (d -> i q): (dd - g box) delta -> q^2 g - q q; mu d/dmu Pi(q^2) = 1/6; Pi = -c ln(q^2/mu^2): 2c = 1/6
    c_log = coef_delta / 2
    ok = ok and c_log == F(1, 12)
    # the scaling-degree-4 part extends uniquely among transverse extensions: its ambiguity c g delta has
    # divergence c d delta, zero only for c = 0; the part is mu-independent
    ok = ok and mu_dmu(m2[0]) == {} and mu_dmu(m2[1]) == {}
    GA.check("vacuum polarisation: (1/12)(dd - g box)s^-2 - (m^2/8)(dd - g box)(1/s), transverse; "
             "mu-derivative (1/6)(dd - g box)delta pi^-2; log coefficient e^2/(12 pi^2)", ok)
    return ok


# ---------------------------------------------------------------- scalar bubble
def check_scalar_bubble_extension_gives_the_quartic_coefficient():
    premise("field-theory.second-quantisation")
    bubble = rmul({(-1, 0): F(1, 4)}, {(-1, 0): F(1, 4)})           # Delta_0^2 = 1/(16 pi^4 s^2)
    ok = bubble == {(-2, 0): F(1, 16)}
    ext = F(1, 16) * F(-1, 4)                                        # times box(L/s)
    ok = ok and rscl(ext, box({(-1, 1): F(1)})) == bubble
    coef = ext * mu_dmu({(-1, 1): F(1)})[(-1, 0)] * delta_coefficient_of_box_inv_s()   # pi^-4 pi^2
    ok = ok and coef == F(1, 8)                                      # delta / (8 pi^2)
    beta = 3 * F(1, 2) * coef                                         # three channels, symmetry factor 1/2
    ok = ok and beta == F(3, 16)
    ok = ok and sd_of(bubble) == 4
    GA.check("scalar bubble: mu-derivative delta/(8 pi^2); quartic coefficient 3/(16 pi^2) for lambda phi^4/4!", ok)
    return ok


# ---------------------------------------------------------------- scaling degrees
def check_scaling_degrees_and_degrees_of_divergence():
    premise("field-theory.second-quantisation")
    premise("synthesis.hadamard-dirac-states-scale-to-the-flat-massless-vacuum-at-every-point-of-a-gravitational-field")
    A, lead, m2 = _vacuum_polarisation_parts()
    ok = max(sd_of(lead[0]), sd_of(lead[1], 2)) == 6
    ok = ok and max(sd_of(m2[0]), sd_of(m2[1], 2)) == 4
    # self-energy numerator structure (Feynman-gauge photon line): x/(2 pi^2 s^2) * 1/(4 pi^2 s) -> x / s^3
    se = rmul({(-2, 0): F(1, 2)}, {(-1, 0): F(1, 4)})
    ok = ok and sd_of(se, 1) == 5
    ok = ok and rscl(F(1, 16), dslash(box({(-1, 1): F(1)}))) == {(-3, 0): F(1)}
    # omega = sd - d with d = 4, and the power-counting values for the vertex, three- and four-photon kernels
    sd_dirac, sd_photon = 3, 2
    omegas = {"vac": 6 - 4, "self": 5 - 4, "bubble": 4 - 4,
              "vertex": 2 * sd_dirac + sd_photon - 8, "three": 3 * sd_dirac - 8, "four": 4 * sd_dirac - 12}
    ok = ok and omegas == {"vac": 2, "self": 1, "bubble": 0, "vertex": 0, "three": 1, "four": 0}
    GA.check("scaling degrees 6, 4, 5, 4 and omega = 2, 1, 0, 0, 1, 0", ok)
    return ok


# ---------------------------------------------------------------- covariant ambiguities
SIG = (1, -1, -1, -1)
G = [GA.gen(i) for i in range(4)]
GENS = [GA.mul(G[i], G[j], SIG) for i in range(4) for j in range(i + 1, 4)]
BL = GA.all_blades(4)


def _m(x, y):
    return GA.mul(x, y, SIG)


def _ch(b, x):
    return GA.scal(F(1, 2), GA.sub(_m(b, x), _m(x, b)))


def _vec_matrix(b):
    mm = [[F(0)] * 4 for _ in range(4)]
    for d in range(4):
        r = _ch(b, G[d])
        for c in range(4):
            mm[c][d] = r.get((c,), F(0))
    return mm


MATS = [_vec_matrix(b) for b in GENS]


def _put(p, key, v):
    w = p.get(key, F(0)) + v
    if w:
        p[key] = w
    else:
        p.pop(key, None)


def _cov(p, nv, b, mm):
    out = {}
    for (e, bl), c in p.items():
        for i in range(nv):
            for cc in range(4):
                k = e[4 * i + cc]
                if not k:
                    continue
                for d in range(4):
                    if mm[cc][d] == 0:
                        continue
                    e2 = list(e)
                    e2[4 * i + cc] -= 1
                    e2[4 * i + d] += 1
                    _put(out, (tuple(e2), bl), c * k * mm[cc][d])
        for b2, v in _ch(b, {bl: F(1)}).items():
            _put(out, (e, b2), -c * v)
    return out


def _subst(p, rule):
    out = {}
    for (e, bl), c in p.items():
        terms = [(tuple(e), c)]
        for i, lin in rule.items():
            new = []
            for ee, cc in terms:
                deg = [ee[4 * i + k] for k in range(4)]
                if sum(deg) == 0:
                    new.append((ee, cc))
                    continue
                comp = deg.index(1)
                for coef, j in lin:
                    e2 = list(ee)
                    e2[4 * i + comp] -= 1
                    e2[4 * j + comp] += 1
                    new.append((tuple(e2), cc * coef))
            terms = new
        for ee, cc in terms:
            _put(out, (ee, bl), cc)
    return out


def _parity(p, nv):
    out = {}
    s = [1, -1, -1, -1]
    for (e, bl), c in p.items():
        sign = 1
        for i in range(nv):
            for k in range(4):
                if e[4 * i + k] % 2 and s[k] < 0:
                    sign = -sign
        _put(out, (e, bl), c * sign)
        for b2, v in _m(_m(G[0], {bl: F(1)}), G[0]).items():
            _put(out, (e, b2), -c * v)
    return out


def _monos(idx, nv, degmax, exact=False):
    comps = [4 * i + k for i in idx for k in range(4)]
    res = []

    def rec(pos, left, cur):
        if pos == len(comps):
            if (not exact) or left == 0:
                res.append(tuple(cur))
            return
        for k in range(left + 1):
            cur[comps[pos]] += k
            rec(pos + 1, left - k, cur)
            cur[comps[pos]] -= k
    rec(0, degmax, [0] * (4 * nv))
    return res


def _basis(nv, mom, pol, degmax, blades):
    mons = _monos(mom, nv, degmax) if mom else [tuple([0] * (4 * nv))]
    pm = [tuple([0] * (4 * nv))]
    for i in pol:
        pm = [tuple(x + y for x, y in zip(a, b)) for a in pm for b in _monos([i], nv, 1, exact=True)]
    return [{(tuple(x + y for x, y in zip(a, b)), bl): F(1)} for a in mons for b in pm for bl in blades]


def _rank(rows):
    piv, rank = {}, 0
    for r in rows:
        r = dict(r)
        while r:
            col = min(r)
            if col in piv:
                f = r[col]
                for k, v in piv[col].items():
                    w = r.get(k, F(0)) - f * v
                    if w:
                        r[k] = w
                    else:
                        r.pop(k, None)
            else:
                f = r[col]
                piv[col] = {k: v / f for k, v in r.items()}
                rank += 1
                break
    return rank


def _dim(bas, cons):
    rows = []
    for p in bas:
        row = {}
        for ci, fn in enumerate(cons):
            for key, v in fn(p).items():
                row[repr((ci, key))] = v
        rows.append(row)
    return len(bas) - _rank(rows)


def _covs(nv):
    return [(lambda p, b=b, mm=mm: _cov(p, nv, b, mm)) for b, mm in zip(GENS, MATS)]


def _sigma_vertex_ward(par):
    bs, bv = _basis(1, [0], [], 1, BL), _basis(1, [], [0], 0, BL)
    cons = _covs(1) + ([lambda p: _parity(p, 1)] if par else [])
    rows = []
    for tag, p in [("S", p) for p in bs] + [("V", p) for p in bv]:
        row = {}
        for ci, fn in enumerate(cons):
            for key, v in fn(p).items():
                row[repr((tag, ci, key))] = v
        for (e, bl), c in p.items():                 # Ward-Takahashi: Lambda(q) + Sigma_1(q) = 0
            if tag == "V" or sum(e) == 1:
                k = repr(("WT", e, bl))
                row[k] = row.get(k, F(0)) + c
        rows.append({k: v for k, v in row.items() if v})
    return len(rows) - _rank(rows)


def check_covariant_ambiguities_are_the_renormalisation_constants():
    premise("field-theory.second-quantisation")
    premise("field-theory.coupled-system-tree-level")
    ok = True
    # photon two-point: q (0), a (1), b (2); omega 2
    bas = _basis(3, [0], [1, 2], 2, [()])
    tr = lambda p: _subst(p, {1: [(F(1), 0)]})
    ok = ok and len(bas) == 240 and _dim(bas, _covs(3)) == 3 and _dim(bas, _covs(3) + [tr]) == 1
    # self-energy: q (0), Clifford valued, omega 1
    bas = _basis(1, [0], [], 1, BL)
    par = lambda p: _parity(p, 1)
    ok = ok and len(bas) == 80 and _dim(bas, _covs(1)) == 4 and _dim(bas, _covs(1) + [par]) == 2
    # vertex: a (0), omega 0
    bas = _basis(1, [], [0], 0, BL)
    ok = ok and len(bas) == 64 and _dim(bas, _covs(1)) == 2 and _dim(bas, _covs(1) + [par]) == 1
    # self-energy and vertex tied by the Ward-Takahashi identity
    ok = ok and _sigma_vertex_ward(True) == 2 and _sigma_vertex_ward(False) == 4
    # the explicit solution: Sigma = c_m + c_2 q, Lambda = c_V a; Ward-Takahashi residual c_V q + c_2 q = 0
    for c2, cv in ((F(1), F(-1)), (F(1), F(1))):
        res = GA.add(GA.scal(cv, G[1]), GA.scal(c2, G[1]))
        ok = ok and (GA.is_zero(res) == (cv == -c2))
    # three-current: q1 (0), q2 (1), a1 (2), a2 (3), a3 (4); omega 1
    bas = _basis(5, [0, 1], [2, 3, 4], 1, [()])
    w1 = lambda p: _subst(p, {2: [(F(1), 0)]})
    w2 = lambda p: _subst(p, {3: [(F(1), 1)]})
    w3 = lambda p: _subst(p, {4: [(F(-1), 0), (F(-1), 1)]})
    ok = ok and len(bas) == 576 and _dim(bas, _covs(5)) == 8
    ok = ok and _dim(bas, _covs(5) + [w1, w2]) == 0 and _dim(bas, _covs(5) + [w2, w3]) == 0
    ok = ok and _dim(bas, _covs(5) + [w1, w3]) == 0
    ok = ok and _dim(bas, _covs(5) + [w1]) > 0
    # four-photon: a1..a4 (0..3), q1 (4) for the transversality substitution; omega 0
    bas = _basis(5, [], [0, 1, 2, 3], 0, [()])
    ok = ok and len(bas) == 256 and _dim(bas, _covs(5)) == 4
    ok = ok and _dim(bas, _covs(5) + [lambda p: _subst(p, {0: [(F(1), 4)]})]) == 0
    GA.check("covariant ambiguities: photon 3 -> 1, self-energy 4 -> 2, vertex 2 -> 1, Ward-Takahashi 2 (4), "
             "three-current 8 -> 0 on two legs, four-photon 4 -> 0", ok)
    return ok


# ---------------------------------------------------------------- floors
S6 = (1, -1, -1, -1, 1, -1)
BIV6 = [b for b in GA.all_blades(6) if len(b) == 2]


def _m6(x, y):
    return GA.mul(x, y, S6)


def _br6(x, y):
    return GA.sub(_m6(x, y), _m6(y, x))


def _v6(x):
    return [x.get(b, F(0)) for b in BIV6]


def _closure(gens):
    basis = []

    def addv(x):
        if GA.rank_of_vectors(basis + [_v6(x)]) > len(basis):
            basis.append(_v6(x))
            return True
        return False
    for g in gens:
        addv(g)
    changed = True
    while changed:
        changed = False
        els = [{b: c for b, c in zip(BIV6, v) if c} for v in basis]
        for x in els:
            for y in els:
                if addv(_br6(x, y)):
                    changed = True
    return len(basis)


def check_no_weighting_of_the_conformal_energy_keeps_a_boost():
    premise("synthesis.floor-regulator-keeps-the-charge-and-the-central-term-below-the-cut-off")
    premise("field-theory.twistor-attachment")
    h = _m6(GA.gen(0), GA.gen(4))
    k = [{b: F(1)} for b in BIV6 if GA.is_zero(_br6(h, {b: F(1)}))]
    ok = len(k) == 7 and _closure(k) == 7
    ninf, n0 = GA.add(GA.gen(4), GA.gen(5)), GA.sub(GA.gen(4), GA.gen(5))
    tests = [_m6(GA.gen(0), GA.gen(1)), _m6(GA.gen(0), GA.gen(3)),
             GA.add(_m6(GA.gen(0), GA.gen(1)), GA.scal(F(2), _m6(GA.gen(0), GA.gen(2)))),
             _m6(GA.gen(1), ninf), _m6(GA.gen(0), ninf), _m6(GA.gen(2), n0), _m6(GA.gen(4), GA.gen(5))]
    for x in tests:
        ok = ok and not GA.is_zero(_br6(h, x)) and _closure(k + [x]) == 15
    # every bivector either commutes or anticommutes with h; the anticommuting ones span the 8-dim complement
    anti = [b for b in BIV6 if GA.is_zero(GA.add(_m6(h, {b: F(1)}), _m6({b: F(1)}, h)))]
    ok = ok and len(anti) == 8
    GA.check("Cl(2,4): commutant of gamma_0 e_+ is 7-dim and closed; with any one boost, translation, special "
             "conformal generator or the dilation it generates all 15 bivectors", ok)
    return ok

synthesis.operator-join-casimir-shifts:
"""synthesis.operator-join-casimir-shifts: exact checks.

Single conformal spinor (N = 1), palatial oscillators in the holomorphic realisation
bar Z = -hbar d/dZ on polynomials in Z^1..Z^4 (homogeneity d), as in the store's operator-join
check, whose grip construction (chart matrices A(U ^ I_Lambda), inverse ambient Gram matrix) is
reproduced verbatim below. The conformal Casimir is sum_ab E_ab E_ba - (1/4)(tr E)^2 with
E_ab the symmetrised quadratic of Z^a bar Z_b, the operator form of C_2(Lambda^2 CS) =
tr(h^2) - (1/4)(tr h)^2.
"""
from fractions import Fraction as F
import GA  # noqa: F401  (house rule; the computation is in Gaussian rationals)
from tp_premise import premise


class C:
    """Gaussian rational a + i b, i the chart's complex unit (I6)."""
    __slots__ = ("re", "im")

    def __init__(self, re=0, im=0):
        self.re, self.im = F(re), F(im)

    def __add__(s, o):
        o = cc(o); return C(s.re + o.re, s.im + o.im)
    __radd__ = __add__

    def __sub__(s, o):
        o = cc(o); return C(s.re - o.re, s.im - o.im)

    def __rsub__(s, o):
        return cc(o) - s

    def __neg__(s):
        return C(-s.re, -s.im)

    def __mul__(s, o):
        o = cc(o); return C(s.re * o.re - s.im * o.im, s.re * o.im + s.im * o.re)
    __rmul__ = __mul__

    def __truediv__(s, o):
        o = cc(o); n = o.re * o.re + o.im * o.im
        return s * C(o.re / n, -o.im / n)

    def conj(s):
        return C(s.re, -s.im)

    def abs2(s):
        return s.re * s.re + s.im * s.im

    def __eq__(s, o):
        o = cc(o); return s.re == o.re and s.im == o.im

    def __repr__(s):
        return f"({s.re}+{s.im}i)"


def cc(x):
    return x if isinstance(x, C) else C(x)


I = C(0, 1)
EPS = [[0, 1], [-1, 0]]          # eps_12 = 1: eps^T eps = 1, eps^2 = -1, det = 1


def rnd(rng, k=3):
    return C(F(rng.randint(-k, k), rng.randint(1, 3)), F(rng.randint(-k, k), rng.randint(1, 3)))




def herm(Z, W):
    return sum((Z[2 + a].conj() * W[a] + Z[a].conj() * W[2 + a] for a in range(2)), C())

def matvec(A, Z):
    return [sum((cc(A[r][c]) * Z[c] for c in range(4)), C()) for r in range(4)]


def _unused_moment(A, Zs):
    """M_A = i sum_i bar Z^i . A Z^i."""
    return I * sum((herm(Z, matvec(A, Z)) for Z in Zs), C())


def A_grading():          # A(n_inf ^ n_0)
    h = F(1, 2)
    return [[-h, 0, 0, 0], [0, -h, 0, 0], [0, 0, h, 0], [0, 0, 0, h]]


def A_trans(x):           # A(x ^ n_inf): omega-block <- b_x pi, (b_x pi)^a = x^{aa'} eps_{a'b'} pi^{b'}
    A = [[0] * 4 for _ in range(4)]
    for a in range(2):
        for bp in range(2):
            A[a][2 + bp] = sum(x[a][ap] * EPS[ap][bp] for ap in range(2))
    return A


def A_spec(x):            # A(x ^ n_0): pi-block <- c_x omega, (c_x w)^{a'} = -x^{ba'} eps_{ba} w^a
    A = [[0] * 4 for _ in range(4)]
    for ap in range(2):
        for a in range(2):
            A[2 + ap][a] = -sum(x[b][ap] * EPS[b][a] for b in range(2))
    return A


def unit_x(a, ap):
    x = [[0, 0], [0, 0]]
    x[a][ap] = 1
    return x


# ambient basis: n_inf, n_0, E_{aa'} (a, a' in 0..1 standing for 1,2 and 3,4)
XS = [(a, ap) for a in range(2) for ap in range(2)]


def gram():
    G = [[F(0)] * 6 for _ in range(6)]
    G[0][1] = G[1][0] = F(1)
    for r, (a, ap) in enumerate(XS):
        for s, (b, bp) in enumerate(XS):
            G[2 + r][2 + s] = F(-EPS[a][b] * EPS[ap][bp])
    return G


def inverse(G):
    n = len(G)
    M = [[cc(G[r][c]) for c in range(n)] + [C(1 if r == c else 0) for c in range(n)] for r in range(n)]
    for col in range(n):
        piv = next(r for r in range(col, n) if not (M[r][col] == 0))
        M[col], M[piv] = M[piv], M[col]
        p = M[col][col]
        M[col] = [v / p for v in M[col]]
        for r in range(n):
            if r != col and not (M[r][col] == 0):
                f = M[r][col]
                M[r] = [M[r][c] - f * M[col][c] for c in range(2 * n)]
    return [row[n:] for row in M]


GI = inverse(gram())



# ---- polynomials: dict {exponent tuple: C}


def padd(*ps):
    out = {}
    for p in ps:
        for m, c in p.items():
            out[m] = out.get(m, C()) + c
    return {m: c for m, c in out.items() if not (c == 0)}


def pscale(p, s):
    s = cc(s)
    return {m: c * s for m, c in p.items() if not (c * s == 0)}


def pmul(p, q):
    out = {}
    for m1, c1 in p.items():
        for m2, c2 in q.items():
            m = tuple(a + b for a, b in zip(m1, m2))
            out[m] = out.get(m, C()) + c1 * c2
    return {m: c for m, c in out.items() if not (c == 0)}


def pdiff(p, v):
    out = {}
    for m, c in p.items():
        if m[v]:
            mm_ = list(m); mm_[v] -= 1
            out[tuple(mm_)] = out.get(tuple(mm_), C()) + c * m[v]
    return {m: c for m, c in out.items() if not (c == 0)}


class Space:
    def __init__(self, N):
        self.N = N
        self.nv = 8 * N          # x_{i,a} at 8i+a, y_{i,a} at 8i+4+a

    def x(self, i, a):
        return 8 * i + a

    def y(self, i, a):
        return 8 * i + 4 + a

    def var(self, v):
        m = [0] * self.nv; m[v] = 1
        return {tuple(m): C(1)}

    def const(self, c):
        return {tuple([0] * self.nv): cc(c)} if not (cc(c) == 0) else {}

    def pairs(self):
        return [(self.x(i, a), self.y(i, a)) for i in range(self.N) for a in range(4)]

    def P(self, f, g):
        out = {}
        for (xv, yv) in self.pairs():
            out = padd(out, pmul(pdiff(f, xv), pdiff(g, yv)), pscale(pmul(pdiff(f, yv), pdiff(g, xv)), -1))
        return out

    def P2(self, f, g):
        out = {}
        for (xk, yk) in self.pairs():
            for (xl, yl) in self.pairs():
                fx = pdiff(f, xk); fy = pdiff(f, yk)
                gx = pdiff(g, xk); gy = pdiff(g, yk)
                out = padd(out,
                           pmul(pdiff(fx, xl), pdiff(gy, yl)),
                           pscale(pmul(pdiff(fx, yl), pdiff(gy, xl)), -1),
                           pscale(pmul(pdiff(fy, xl), pdiff(gx, yl)), -1),
                           pmul(pdiff(fy, yl), pdiff(gx, xl)))
        return out

    def star(self, f, g):
        """Moyal product of two polynomials of degree <= 2, as (hbar^0, hbar^1, hbar^2) parts."""
        return (pmul(f, g), pscale(self.P(f, g), F(1, 2)), pscale(self.P2(f, g), F(1, 8)))


def tri_add(*ts):
    return tuple(padd(*[t[k] for t in ts]) for k in range(3))


def tri_scale(t, s):
    return tuple(pscale(p, s) for p in t)


S_SWAP = [2, 3, 0, 1]     # S exchanges the halves: (S v)_a = v_{S_SWAP[a]}


def moment(sp, A):
    """M_A = i sum_i bar Z_i . A Z^i = i sum_i y_{i,b} A^b_a x_{i,a} (y = bar Z as a dual vector).
    Here bar Z . W = conj(Z)^T S W, so y_b = sum_a conj(Z)_a S_ab and bar Z . A Z = y . (A x)."""
    out = {}
    for i in range(sp.N):
        for b in range(4):
            for a in range(4):
                if A[b][a]:
                    out = padd(out, pscale(pmul(sp.var(sp.y(i, b)), sp.var(sp.x(i, a))), I * cc(A[b][a])))
    return out


def omega_mat(lam):
    O = [[F(0)] * 4 for _ in range(4)]
    for a in range(2):
        for b in range(2):
            O[a][b] = lam * EPS[a][b]
            O[2 + a][2 + b] = F(EPS[a][b])
    return O


def Bpoly(sp, i, l, lam):
    O = omega_mat(lam)
    out = {}
    for a in range(4):
        for b in range(4):
            if O[a][b]:
                out = padd(out, pscale(pmul(sp.var(sp.x(i, a)), sp.var(sp.x(l, b))), O[a][b]))
    return out


def Bbar_poly(sp, i, l, lam):
    """conj(B) = conj(x_i)^T O conj(x_l), conj(x) = S y (S real, symmetric, S^2 = 1)."""
    O = omega_mat(lam)
    out = {}
    for a in range(4):
        for b in range(4):
            if O[a][b]:
                out = padd(out, pscale(pmul(sp.var(sp.y(i, S_SWAP[a])), sp.var(sp.y(l, S_SWAP[b]))), O[a][b]))
    return out


def hpoly(sp, i, l):
    """h_il = bar Z^i . Z^l = y_i . x_l."""
    out = {}
    for a in range(4):
        out = padd(out, pmul(sp.var(sp.y(i, a)), sp.var(sp.x(l, a))))
    return out


def grip_values(sp, lam):
    d = moment(sp, A_grading())
    v = [pscale(d, lam), pscale(d, -1)]
    for (a, ap) in XS:
        x = unit_x(a, ap)
        v.append(padd(moment(sp, A_trans(x)), pscale(moment(sp, A_spec(x)), lam)))
    return v


def run(N, lam):
    sp = Space(N)
    v = grip_values(sp, lam)
    lhs = ({}, {}, {})
    cl = {}
    for r in range(6):
        for s in range(6):
            if not (GI[r][s] == 0):
                lhs = tri_add(lhs, tri_scale(sp.star(v[r], v[s]), GI[r][s]))
                cl = padd(cl, pscale(pmul(v[r], v[s]), GI[r][s]))
    # RHS in symmetric (palatial) ordering
    rhs = ({}, {}, {})
    rcl = {}
    for i in range(N):
        for l in range(i + 1, N):
            Bp, Bb = Bpoly(sp, i, l, lam), Bbar_poly(sp, i, l, lam)
            rhs = tri_add(rhs, sp.star(Bb, Bp), sp.star(Bp, Bb))          # (B^dag B + B B^dag)
            rcl = padd(rcl, pscale(pmul(Bb, Bp), 2))
    H = [[hpoly(sp, i, l) for l in range(N)] for i in range(N)]
    trh = padd(*[H[i][i] for i in range(N)])
    for i in range(N):
        for l in range(N):
            rhs = tri_add(rhs, tri_scale(sp.star(H[i][l], H[l][i]), lam))   # 2 lam (1/2) tr h^2
            rcl = padd(rcl, pscale(pmul(H[i][l], H[l][i]), lam))
    rhs = tri_add(rhs, tri_scale(sp.star(trh, trh), -lam / 2))             # 2 lam (-1/4)(tr h)^2
    rcl = padd(rcl, pscale(pmul(trh, trh), -lam / 2))
    assert padd(cl, pscale(rcl, -1)) == {}, "classical identity fails"
    assert lhs[0] == cl
    diff = [padd(lhs[k], pscale(rhs[k], -1)) for k in range(3)]
    return sp, lhs, rhs, diff, H, trh



def mono(nv, k):
    m = [0]*nv; m[k] = 1; return tuple(m)

class Rep:
    def __init__(self, N, hb):
        self.N, self.nv, self.hb = N, 4*N, F(hb)
    def X(self, k):            # multiplication by x_k
        return lambda f: pmul({mono(self.nv, k): C(1)}, f)
    def Y(self, k):            # -hbar d/dx_k
        return lambda f: pscale(pdiff(f, k), -self.hb)
    def ix(self, i, a): return 4*i + a

def comp(*ops):
    def g(f):
        for op in reversed(ops):
            f = op(f)
        return f
    return g

def lin(terms):
    """terms: list of (coef, op)"""
    return lambda f: padd(*[pscale(op(f), c) for c, op in terms]) if terms else {}

def sym2(R, yk, xk):
    """Weyl quantisation of the classical product y_k x_k' : 1/2 (Y X + X Y)."""
    return lin([(F(1,2), comp(R.Y(yk), R.X(xk))), (F(1,2), comp(R.X(xk), R.Y(yk)))])

def moment_op(R, A):
    terms = []
    for i in range(R.N):
        for b in range(4):
            for a in range(4):
                if A[b][a]:
                    terms.append((I*cc(A[b][a]), sym2(R, R.ix(i,b), R.ix(i,a))))
    return lin(terms)

def grip_sq(R, lam):
    d = moment_op(R, A_grading())
    v = [lin([(lam, d)]), lin([(-1, d)])]
    for (a, ap) in XS:
        x = unit_x(a, ap)
        v.append(lin([(1, moment_op(R, A_trans(x))), (lam, moment_op(R, A_spec(x)))]))
    terms = []
    for r in range(6):
        for s in range(6):
            if not (GI[r][s] == 0):
                terms.append((GI[r][s], comp(v[r], v[s])))
    return lin(terms)

def rhs_op(R, lam):
    O = omega_mat(lam)
    terms = []
    N = R.N
    for i in range(N):
        for l in range(i+1, N):
            Bt, Bbt = [], []
            for a in range(4):
                for b in range(4):
                    if O[a][b]:
                        Bt.append((O[a][b], comp(R.X(R.ix(i,a)), R.X(R.ix(l,b)))))
                        Bbt.append((O[a][b], comp(R.Y(R.ix(i,S_SWAP[a])), R.Y(R.ix(l,S_SWAP[b])))))
            Bo, Bbo = lin(Bt), lin(Bbt)
            terms += [(1, comp(Bbo, Bo)), (1, comp(Bo, Bbo))]
    H = [[lin([(1, sym2(R, R.ix(i,a), R.ix(l,a))) for a in range(4)]) for l in range(N)] for i in range(N)]
    trh = lin([(1, H[i][i]) for i in range(N)])
    for i in range(N):
        for l in range(N):
            terms.append((lam, comp(H[i][l], H[l][i])))
    terms.append((-lam/2, comp(trh, trh)))
    return lin(terms), trh





def monomials(nv, d):
    if nv == 1:
        return [(d,)]
    return [(k,) + m for k in range(d + 1) for m in monomials(nv - 1, d - k)]


def conf_casimir(R):
    E = [[sym2(R, R.ix(0, b), R.ix(0, a)) for b in range(4)] for a in range(4)]   # E_ab ~ Z^a bar Z_b
    trE = lin([(1, E[a][a]) for a in range(4)])
    terms = [(1, comp(E[a][b], E[b][a])) for a in range(4) for b in range(4)]
    terms.append((F(-1, 4), comp(trE, trE)))
    return lin(terms), trE


def check_operator_join_casimir_shifts():
    premise("synthesis.operator-join-ordering-constants")
    premise("mass.casimir-form-join")
    premise("mass.imported-palatial-quadratics-homogeneity-charge")
    premise("mass.imported-unitary-representations-de-sitter-group")
    premise("mass.mass-weight-dictionary")
    premise("mass.weight-polynomial-two-series")
    premise("field-theory.imported-standard-field-theory")
    premise("mass.de-sitter-scale-frozen-point")
    premise("mass.chart-form-spin-isomorphism")
    # Weyl-algebra identities by the Moyal product (exact on products of quadratics), N = 1:
    # m^2_op = (lam/2) h*h - 2 lam hbar^2 and C_conf = (3/4) h*h - 3 hbar^2, h the helicity symbol
    for lam in (F(1), F(-2, 3), F(0)):
        sp = Space(1)
        v = grip_values(sp, lam)
        lhs = ({}, {}, {})
        for r in range(6):
            for s in range(6):
                if not (GI[r][s] == 0):
                    lhs = tri_add(lhs, tri_scale(sp.star(v[r], v[s]), GI[r][s]))
        hs = hpoly(sp, 0, 0)
        hh = sp.star(hs, hs)
        zero = tuple([0] * sp.nv)
        assert lhs[0] == pscale(hh[0], lam / 2) and lhs[1] == {} and hh[1] == {}
        assert lhs[2] == padd(pscale(hh[2], lam / 2), {zero: C(-2 * lam)} if lam else {})
        e = [[pmul(sp.var(sp.x(0, a)), sp.var(sp.y(0, b))) for b in range(4)] for a in range(4)]
        cas = ({}, {}, {})
        for a in range(4):
            for b in range(4):
                cas = tri_add(cas, sp.star(e[a][b], e[b][a]))
        cas = tri_add(cas, tri_scale(sp.star(hs, hs), F(-1, 4)))
        assert cas[0] == pscale(hh[0], F(3, 4)) and cas[1] == {}
        assert cas[2] == padd(pscale(hh[2], F(3, 4)), {zero: C(-3)})
    for lam in (F(1), F(-2, 3)):
        for hb in (1, 3):
            R = Rep(1, hb)
            G = grip_sq(R, lam)
            Cc, h = conf_casimir(R)
            for d in range(4):
                for m in monomials(4, d):
                    f = {m: C(1)}
                    # helicity: h acts as -(d + 2) hbar (imported), so h^2 - 4 hbar^2 = d (d + 4) hbar^2
                    assert h(f) == pscale(f, -(d + 2) * R.hb)
                    q = d * (d + 4) * R.hb ** 2
                    assert G(f) == pscale(f, lam * q / 2)            # m^2_op = (lam/2)(h^2 - 4 hbar^2)
                    assert Cc(f) == pscale(f, F(3, 4) * q)           # C_conf = (3/4)(h^2 - 4 hbar^2)
                    # de Sitter Casimir from the split C_dS = C_conf - m^2/<I,I>, <I,I> = 2 lam
                    cds = F(3, 4) * q - (lam * q / 2) / (2 * lam)
                    assert cds == F(1, 2) * q
            # operator identities on a mixed-degree test function (Weyl-algebra identities)
            f = {(2, 0, 1, 0): C(1, 2), (0, 1, 0, 0): C(-3), (1, 1, 1, 1): C(0, 1), (0, 0, 0, 0): C(5)}
            hh = comp(h, h)
            assert G(f) == padd(pscale(hh(f), lam / 2), pscale(f, -2 * lam * R.hb ** 2))
            assert Cc(f) == padd(pscale(hh(f), F(3, 4)), pscale(f, -3 * R.hb ** 2))
    # helicity values: on homogeneity n the palatial helicity is -(n + 2) hbar = 2 s hbar, so with
    # q = h^2 - 4 hbar^2 = 4 (s^2 - 1) hbar^2: C_conf = 3 (s^2 - 1), C_dS = 2 (s^2 - 1), m^2 = 2 lam (s^2 - 1)
    for s2 in (F(0), F(1, 4), F(1), F(4)):           # s^2 for s = 0, 1/2, 1, 2
        q = 4 * (s2 - 1)
        assert F(3, 4) * q == 3 * (s2 - 1) and F(1, 2) * q == 2 * (s2 - 1)
    # the scalar module (n = -2, s = 0): C_dS = -2, the scalar-module Casimir -m^2/H^2 of m^2 = 2 H^2,
    # i.e. Delta (3 - Delta) = 2 at Delta = 1, 2, and the weight dictionary -w (w + 3) = 2 at w = -1
    s2 = F(0)
    cds = 2 * (s2 - 1)
    m2_field = -cds
    assert m2_field == 2 and [D for D in range(4) if D * (3 - D) == m2_field] == [1, 2]
    assert -(-1) * (-1 + 3) == m2_field
    m2_grip = 2 * F(1, 2) * (s2 - 1) * 1                 # 2 lam (s^2 - 1) at lam = H^2 / 2, H = 1
    cconf = 3 * (s2 - 1)
    assert m2_grip == -1 and m2_field - m2_grip == -cconf == 3
    # classical values (no ordering): C_conf = 3 s^2, C_dS = 2 s^2, m^2 = 2 lam s^2: at s = 0 all vanish,
    # so the classical dS Casimir gives m^2 = 0, not the conformally coupled 2 H^2
    assert 2 * s2 == 0
    return True

synthesis.operator-join-ordering-constan:
"""synthesis.operator-join-ordering-constants: exact checks.

Palatial oscillators x = Z^a_i, y = bar Z_{i,a} with [x, y] = hbar. Two independent routes:
route 1 composes Weyl symbols by the Moyal product (exact on products of quadratics) and reads off
the hbar^1 and hbar^2 parts; route 2 realises bar Z = -hbar d/dZ on polynomials and applies the
operators to random test functions with hbar a number. Coefficients are Gaussian rationals.
"""
from fractions import Fraction as F
import GA  # noqa: F401  (house rule; the computation is in Gaussian rationals)
from tp_premise import premise


class _Rng:
    """Deterministic integer generator (Lehmer, modulus 2^31 - 1) giving a fixed, reproducible list
    of rational test points; no floats and no random module."""

    def __init__(self, seed):
        self.s = seed % 2147483647 or 1

    def _next(self):
        self.s = (self.s * 48271) % 2147483647
        return self.s

    def randint(self, a, b):
        return a + self._next() % (b - a + 1)

    def randrange(self, n):
        return self._next() % n

class C:
    """Gaussian rational a + i b, i the chart's complex unit (I6)."""
    __slots__ = ("re", "im")

    def __init__(self, re=0, im=0):
        self.re, self.im = F(re), F(im)

    def __add__(s, o):
        o = cc(o); return C(s.re + o.re, s.im + o.im)
    __radd__ = __add__

    def __sub__(s, o):
        o = cc(o); return C(s.re - o.re, s.im - o.im)

    def __rsub__(s, o):
        return cc(o) - s

    def __neg__(s):
        return C(-s.re, -s.im)

    def __mul__(s, o):
        o = cc(o); return C(s.re * o.re - s.im * o.im, s.re * o.im + s.im * o.re)
    __rmul__ = __mul__

    def __truediv__(s, o):
        o = cc(o); n = o.re * o.re + o.im * o.im
        return s * C(o.re / n, -o.im / n)

    def conj(s):
        return C(s.re, -s.im)

    def abs2(s):
        return s.re * s.re + s.im * s.im

    def __eq__(s, o):
        o = cc(o); return s.re == o.re and s.im == o.im

    def __repr__(s):
        return f"({s.re}+{s.im}i)"


def cc(x):
    return x if isinstance(x, C) else C(x)


I = C(0, 1)
EPS = [[0, 1], [-1, 0]]          # eps_12 = 1: eps^T eps = 1, eps^2 = -1, det = 1


def rnd(rng, k=3):
    return C(F(rng.randint(-k, k), rng.randint(1, 3)), F(rng.randint(-k, k), rng.randint(1, 3)))




def herm(Z, W):
    return sum((Z[2 + a].conj() * W[a] + Z[a].conj() * W[2 + a] for a in range(2)), C())

def matvec(A, Z):
    return [sum((cc(A[r][c]) * Z[c] for c in range(4)), C()) for r in range(4)]


def _unused_moment(A, Zs):
    """M_A = i sum_i bar Z^i . A Z^i."""
    return I * sum((herm(Z, matvec(A, Z)) for Z in Zs), C())


def A_grading():          # A(n_inf ^ n_0)
    h = F(1, 2)
    return [[-h, 0, 0, 0], [0, -h, 0, 0], [0, 0, h, 0], [0, 0, 0, h]]


def A_trans(x):           # A(x ^ n_inf): omega-block <- b_x pi, (b_x pi)^a = x^{aa'} eps_{a'b'} pi^{b'}
    A = [[0] * 4 for _ in range(4)]
    for a in range(2):
        for bp in range(2):
            A[a][2 + bp] = sum(x[a][ap] * EPS[ap][bp] for ap in range(2))
    return A


def A_spec(x):            # A(x ^ n_0): pi-block <- c_x omega, (c_x w)^{a'} = -x^{ba'} eps_{ba} w^a
    A = [[0] * 4 for _ in range(4)]
    for ap in range(2):
        for a in range(2):
            A[2 + ap][a] = -sum(x[b][ap] * EPS[b][a] for b in range(2))
    return A


def unit_x(a, ap):
    x = [[0, 0], [0, 0]]
    x[a][ap] = 1
    return x


# ambient basis: n_inf, n_0, E_{aa'} (a, a' in 0..1 standing for 1,2 and 3,4)
XS = [(a, ap) for a in range(2) for ap in range(2)]


def gram():
    G = [[F(0)] * 6 for _ in range(6)]
    G[0][1] = G[1][0] = F(1)
    for r, (a, ap) in enumerate(XS):
        for s, (b, bp) in enumerate(XS):
            G[2 + r][2 + s] = F(-EPS[a][b] * EPS[ap][bp])
    return G


def inverse(G):
    n = len(G)
    M = [[cc(G[r][c]) for c in range(n)] + [C(1 if r == c else 0) for c in range(n)] for r in range(n)]
    for col in range(n):
        piv = next(r for r in range(col, n) if not (M[r][col] == 0))
        M[col], M[piv] = M[piv], M[col]
        p = M[col][col]
        M[col] = [v / p for v in M[col]]
        for r in range(n):
            if r != col and not (M[r][col] == 0):
                f = M[r][col]
                M[r] = [M[r][c] - f * M[col][c] for c in range(2 * n)]
    return [row[n:] for row in M]


GI = inverse(gram())



# ---- polynomials: dict {exponent tuple: C}


def padd(*ps):
    out = {}
    for p in ps:
        for m, c in p.items():
            out[m] = out.get(m, C()) + c
    return {m: c for m, c in out.items() if not (c == 0)}


def pscale(p, s):
    s = cc(s)
    return {m: c * s for m, c in p.items() if not (c * s == 0)}


def pmul(p, q):
    out = {}
    for m1, c1 in p.items():
        for m2, c2 in q.items():
            m = tuple(a + b for a, b in zip(m1, m2))
            out[m] = out.get(m, C()) + c1 * c2
    return {m: c for m, c in out.items() if not (c == 0)}


def pdiff(p, v):
    out = {}
    for m, c in p.items():
        if m[v]:
            mm_ = list(m); mm_[v] -= 1
            out[tuple(mm_)] = out.get(tuple(mm_), C()) + c * m[v]
    return {m: c for m, c in out.items() if not (c == 0)}


class Space:
    def __init__(self, N):
        self.N = N
        self.nv = 8 * N          # x_{i,a} at 8i+a, y_{i,a} at 8i+4+a

    def x(self, i, a):
        return 8 * i + a

    def y(self, i, a):
        return 8 * i + 4 + a

    def var(self, v):
        m = [0] * self.nv; m[v] = 1
        return {tuple(m): C(1)}

    def const(self, c):
        return {tuple([0] * self.nv): cc(c)} if not (cc(c) == 0) else {}

    def pairs(self):
        return [(self.x(i, a), self.y(i, a)) for i in range(self.N) for a in range(4)]

    def P(self, f, g):
        out = {}
        for (xv, yv) in self.pairs():
            out = padd(out, pmul(pdiff(f, xv), pdiff(g, yv)), pscale(pmul(pdiff(f, yv), pdiff(g, xv)), -1))
        return out

    def P2(self, f, g):
        out = {}
        for (xk, yk) in self.pairs():
            for (xl, yl) in self.pairs():
                fx = pdiff(f, xk); fy = pdiff(f, yk)
                gx = pdiff(g, xk); gy = pdiff(g, yk)
                out = padd(out,
                           pmul(pdiff(fx, xl), pdiff(gy, yl)),
                           pscale(pmul(pdiff(fx, yl), pdiff(gy, xl)), -1),
                           pscale(pmul(pdiff(fy, xl), pdiff(gx, yl)), -1),
                           pmul(pdiff(fy, yl), pdiff(gx, xl)))
        return out

    def star(self, f, g):
        """Moyal product of two polynomials of degree <= 2, as (hbar^0, hbar^1, hbar^2) parts."""
        return (pmul(f, g), pscale(self.P(f, g), F(1, 2)), pscale(self.P2(f, g), F(1, 8)))


def tri_add(*ts):
    return tuple(padd(*[t[k] for t in ts]) for k in range(3))


def tri_scale(t, s):
    return tuple(pscale(p, s) for p in t)


S_SWAP = [2, 3, 0, 1]     # S exchanges the halves: (S v)_a = v_{S_SWAP[a]}


def moment(sp, A):
    """M_A = i sum_i bar Z_i . A Z^i = i sum_i y_{i,b} A^b_a x_{i,a} (y = bar Z as a dual vector).
    Here bar Z . W = conj(Z)^T S W, so y_b = sum_a conj(Z)_a S_ab and bar Z . A Z = y . (A x)."""
    out = {}
    for i in range(sp.N):
        for b in range(4):
            for a in range(4):
                if A[b][a]:
                    out = padd(out, pscale(pmul(sp.var(sp.y(i, b)), sp.var(sp.x(i, a))), I * cc(A[b][a])))
    return out


def omega_mat(lam):
    O = [[F(0)] * 4 for _ in range(4)]
    for a in range(2):
        for b in range(2):
            O[a][b] = lam * EPS[a][b]
            O[2 + a][2 + b] = F(EPS[a][b])
    return O


def Bpoly(sp, i, l, lam):
    O = omega_mat(lam)
    out = {}
    for a in range(4):
        for b in range(4):
            if O[a][b]:
                out = padd(out, pscale(pmul(sp.var(sp.x(i, a)), sp.var(sp.x(l, b))), O[a][b]))
    return out


def Bbar_poly(sp, i, l, lam):
    """conj(B) = conj(x_i)^T O conj(x_l), conj(x) = S y (S real, symmetric, S^2 = 1)."""
    O = omega_mat(lam)
    out = {}
    for a in range(4):
        for b in range(4):
            if O[a][b]:
                out = padd(out, pscale(pmul(sp.var(sp.y(i, S_SWAP[a])), sp.var(sp.y(l, S_SWAP[b]))), O[a][b]))
    return out


def hpoly(sp, i, l):
    """h_il = bar Z^i . Z^l = y_i . x_l."""
    out = {}
    for a in range(4):
        out = padd(out, pmul(sp.var(sp.y(i, a)), sp.var(sp.x(l, a))))
    return out


def grip_values(sp, lam):
    d = moment(sp, A_grading())
    v = [pscale(d, lam), pscale(d, -1)]
    for (a, ap) in XS:
        x = unit_x(a, ap)
        v.append(padd(moment(sp, A_trans(x)), pscale(moment(sp, A_spec(x)), lam)))
    return v


def run(N, lam):
    sp = Space(N)
    v = grip_values(sp, lam)
    lhs = ({}, {}, {})
    cl = {}
    for r in range(6):
        for s in range(6):
            if not (GI[r][s] == 0):
                lhs = tri_add(lhs, tri_scale(sp.star(v[r], v[s]), GI[r][s]))
                cl = padd(cl, pscale(pmul(v[r], v[s]), GI[r][s]))
    # RHS in symmetric (palatial) ordering
    rhs = ({}, {}, {})
    rcl = {}
    for i in range(N):
        for l in range(i + 1, N):
            Bp, Bb = Bpoly(sp, i, l, lam), Bbar_poly(sp, i, l, lam)
            rhs = tri_add(rhs, sp.star(Bb, Bp), sp.star(Bp, Bb))          # (B^dag B + B B^dag)
            rcl = padd(rcl, pscale(pmul(Bb, Bp), 2))
    H = [[hpoly(sp, i, l) for l in range(N)] for i in range(N)]
    trh = padd(*[H[i][i] for i in range(N)])
    for i in range(N):
        for l in range(N):
            rhs = tri_add(rhs, tri_scale(sp.star(H[i][l], H[l][i]), lam))   # 2 lam (1/2) tr h^2
            rcl = padd(rcl, pscale(pmul(H[i][l], H[l][i]), lam))
    rhs = tri_add(rhs, tri_scale(sp.star(trh, trh), -lam / 2))             # 2 lam (-1/4)(tr h)^2
    rcl = padd(rcl, pscale(pmul(trh, trh), -lam / 2))
    assert padd(cl, pscale(rcl, -1)) == {}, "classical identity fails"
    assert lhs[0] == cl
    diff = [padd(lhs[k], pscale(rhs[k], -1)) for k in range(3)]
    return sp, lhs, rhs, diff, H, trh



def mono(nv, k):
    m = [0]*nv; m[k] = 1; return tuple(m)

class Rep:
    def __init__(self, N, hb):
        self.N, self.nv, self.hb = N, 4*N, F(hb)
    def X(self, k):            # multiplication by x_k
        return lambda f: pmul({mono(self.nv, k): C(1)}, f)
    def Y(self, k):            # -hbar d/dx_k
        return lambda f: pscale(pdiff(f, k), -self.hb)
    def ix(self, i, a): return 4*i + a

def comp(*ops):
    def g(f):
        for op in reversed(ops):
            f = op(f)
        return f
    return g

def lin(terms):
    """terms: list of (coef, op)"""
    return lambda f: padd(*[pscale(op(f), c) for c, op in terms]) if terms else {}

def sym2(R, yk, xk):
    """Weyl quantisation of the classical product y_k x_k' : 1/2 (Y X + X Y)."""
    return lin([(F(1,2), comp(R.Y(yk), R.X(xk))), (F(1,2), comp(R.X(xk), R.Y(yk)))])

def moment_op(R, A):
    terms = []
    for i in range(R.N):
        for b in range(4):
            for a in range(4):
                if A[b][a]:
                    terms.append((I*cc(A[b][a]), sym2(R, R.ix(i,b), R.ix(i,a))))
    return lin(terms)

def grip_sq(R, lam):
    d = moment_op(R, A_grading())
    v = [lin([(lam, d)]), lin([(-1, d)])]
    for (a, ap) in XS:
        x = unit_x(a, ap)
        v.append(lin([(1, moment_op(R, A_trans(x))), (lam, moment_op(R, A_spec(x)))]))
    terms = []
    for r in range(6):
        for s in range(6):
            if not (GI[r][s] == 0):
                terms.append((GI[r][s], comp(v[r], v[s])))
    return lin(terms)

def rhs_op(R, lam):
    O = omega_mat(lam)
    terms = []
    N = R.N
    for i in range(N):
        for l in range(i+1, N):
            Bt, Bbt = [], []
            for a in range(4):
                for b in range(4):
                    if O[a][b]:
                        Bt.append((O[a][b], comp(R.X(R.ix(i,a)), R.X(R.ix(l,b)))))
                        Bbt.append((O[a][b], comp(R.Y(R.ix(i,S_SWAP[a])), R.Y(R.ix(l,S_SWAP[b])))))
            Bo, Bbo = lin(Bt), lin(Bbt)
            terms += [(1, comp(Bbo, Bo)), (1, comp(Bo, Bbo))]
    H = [[lin([(1, sym2(R, R.ix(i,a), R.ix(l,a))) for a in range(4)]) for l in range(N)] for i in range(N)]
    trh = lin([(1, H[i][i]) for i in range(N)])
    for i in range(N):
        for l in range(N):
            terms.append((lam, comp(H[i][l], H[l][i])))
    terms.append((-lam/2, comp(trh, trh)))
    return lin(terms), trh



def check_operator_join():
    premise("correspondence.symmetrised-quadratics-palatial-algebra")
    premise("correspondence.shared-core-ordering-dictionary")
    premise("mass.chart-form-spin-isomorphism")
    premise("mass.imported-flat-model-twistor-chart-infinity")
    premise("mass.de-sitter-scale-frozen-point")
    premise("mass.exact-join")
    rng = _Rng(11)
    # (1) every grip generator A(U ^ I) is traceless, so its symmetrised quadratic has no shift
    for lam in (F(1), F(-2, 3)):
        mats = [A_grading()] + [A_trans(unit_x(a, ap)) for (a, ap) in XS] + [A_spec(unit_x(a, ap)) for (a, ap) in XS]
        for A in mats:
            assert sum(F(A[k][k]) for k in range(4)) == 0
    # (2) the key matrix: sum_{U,V} G^{UV} A(U^I) A(V^I) = -(5/4) <I,I> 1 = -(5/2) lam 1
    for lam in (F(1), F(1, 6), F(-2, 3)):
        As = [[[cc(v) * lam for v in row] for row in A_grading()],
              [[cc(v) * -1 for v in row] for row in A_grading()]]
        for (a, ap) in XS:
            T, K = A_trans(unit_x(a, ap)), A_spec(unit_x(a, ap))
            As.append([[cc(T[r][c]) + cc(K[r][c]) * lam for c in range(4)] for r in range(4)])
        tot = [[C() for _ in range(4)] for _ in range(4)]
        for r in range(6):
            for s in range(6):
                if not (GI[r][s] == 0):
                    prod = [[sum((As[r][p][q] * As[s][q][t] for q in range(4)), C()) for t in range(4)] for p in range(4)]
                    tot = [[tot[p][t] + GI[r][s] * prod[p][t] for t in range(4)] for p in range(4)]
        assert tot == [[C(-F(5, 2) * lam if p == t else 0) for t in range(4)] for p in range(4)]
    # (3) route 1 (Moyal product of Weyl symbols, exact for products of quadratics), N = 2, 3:
    # the operator grip minus the symmetrised right side is the central constant -2 N lam hbar^2,
    # with no hbar^1 part; the classical parts agree (run() asserts the polynomial identity)
    def lap(sp, p):
        out = {}
        for (xv, yv) in sp.pairs():
            out = padd(out, pdiff(pdiff(p, xv), yv))
        return out
    for N in (2, 3):
        for lam in (F(1), F(-2, 3)):
            sp, lhs, rhs, diff, H, trh = run(N, lam)
            zero = tuple([0] * sp.nv)
            assert diff[0] == {} and diff[1] == {}
            assert diff[2] == {zero: C(-2 * N * lam)}
            # normal (Z-left) form: N-symbol = exp(-(hbar/2) Delta) W-symbol; Delta m^2 = 5 lam tr h and
            # (1/8) Delta^2 m^2 cancels the Weyl constant -(5N/2) lam: m^2_op = :m^2: - (5/2) lam hbar :tr h:
            # the Weyl-relative constant: m^2_op = W(m^2) - (5N/2) lam hbar^2 = W(m^2) - (5 N Lambda/12) hbar^2,
            # while relative to the Jordan-symmetrised RHS it is -2N lam hbar^2 = -(N Lambda/3) hbar^2 (asserted above)
            assert lhs[1] == {} and lhs[2] == {zero: C(-F(5 * N, 2) * lam)}
            L1 = lap(sp, lhs[0])
            assert L1 == pscale(trh, 5 * lam)
            assert lap(sp, L1) == {zero: C(20 * N * lam)}
            # the commutator [B, Bbar] = hbar lam (h_ii + h_ll) (symmetrised Gram operators)
            Bp, Bb = Bpoly(sp, 0, 1, lam), Bbar_poly(sp, 0, 1, lam)
            assert sp.P(Bp, Bb) == pscale(padd(H[0][0], H[1][1]), lam)
    # (4) route 2 (holomorphic realisation Zbar = -hbar d/dZ, no Moyal product), N = 2, hbar = 1, 3:
    # the palatial form and the normal form on random polynomial test functions
    def normal_op(R, poly):
        def g(f):
            out = {}
            for m, c in poly.items():
                h = f
                for i in range(R.N):
                    for a in range(4):
                        for _ in range(m[8 * i + 4 + a]):
                            h = R.Y(R.ix(i, a))(h)
                for i in range(R.N):
                    for a in range(4):
                        for _ in range(m[8 * i + a]):
                            h = R.X(R.ix(i, a))(h)
                out = padd(out, pscale(h, c))
            return out
        return g

    def randpoly(nv, deg):
        f = {}
        for _ in range(5):
            m = [0] * nv
            for _ in range(rng.randint(0, deg)):
                m[rng.randrange(nv)] += 1
            f[tuple(m)] = f.get(tuple(m), C()) + C(rng.randint(-3, 3), rng.randint(-3, 3))
        return {k: v for k, v in f.items() if not (v == 0)}
    N = 2
    for lam in (F(1), F(-2, 3)):
        sp, lhs, rhs, diff, H, trh_poly = run(N, lam)
        for hb in (1, 3):
            R = Rep(N, hb)
            G = grip_sq(R, lam)
            Rh, trh = rhs_op(R, lam)
            nm, ntr = normal_op(R, lhs[0]), normal_op(R, trh_poly)
            for _ in range(2):
                f = randpoly(R.nv, 3)
                Gf = G(f)
                assert padd(Gf, pscale(Rh(f), -1), pscale(f, 2 * N * lam * R.hb ** 2)) == {}
                assert padd(Gf, pscale(nm(f), -1), pscale(ntr(f), F(5, 2) * lam * R.hb)) == {}
            # palatial helicity: the symmetrised h_ii acts on homogeneity d as -(d + 2) hbar
            d = 3
            f = {tuple([d] + [0] * (R.nv - 1)): C(1)}
            assert lin([(1, sym2(R, R.ix(0, a), R.ix(0, a))) for a in range(4)])(f) == pscale(f, -(d + 2) * R.hb)
    # Lambda = 0: no ordering terms at all
    sp, lhs, rhs, diff, H, trh = run(2, F(0))
    assert diff == [{}, {}, {}] and lhs[1] == {} and lhs[2] == {}
    return True

synthesis.operator-join-point-spectrum-o:
"""synthesis.operator-join-has-no-zero-modes-on-positive-energy-modules: exact checks.

Positive-energy (oscillator) model of two constituents: bosonic modes a_{iA}, c_{iA} (i = constituent, A = spinor
index), unnormalised basis |n> = prod (x^dag)^{n_x}|0>, so x|n> = n_x|n - e_x>, x^dag|n> = |n + e_x>,
<n|n> = prod n_x!. Store components: omega = (Z^0, Z^1), pi = (Z^2, Z^3), pibar_A = Zbar_A, omegabar = Zbar_{2,3}.
With s^2 = sig:  Z^A = s(a_A + c_A^dag)/sqrt2,  Z^{2+A} = (a_A - c_A^dag)/(sqrt2 s),
                 Zbar_A = (Z^{2+A})^dag = (a_A^dag - c_A)/(sqrt2 s),  Zbar_{2+A} = (Z^A)^dag = s(a_A^dag + c_A)/sqrt2.
Every operator used is a sum of products of two Z or Zbar, so coefficients are rational (1/2) sig^{0, +-1}.
B = <pi^1 pi^2> + lam [omega^1 omega^2], Bdag its conjugate (store's convention), lam = Lambda/6, hbar = 1;
h_il = (Zbar_i.Z^l + Z^l.Zbar_i)/2; C = (1/2) sum h_il h_li - (1/4)(tr h)^2;
m2 = Bdag B + B Bdag + (Lambda/3) C - (2 Lambda/3) (the stored palatial form, N = 2).
Pair form (lam sig^2 = 1): B = sqrt(lam) (det a + det c^dag); K- = B/sqrt(lam), K+ = Bdag/sqrt(lam), K0 = tr h/2,
C_sl = K0^2 - K0 - K+ K-, and m2 = (Lambda/3)(K0^2 - C_sl + C - 2).
Runs at (Lambda, sig) = (6, 1) (sqrt lam = 1) and (3/2, 2) (sqrt lam = 1/2).
"""
from fractions import Fraction as F
from itertools import product

import GA
from tp_premise import premise

MODES = [(k, i, A) for k in "ac" for i in (0, 1) for A in (0, 1)]
IDX = {m: n for n, m in enumerate(MODES)}
NM = len(MODES)


def _fact(n):
    p = 1
    for t in range(2, n + 1):
        p *= t
    return p


def vadd(*vs):
    out = {}
    for v in vs:
        for k, x in v.items():
            out[k] = out.get(k, F(0)) + x
    return {k: x for k, x in out.items() if x != 0}


def vsc(c, v):
    return {k: c * x for k, x in v.items() if c * x != 0}


def low(m):
    j = IDX[m]

    def f(v):
        out = {}
        for k, x in v.items():
            if k[j]:
                kk = list(k)
                kk[j] -= 1
                kk = tuple(kk)
                out[kk] = out.get(kk, F(0)) + k[j] * x
        return out
    return f


def rai(m):
    j = IDX[m]

    def f(v):
        out = {}
        for k, x in v.items():
            kk = list(k)
            kk[j] += 1
            kk = tuple(kk)
            out[kk] = out.get(kk, F(0)) + x
        return out
    return f


def comp(*ops):
    def f(v):
        for o in reversed(ops):
            v = o(v)
        return v
    return f


def lin(*terms):
    return lambda v: vadd(*[vsc(c, o(v)) for c, o in terms])


def ident(v):
    return dict(v)


def inner(u, v):
    tot = F(0)
    for k, x in u.items():
        if k in v:
            w = 1
            for n in k:
                w *= _fact(n)
            tot += x * v[k] * w
    return tot


def zeta(i, al):
    """(weight exponent, [(coef, op)]) for sqrt2 Z^al_i, weight s^e."""
    A = al % 2
    a, c = ("a", i, A), ("c", i, A)
    if al < 2:
        return 1, [(F(1), low(a)), (F(1), rai(c))]
    return -1, [(F(1), low(a)), (F(-1), rai(c))]


def zetabar(i, al):
    A = al % 2
    a, c = ("a", i, A), ("c", i, A)
    if al < 2:
        return -1, [(F(1), rai(a)), (F(-1), low(c))]
    return 1, [(F(1), rai(a)), (F(1), low(c))]


class Model:
    def __init__(self, LAM, sig):
        self.LAM, self.sig = LAM, sig
        self.lam = LAM / 6

        def prod2(X, Y, extra=F(1)):
            (e1, t1), (e2, t2) = X, Y
            w = {-2: 1 / sig, 0: F(1), 2: sig}[e1 + e2]
            return lin(*[(extra * F(1, 2) * w * cx * cy, comp(ox, oy)) for cx, ox in t1 for cy, oy in t2])
        self.prod2 = prod2

        def br(Xf, i, l, a, b):
            return lin((F(1), prod2(Xf(i, a), Xf(l, b))), (F(-1), prod2(Xf(i, b), Xf(l, a))))
        self.b = br(zeta, 0, 1, 2, 3)
        self.om = br(zeta, 0, 1, 0, 1)
        self.bd = br(zetabar, 0, 1, 0, 1)
        self.omd = br(zetabar, 0, 1, 2, 3)
        self.B = lin((F(1), self.b), (self.lam, self.om))
        self.Bd = lin((F(1), self.bd), (self.lam, self.omd))

        def h(i, l):
            terms = []
            for al in range(4):
                terms.append((F(1, 2), prod2(zetabar(i, al), zeta(l, al))))
                terms.append((F(1, 2), prod2(zeta(l, al), zetabar(i, al))))
            return lin(*terms)
        self.H = [[h(i, l) for l in range(2)] for i in range(2)]
        H = self.H
        self.trh = lin((F(1), H[0][0]), (F(1), H[1][1]))
        self.C = lin(*([(F(1, 2), comp(H[i][l], H[l][i])) for i in range(2) for l in range(2)]
                       + [(F(-1, 4), comp(self.trh, self.trh))]))
        L3 = LAM / 3
        self.m2 = lin((F(1), comp(self.Bd, self.B)), (F(1), comp(self.B, self.Bd)), (L3, self.C), (-2 * L3, ident))


def det_a():
    return lin((F(1), comp(low(("a", 0, 0)), low(("a", 1, 1)))), (F(-1), comp(low(("a", 0, 1)), low(("a", 1, 0)))))


def det_cd():
    return lin((F(1), comp(rai(("c", 0, 0)), rai(("c", 1, 1)))), (F(-1), comp(rai(("c", 0, 1)), rai(("c", 1, 0)))))


def det_ad():
    return lin((F(1), comp(rai(("a", 0, 0)), rai(("a", 1, 1)))), (F(-1), comp(rai(("a", 0, 1)), rai(("a", 1, 0)))))


