    sgn = F(-1) if al < 2 else F(1)
    return lin((F(1), lambda p: mul(xv(i, A), p)), (sgn, lambda p: der(yv(i, A), p)))


def bracket2(op, i, l, a, b):
    return lin((F(1), comp(op(i, a), op(l, b))), (F(-1), comp(op(i, b), op(l, a))))


def build(LAM_):
