    REST = lin((HBAR * lam_, trh), (LAM_ / 3, Cop), (-2 * LAM_ / 3 * HBAR ** 2, ID))
    J3 = lin((F(1, 2), H[0][0]), (F(-1, 2), H[1][1]))
    return dict(B=B, Bd=Bd, H=H, trh=trh, Cop=Cop, m2=m2, REST=REST, J3=J3)


