def factorial(n):
    out = 1
    for k in range(2, n + 1):
        out *= k
    return out


def fock_ip(p, q):
    s = F(0)
    for k, v in p.items():
        if k in q:
            w = 1
            for e in k:
                w *= factorial(e)
            s += v * q[k] * w
    return s


def xx(p):
    return padd(comp(lambda q: mul(xv(0, 0), q), lambda q: mul(xv(1, 1), q))(p),
                pscale(F(-1), comp(lambda q: mul(xv(0, 1), q), lambda q: mul(xv(1, 0), q))(p)))


def yy(p):
