    # the source S = (Lambda/3)(Abar b + A bdag), A a c-number: no block-diagonal part in bidegree
    A, Abar = F(5, 7), F(5, 7)
    S = lin((LAM / 3 * Abar, b_hat), (LAM / 3 * A, bdag))
    for p in MONOS:
