    return True

synthesis.pair-singlet-mass-form-is-floo:
"""synthesis.pair-singlet-mass-form-is-floor-plus-face-density: exact checks.

Exact arithmetic over Q(i) (GA.QI) in the six-mode bosonic Fock space of the skeleton theorem, in
the unnormalised occupation basis (|m> = prod (a_p^dag)^{m_p} |0>, norm prod m_p!). Face operators
Omega_k = (1/2) eps_kij eps_AB a_iA a_jB, family density rho_lk = sum_A a^dag_lA a_kA, number N, and the
mass form H_kl = (1/2) <Omega_k^dag Omega_l + Omega_l Omega_k^dag> of the stored mass-form result.
  (1) the face-word monomials Om^{dag m}|0> (D = |m| <= 3) are orthogonal with norm (D+1)! m!, and
      Omega_l, rho_lk and V = sum_k Omega_k^dag Omega_k act on them by the stated formulas;
  (2) on five non-Gaussian superpositions with complex rational coefficients H equals
      (1 + <D>/2) 1 + G, G_kl = sum (D + 3/2) <z_k psi_D, z_l psi_D> in the auxiliary boson picture;
  (3) in the normal frame of the stored Z2 result (c = (1, a, ia), a = 1 and a = 2/3) every tested state
      built from Omega(c)^dag, Omega(cbar)^dag and V is annihilated by Omega(n), n = c_R x c_I, has
      H n = (1 + <D>/2) n, and has n strictly lowest when the light pair is split; the stored values
      h_n = 32/17, 145/77, 505/257, 55/32 are reproduced as 1 + <D>/2;
  (4) the trace identity tr H = 3 + 3<D> + <D^2> on the singlet span, hence the heavy-pair sum rule.
"""
from fractions import Fraction as F
from itertools import product
import GA
from tp_premise import premise

QI = GA.QI
MODES = [(i, A) for i in range(3) for A in range(2)]
IDX = {m: p for p, m in enumerate(MODES)}
Z = QI(0)
ONE = QI(1)


def eps3(k, i, j):
    if len({k, i, j}) < 3:
        return 0
    return 1 if (k, i, j) in [(0, 1, 2), (1, 2, 0), (2, 0, 1)] else -1


def eps2(A, B):
    return 0 if A == B else (1 if (A, B) == (0, 1) else -1)


THETA = [[[F(1, 2) * eps3(k, p[0], q[0]) * eps2(p[1], q[1]) for q in MODES] for p in MODES] for k in range(3)]


def fact(n):
    out = 1
    for j in range(2, n + 1):
        out *= j
    return out


def iszero(x):
    return x.re == 0 and x.im == 0


def qeq(x, y):
    return x.re == y.re and x.im == y.im


def sadd(s, m, co):
    v = s.get(m, Z) + co
    if iszero(v):
        s.pop(m, None)
    else:
        s[m] = v


def ann(p, st):
    out = {}
    for m, co in st.items():
        if m[p]:
            mm = list(m)
            mm[p] -= 1
            sadd(out, tuple(mm), co * m[p])
    return out


def cre(p, st):
    out = {}
    for m, co in st.items():
        mm = list(m)
        mm[p] += 1
        sadd(out, tuple(mm), co)
    return out


def lin(terms):
    out = {}
    for coef, st in terms:
        for m, co in st.items():
            sadd(out, m, coef * co)
    return out


def inner(s, t):
    tot = Z
    for m, co in s.items():
        if m in t:
            w = 1
            for x in m:
                w *= fact(x)
            tot = tot + co.conj() * t[m] * w
    return tot


def omega(k, st):
    return lin([(QI(THETA[k][p][q]), ann(p, ann(q, st))) for p in range(6) for q in range(6) if THETA[k][p][q]])


def omega_dag(k, st):
    return lin([(QI(THETA[k][p][q]), cre(q, cre(p, st))) for p in range(6) for q in range(6) if THETA[k][p][q]])


def omega_vec(cv, st):
    """Omega(c) = sum_k c_k Omega_k."""
    return lin([(cv[k], omega(k, st)) for k in range(3) if not iszero(cv[k])])


def omega_vec_dag(cv, st):
    """Omega(c)^dag = sum_k conj(c_k) Omega_k^dag."""
    return lin([(cv[k].conj(), omega_dag(k, st)) for k in range(3) if not iszero(cv[k])])


def rho(l, k, st):
    return lin([(ONE, cre(IDX[(l, A)], ann(IDX[(k, A)], st))) for A in range(2)])


def vac():
    return {tuple([0] * 6): ONE}


def V(st):
    return lin([(ONE, omega_dag(k, omega(k, st))) for k in range(3)])


def mono(m):
    st = vac()
    for k in range(3):
        for _ in range(m[k]):
            st = omega_dag(k, st)
    return st


def steq(a, b):
    return not lin([(ONE, a), (QI(-1), b)])


def mass_form(psi):
    Om = [omega(k, psi) for k in range(3)]
    Od = [omega_dag(k, psi) for k in range(3)]
    H = [[(inner(Om[k], Om[l]) + inner(Od[l], Od[k])) * F(1, 2) for l in range(3)] for k in range(3)]
    return H, inner(psi, psi)


def mfact(m):
    return fact(m[0]) * fact(m[1]) * fact(m[2])


def predicted(coef):
    """Norm, <D> (unnormalised), and G (unnormalised) from the monomial coefficients."""
    norm = Z
    dsum = Z
    d2sum = Z
    for m, c in coef.items():
        D = sum(m)
        w = c.conj() * c * (fact(D + 1) * mfact(m))
        norm = norm + w
        dsum = dsum + w * D
        d2sum = d2sum + w * (D * D)
    G = [[Z] * 3 for _ in range(3)]
    for k in range(3):
        for l in range(3):
            s = Z
            for m, c in coef.items():
                if not m[k]:
                    continue
                mp = list(m)
                mp[k] -= 1
                mp[l] += 1
                mp = tuple(mp)
                if mp not in coef:
                    continue
                D = sum(m)
                base = list(m)
                base[k] -= 1
                w = fact(D + 1) * m[k] * mp[l] * mfact(base)
                s = s + c.conj() * coef[mp] * w * (F(D) + F(3, 2))
            G[k][l] = s
    return norm, dsum, d2sum, G


MONOS = [m for m in product(range(4), repeat=3) if sum(m) <= 3]


def check_face_word_monomial_algebra():
    premise("families.skeleton-rank-one-plus-ordering-shift")
    premise("families.imported-squeezed-vacuum-bosonic-pairing")
    ok = True
    st = {m: mono(m) for m in MONOS}
    for m in MONOS:
        D = sum(m)
        for m2 in MONOS:
            ip = inner(st[m], st[m2])
            exp = fact(D + 1) * mfact(m) if m == m2 else 0
            ok = ok and ip.re == exp and ip.im == 0
        for l in range(3):
            if m[l]:
                mm = list(m)
                mm[l] -= 1
                rhs = lin([(QI((D + 1) * m[l]), mono(tuple(mm)))])
            else:
                rhs = {}
            ok = ok and steq(omega(l, st[m]), rhs)
            for k in range(3):
                terms = []
                if k == l:
                    terms.append((QI(D), st[m]))
                if m[l]:
                    mm = list(m)
                    mm[l] -= 1
                    mm[k] += 1
                    terms.append((QI(-m[l]), mono(tuple(mm))))
                ok = ok and steq(rho(l, k, st[m]), lin(terms))
        ok = ok and steq(V(st[m]), lin([(QI(D * (D + 1)), st[m])]))
    GA.check("face-word monomials: norms (D+1)! m!, Omega_l, rho_lk and V act by the stated formulas", ok)
    return ok


SAMPLES = [
    {(0, 0, 0): QI(1), (1, 0, 0): QI(2, 1), (0, 1, 1): QI(F(1, 3), -1), (2, 1, 0): QI(0, F(1, 2))},
    {(1, 1, 0): QI(1), (0, 0, 2): QI(-1, 3), (1, 1, 1): QI(F(2, 5), 1), (3, 0, 0): QI(1, 1), (0, 1, 0): QI(F(-1, 2))},
    {(0, 0, 0): QI(1), (0, 1, 0): QI(1), (1, 0, 0): QI(0, 1), (0, 2, 0): QI(F(1, 2)), (1, 1, 0): QI(F(2, 3)), (2, 0, 0): QI(F(-1, 2))},
    {(2, 0, 1): QI(1, -2), (0, 2, 1): QI(3), (1, 0, 2): QI(F(1, 7), 1)},
    {(0, 0, 0): QI(F(1, 2)), (1, 1, 1): QI(1), (0, 3, 0): QI(0, -1), (0, 0, 3): QI(2, F(1, 3))},
]


def check_mass_form_is_floor_plus_weighted_density():
    premise("synthesis.face-mass-form-unit-plus-gram")
    premise("families.skeleton-rank-one-plus-ordering-shift")
    premise("synthesis.cumulants-at-fixed-second-moments-keep-the-floor")
    ok = True
    for coef in SAMPLES:
        psi = lin([(c, mono(m)) for m, c in coef.items()])
        H, n = mass_form(psi)
        norm, dsum, d2sum, G = predicted(coef)
        ok = ok and qeq(n, norm)
        trH = Z
        for k in range(3):
            trH = trH + H[k][k]
            for l in range(3):
                exp = G[k][l] + (norm + dsum * F(1, 2) if k == l else Z)
                ok = ok and qeq(H[k][l], exp)
                # G is Hermitian
                ok = ok and qeq(G[k][l], G[l][k].conj())
        # trace identity tr H = 3 + 3<D> + <D^2> (unnormalised)
        ok = ok and qeq(trH, norm * 3 + dsum * 3 + d2sum)
        # leading principal minors of G are nonnegative (G is a Gram matrix)
        g11 = G[0][0]
        g2 = G[0][0] * G[1][1] - G[0][1] * G[1][0]
        ok = ok and g11.im == 0 and g11.re >= 0 and g2.im == 0 and g2.re >= 0
    GA.check("H = (1 + <D>/2) 1 + G on five non-Gaussian singlet states, entrywise; tr H = 3 + 3<D> + <D^2>", ok)
    return ok


def poly_state(words):
    """words: list of (coefficient, list of face vectors y, power of V): coef * V^p prod Omega(y)^dag |0>."""
    out = {}
    for coef, ys, p in words:
        st = vac()
        for y in ys:
            st = omega_vec_dag(y, st)
        for _ in range(p):
            st = V(st)
        out = lin([(ONE, out), (coef, st)])
    return out


def mat_apply(H, v):
    return [sum((H[k][l] * v[l] for l in range(3)), Z) for k in range(3)]


def check_forced_eigenvector_is_lowest_in_source_built_states():
    premise("synthesis.real-structure-breaks-source-stabiliser-to-z2")
    premise("synthesis.face-mass-form-unit-plus-gram")
    ok = True
    results = []
    for a in (F(1), F(2, 3)):
        c = [QI(1), QI(a), QI(0, a)]
        cb = [x.conj() for x in c]
        n = [QI(a), QI(-1), QI(0)]          # proportional to c_R x c_I = (a^2, -a, 0)
        cR = [QI(1), QI(a), QI(0)]
        cI = [QI(0), QI(0), QI(a)]
        states = [
            ("single", [(ONE, [], 0), (ONE, [c], 0), (QI(F(1, 2)), [c, c], 0)]),
            ("real1", [(ONE, [], 0), (ONE, [c], 0), (ONE, [cb], 0), (QI(1), [c, cb], 0)]),
            ("real2", [(ONE, [], 0), (ONE, [c], 0), (ONE, [cb], 0), (QI(2), [c, cb], 0)]),
            ("realm", [(ONE, [], 0), (ONE, [c], 0), (ONE, [cb], 0), (QI(F(-1, 2)), [c, cb], 0)]),
            ("two", [(ONE, [], 0), (ONE, [c], 0), (QI(F(2, 3)), [c, cb], 0)]),
            ("mixV", [(QI(1, 1), [c], 0), (QI(F(1, 3), -1), [cb, cb], 1), (QI(0, 2), [c, cb, c], 0)]),
            ("deg3", [(QI(2), [cb], 0), (QI(-1, F(1, 2)), [c, c, cb], 0), (QI(F(1, 5)), [cb, cb, cb], 1)]),
        ]
        for name, words in states:
            psi = poly_state(words)
            ok = ok and not omega_vec(n, psi)          # Omega(n) psi = 0
            H, nn = mass_form(psi)
            # <D> from the number operator: N = 2D on the singlet span
            num = lin([(ONE, cre(p, ann(p, psi))) for p in range(6)])
            Dbar = inner(psi, num) * F(1, 2)
            hn = nn + Dbar * F(1, 2)                   # unnormalised floor
            Hn = mat_apply(H, n)
            ok = ok and all(qeq(Hn[k], n[k] * hn) for k in range(3))
            # block on n-perp in the real basis cR, cI (not orthonormal): compare via B - h_n Gram
            basis = [cR, cI]
            Bm = [[sum((basis[i][k].conj() * mat_apply(H, basis[j])[k] for k in range(3)), Z) for j in range(2)] for i in range(2)]
            Gm = [[sum((basis[i][k].conj() * basis[j][k] for k in range(3)), Z) for j in range(2)] for i in range(2)]
            X = [[Bm[i][j] - Gm[i][j] * hn for j in range(2)] for i in range(2)]   # PSD exactly when n is lowest
            det = X[0][0] * X[1][1] - X[0][1] * X[1][0]
            tr = X[0][0] + X[1][1]
            ok = ok and det.im == 0 and tr.im == 0 and det.re >= 0 and tr.re > 0
            results.append((a, name, hn.re / nn.re, det.re == 0))
    by = {(a, nm): (h, deg) for a, nm, h, deg in results}
    ok = ok and by[(F(1), "single")] == (F(32, 17), True)
    ok = ok and by[(F(1), "real1")] == (F(145, 77), False)
    ok = ok and by[(F(1), "real2")][0] == F(505, 257) and by[(F(1), "realm")][0] == F(55, 32)
    ok = ok and by[(F(1), "two")] == (F(190, 101), False)
    ok = ok and not by[(F(2, 3), "mixV")][1] and not by[(F(1), "deg3")][1]
    # a word in the forced direction itself moves n off the floor (stored instance: h_n = 1738/199, on top)
    c = [QI(1), QI(1), QI(0, 1)]
    n = [QI(1), QI(-1), QI(0)]
    psi = poly_state([(ONE, [], 0), (ONE, [c], 0), (QI(2), [n, n], 0)])
    H, nn = mass_form(psi)
    Hn = mat_apply(H, n)
    hn_val = Hn[0].re / n[0].re / nn.re
    num = lin([(ONE, cre(p, ann(p, psi))) for p in range(6)])
    floor = 1 + inner(psi, num).re / nn.re / 4
    ok = ok and hn_val == F(1738, 199) and hn_val > floor and bool(omega_vec(n, psi))
    GA.check("source-built states: Omega(n) psi = 0, H n = (1 + <D>/2) n at the floor, n lowest, stored h_n reproduced", ok)
    return ok

synthesis.principality-is-genericity:
"""synthesis.principality-is-genericity: exact checks.

For every partition lambda of n (n up to 6) build the standard sl2 triple (e, h, f) in gl_n
block by block, verify the sl2 relations, and compute by exact rank:
  - the centraliser of e (so the conjugation orbit of e has dimension n^2 - dim centraliser),
  - the commutant of the triple (the symmetries left once the embedding is fixed).
"""
from fractions import Fraction as F
import GA
from tp_premise import premise

NMAX = 6


def partitions(n, top=None):
    top = n if top is None else top
    if n == 0:
        yield ()
        return
    for k in range(min(n, top), 0, -1):
        for rest in partitions(n - k, k):
            yield (k,) + rest


def transpose_partition(lam):
    return tuple(sum(1 for p in lam if p > i) for i in range(lam[0])) if lam else ()


def triple(lam):
    n = sum(lam)
    e = [[F(0)] * n for _ in range(n)]
    f = [[F(0)] * n for _ in range(n)]
    h = [[F(0)] * n for _ in range(n)]
    off = 0
    for d in lam:
        for i in range(d):
            h[off + i][off + i] = F(d - 1 - 2 * i)
            if i + 1 < d:
                e[off + i][off + i + 1] = F(1)
                f[off + i + 1][off + i] = F((i + 1) * (d - 1 - i))
        off += d
    return e, h, f


def br(A, B):
    AB, BA = GA.mat_mul(A, B), GA.mat_mul(B, A)
    return [[AB[i][j] - BA[i][j] for j in range(len(A))] for i in range(len(A))]


def scal(c, A):
    return [[c * x for x in row] for row in A]


def nullity_of_ad(mats, n):
    """dim {X in gl_n : [X, M] = 0 for all M in mats}."""
    rows = []
    for M in mats:
        for p in range(n):
            for q in range(n):
                row = [F(0)] * (n * n)
                # [X, M]_{pq} = sum_k X_{pk} M_{kq} - M_{pk} X_{kq}
                for k in range(n):
                    row[p * n + k] += M[k][q]
                    row[k * n + q] -= M[p][k]
                rows.append(row)
    return n * n - GA.rank_of_vectors(rows)


def check_principal_is_the_unique_full_dimensional_orbit():
    """dim orbit(e_lambda) = n^2 - sum (lambda^T_i)^2, which equals n^2 - n (the dimension of the
    nilpotent cone) exactly for lambda = (n); the zero orbit (1^n) is the only conjugation-fixed one."""
    premise("scrambling.imported-kostant-madore-partition-data")
    premise("scrambling.boundary-mode-space-matrix")
    for n in range(2, NMAX + 1):
        top = []
        fixed = []
        for lam in partitions(n):
            e, h, f = triple(lam)
            assert br(h, e) == scal(F(2), e) and br(h, f) == scal(F(-2), f) and br(e, f) == h
            cent = nullity_of_ad([e], n)
            assert cent == sum(c * c for c in transpose_partition(lam))
            orbit = n * n - cent
            assert orbit <= n * n - n
            if orbit == n * n - n:
                top.append(lam)
            if orbit == 0:
                fixed.append(lam)
        assert top == [(n,)]
        assert fixed == [tuple([1] * n)]
    return True


def check_indistinguishable_blocks_are_the_rectangular_types():
    """The commutant of the sl2 image has dimension sum over sizes d of m_d^2 (m_d = multiplicity).
    Its blocks of one size are permuted by GL(m_d); blocks of different sizes are told apart by
    their size. So no block is distinguished exactly for rectangular lambda = (k^m), k | n: for n
    prime only (n) and the zero map (1^n); for composite n also every (k^m), 1 < k < n."""
    premise("scrambling.imported-kostant-madore-partition-data")
    premise("scrambling.boundary-mode-space-matrix")
    for n in range(2, NMAX + 1):
        rect = []
        for lam in partitions(n):
            e, h, f = triple(lam)
            comm = nullity_of_ad([e, f], n)
            mult = {}
            for d in lam:
                mult[d] = mult.get(d, 0) + 1
            assert comm == sum(m * m for m in mult.values())
            if len(mult) == 1:
                rect.append(lam)
        divisors = [k for k in range(n, 0, -1) if n % k == 0]
        assert rect == [tuple([k] * (n // k)) for k in divisors]
        assert (len(rect) == 2) == all(n % k for k in range(2, n))      # n prime
    # n = 4: (2,2) has a GL(2) commutant moving its two blocks into each other
    e, h, f = triple((2, 2))
    assert nullity_of_ad([e, f], 4) == 4
    return True

synthesis.quarter-turn-rotors-of-the-eve:
"""synthesis.quarter-turn-rotors-of-the-even-subalgebra-form-a-state-design-of-order-three: exact checks.

Setting: Cl(p,q), p + q = 2N, with pseudoscalar I of square -1; E the even subalgebra, D = 2^(N-1). A class is a
pair {S, complement of S} of even index sets; its hermitian unit h is the one of e_S, I e_S (up to sign) of square
+1. Gamma is generated by the conjugations by 1 + I h (quarter-turn rotors, unnormalised).
(1) The group: its order in Cl(1,3) and Cl(6,0); each generator acts on the units as a signed transvection; orbits on
    classes and on ordered commuting pairs in Cl(1,3), Cl(3,1), Cl(6,0) and Cl(7,1).
(2) The two identities of a state (a rational idempotent of scalar part 1/D): sum of squares and the product rule.
(3) Averages over Gamma of degree at most three in the coordinates of a state, on a blade state and a generic one,
    against the closed values and against the permutation formula of the imported moments.
(4) The mean purity of a matrix factor against the imported value.
"""
from fractions import Fraction as F
from itertools import combinations, permutations

import GA
from tp_premise import premise

ONE = GA.sc(1)
SIGNATURES_SMALL = ((1, 3), (3, 1), (6, 0))
EXPECTED_ORDER = {(1, 3): 24, (3, 1): 24, (6, 0): 11520}


def key(x):
    return tuple(sorted((b, c) for b, c in x.items() if c != 0))


def nonzero(x):
    return {b: c for b, c in x.items() if c != 0}


class Even(object):
    """Hermitian units, generators and the signed action of the quarter-turn rotors for Cl(p,q)."""

    def __init__(self, p, q):
        self.SQ = GA.sig(p, q)
        self.n = p + q
        self.D = 2 ** (self.n // 2 - 1)
        I = ONE
        for i in range(self.n):
            I = GA.mul(I, GA.gen(i), self.SQ)
        self.I = I
        self.units = []
        seen = set()
        for r in range(0, self.n + 1, 2):
            for S in combinations(range(self.n), r):
                comp = tuple(i for i in range(self.n) if i not in S)
                if S in seen or comp in seen:
                    continue
                seen.add(S)
                seen.add(comp)
                b = ONE
                for i in S:
                    b = GA.mul(b, GA.gen(i), self.SQ)
                h = b if GA.eq(self.m(b, b), ONE) else GA.mul(I, b, self.SQ)
                self.units.append(h)
        self.nz = self.units[1:]
        self.index = {}
        for i, h in enumerate(self.nz):
            self.index[key(h)] = (i, 1)
            self.index[key(GA.neg(h))] = (i, -1)

    def m(self, *xs):
        r = xs[0]
        for x in xs[1:]:
            r = GA.mul(r, x, self.SQ)
        return r

    def rotor_action(self, c):
        """Signed permutation of the nonzero units under conjugation by 1 + I h_c."""
        k = self.m(self.I, self.nz[c])
        up, down = GA.add(ONE, k), GA.sub(ONE, k)
        return tuple(self.index[key(GA.scal(F(1, 2), self.m(up, t, down)))] for t in self.nz)

    def product_sign(self, c, d):
        """(e, eps) with h_c h_d = eps h_e for commuting distinct units, None otherwise."""
        prod = self.m(self.nz[c], self.nz[d])
        return self.index.get(key(prod))

    def group(self):
        gens = [self.rotor_action(c) for c in range(len(self.nz))]
        ident = tuple((i, 1) for i in range(len(self.nz)))
        seen = {ident}
        frontier = [ident]
        while frontier:
            new = []
            for g in frontier:
                for h in gens:
                    x = tuple((h[j][0], h[j][1] * s) for (j, s) in g)
                    if x not in seen:
                        seen.add(x)
                        new.append(x)
            frontier = new
        return gens, seen

    def coordinates(self, rho):
        return [self.D * self.m(rho, h).get((), F(0)) for h in self.nz]

    def blade_state(self):
        comm = []
        for h in self.nz:
            if all(GA.commutes(h, c, self.SQ) for c in comm):
                trial = ONE
                for c in comm + [h]:
                    trial = GA.scal(F(1, 2), self.m(trial, GA.add(ONE, c)))
                if trial.get((), F(0)) == F(1, 2 ** (len(comm) + 1)):
                    comm.append(h)
            if 2 ** len(comm) == self.D:
                break
        rho = ONE
        for c in comm:
            rho = GA.scal(F(1, 2), self.m(rho, GA.add(ONE, c)))
        return rho

    def generic_state(self):
        rho = self.blade_state()
        steps = (F(1, 2), F(2, 3), F(3, 5), F(1, 3), F(5, 7), F(2, 5))
        for j, t in enumerate(steps):
            k = self.m(self.I, self.nz[(5 * j + 1) % len(self.nz)])
            V = GA.add(ONE, GA.scal(t, k))
            Vinv = GA.scal(1 / (1 + t * t), GA.sub(ONE, GA.scal(t, k)))
            rho = self.m(V, rho, Vinv)
        return rho


def orbits(points, moves):
    left = set(points)
    out = []
    while left:
        start = next(iter(left))
        orb = {start}
        frontier = [start]
        while frontier:
            new = []
            for pnt in frontier:
                for mv in moves:
                    y = mv(pnt)
                    if y not in orb:
                        orb.add(y)
                        new.append(y)
            frontier = new
        out.append(orb)
        left -= orb
    return out


def check_group_is_finite_and_transitive_on_classes_and_commuting_pairs():
    premise("synthesis.signed-directions-and-the-integer-clifford-algebra")
    ok = True
    for sgn in SIGNATURES_SMALL + ((7, 1),):
        A = Even(*sgn)
        ok &= GA.eq(A.m(A.I, A.I), GA.sc(-1))
        ok &= len(A.nz) == A.D * A.D - 1
        ok &= all(GA.commutes(A.I, h, A.SQ) for h in A.nz)
        m = len(A.nz)
        acts = [A.rotor_action(c) for c in range(m)]
        anti = [[not GA.commutes(A.nz[c], A.nz[d], A.SQ) for d in range(m)] for c in range(m)]
        # a generator is the transvection of its class: fixed if commuting, moved to the product class otherwise
        for c in range(m):
            for d in range(m):
                image = acts[c][d][0]
                if anti[c][d]:
                    prod = A.m(A.I, A.nz[d], A.nz[c])
                    ok &= A.index[key(prod)][0] == image and image != d
                else:
                    ok &= acts[c][d] == (d, 1)
        ok &= len(orbits(range(m), [lambda x, a=a: a[x][0] for a in acts])) == 1
        pairs = [(c, d) for c in range(m) for d in range(m) if c != d and not anti[c][d]]
        if A.D > 2:
            ok &= len(orbits(pairs, [lambda pr, a=a: (a[pr[0]][0], a[pr[1]][0]) for a in acts])) == 1
            # ordered commuting pairs with a given product: D^2/2 - 2 of them
            count = sum(1 for (c, d) in pairs if A.product_sign(c, d)[0] == 0)
            ok &= 2 * count == A.D * A.D - 4
        else:
            ok &= pairs == []
        if sgn in EXPECTED_ORDER:
            ok &= len(A.group()[1]) == EXPECTED_ORDER[sgn]
    GA.check("the rotor group is finite and transitive on classes and commuting pairs", ok)
    return ok


def check_two_identities_of_a_state():
    premise("synthesis.signed-directions-and-the-integer-clifford-algebra")
    ok = True
    for sgn in SIGNATURES_SMALL:
        A = Even(*sgn)
        for rho in (A.blade_state(), A.generic_state()):
            ok &= GA.eq(nonzero(A.m(rho, rho)), nonzero(rho))
            ok &= rho.get((), F(0)) == F(1, A.D)
            x = A.coordinates(rho)
            rebuilt = GA.scal(F(1, A.D), GA.add(ONE, *[GA.scal(x[i], h) for i, h in enumerate(A.nz)]))
            ok &= GA.eq(nonzero(rebuilt), nonzero(rho))
            ok &= sum(v * v for v in x) == A.D - 1
            for u in range(len(A.nz)):
                total = F(0)
                for c in range(len(A.nz)):
