            img = []
            for g in (e, f, h):
                img += flat(add(mm(X, g), mm(T(g), X)))
            cols.append(img)
        assert n * n - rank(cols) == 1
        # build the solution: eps_{a,b} nonzero only for a + b = n - 1 (weights m, -m)
        # solve the recursion directly and test nondegeneracy and the invariance equations
        eps = zeros(n, n)
        eps[0][n - 1] = F(1)
        for a in range(1, n):
