            # (X e + e^T X)_{a, b+1} = 0 links eps[a][b] and eps[a-1][b+1]
            eps[a][b] = -eps[a - 1][b + 1] * e[a - 1][a] / e[b][b + 1]
        for g in (e, f, h):
