        assert rank([list(r) for r in eps]) == n
        # symmetric for integer j (odd n), symplectic for half-integer j (even n)
        sgn = 1 if n % 2 == 1 else -1
        assert eq(T(eps), scal(sgn, eps))
    half = F(1, 2)
