    return out


def gram_schmidt(vs):
    out = []
    for v in vs:
        w = v
        for u in out:
            w = cadd(w, u, -G(w, u) / G(u, u))
        if G(w, w) != 0:
            out.append(w)
    return out


def proj_sq(w, basis):
    """|P w|^2 in the G metric onto span(basis) (basis G-orthogonal)."""
    return sum((G(w, u) ** 2 / G(u, u) for u in basis), F(0))


