def hess_on_L_n(V, cs, d, npts):
    s_e = q(-1) * Q(d) / (q(2) * Q(cs))
    e = ([s_e * a for a in cs[0]], [s_e * a for a in cs[1]])

    def c_of(s):
        return ([a + s * b + s * s * ee for a, b, ee in zip(cs[0], d[0], e[0])],
                [a + s * b + s * s * ee for a, b, ee in zip(cs[1], d[1], e[1])])
    h = npts // 2
    pts = [F(k, 3) for k in range(-h, h + 1)]
    vals = [V(c_of(p)) for p in pts]
    n = len(pts)
    A = [[p ** j for j in range(n)] + [vals[i]] for i, p in enumerate(pts)]
    for col in range(n):
        piv = next(r for r in range(col, n) if A[r][col] != 0)
        A[col], A[piv] = A[piv], A[col]
        pv = A[col][col]
        A[col] = [v / pv for v in A[col]]
        for r in range(n):
            if r != col and A[r][col] != 0:
                f = A[r][col]
                A[r] = [a - f * b for a, b in zip(A[r], A[col])]
    return A[1][n], 2 * A[2][n]


def make_VW(zeta, Wf):
    def V(c):
        mus = mu(c)
        return (g * g * sum(x * x for x in mus[:3]) + gp * gp * (mus[3] - zeta) ** 2) / 2 + Wf(N(c))
    return V


def charged_dirs(cs):
    d0 = dclam_any(cs)
    out = []
    for d in physical_dirs(cs):
        dd = cadd(d, d0, -G(d, d0) / G(d0, d0))
        if N(dd) != 0:
            out.append(dd)
    return out


def dclam_any(cs):
    lam = -cs[1][0].re
    return dclam(lam)


def check_level_necessary_for_an_off_balanced_vacuum():
    """(i): for V = V_D + W(N) with any W, at a critical family point with m* != 0 the charged pair has
    m_pm^2 = (M_Z^2 - M_W^2)(xi/m* - 1), by exact Hessians on L for a quadratic and a cubic W with
    constants, in two frames on either side of the balanced one; with xi = 0 the charged mass squared is
    -(M_Z^2 - M_W^2) < 0."""
    premise("synthesis.rung-field-d-term-action-and-tree-masses-on-the-lift-locus")
    premise("synthesis.rung-field-on-the-lift-locus")
    Ws = [
        (lambda n: F(3, 2) * (n - F(7)) ** 2, lambda n: 3 * (n - F(7))),
        (lambda n: F(1, 4) * (n - F(2)) ** 3 + F(5) * n, lambda n: F(3, 4) * (n - F(2)) ** 2 + F(5)),
    ]
    seen_zero = False
    for lamstar in (F(1, 2), F(5)):
        cs = clam(lamstar)
        mstar, Nst = m(cs), N(cs)
        GA.check("off the balanced frame", mstar != 0)
        MZ2, MW2 = (g * g + gp * gp) * Nst / 2, g * g * Nst / 2
        tests = list(Ws)
        kz = F(1)
        N0 = Nst + (g * g + gp * gp) * Nst / (8 * kz)
        tests.append((lambda n, N0=N0: kz * (n - N0) ** 2, lambda n, N0=N0: 2 * kz * (n - N0)))
        for Wf, Wp in tests:
            xi = mstar + (4 / (gp * gp)) * (g * g * mstar / 4 + Wp(Nst) * mstar / Nst)
            V = make_VW(xi / 2, Wf)
            first, _ = hess_on_L_n(V, cs, dclam(lamstar), 17)
            GA.check("critical along the family", first == 0)
            pred = (MZ2 - MW2) * (xi / mstar - 1)
            cd = charged_dirs(cs)
            GA.check("charged plane two-dimensional", len(cd) == 2)
            for d in cd + [cadd(cd[0], cd[1])]:
                first, hh = hess_on_L_n(V, cs, d, 17)
                GA.check("critical in the charged plane", first == 0)
                GA.check("m_pm^2 = (M_Z^2 - M_W^2)(xi/m* - 1)", hh / (2 * N(d)) == pred)
            if xi == 0:
                seen_zero = True
                GA.check("xi = 0 gives m_pm^2 = -(M_Z^2 - M_W^2) < 0", pred == -(MZ2 - MW2) and pred < 0)
    GA.check("the xi = 0 case was reached", seen_zero)
    return True

synthesis.rung-unit-transverse-to-norm:
"""synthesis.rung-unit-transverse-to-norm: exact checks in the Clifford algebra of GA.py.

Generators (squares): 0 f+ (+1), 1 f- (-1)  the first rung, holding I = n_inf - (Lambda/6) n_O;
                      2 e+ (+1), 3 e- (-1)  the second rung, v = (e- + e+)/2, w = (e+ - e-)/2;
                      4 x1 (+1), 5 x2 (-1)  two further ground directions for generic lifts.
The lift with unit mu is X_mu(x) = mu n_O' + x + Q(x)/(2 mu) n_inf' with n_O' = -w, n_inf' = 2 v
(mu = 1 is transport.totality's X); the rung boost B_s is v -> s v, w -> w/s, the rest fixed;
* fixes e+ and negates e- (so v* = w).
"""
from fractions import Fraction as F
import GA
from tp_premise import premise

SQ = (1, -1, 1, -1, 1, -1)


def vec(cs):
    return GA.add(*[GA.scal(c, GA.gen(i)) for i, c in enumerate(cs) if c != 0]) if any(cs) else {}


def dot(x, y):
    return GA.dot(x, y, SQ)


def mul(x, y):
    return GA.mul(x, y, SQ)


H = F(1, 2)
V = vec([0, 0, H, H, 0, 0])            # v = (e- + e+)/2
Wm = vec([0, 0, H, -H, 0, 0])          # w = (e+ - e-)/2
NO1 = vec([-H, H, 0, 0, 0, 0])         # n_O of the first rung = (f- - f+)/2
NI1 = vec([1, 1, 0, 0, 0, 0])          # n_inf of the first rung = f- + f+


def I_of(Lam):
    return GA.add(NI1, GA.scal(-Lam / 6, NO1))


def Q(x):
    return dot(x, x)


def X(x, mu):
    """X_mu(x) = mu n_O' + x + Q(x)/(2 mu) n_inf' = -mu w + x + (Q(x)/mu) v."""
    return GA.add(GA.scal(-mu, Wm), x, GA.scal(Q(x) / mu, V))


def coords(x):
    return [x.get((i,), F(0)) for i in range(6)]


def boost(x, s):
    """B_s: v -> s v, w -> w/s on the second rung, identity on generators 0, 1, 4, 5."""
    c = coords(x)
    a, b = c[2], c[3]                  # x has a e+ + b e- = (a + b) v + (a - b) w
    pv, pw = a + b, a - b
    pv, pw = pv * s, pw / s
    # back to e+, e-: p v + q w = (p + q)/2 e+ + (p - q)/2 e-
    c[2], c[3] = (pv + pw) / 2, (pv - pw) / 2
    return vec(c)


def star(x):
    c = coords(x)
    c[3] = -c[3]
    return vec(c)


def rung(x):
    c = coords(x)
    return vec([0, 0, c[2], c[3], 0, 0])


def herm(x):
    return dot(star(x), x)


def proportional(a, b):
    """a = t b for some nonzero rational t (vectors)."""
    ca, cb = coords(a), coords(b)
    k = next(i for i in range(6) if cb[i] != 0)
    t = ca[k] / cb[k]
    return t != 0 and all(ca[i] == t * cb[i] for i in range(6))


def _generic_part():
    lams = (F(3, 5), F(4, 3), F(3), F(-6, 7))
    mus = (F(1), F(2), F(1, 3), F(7, 5))
    gens = [vec([1 if j == i else 0 for j in range(6)]) for i in range(6)]
    for s in mus:
        # the boost is a Klein isometry and keeps the CAR pair
        for a in gens:
            for b in gens:
                assert dot(boost(a, s), boost(b, s)) == dot(a, b)
        bv, bw = boost(V, s), boost(Wm, s)
        assert mul(bv, bv) == {} and mul(bw, bw) == {}
        assert GA.add(mul(bv, bw), mul(bw, bv)) == GA.sc(1)
        # * does not commute with the boost unless s = 1
        assert (star(boost(V, s)) == boost(star(V), s)) == (s == 1)
    xs = [vec([1, 2, 0, 0, 3, 1]), vec([F(1, 2), 0, 0, 0, -1, 2]), vec([0, 1, 0, 0, 1, 1])]
    for mu in mus:
        ep = boost(vec([0, 0, 1, 0, 0, 0]), 1 / mu)        # the boosted e+
        for x in xs:
            Xm = X(x, mu)
            assert Q(Xm) == 0 and Xm == boost(X(x, F(1)), 1 / mu)
            if Q(x) != 0:
                # totality (2) in the boosted frame: e+ X_mu(x) e+ is proportional to X_mu(x/Q(x))
                r = mul(mul(ep, Xm), ep)
                assert proportional(r, X(GA.scal(1 / Q(x), x), mu))
        for Lam in lams:
            I = I_of(Lam)
            assert Q(I) == Lam / 3
            c = rung(X(I, mu))
            assert Q(c) == -Lam / 3                         # Klein norm: Lambda only
            hn = herm(c)
            assert hn == (mu * mu + (Lam / (3 * mu)) ** 2) / 2
            if Lam > 0:
                assert hn - Lam / 3 == (mu - Lam / (3 * mu)) ** 2 / 2
                # mu <-> (Lambda/3)/mu leaves the Hermitian norm unchanged
                assert herm(rung(X(I, Lam / (3 * mu)))) == hn
            # rapidity tangent dc/dmu = -w - Lambda/(3 mu^2) v is Klein-orthogonal to c
            dc = GA.add(GA.scal(-1, Wm), GA.scal(-Lam / (3 * mu * mu), V))
            assert dot(dc, c) == 0 and (Q(c) != 0) == (Lam != 0)
    return True


def check_rung_unit_transverse_to_norm():
    premise("transport.totality")
    premise("standard-model.transported-frozen-point")
    premise("standard-model.imported-tower-commuting-copies-fock-module")
    premise("odd-extensions.transport-constrains-frozen-point-only-through")
    # worked numbers at Lambda = 4/3 (Lambda/3 = 4/9, H = 2/3 in the lift's unit)
    Lam = F(4, 3)
    I = I_of(Lam)
    c1 = rung(X(I, F(1)))
    assert c1 == GA.add(GA.scal(-1, Wm), GA.scal(F(4, 9), V))          # transported-frozen-point (i)
    assert Q(c1) == F(-4, 9) and herm(c1) == F(97, 162)
    c2 = rung(X(I, F(2)))
    assert Q(c2) == F(-4, 9) and herm(c2) == F(328, 162)
    cb = rung(X(I, F(2, 3)))                                            # the balanced frame mu = H
    assert herm(cb) == F(4, 9) == -Q(cb)
    # the reciprocal's lift (transported-frozen-point (ii)) is the frame mu = Lambda/3
    recip = rung(GA.add(GA.scal(Lam / 3, vec([0, 0, -H, H, 0, 0])), GA.scal(H, GA.scal(2, V)), I))
    assert recip == rung(X(I, Lam / 3)) and herm(recip) == herm(c1)
    # a change of Lambda at fixed unit moves c off its level set: (d c/d Lambda) . c = -1/6
    for mu in (F(1), F(5, 2)):
        c = rung(X(I, mu))
        assert dot(GA.scal(1 / (3 * mu), V), c) == F(-1, 6)
        dc = GA.add(GA.scal(-1, Wm), GA.scal(-Lam / (3 * mu * mu), V))
        assert dot(dc, c) == 0
    # the boost by 3 moves the CAR pair but * sees it
    assert herm(boost(V, F(3))) == F(9, 2) and herm(V) == F(1, 2)
    return _generic_part()

synthesis.scalar-sector-at-the-isotropic:
"""synthesis.scalar-sector-at-the-isotropic-scalar-kasner-point-obeys-the-spectator-equation: exact checks.

Background: the isotropic point of the scalar Kasner disk, exponents (1/3, 1/3, 1/3), scalar phi_0 = q log T with
c^2 = 8 pi G q^2 = 2/3. The linearised computation uses the mostly-plus component reading
-dT^2 + T^(2/3) sum (dx^i)^2 (the store's sign dT^2 - ... differs by an overall sign, which changes no mode
equation), in which the Einstein-scalar equations read Ric = 8 pi G dphi dphi. Units: delta phi = q u, so every
coefficient is rational (only c^2 = 2/3 enters).

Perturbation in the gauge with unperturbed spatial metric, momentum k along x^1:
  g_00 = -(1 + 2 f(T) cos kx),  g_01 = b(T) sin kx,  g_ij = T^(2/3) delta_ij,  delta phi = q u(T) cos kx.
A formal engine holds terms  coeff * T^n * A^(d)(T) * trig(k x) * k^m  to first order in one unknown function A
(d = -1: no A factor; trig 0 none, 1 cos, 2 sin), and computes Christoffel symbols and the Ricci tensor exactly.

(1) Background: both five-dimensional isotropic vacuum points reduce to (1/3,1/3,1/3), c^2 = 2/3 (stored map);
    the background Ricci tensor is (2/3) T^-2 on T T only, equal to c^2 T^-2; epsilon = -H'/H^2 = 3.
(2) The three linear operators (f alone, b alone, u alone) of E = delta Ric - 8 pi G delta(dphi dphi): pinned
    component by component. The (0,1) component is (2/3)(k/T)(u - f) sin, the (2,2) component is
    -(1/3) T^(-1/3) f' - (1/3)(k/T) b, so f = u and b = -T^(2/3) u'/k are forced for k != 0.
(3) With f = u = A and b = -T^(2/3) A'/k the (0,0) component is -(A'' + A'/T + k^2 T^(-2/3) A) cos and the (1,1)
    component is T^(2/3) times the same operator; every other component vanishes identically. Modulo the
    spectator equation all ten vanish. Controls: the opposite sign of b, f = 2u, and friction 2 in place of 1 fail.
(4) Order zero: on A = T^(2n/3) (s = (3/2) k T^(2/3)) the operator is k^2 T^(-2/3) s-weights [n^2 s^(n-2) + s^n],
    Bessel order 0; control: order 1/2 fails. The comoving curvature perturbation in this gauge is
    (H/phi_0') delta phi = u/3 = f/3.
(5) Clifford reading: in Cl(1,3) the field hbar^-1(e_0) = (1 + eps F) e_0, hbar^-1(e_1) = a e_1 + eps B e_0,
    hbar^-1(e_i) = a e_i has derived metric with first-order parts 2F, B, 0 in (00, 01, 11), and the residue
    B_w = (1/3) sum e_0 e_i completed by c e_0 e_4 in Cl(1,4) is a unit boost exactly for c^2 = 2/3.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

P_ISO = F(1, 3)
C2 = F(2, 3)
D4 = 4


# ---------------------------------------------------------------- formal engine
def eadd(*xs):
    out = {}
    for x in xs:
        for key, v in x.items():
            nv = out.get(key, 0) + v
            if nv == 0:
                out.pop(key, None)
            else:
                out[key] = nv
    return out


def escal(c, x):
    return {key: c * v for key, v in x.items() if c * v != 0}


def emul(x, y):
    out = {}
    for (n1, d1, t1, m1), v1 in x.items():
        for (n2, d2, t2, m2), v2 in y.items():
            if d1 >= 0 and d2 >= 0:
                continue
            key = (n1 + n2, max(d1, d2), max(t1, t2), m1 + m2)
            nv = out.get(key, 0) + v1 * v2
            if nv == 0:
                out.pop(key, None)
            else:
                out[key] = nv
    return out


def ediff(x, coord):
    """coord 0 = T; coord 1 = the momentum axis; any other coordinate gives 0"""
    out = {}
    for (n, d, t, m), v in x.items():
        if coord == 0:
            if n != 0:
                out = eadd(out, {(n - 1, d, t, m): v * n})
            if d >= 0:
                out = eadd(out, {(n, d + 1, t, m): v})
        elif coord == 1 and t:
            out = eadd(out, {(n, d, 2, m + 1): -v} if t == 1 else {(n, d, 1, m + 1): v})
    return out


def mono(c, n):
    return {(F(n), -1, 0, 0): F(c)} if c != 0 else {}


def ricci(G, Gi):
    D = len(G)
    dG = [[[ediff(G[x][y], c) for c in range(D)] for y in range(D)] for x in range(D)]
    Gam = [[[{} for _ in range(D)] for _ in range(D)] for _ in range(D)]
    for s in range(D):
        for x in range(D):
            for y in range(x, D):
                acc = {}
                for l in range(D):
                    if not Gi[s][l]:
                        continue
                    t = eadd(dG[l][y][x], dG[l][x][y], escal(-1, dG[x][y][l]))
                    if t:
                        acc = eadd(acc, emul(Gi[s][l], t))
                Gam[s][x][y] = Gam[s][y][x] = escal(F(1, 2), acc)
    Ric = {}
    for x in range(D):
        for y in range(x, D):
            acc = {}
            for s in range(D):
                acc = eadd(acc, ediff(Gam[s][x][y], s), escal(-1, ediff(Gam[s][x][s], y)))
                for l in range(D):
                    acc = eadd(acc, emul(Gam[s][s][l], Gam[l][x][y]), escal(-1, emul(Gam[s][y][l], Gam[l][x][s])))
            Ric[(x, y)] = acc
    return Ric


def residual(f_term, b_term, u_coeff, p=P_ISO):
    """E = Ric - 8 pi G dphi dphi for g_00 = -(1 + 2 f), g_01 = b, g_ii = T^(2p), phi = q (log T + u cos kx);
    f_term, b_term are engine expressions (cos and sin carried in the keys), u_coeff multiplies u = A."""
    G = [[{} for _ in range(D4)] for _ in range(D4)]
    Gi = [[{} for _ in range(D4)] for _ in range(D4)]
    G[0][0] = eadd(mono(-1, 0), escal(-2, f_term))
    Gi[0][0] = eadd(mono(-1, 0), escal(2, f_term))
    for i in range(1, D4):
        G[i][i] = mono(1, 2 * p)
        Gi[i][i] = mono(1, -2 * p)
    if b_term:
        G[0][1] = G[1][0] = b_term
        # g^{01} = - g^{00} g^{11} g_01 = T^(-2p) b to first order
        Gi[0][1] = Gi[1][0] = emul(b_term, mono(1, -2 * p))
    Ric = ricci(G, Gi)
    src = {(0, 0): eadd(mono(C2, -2), {(F(-1), 1, 1, 0): 2 * C2 * u_coeff}),
           (0, 1): {(F(-1), 0, 2, 1): -C2 * u_coeff}}
    return {key: eadd(Ric[key], escal(-1, src.get(key, {}))) for key in Ric}


def reduce_ode(x, friction, p=P_ISO):
    """replace A^(d), d >= 2, by derivatives of A'' = -friction A'/T - k^2 T^(-2p) A"""
    while True:
        hi = [key for key in x if key[1] >= 2]
        if not hi:
            return x
        key = max(hi, key=lambda q: q[1])
        n, d, t, m = key
        v = x[key]
        x = dict(x)
        del x[key]
        rhs = {(F(-1), 1, 0, 0): -F(friction), (-2 * p, 0, 0, 2): F(-1)}
        for _ in range(d - 2):
            rhs = ediff(rhs, 0)
        x = eadd(x, {(n + a, dd, t, m + mm): v * c for (a, dd, _, mm), c in rhs.items()})


COS_A = {(F(0), 0, 1, 0): F(1)}                        # A cos kx


def b_solution(sign):
    return {(F(2, 3), 1, 2, -1): F(sign)}              # sign * T^(2/3) A' sin(kx) / k


def spectator(prefactor_power, overall):
    """overall * T^prefactor_power * (A'' + A'/T + k^2 T^(-2/3) A) cos kx"""
    n = F(prefactor_power)
    return {(n, 2, 1, 0): F(overall), (n - 1, 1, 1, 0): F(overall), (n - F(2, 3), 0, 1, 2): F(overall)}


# ---------------------------------------------------------------- checks
def check_background_point():
    premise("synthesis.scalar-kasner-wall-is-reduced-five-dimensional-vacuum-wall")
    for P in ((F(1, 2), F(1, 2), F(1, 2), F(-1, 2)), (F(0), F(0), F(0), F(1))):
        kk = 1 + P[3] / 2
        p = tuple((P[i] + P[3] / 2) / kk for i in range(3))
        c2 = 3 * P[3] * P[3] / (2 * kk * kk)
        GA.check("five-dimensional isotropic vacuum point %s reduces to (1/3,1/3,1/3), c^2 = 2/3" % (P,),
                 sum(P) == 1 and sum(x * x for x in P) == 1 and p == (P_ISO,) * 3 and c2 == C2)
    GA.check("disk relation at the isotropic point: sum p^2 + c^2 = 1", 3 * P_ISO * P_ISO + C2 == 1)
    E = residual({}, {}, 0)
    GA.check("background: Ric = c^2 T^-2 on T T and nothing else (no perturbation)", all(v == {} for v in E.values()))
    bare = residual({}, {}, 0, p=F(1, 2))
    GA.check("control: exponent 1/2 is not a solution with c^2 = 2/3", any(v for v in bare.values()))
    # epsilon = -H'/H^2 with H = p/T, and c^2 = 2 epsilon p^2 (units 8 pi G = 1)
    eps = 1 / P_ISO
    GA.check("epsilon = 3 and c^2 = 2 epsilon H^2 T^2", eps == 3 and 2 * eps * P_ISO * P_ISO == C2)
    return True


def check_three_operators_force_lapse_and_shift():
    premise("synthesis.kasner-approach-coupled-modes-reach-measured-tilt-only-by-a-fitted-curvature-coupling")
    Ef = {k: v for k, v in residual(COS_A, {}, 0).items() if v}
    Eb = {k: v for k, v in residual({}, {(F(0), 0, 2, 0): F(1)}, 0).items() if v}
    Eu = {k: v for k, v in residual({}, {}, 1).items() if v}
    GA.check("lapse operator, pinned",
             Ef == {(0, 0): {(F(-2, 3), 0, 1, 2): F(-1), (F(-1), 1, 1, 0): F(1)},
                    (0, 1): {(F(-1), 0, 2, 1): F(-2, 3)},
                    (1, 1): {(F(-1, 3), 1, 1, 0): F(-1, 3), (F(0), 0, 1, 2): F(1)},
                    (2, 2): {(F(-1, 3), 1, 1, 0): F(-1, 3)},
                    (3, 3): {(F(-1, 3), 1, 1, 0): F(-1, 3)}})
    GA.check("shift operator, pinned",
             Eb == {(0, 0): {(F(-2, 3), 1, 1, 1): F(1)},
                    (1, 1): {(F(0), 1, 1, 1): F(-1), (F(-1), 0, 1, 1): F(-2, 3)},
                    (2, 2): {(F(-1), 0, 1, 1): F(-1, 3)},
                    (3, 3): {(F(-1), 0, 1, 1): F(-1, 3)}})
    GA.check("scalar operator, pinned",
             Eu == {(0, 0): {(F(-1), 1, 1, 0): F(-4, 3)}, (0, 1): {(F(-1), 0, 2, 1): F(2, 3)}})
    # (0,1): -(2/3)(k/T) f + (2/3)(k/T) u = 0 forces f = u
    GA.check("momentum constraint forces f = u",
             eadd(Ef[(0, 1)], Eu[(0, 1)]) == {} and Ef[(0, 1)] != {})
    # (2,2): -(1/3) T^(-1/3) f' - (1/3)(k/T) b = 0 forces b = -T^(2/3) f'/k
    b_from_f = residual({}, b_solution(-1), 0)[(2, 2)]
    GA.check("transverse diagonal component forces b = -T^(2/3) f'/k",
             eadd(Ef[(2, 2)], b_from_f) == {} and eadd(Ef[(2, 2)], residual({}, b_solution(1), 0)[(2, 2)]) != {})
    return True


def check_flat_gauge_solution_is_the_spectator_equation():
    premise("synthesis.kasner-approach-gives-horizon-exit-and-index-three")
    E = residual(COS_A, b_solution(-1), 1)
    nonzero = {k: v for k, v in E.items() if v}
    GA.check("only the (0,0) and (1,1) components survive", sorted(nonzero) == [(0, 0), (1, 1)])
    GA.check("(0,0) component is minus the spectator operator", nonzero[(0, 0)] == spectator(0, -1))
    GA.check("(1,1) component is T^(2/3) times the spectator operator", nonzero[(1, 1)] == spectator(F(2, 3), 1))
    GA.check("all ten components vanish modulo A'' + A'/T + k^2 T^(-2/3) A = 0",
             all(reduce_ode(v, 1) == {} for v in E.values()))
    GA.check("control: friction 2 does not solve the equations",
             any(reduce_ode(v, 2) != {} for v in E.values()))
    wrong_shift = residual(COS_A, b_solution(1), 1)
    GA.check("control: the opposite shift fails", any(reduce_ode(v, 1) != {} for v in wrong_shift.values()))
    wrong_lapse = residual(escal(2, COS_A), b_solution(-1), 1)
    GA.check("control: f = 2u fails", any(reduce_ode(v, 1) != {} for v in wrong_lapse.values()))
    return True


def check_order_zero_and_curvature_perturbation():
    premise("synthesis.kasner-approach-gives-horizon-exit-and-index-three")
    q = 1 - P_ISO

    def bessel(n, nu2):
        """k^2 T^(-2p) [(n^2 - nu^2) s^(n-2) + s^n] with s = T^q / q, in powers of T (k = 1)"""
        out = {-2 * P_ISO + q * (n - 2): q * q * (n * n - nu2), -2 * P_ISO + q * n: F(1)}
        return {x: v for x, v in out.items() if v != 0}

    for n in (F(0), F(1), F(2), F(5, 2), F(-1, 2), F(7, 3)):
        e = q * n                                        # A = T^e, a constant times s^n
        lhs = {e - 2: e * (e - 1) + e, e - 2 * P_ISO: F(1)}
        lhs = {x: v for x, v in lhs.items() if v != 0}
        GA.check("order zero on s^n, n = %s" % n, lhs == bessel(n, F(0)))
        GA.check("control: order 1/2 fails, n = %s" % n, lhs != bessel(n, F(1, 4)))
    GA.check("s = k T^q / q with q = 2/3", q == F(2, 3) and 1 / q == F(3, 2))
    # comoving curvature perturbation in the gauge of unperturbed spatial metric: (H/phi_0') q u = (p/T) u T = p u
    # computed from the background rates: H tau = p, phi_0' tau = q, so (H/phi_0') q u = p u; friction of zeta is
    # (3H + 2 (z'/z - H)) tau = 3p + 2(p - p) with z = (c/p) a, which must equal the spectator's friction 1
    h_tau = P_ISO
    zeta_over_u = h_tau
    friction = 3 * h_tau + 2 * (P_ISO - h_tau)
    GA.check("zeta = u/3 and the friction of zeta from the pump field z = 3 q a is 1/tau",
             zeta_over_u == F(1, 3) and friction == 1)
    # pump field of the curvature perturbation: z^2 = (phi_0'/H)^2 a^2 = (c^2/p^2) a^2 (units 8 pi G = 1)
    GA.check("z^2/a^2 = c^2/p^2 = 6, a constant", C2 / (P_ISO * P_ISO) == 6)
    return True


def check_clifford_frame_and_residue():
    premise("synthesis.scalar-kasner-wall-is-reduced-five-dimensional-vacuum-wall")
    sq = (1, -1, -1, -1)
    a, Fv, Bv = F(7, 5), F(3, 11), F(-2, 13)
    met = {}
    for eps in (F(1, 9), F(-1, 9)):
        h = [GA.scal(1 + eps * Fv, GA.gen(0)), GA.add(GA.scal(a, GA.gen(1)), GA.scal(eps * Bv, GA.gen(0))),
             GA.scal(a, GA.gen(2)), GA.scal(a, GA.gen(3))]
        met[eps] = {(i, j): GA.dot(h[i], h[j], sq) for i in range(4) for j in range(i, 4)}
    e1, e2 = F(1, 9), F(-1, 9)
    lin = {key: (met[e1][key] - met[e2][key]) / (e1 - e2) for key in met[e1]}
    expect = {key: F(0) for key in lin}
    expect[(0, 0)] = 2 * Fv
    expect[(0, 1)] = Bv
    GA.check("first-order derived metric: 2F on (0,0), B on (0,1), nothing else", lin == expect)
    even = {key: (met[e1][key] + met[e2][key]) / 2 for key in met[e1]}
    GA.check("zeroth order diag(1, -a^2, -a^2, -a^2), corrections of second order only",
             even[(0, 0)] == 1 + e1 * e1 * Fv * Fv and even[(1, 1)] == -a * a + e1 * e1 * Bv * Bv
             and even[(2, 2)] == -a * a and even[(3, 3)] == -a * a and even[(1, 2)] == 0 and even[(0, 1)] == e1 * e1 * Fv * Bv)
    sq5 = (1, -1, -1, -1, -1)
    Bw = GA.scal(P_ISO, GA.add(GA.mul(GA.gen(0), GA.gen(1), sq5), GA.mul(GA.gen(0), GA.gen(2), sq5),
                             GA.mul(GA.gen(0), GA.gen(3), sq5)))
    B4 = GA.mul(GA.gen(0), GA.gen(4), sq5)
    GA.check("B_w^2 = 1/3, so 1 - B_w^2 = c^2 = 2/3", GA.eq(GA.mul(Bw, Bw, sq5), GA.sc(F(1, 3))) and 1 - F(1, 3) == C2)
    cross = GA.add(GA.mul(Bw, B4, sq5), GA.mul(B4, Bw, sq5))
    GA.check("B_w and e_0 e_4 anticommute and (e_0 e_4)^2 = 1: the completed residue squares to B_w^2 + c^2 = 1",
             GA.is_zero(cross) and GA.eq(GA.mul(B4, B4, sq5), GA.sc(1)))
    return True

synthesis.set-and-clear-of-a-bit-generat:
"""synthesis.set-and-clear-of-a-bit-generate-the-hyperbolic-plane: exact checks.

The bit is modelled by 2 x 2 matrices in the basis (s_off, s_on); integer entries stay integral,
so the identities checked hold over Z and, by reduction, over every commutative ring. Targets of
the universal property are switches in Clifford algebras computed with GA.py and conjugates of the
model under GL_2(Z).
"""
from fractions import Fraction as F
from itertools import combinations, product

import GA


def M(a, b, c, d):
    return ((F(a), F(b)), (F(c), F(d)))


def mm(A, B):
    n = len(A)
    return tuple(tuple(sum(A[i][k] * B[k][j] for k in range(n)) for j in range(n)) for i in range(n))


def ma(A, B):
    return tuple(tuple(x + y for x, y in zip(r, s)) for r, s in zip(A, B))


def ms(c, A):
    return tuple(tuple(F(c) * x for x in r) for r in A)


def flat(A):
    return [x for r in A for x in r]


I2, Z2 = M(1, 0, 0, 1), M(0, 0, 0, 0)
# states: s_off = (1,0)^T, s_on = (0,1)^T
V = M(0, 0, 1, 0)      # set:   off -> on, on -> 0
W = M(0, 1, 0, 0)      # clear: on -> off, off -> 0
VW, WV = mm(V, W), mm(W, V)


def det(A):
    return A[0][0] * A[1][1] - A[0][1] * A[1][0]


def inv(A):
    d = det(A)
    return ms(1 / d, ((A[1][1], -A[0][1]), (-A[1][0], A[0][0])))


def is_scalar(A):
    return A[0][1] == 0 and A[1][0] == 0 and A[0][0] == A[1][1]


def check_set_and_clear_are_a_switch_with_tests():
    assert mm(V, V) == Z2 and mm(W, W) == Z2
    assert ma(VW, WV) == I2
    assert mm(VW, VW) == VW and mm(WV, WV) == WV and mm(VW, WV) == Z2 and mm(WV, VW) == Z2
    assert VW == M(0, 0, 0, 1) and WV == M(1, 0, 0, 0)      # is-on, is-off
    return True


def _det4(rows):
    m = [list(r) for r in rows]
    d = F(1)
    for c in range(4):
        p = next((r for r in range(c, 4) if m[r][c] != 0), None)
        if p is None:
            return F(0)
        if p != c:
            m[c], m[p] = m[p], m[c]
            d = -d
        d *= m[c][c]
        for r in range(c + 1, 4):
            f = m[r][c] / m[c][c]
            m[r] = [a - f * b for a, b in zip(m[r], m[c])]
    return d


def check_basis_of_the_endomorphisms_over_the_integers():
    assert (WV, W, V, VW) == (M(1, 0, 0, 0), M(0, 1, 0, 0), M(0, 0, 1, 0), M(0, 0, 0, 1))
    assert abs(_det4([flat(I2), flat(V), flat(W), flat(VW)])) == 1
    return True


BOX = list(range(-4, 5))


def check_square_is_the_hyperbolic_form():
    for a, b in product(BOX, repeat=2):
        x = ma(ms(a, V), ms(b, W))
        assert mm(x, x) == ms(a * b, I2)
    x = ma(ms(3, V), ms(5, W))          # hand value: (3v + 5w)^2 = 15
    assert mm(x, x) == ms(15, I2)
    x = ma(ms(-2, V), ms(7, W))         # hand value: (-2v + 7w)^2 = -14
    assert mm(x, x) == ms(-14, I2)
    return True


def _table_ok(one, a, b, mul_, lin_eq):
    src = [I2, V, W, VW]
    tgt = [one, a, b, mul_(a, b)]

    def coords(X):   # X = p*1 + r*v + q*w + (s - p)*vw for X = [[p, q], [r, s]]
        return [X[0][0], X[1][0], X[0][1], X[1][1] - X[0][0]]
    return all(lin_eq(mul_(tgt[i], tgt[j]), coords(mm(src[i], src[j])), tgt) for i in range(4) for j in range(4))


def check_universal_property_on_target_switches():
    h = F(1, 2)

    def ga_target(sq, a, b):
        mul_ = lambda x, y: GA.mul(x, y, sq)
        assert GA.is_zero(mul_(a, a)) and GA.is_zero(mul_(b, b)) and GA.eq(GA.add(mul_(a, b), mul_(b, a)), GA.sc(1))

        def lin_eq(lhs, c, tgt):
            rhs = {}
            for ci, t in zip(c, tgt):
                rhs = GA.add(rhs, GA.scal(ci, t))
            return GA.eq(lhs, rhs)
        return _table_ok(GA.sc(1), a, b, mul_, lin_eq)
    s11, s22 = GA.sig(1, 1), GA.sig(2, 2)
    assert ga_target(s11, GA.scal(h, GA.add(GA.gen(0), GA.gen(1))), GA.scal(h, GA.sub(GA.gen(0), GA.gen(1))))
    a22, b22 = GA.scal(h, GA.add(GA.gen(0), GA.gen(2))), GA.scal(h, GA.sub(GA.gen(0), GA.gen(2)))
    assert ga_target(s22, a22, b22)
    # a switch that is not a pair of vectors: conjugate by the unit 1 + n, n nilpotent
    n_ = GA.mul(GA.scal(h, GA.add(GA.gen(1), GA.gen(3))), GA.gen(0), s22)
    u, ui = GA.add(GA.sc(1), n_), GA.sub(GA.sc(1), n_)
    assert GA.eq(GA.mul(u, ui, s22), GA.sc(1))
    conj = lambda x: GA.mul(GA.mul(u, x, s22), ui, s22)
    assert ga_target(s22, conj(a22), conj(b22))
    # integer switches: GL_2(Z)-conjugates of (v, w)
    count = 0
    for p, q, r, s in product(range(-2, 3), repeat=4):
        g = M(p, q, r, s)
        if abs(det(g)) != 1:
            continue
        gi = inv(g)
        a, b = mm(mm(g, V), gi), mm(mm(g, W), gi)

        def lin_eq(lhs, c, tgt):
            rhs = Z2
            for ci, t in zip(c, tgt):
                rhs = ma(rhs, ms(ci, t))
            return lhs == rhs
        assert _table_ok(I2, a, b, mm, lin_eq)
        count += 1
    assert count == 104      # the unimodular integer matrices with entries in [-2, 2]
    return True


def check_orthonormal_pair_from_the_switch():
    ep, em = ma(V, W), ma(V, ms(-1, W))
    assert mm(ep, ep) == I2 and mm(em, em) == ms(-1, I2)
    assert mm(ep, em) == ms(-1, mm(em, ep)) == ma(WV, ms(-1, VW))
    assert ep == M(0, 1, 1, 0) and mm(ep, em) == M(1, 0, 0, -1)
    return True

synthesis.signed-directions-and-the-inte:
"""synthesis.signed-directions-and-the-integer-clifford-algebra: exact checks.

A configuration S of the n directions is a bitmask; e_S is the increasing product. The group G of
the premise is built from its relations alone, by rewriting words in the letters c, e_1, ..., e_n
(c central, c^2 = 1, e_i e_i -> c^{s_i}, e_i e_j -> c e_j e_i for i > j); s is the sign vector
(s_i = 1 when e_i^2 = c). The algebra A = Z[G]/(c + 1) is built from the integer group ring.
Everything is exact: integers for Z, Fractions (GA.py) where an algebra over Q or R is compared.
No premise: the result is self-contained (the stored blade-square-sign theorem is a comparison).
(0) Existence: the bilinear cocycle f gives a group on {0,1} x F_2^n with the relations, for every
    sign vector with n <= 4, equal to the rewriting product.
(1) The sign: two directions force c^2 = 1 (the Heisenberg group mod k reads its relation both ways
    only for k = 2); for one direction the clause is independent (Z_{2m} with c = e^2).
(2) Normal form and table: the rewriting product is associative with 2^{n+1} elements, equals the
    GA product of blades with c -> -1, every square and commutator lies in {1, c}, and q, b have the
    closed forms C(|S|,2) + |S cap N| and |S||T| + |S cap T|.
(3) Centre: {1, c} for n even (extraspecial: centre = commutators = squares), {1, c, e_full,
    c e_full} for n odd; central involutions other than 1: c alone unless n odd and q(full) = 0.
(4) The integer algebra: the ideal (c + 1) is the Z-span of the (1 + c) e_S, the quotient is free
    of rank 2^n with blade basis, structure constants are integers equal to the GA ones, and
    v^2 = Q(v) for integer and rational vectors.
(5) Universal property: maps of the directions to anticommuting elements of square (-1)^{s_i} in
    Cl(p+1, q+1) (twisted generators), in rotor-conjugated frames and in A itself extend to
    algebra maps, multiplicative on every pair of blades; base change to F_2 gives the commutative
    group algebra of the configurations.
(6) Classification: for every pair of signatures of the same n <= 6, the forms are equivalent over
    F_2 exactly when the Gauss sums agree; an explicit F_2-isometry is built and lifted to anticommuting
    blades in GA, giving the algebra isomorphism over Z (blades to signed blades); the trace form
    Tr(L_{xy}) / 2^n is the scalar part and is diagonal in the blades with entries e_S^2.
"""
from fractions import Fraction as F
from itertools import product

import GA


# ---------------------------------------------------------------- helpers (not mutated)

def idx(mask, n):
    return [i for i in range(n) if mask >> i & 1]


def popcount(m):
    return bin(m).count("1")


def reduce_word(word, s):
    """Normal form (a, mask) of a word in 'c' and direction indices, from the relations only."""
    a = sum(1 for x in word if x == "c")
    lst = [x for x in word if x != "c"]
    i = 0
    while i < len(lst) - 1:
        if lst[i] < lst[i + 1]:
            i += 1
        elif lst[i] > lst[i + 1]:
            lst[i], lst[i + 1] = lst[i + 1], lst[i]      # e_i e_j = c e_j e_i
            a += 1
            i = max(i - 1, 0)
        else:
            a += s[lst[i]]                                  # e_i e_i = c^{s_i}
            del lst[i:i + 2]
            i = max(i - 1, 0)
    mask = 0
    for x in lst:
        assert not mask >> x & 1
        mask |= 1 << x
    assert lst == sorted(lst)
    return (a % 2, mask)


def gmul(x, y, s):
    n = len(s)
    return reduce_word(["c"] * x[0] + idx(x[1], n) + ["c"] * y[0] + idx(y[1], n), s)


def elements(n):
    return [(a, m) for a in (0, 1) for m in range(2 ** n)]


def ginv(x, s):
    return [y for y in elements(len(s)) if gmul(x, y, s) == (0, 0)][0]


def squares_of(s):
    return tuple(1 if t == 0 else -1 for t in s)


def blade(mask, n):
    return tuple(idx(mask, n))


def ga_elem(x, n):
    return {blade(x[1], n): F(-1) ** x[0]}


def qf(s):
    n = len(s)
    return [reduce_word(idx(m, n) + idx(m, n), s)[0] for m in range(2 ** n)]


def bform(qv, x, y):
    return qv[x ^ y] ^ qv[x] ^ qv[y]


def gauss(qv):
    return sum(1 - 2 * t for t in qv)


def sign_vectors(n):
    return [tuple(v) for v in product((0, 1), repeat=n)]


# integer algebra A = Z[G]/(c + 1): elements {mask: int}
def amul(x, y, s):
    out = {}
    n = len(s)
    for m1, c1 in x.items():
        for m2, c2 in y.items():
            a, m = gmul((0, m1), (0, m2), s)
            out[m] = out.get(m, 0) + (-1) ** a * c1 * c2
    return {m: c for m, c in out.items() if c != 0}


def quotient(z):
    """Z[G] -> A: c^a e_S -> (-1)^a e_S; z = {(a, mask): int}."""
    out = {}
    for (a, m), k in z.items():
        out[m] = out.get(m, 0) + (-1) ** a * k
    return {m: c for m, c in out.items() if c != 0}


def gring_mul(x, y, s):
    out = {}
    for g, c1 in x.items():
        for h, c2 in y.items():
            k = gmul(g, h, s)
            out[k] = out.get(k, 0) + c1 * c2
    return {k: c for k, c in out.items() if c != 0}


def det_int(M):
    """Exact determinant (Fractions, Bareiss-free elimination)."""
    M = [[F(v) for v in row] for row in M]
    n, d = len(M), F(1)
    for col in range(n):
        piv = next((r for r in range(col, n) if M[r][col] != 0), None)
        if piv is None:
            return F(0)
        if piv != col:
            M[col], M[piv] = M[piv], M[col]
            d = -d
        d *= M[col][col]
        for r in range(col + 1, n):
            f = M[r][col] / M[col][col]
            M[r] = [M[r][j] - f * M[col][j] for j in range(n)]
    return d


# F_2 linear algebra on bitmasks
def solve_f2(basis, x):
    """Coordinates of x in the F_2-basis (list of masks); exact Gaussian elimination."""
    n = len(basis)
    rows = [(basis[k], 1 << k) for k in range(n)]
    red = []
    for v, tag in rows:
        for (pv, pt, bit) in red:
            if v >> bit & 1:
                v ^= pv
                tag ^= pt
        if v:
            bit = v.bit_length() - 1
            red2 = []
            for (pv, pt, b2) in red:
                if pv >> bit & 1:
                    pv ^= v
                    pt ^= tag
                red2.append((pv, pt, b2))
            red = red2 + [(v, tag, bit)]
    assert len(red) == n
    coord = 0
    for (pv, pt, bit) in red:
        if x >> bit & 1:
            x ^= pv
            coord ^= pt
    assert x == 0
    return coord


def canon(qv, n):
    """A basis in which q is H + ... + H (+ P) (+ <z>), and its type (#P, q(z) or None)."""
    full = 2 ** n - 1
    z = full if n % 2 else None
    if z is not None:
        assert all(bform(qv, z, 1 << i) == 0 for i in range(n))
        W = [1 << i for i in range(n - 1)]
    else:
        W = [1 << i for i in range(n)]
    pairs = []

    def reduce_pairs(vecs):
        out = []
        vecs = list(vecs)
        while vecs:
            u = vecs.pop(0)
            k = next(k for k, w in enumerate(vecs) if bform(qv, u, w) == 1)
            w = vecs.pop(k)
            vecs = [v ^ (u if bform(qv, v, w) else 0) ^ (w if bform(qv, v, u) else 0) for v in vecs]
            if qv[u] == 0 and qv[w] == 1:
                w ^= u
            elif qv[u] == 1 and qv[w] == 0:
                u ^= w
            out.append((u, w))
        return out

    pairs = reduce_pairs(W)
    while True:
        Ps = [pr for pr in pairs if qv[pr[0]] == 1]
        if len(Ps) < 2:
            break
        (u1, w1), (u2, w2) = Ps[0], Ps[1]
        rest = [pr for pr in pairs if pr not in (Ps[0], Ps[1])]
        new = reduce_pairs([u1 ^ u2, w1 ^ u2, u1, w2])
        pairs = rest + new
    Ps = [pr for pr in pairs if qv[pr[0]] == 1]
    if z is not None and qv[z] == 1 and Ps:
        (u, w) = Ps[0]
        pairs = [pr for pr in pairs if pr != Ps[0]] + reduce_pairs([u ^ z, w])
        Ps = [pr for pr in pairs if qv[pr[0]] == 1]
    Hs = [pr for pr in pairs if qv[pr[0]] == 0]
    for (u, w) in Hs:
        assert qv[u] == 0 and qv[w] == 0 and bform(qv, u, w) == 1
    basis = [v for pr in Hs + Ps for v in pr] + ([z] if z is not None else [])
    return basis, (len(Ps), None if z is None else qv[z])


def isometry(s, t):
    """An F_2-linear bijection A with q_t(A x) = q_s(x), or None; built from the canonical bases."""
    n = len(s)
    qs, qt = qf(s), qf(t)
    bs, ts_ = canon(qs, n)
    bt, tt = canon(qt, n)
    if ts_ != tt:
        return None

    def A(x):
        c = solve_f2(bs, x)
        y = 0
        for k in range(n):
            if c >> k & 1:
                y ^= bt[k]
        return y
    return A


# ---------------------------------------------------------------- checks

def fcoc(S, T, s):
    """The bilinear cocycle f(S,T) = #{(i,j) in S x T : i > j} + |S cap T cap N| mod 2."""
    n = len(s)
    return (sum(1 for i in idx(S, n) for j in idx(T, n) if i > j)
            + sum(s[i] for i in idx(S & T, n))) % 2


def check_existence_by_the_bilinear_cocycle():
    groups = 0
    for n in range(1, 5):
        for s in sign_vectors(n):
            E = elements(n)

            def cm(x, y):
                return ((x[0] + y[0] + fcoc(x[1], y[1], s)) % 2, x[1] ^ y[1])
            for x in E:
                for y in E:
                    assert cm(x, y) == gmul(x, y, s)
                    for z in E:
                        assert cm(cm(x, y), z) == cm(x, cm(y, z))
                inv = ((x[0] + fcoc(x[1], x[1], s)) % 2, x[1])
                assert cm(x, inv) == (0, 0) == cm(inv, x) and cm(x, (0, 0)) == x
            c = (1, 0)
            assert c != (0, 0) and cm(c, c) == (0, 0)
            assert all(cm(c, x) == cm(x, c) for x in E)
            for i in range(n):
                ei = (0, 1 << i)
                assert cm(ei, ei) == (s[i], 0)
                for j in range(n):
                    if i != j:
                        ej = (0, 1 << j)
                        assert cm(ei, ej) == cm(c, cm(ej, ei))
            for m in range(2 ** n):
                x = (0, 0)
                for i in idx(m, n):
                    x = cm(x, (0, 1 << i))
                assert x == (0, m)
            groups += 1
    assert groups == 2 + 4 + 8 + 16
    return True


def check_radical_and_gauss_sums_over_the_integers():
    j = {(0,): F(1)}
    Z1 = GA.sig(0, 1)
    one = GA.sc(1)
    assert GA.eq(GA.mul(j, j, Z1), GA.sc(-1))
    table = {0: (1, 0), 2: (1, 0), 4: (-1, 0), 6: (-1, 0), 1: (1, 1), 5: (-1, 1), 3: (0, 0), 7: (0, 0)}
    count = 0
    for n in range(1, 9):
        full = 2 ** n - 1
        for p in range(n + 1):
            q = n - p
            s = tuple([0] * p + [1] * q)
            qv = qf(s)
            rad = [x for x in range(2 ** n) if all(bform(qv, x, 1 << i) == 0 for i in range(n))]
            assert rad == ([0] if n % 2 == 0 else [0, full])
            x = GA.sub(one, j)
            for _ in range(p):
                x = GA.mul(x, GA.add(one, j), Z1)
            for _ in range(q):
                x = GA.mul(x, GA.sub(one, j), Z1)
            assert all(v.denominator == 1 for v in x.values())
            g = gauss(qv)
            assert x.get((), F(0)) == g
            sign, odd = table[(p - q) % 8]
            assert g == sign * 2 ** ((n + odd) // 2)
            count += 1
    assert count == 44
    return True

def check_the_sign_bit_is_forced():
    # two directions: Heisenberg group mod k, (x,y,z)(x',y',z') = (x+x', y+y', z+z'+x y');
    # e1 e2 = c e2 e1 with c = (0,0,1); the exchanged relation e2 e1 = c e1 e2 holds iff c^2 = 1
    both_ways = []
    for k in range(2, 8):
        def hm(u, v):
            return ((u[0] + v[0]) % k, (u[1] + v[1]) % k, (u[2] + v[2] + u[0] * v[1]) % k)
        e1, e2, c = (1, 0, 0), (0, 1, 0), (0, 0, 1)
        assert hm(e1, e2) == hm(c, hm(e2, e1))
        sym = hm(e2, e1) == hm(c, hm(e1, e2))
        csq = hm(c, c) == (0, 0, 0)
        assert sym == csq
        both_ways.append(sym)
    assert both_ways == [True, False, False, False, False, False]
    # in the group of the premise (n >= 2) the relation holds both ways and c^2 = 1
    for s in ((0, 0), (0, 1), (1, 1), (0, 1, 1)):
        c = (1, 0)
        assert gmul(c, c, s) == (0, 0)
        e1, e2 = (0, 1), (0, 2)
        assert gmul(e1, e2, s) == gmul(c, gmul(e2, e1, s), s)
        assert gmul(e2, e1, s) == gmul(c, gmul(e1, e2, s), s)
    # one direction: Z_{2m}, e = 1, c = e^2 = 2: c central, c != 1, G/<c> of order 2,
    # and c^2 = 1 exactly when m = 2: the order clause is independent at n = 1
    orders = []
    for m in range(2, 8):
        N = 2 * m
        c = 2 % N
        sub = {(c * t) % N for t in range(N)}
        assert c != 0 and N // len(sub) == 2
        orders.append(len(sub))
        assert ((2 * c) % N == 0) == (m == 2)
    assert orders == [2, 3, 4, 5, 6, 7]
    return True


def check_normal_form_table_squares_commutators():
    count = 0
    for n in range(1, 6):
        for s in sign_vectors(n):
            if n == 5 and s != tuple(sorted(s)):
                continue
            Sq = squares_of(s)
            E = elements(n)
            assert len(set(E)) == 2 ** (n + 1)
            neg = sum(1 << i for i in range(n) if s[i])
            qv = qf(s)
            for x in E:
                for y in E:
                    xy = gmul(x, y, s)
                    # the rewriting product is the GA product of signed blades with c -> -1
                    assert GA.eq(ga_elem(xy, n), GA.mul(ga_elem(x, n), ga_elem(y, n), Sq))
                    yx = gmul(y, x, s)
                    comm = gmul(gmul(x, y, s), ginv(yx, s), s) if n <= 3 else None
                    if comm is not None:
                        assert comm in ((0, 0), (1, 0))
                    # commutator form b(S, T) = |S||T| + |S cap T|, read from xy = c^b yx
                    b = 0 if xy == yx else 1
                    assert xy == (yx[0] ^ b, yx[1])
                    assert b == (popcount(x[1]) * popcount(y[1]) + popcount(x[1] & y[1])) % 2
                    assert b == bform(qv, x[1], y[1])
                sq = gmul(x, x, s)
                assert sq[1] == 0 and sq[0] == qv[x[1]]
                k = popcount(x[1])
                assert qv[x[1]] == (k * (k - 1) // 2 + popcount(x[1] & neg)) % 2
            if n <= 3:
                for x in E:
                    for y in E:
                        for z in E:
                            assert gmul(gmul(x, y, s), z, s) == gmul(x, gmul(y, z, s), s)
            if n >= 2:
                sqs = {gmul(x, x, s) for x in E}
                assert sqs == {(0, 0), (1, 0)}
            count += 1
    assert count == 2 + 4 + 8 + 16 + 6
    return True


def check_centre_and_extraspecial():
    seen = []
    for n in range(1, 6):
        for p in range(n + 1):
            s = tuple([0] * p + [1] * (n - p))
            E = elements(n)
            Z = [x for x in E if all(gmul(x, y, s) == gmul(y, x, s) for y in E)]
            full = 2 ** n - 1
            if n % 2 == 0:
                assert Z == [(0, 0), (1, 0)]
            else:
                assert sorted(Z) == [(0, 0), (0, full), (1, 0), (1, full)]
            invol = [x for x in Z if x != (0, 0) and gmul(x, x, s) == (0, 0)]
            qfull = qf(s)[full]
            assert len(invol) == (1 if n % 2 == 0 or qfull == 1 else 3)
            comms = {gmul(gmul(x, y, s), ginv(gmul(y, x, s), s), s) for x in E for y in E}
            sqs = {gmul(x, x, s) for x in E}
            if n % 2 == 0:
                # extraspecial: centre = commutator subgroup = squares = {1, c}, order 2^{1+n}
                assert set(Z) == comms == sqs == {(0, 0), (1, 0)} and len(E) == 2 ** (1 + n)
            seen.append((n, p, len(Z), len(invol)))
    assert len(seen) == 20
    assert [x for x in seen if x[0] == 3] == [(3, 0, 4, 3), (3, 1, 4, 1), (3, 2, 4, 3), (3, 3, 4, 1)]
    return True


def check_integer_algebra_free_and_contraction():
    total = 0
    for n in range(1, 5):
        for s in sign_vectors(n):
            Sq = squares_of(s)
            E = elements(n)
            cp1 = {(1, 0): 1, (0, 0): 1}
            # the two-sided ideal (c + 1): every g (c + 1) h is (c + 1) gh, in the span of (1 + c) e_S
            span = {m: {(0, m): 1, (1, m): 1} for m in range(2 ** n)}
            for g in E:
                for h in E:
                    z = gring_mul(gring_mul({g: 1}, cp1, s), {h: 1}, s)
                    m = gmul(g, h, s)[1]
                    assert z == span[m]
                    assert quotient(z) == {}
            # a Z-basis of Z[G]: the (1 + c) e_S and the e_S (unimodular), so A is free on the e_S
            cols = [(0, m) for m in range(2 ** n)] + [(1, m) for m in range(2 ** n)]
            M = [[span[m].get(cc, 0) for cc in cols] for m in range(2 ** n)]
            M += [[1 if cc == (0, m) else 0 for cc in cols] for m in range(2 ** n)]
            assert abs(det_int(M)) == 1
            # quotient is a ring map; structure constants are integers and equal to GA's
            for x in E:
                for y in E:
                    lhs = quotient(gring_mul({x: 1}, {y: 1}, s))
                    rhs = amul(quotient({x: 1}), quotient({y: 1}), s)
                    assert lhs == rhs
            for m1 in range(2 ** n):
                for m2 in range(2 ** n):
                    pr = amul({m1: 1}, {m2: 1}, s)
                    ga = GA.mul({blade(m1, n): F(1)}, {blade(m2, n): F(1)}, Sq)
                    assert {blade(m, n): F(c) for m, c in pr.items()} == ga
            # v^2 = Q(v) for integer vectors with entries in [-2, 2]
            for a in product(range(-2, 3), repeat=n):
                v = {1 << i: a[i] for i in range(n) if a[i]}
                Qv = sum((-1) ** s[i] * a[i] ** 2 for i in range(n))
                assert amul(v, v, s) == ({0: Qv} if Qv else {})
                total += 1
    assert total == 2 * 5 + 4 * 25 + 8 * 125 + 16 * 625
    # over Q (base change): v^2 = Q(v) with rational coefficients in Cl(p,q)
    for p, q in ((3, 0), (1, 3), (2, 2)):
        S = GA.sig(p, q)
        coeffs = [F(1, 2), F(-2, 3), F(5, 7), F(3, 4)]
        v = GA.add(*[GA.scal(coeffs[i], GA.gen(i)) for i in range(p + q)])
        Qv = sum(S[i] * coeffs[i] ** 2 for i in range(p + q))
        assert GA.eq(GA.mul(v, v, S), GA.sc(Qv))
    return True


def check_universal_property_and_base_change():
    cases = 0
    for p, q in ((1, 0), (0, 1), (2, 0), (1, 1), (0, 2), (3, 0), (1, 2), (2, 2), (1, 3)):
        n = p + q
        s = tuple([0] * p + [1] * q)
        Sq = squares_of(s)
        targets = []
        # (a) twisted generators x_i omega in Cl(p+1, q+1), omega = e f
        B1 = tuple(list(Sq) + [1, -1])
        om = {(n, n + 1): F(1)}
        targets.append((B1, [GA.mul(GA.gen(i), om, B1) for i in range(n)]))
        # (b) a frame conjugated by the rational rotor R = 2 + e_1 e_2 (or 2 + e_1 for n = 1)
        Rr = GA.add(GA.sc(2), {(0, 1): F(1)} if n >= 2 else {(0,): F(1)})
        Rb = GA.reverse(Rr) if n >= 2 else GA.grade_inv(Rr)
        RR = GA.mul(Rr, Rb, Sq)
        assert list(RR) == [()]
        Rinv = GA.scal(F(1) / RR[()], Rb)
        assert GA.eq(GA.mul(Rr, Rinv, Sq), GA.sc(1))
        targets.append((Sq, [GA.mul(GA.mul(Rr, GA.gen(i), Sq), Rinv, Sq) for i in range(n)]))
        # (c) the grade involution of A itself: e_i -> -e_i (integer coefficients)
        targets.append((Sq, [GA.neg(GA.gen(i)) for i in range(n)]))
        for B, u in targets:
            for i in range(n):
                assert GA.eq(GA.mul(u[i], u[i], B), GA.sc(Sq[i]))
                for j in range(i):
                    assert GA.anticommutes(u[i], u[j], B)
            # F(e_S) = product of the u_i; multiplicative on all blades
            def Fm(m):
                x = GA.sc(1)
                for i in idx(m, n):
                    x = GA.mul(x, u[i], B)
                return x
            for m1 in range(2 ** n):
                for m2 in range(2 ** n):
                    pr = amul({m1: 1}, {m2: 1}, s)
                    lhs = GA.add(*[GA.scal(c, Fm(m)) for m, c in pr.items()])
                    assert GA.eq(lhs, GA.mul(Fm(m1), Fm(m2), B))
            cases += 1
    assert cases == 27
    # base change to F_2: structure constants reduce to e_S e_T = e_{S xor T}, commutative
    for s in sign_vectors(3):
        for m1 in range(8):
            for m2 in range(8):
                pr = amul({m1: 1}, {m2: 1}, s)
                assert len(pr) == 1 and list(pr)[0] == m1 ^ m2 and pr[m1 ^ m2] % 2 == 1
    return True


def check_classification_by_gauss_sum():
    pairs_iso = 0
    pairs_non = 0
    for n in range(1, 7):
        sigs = [tuple(v) for v in sign_vectors(n)] if n <= 3 else \
            [tuple([0] * p + [1] * (n - p)) for p in range(n + 1)]
        for s in sigs:
            for t in sigs:
                qs, qt = qf(s), qf(t)
                A = isometry(s, t)
                same = gauss(qs) == gauss(qt)
                assert (A is not None) == same
                if A is None:
                    pairs_non += 1
                    continue
                imgs = [A(1 << i) for i in range(n)]
                assert solve_f2(imgs, 2 ** n - 1) >= 0          # A is bijective
                for x in range(2 ** n):
                    y = 0
                    for i in idx(x, n):
                        y ^= imgs[i]
                    assert y == A(x) and qt[y] == qs[x]
                # lift: u_i = e'_{A(i)} in the algebra of t; Clifford relations of s
                if n <= 4:
                    Bt = squares_of(t)
                    u = [{blade(imgs[i], n): F(1)} for i in range(n)]
                    for i in range(n):
                        assert GA.eq(GA.mul(u[i], u[i], Bt), GA.sc(squares_of(s)[i]))
                        for j in range(i):
                            assert GA.anticommutes(u[i], u[j], Bt)
                    # images of the blades are signed blades, all distinct: an iso over Z
                    imgb = set()
                    for m in range(2 ** n):
                        x = GA.sc(1)
                        for i in idx(m, n):
                            x = GA.mul(x, u[i], Bt)
                        assert len(x) == 1 and abs(list(x.values())[0]) == 1
                        imgb.add(list(x)[0])
                    assert len(imgb) == 2 ** n
                pairs_iso += 1
    assert (pairs_iso, pairs_non) == (90, 104)
    # Cl(2,0) = Cl(1,1) over Z; Cl(1,0) and Cl(0,1) are not isomorphic (Gauss sums 2 and 0)
    assert isometry((0, 0), (0, 1)) is not None and isometry((0,), (1,)) is None
    # the trace form: Tr(L_{e_S}) = 2^n [S empty], so Tr(L_{xy}) / 2^n is the scalar part,
    # diagonal on the blades with entries e_S^2, signature P - M = Gauss sum
    for p, q in ((2, 0), (1, 1), (0, 2), (2, 1), (0, 3), (2, 2)):
        n = p + q
        S = GA.sig(p, q)
        bl = [blade(m, n) for m in range(2 ** n)]
        for m in range(2 ** n):
            tr = sum(GA.mul({bl[m]: F(1)}, {b: F(1)}, S).get(b, F(0)) for b in bl)
            assert tr == (2 ** n if m == 0 else 0)
        diag = [GA.mul({b: F(1)}, {b: F(1)}, S)[()] for b in bl]
        assert sum(diag) == gauss(qf(tuple([0] * p + [1] * q)))
    return True

synthesis.slot-count-not-from-constituen:
"""synthesis.slot-count-not-from-constituent-fock-space: exact checks.

Constituent Fock spaces over C^K (x) C^4 (C^4 standing for the conformal spinor space CS as an
SL(4) = Spin(6) module), fermionic (exterior algebra, bitmask states with signs) and bosonic
(polynomials, monomial states). Multiplicity of the GL(K) x GL(4) highest weight (rows; cols) =
dimension of the joint kernel of the simple raising operators E_{i,i+1} (slot index) and
E_{a,a+1} (twistor index) on that weight space, by exact rank over Q (GA.rank_of_vectors).
An SL(K)-singlet (x) CS component has rows (m,...,m) and cols (c+1,c,c,c); (x) CS* has cols
(c+1,c+1,c+1,c).
"""
from fractions import Fraction as F
from itertools import combinations
import GA
from tp_premise import premise


def _ferm_basis(K, rows, cols):
    n = sum(rows)
    out = []
    for S in combinations(range(4 * K), n):
        r, c = [0] * K, [0] * 4
        for m in S:
            r[m // 4] += 1
            c[m % 4] += 1
        if r == list(rows) and c == list(cols):
            out.append(frozenset(S))
    return out


def _hop(S, src, dst):
    if src not in S:
        return None
    sign = (-1) ** sum(1 for m in S if m < src)
    S1 = S - {src}
    if dst in S1:
        return None
    sign *= (-1) ** sum(1 for m in S1 if m < dst)
    return sign, S1 | {dst}


def _raising(K):
    ops = [[((i + 1) * 4 + a, i * 4 + a) for a in range(4)] for i in range(K - 1)]
    ops += [[(i * 4 + a + 1, i * 4 + a) for i in range(K)] for a in range(3)]
    return ops


def hw_ferm(K, rows, cols):
    """(multiplicity, weight-space dimension) in Lambda(C^K (x) C^4)."""
    basis = _ferm_basis(K, rows, cols)
    imgs = []
    for S in basis:
        vec = {}
        for oi, op in enumerate(_raising(K)):
            for (src, dst) in op:
                r = _hop(S, src, dst)
                if r:
                    key = (oi, tuple(sorted(r[1])))
                    vec[key] = vec.get(key, 0) + r[0]
        imgs.append(vec)
    keys = sorted({k for v in imgs for k in v})
    M = [[F(v.get(k, 0)) for v in imgs] for k in keys]
    rank = GA.rank_of_vectors(M) if M else 0
    return len(basis) - rank, len(basis)


def _compositions(total, parts):
    if parts == 1:
        yield (total,)
        return
    for k in range(total + 1):
        for rest in _compositions(total - k, parts - 1):
            yield (k,) + rest


def _bos_basis(K, rows, cols):
    out = []

    def rec(i, rem, acc):
        if i == K:
            if all(x == 0 for x in rem):
                out.append(tuple(acc))
            return
        for row in _compositions(rows[i], 4):
            if all(row[a] <= rem[a] for a in range(4)):
                rec(i + 1, [rem[a] - row[a] for a in range(4)], acc + [row])
    rec(0, list(cols), [])
    return out


def hw_bos(K, rows, cols):
    """(multiplicity, weight-space dimension) in Sym(C^K (x) C^4); E = x_dst d/dx_src."""
    basis = _bos_basis(K, rows, cols)
    ops = [[((i + 1, a), (i, a)) for a in range(4)] for i in range(K - 1)]
    ops += [[((i, a + 1), (i, a)) for i in range(K)] for a in range(3)]
    imgs = []
    for e in basis:
        vec = {}
        for oi, op in enumerate(ops):
            for (src, dst) in op:
                ex = e[src[0]][src[1]]
                if ex:
                    m = [list(r) for r in e]
                    m[src[0]][src[1]] -= 1
                    m[dst[0]][dst[1]] += 1
                    key = (oi, tuple(tuple(r) for r in m))
                    vec[key] = vec.get(key, 0) + ex
        imgs.append(vec)
    keys = sorted({k for v in imgs for k in v})
    M = [[F(v.get(k, 0)) for v in imgs] for k in keys]
    return len(basis) - (GA.rank_of_vectors(M) if M else 0), len(basis)


def singlet_targets(K, nmax):
    """All (rows, cols) for SL(K)-singlet (x) CS or CS* up to total degree nmax."""
    out = []
    for n in range(nmax + 1):
        if n % K:
            continue
        for c in range(n + 1):
            for cols in ((c + 1, c, c, c), (c + 1, c + 1, c + 1, c)):
                if sum(cols) == n:
                    out.append(((n // K,) * K, cols))
    return out


def s_space_zero_slot_sector():
    """(S): Lambda(C^2 + W), modes 0,1 slots and 2,3,4 pairs. States killed by the slot sl(2)
    (s0^dag s1, s1^dag s0) with slot number 0 or 2, split by W parity."""
    out = {}
    for mask in range(32):
        j = (mask & 1) + ((mask >> 1) & 1)
        if j == 1:
            continue
        k = bin(mask >> 2).count("1")
        out[(j, k % 2)] = out.get((j, k % 2), 0) + 1
    return out


def check_slot_count_not_from_constituent_fock_space():
    premise("field-theory.twistor-attachment")
    premise("rungs.two-twistor-bivector-null-invites-one")
    premise("standard-model.under-s-composites-state-space-spinor")
    # controls: the method sees CS where it is (one constituent; doublets at K = 2)
    assert hw_ferm(1, (1,), (1, 0, 0, 0)) == (1, 1) and hw_bos(1, (1,), (1, 0, 0, 0)) == (1, 1)
    assert hw_ferm(2, (1, 0), (1, 0, 0, 0)) == (1, 1)
    assert hw_ferm(2, (4, 3), (2, 2, 2, 1)) == (1, 1)
    # every simple raising operator matters: (1,1,0,1) is killed only by E_{34}, (1,0,1,0) only by E_{23}
    assert hw_ferm(1, (3,), (1, 1, 0, 1)) == (0, 1) and hw_ferm(1, (2,), (1, 0, 1, 0)) == (0, 1)
    # K = 2, both statistics: an SL(2)-singlet has even degree, CS and CS* odd: no weight space at all
    assert singlet_targets(2, 8) == [] and singlet_targets(1, 3) == [((1,), (1, 0, 0, 0)), ((3,), (1, 1, 1, 0))]
    # K = 3 fermionic: the weight spaces exist (dimension 6) but carry no highest weight vector
    assert hw_ferm(3, (1, 1, 1), (1, 1, 1, 0)) == (0, 6)
    assert hw_ferm(3, (3, 3, 3), (3, 2, 2, 2)) == (0, 6)
    # K = 3 bosonic: det (x) CS* occurs once (the dual twistor of three constituents), CS does not
    assert hw_bos(3, (1, 1, 1), (1, 1, 1, 0)) == (1, 6)
    assert hw_bos(3, (3, 3, 3), (3, 2, 2, 2)) == (0, 132)
    # K = 4 fermionic: no singlet target meets the box (rows <= 4 per column)
    assert singlet_targets(4, 16) == [] and len(singlet_targets(3, 12)) == 2
    # (S): zero- and two-slot sectors carry the even W states (CS, dimension 4) and odd (CS*, 4)
    sec = s_space_zero_slot_sector()
    assert sec == {(0, 0): 4, (0, 1): 4, (2, 0): 4, (2, 1): 4}
    return True

synthesis.slot-covariance-forces-gram-sq:
"""synthesis.slot-covariance-forces-gram-square: exact checks.

Complex numbers are Gaussian rationals (re, im) of Fractions; the unit is checked to be the
field theory's I4 of Cl(1,3) (I4^2 = -1, central in the even algebra), whose span{1, I4} the
store reads physical numbers in. Conformal spinors Z = (omega, pi) are pairs of 2-spinors; the
face vector is beta_k = B^{ij}_Lambda for (i, j) the cyclic successors of k, with
B^{il}_Lambda = [pi^i pi^l] + lam [omega^i omega^l] (lam = Lambda/6) and h = t + t^dagger,
t_il = conj(pi^i) . omega^l, as in the many-twistor join.
"""
from fractions import Fraction as F
import itertools
import GA
from GA import mul, gen
from tp_premise import premise

Z0 = (F(0), F(0)); ONE = (F(1), F(0)); IU = (F(0), F(1))


def cm(a, b): return (a[0] * b[0] - a[1] * b[1], a[0] * b[1] + a[1] * b[0])
def ca(*xs): return (sum((x[0] for x in xs), F(0)), sum((x[1] for x in xs), F(0)))
def cc(a): return (a[0], -a[1])
def cn(a): return (-a[0], -a[1])
def cr(q): return (F(q), F(0))
def ab2(a): return a[0] * a[0] + a[1] * a[1]


def unit_is_I4():
    sq = (1, -1, -1, -1)
    I4 = mul(mul(gen(0), gen(1), sq), mul(gen(2), gen(3), sq), sq)
    assert mul(I4, I4, sq) == {(): F(-1)}
    e01 = mul(gen(0), gen(1), sq)
    assert mul(I4, e01, sq) == mul(e01, I4, sq)          # central in the even algebra
    assert cm(IU, IU) == (F(-1), F(0))


def mat(M, N):
    return [[ca(*[cm(M[i][k], N[k][j]) for k in range(3)]) for j in range(3)] for i in range(3)]
def dag(M): return [[cc(M[j][i]) for j in range(3)] for i in range(3)]
def tr_(M): return [[M[j][i] for j in range(3)] for i in range(3)]
def det3(M):
    s = Z0
    for p in itertools.permutations(range(3)):
        sg = 1
        for a in range(3):
            for b in range(a + 1, 3):
                if p[a] > p[b]: sg = -sg
        t = cr(sg)
        for i in range(3): t = cm(t, M[i][p[i]])
        s = ca(s, t)
    return s


def br(x, y): return ca(cm(x[0], y[1]), cn(cm(x[1], y[0])))          # [x y] = eps_AB x^A y^B
def hp(x, y): return ca(cm(cc(x[0]), y[0]), cm(cc(x[1]), y[1]))      # conj(x) . y


def face_data(Zs, lam):
    B = [[ca(br(Zs[i][1], Zs[l][1]), cm(cr(lam), br(Zs[i][0], Zs[l][0]))) for l in range(3)] for i in range(3)]
    beta = [B[(k + 1) % 3][(k + 2) % 3] for k in range(3)]
    t = [[hp(Zs[i][1], Zs[l][0]) for l in range(3)] for i in range(3)]
    h = [[ca(t[i][l], cc(t[l][i])) for l in range(3)] for i in range(3)]
    return B, beta, h


def mix(Zs, U):
    return [tuple(tuple(ca(*[cm(Zs[j][s][A], U[j][i]) for j in range(3)]) for A in range(2))
                  for s in range(2)) for i in range(3)]


def g(re, im=0): return (F(re), F(im))
CONFIGS = [
    [((g(1), g(0, 1)), (g(2), g(-1))), ((g(0), g(1, 1)), (g(3), g(1, -2))), ((g(-1), g(2)), (g(1, 1), g(0)))],
    [((g(1, 2), g(3)), (g(0, -1), g(1))), ((g(2), g(-1, 1)), (g(1), g(2, 1))), ((g(1), g(1)), (g(-2), g(0, 3)))],
    [((g(F(1, 2)), g(0)), (g(1), g(1, 1))), ((g(1), g(-1)), (g(0, 2), g(3))), ((g(0, 1), g(2)), (g(1), g(-1, -1)))],
    [((g(3), g(1)), (g(1, -1), g(2))), ((g(0), g(0, 1)), (g(1), g(0))), ((g(2, 1), g(-1)), (g(0), g(1, 2)))],
]
LAMS = [F(0), F(1, 6), F(-2, 3), F(5)]
H2 = [[g(F(1, 2), F(1, 2)), g(F(1, 2), F(-1, 2))], [g(F(1, 2), F(-1, 2)), g(F(1, 2), F(1, 2))]]
UNITARIES = [
    [[g(0), g(1), g(0)], [g(1), g(0), g(0)], [g(0), g(0), g(1)]],                 # odd permutation
    [[g(0), g(0), g(1)], [g(1), g(0), g(0)], [g(0), g(1), g(0)]],                 # 3-cycle
    [[g(0, 1), g(0), g(0)], [g(0), g(1), g(0)], [g(0), g(0), g(-1)]],             # phases
    [[g(F(3, 5)), g(F(-4, 5)), g(0)], [g(F(4, 5)), g(F(3, 5)), g(0)], [g(0), g(0), g(1)]],
    [[g(1), g(0), g(0)], [g(0), H2[0][0], H2[0][1]], [g(0), H2[1][0], H2[1][1]]],
]


def check_face_vector_cofactor():
    premise("synthesis.many-twistor-join")
    premise("standard-model.internal-symmetry-ladder")
    premise("families.chart-computation-sign-twist-bracket-form")
    unit_is_I4()
    for U in UNITARIES:
        Id = mat(dag(U), U)
        assert Id == [[ONE if i == j else Z0 for j in range(3)] for i in range(3)]
        d = det3(U)
        R = [[cm(d, x) for x in row] for row in dag(U)]                         # det(U) U^{-1}
        for Zs in CONFIGS:
            for lam in LAMS:
                B, beta, h = face_data(Zs, lam)
                B2, beta2, h2 = face_data(mix(Zs, U), lam)
                assert B2 == mat(mat(tr_(U), B), U)                             # B -> U^T B U
                assert beta2 == [ca(*[cm(R[k][m], beta[m]) for m in range(3)]) for k in range(3)]
                assert h2 == mat(mat(dag(U), h), U)                             # h -> U^dag h U
        if U is UNITARIES[0]:                                                   # sign twist: Omega -> -P Omega
            assert d == cr(-1)
    return True


# ---- invariant tensors A[k][l][m][n] of forms M_kl = sum A conj(beta_m) beta_n ----
def idx(k, l, m, n): return ((k * 3 + l) * 3 + m) * 3 + n


def nullity(rows, ncols=81):
    Mx = [[r.get(j, Z0) for j in range(ncols)] for r in rows]
    rank = 0
    for c in range(ncols):
        p = next((i for i in range(rank, len(Mx)) if Mx[i][c] != Z0), None)
        if p is None: continue
        Mx[rank], Mx[p] = Mx[p], Mx[rank]
        a = Mx[rank][c]; dd = ab2(a); iv = (a[0] / dd, -a[1] / dd)
        Mx[rank] = [cm(iv, x) for x in Mx[rank]]
        for i in range(len(Mx)):
            if i != rank and Mx[i][c] != Z0:
                f = Mx[i][c]; Mx[i] = [ca(x, cn(cm(f, y))) for x, y in zip(Mx[i], Mx[rank])]
        rank += 1
    return ncols - rank


def lie_rows(X):
    rows = []
    for k, l, a, b in itertools.product(range(3), repeat=4):
        r = {}
        def add(col, v): r[col] = ca(r.get(col, Z0), v)
        for m in range(3): add(idx(k, l, m, b), cc(X[m][a]))
        for n in range(3): add(idx(k, l, a, n), X[n][b])
        for p in range(3): add(idx(p, l, a, b), cn(cc(X[k][p])))
        for p in range(3): add(idx(k, p, a, b), cn(X[l][p]))
        r = {c: v for c, v in r.items() if v != Z0}
        if r: rows.append(r)
    return rows


def grp_rows(R):
    rows = []
    for k, l, a, b in itertools.product(range(3), repeat=4):
        r = {}
        for m in range(3):
            for n in range(3):
                c = R[m][a] * R[n][b]
                if c: r[idx(k, l, m, n)] = ca(r.get(idx(k, l, m, n), Z0), cr(c))
                c = R[k][m] * R[l][n]
                if c: r[idx(m, n, a, b)] = ca(r.get(idx(m, n, a, b), Z0), cr(-c))
        r = {c: v for c, v in r.items() if v != Z0}
        if r: rows.append(r)
    return rows


def u3_generators():
    gens = []
    def E(a, b, v):
        X = [[Z0] * 3 for _ in range(3)]; X[a][b] = v; return X
    for a in range(3):
        gens.append(E(a, a, IU))
        for b in range(a + 1, 3):
            X = E(a, b, ONE); X[b][a] = cr(-1); gens.append(X)
            X = E(a, b, IU); X[b][a] = IU; gens.append(X)
    return gens


def zero_diag_rows():
    return [{idx(k, k, m, n): ONE} for k in range(3) for m in range(3) for n in range(3)]


def tensor_ok(rows, A):
    return all(ca(*[cm(v, A.get(c, Z0)) for c, v in r.items()]) == Z0 for r in rows)


def check_invariant_forms():
    premise("standard-model.internal-symmetry-ladder")
    premise("families.chart-computation-sign-twist-bracket-form")
    U3 = [r for X in u3_generators() for r in lie_rows(X)]
    T = [[0, -1, 0], [-1, 0, 0], [0, 0, -1]]          # sgn(P) P, P a transposition
    C = [[0, 0, 1], [1, 0, 0], [0, 1, 0]]
    S3 = grp_rows(T) + grp_rows(C)
    assert nullity(U3) == 2                            # Schur: two covariant forms
    assert nullity(U3 + zero_diag_rows()) == 0         # the face-wise diagonal fixes the form
    assert nullity(S3) == 14
    assert nullity(S3 + zero_diag_rows()) == 9         # S3 alone leaves nine directions free
    gram = {idx(k, l, k, l): ONE for k in range(3) for l in range(3)}
    ident = {idx(k, k, m, m): ONE for k in range(3) for m in range(3)}
    facewise = {idx(k, k, k, k): ONE for k in range(3)}
    jminus = {idx(k, l, m, m): ONE for k in range(3) for l in range(3) if k != l for m in range(3)}
    for A in (gram, ident):
        assert tensor_ok(U3, A) and tensor_ok(S3, A)
    for A in (facewise, jminus):
        assert tensor_ok(S3, A) and not tensor_ok(U3, A)
    # 2 gram + c (J - 1)|beta|^2 at beta = e_1: the lower 2x2 block [[0, c], [c, 0]] has det -c^2 < 0
    for c in (F(1), F(-1, 3)):
        M = [[F(2), c, c], [c, F(0), c], [c, c, F(0)]]
        assert M[1][1] * M[2][2] - M[1][2] * M[2][1] < 0
    return True


def form_from(A, beta):
    return [[ca(*[cm(A.get(idx(k, l, m, n), Z0), cm(cc(beta[m]), beta[n]))
                  for m in range(3) for n in range(3)]) for l in range(3)] for k in range(3)]


def check_gram_square_on_configurations():
    premise("synthesis.many-twistor-join")
    premise("standard-model.internal-symmetry-ladder")
    gram2 = {idx(k, l, k, l): cr(2) for k in range(3) for l in range(3)}
    for Zs in CONFIGS:
        for lam in LAMS:
            B, beta, h = face_data(Zs, lam)
            M = form_from(gram2, beta)
            n2 = sum((ab2(b) for b in beta), F(0))
            # diagonal: each face's two-spinor bracket term 2|B^{ij}|^2
            assert all(M[k][k] == cr(2 * ab2(beta[k])) for k in range(3))
            # trace: the bracket part of the three-spinor join, 2 sum_{i<l} |B^{il}|^2
            assert ca(*[M[k][k] for k in range(3)]) == cr(2 * sum(ab2(B[i][l]) for i in range(3) for l in range(i + 1, 3)))
            assert M == dag(M)
            for a, b in itertools.combinations(range(3), 2):              # rank one
                for c, d in itertools.combinations(range(3), 2):
                    assert ca(cm(M[a][c], M[b][d]), cn(cm(M[a][d], M[b][c]))) == Z0
            vb = [cc(x) for x in beta]                                     # eigenvector conj(beta)
            assert [ca(*[cm(M[k][l], vb[l]) for l in range(3)]) for k in range(3)] == [cm(cr(2 * n2), x) for x in vb]
            for U in UNITARIES:
                d = det3(U); R = [[cm(d, x) for x in row] for row in dag(U)]
                _, beta2, _ = face_data(mix(Zs, U), lam)
                assert form_from(gram2, beta2) == mat(mat([[cc(x) for x in row] for row in R], M), tr_(R))
    return True


def casimir2(h, i, j):
    a, d, c = h[i][i][0], h[j][j][0], h[i][j]
    return (a - d) * (a - d) / 4 + ab2(c)


def rank_q(rows):
    Mx = [list(r) for r in rows]; rank = 0
    for c in range(len(Mx[0])):
        p = next((i for i in range(rank, len(Mx)) if Mx[i][c] != 0), None)
        if p is None: continue
        Mx[rank], Mx[p] = Mx[p], Mx[rank]
        Mx[rank] = [x / Mx[rank][c] for x in Mx[rank]]
        for i in range(len(Mx)):
            if i != rank and Mx[i][c] != 0:
                f = Mx[i][c]; Mx[i] = [x - f * y for x, y in zip(Mx[i], Mx[rank])]
        rank += 1
    return rank


def check_lambda_obstruction():
    premise("synthesis.many-twistor-join")
    premise("standard-model.internal-symmetry-ladder")
    rows = []
    for Zs in CONFIGS:
        for lam in LAMS[1:]:
            B, beta, h = face_data(Zs, lam)
            Lam3 = 2 * lam                                                  # Lambda/3 = 2 lam
            assert all(x[1] == 0 for x in (h[0][0], h[1][1], h[2][2]))
            hb = [[cc(x) for x in row] for row in h]
            for U in UNITARIES:                                               # conj(h) is covariant
                _, _, hU = face_data(mix(Zs, U), lam)
                assert [[cc(x) for x in row] for row in hU] == mat(mat(tr_(U), hb), [[cc(x) for x in row] for row in U])
            trh = sum((h[i][i][0] for i in range(3)), F(0))
            h2 = mat(h, h)
            trh2 = sum((h2[i][i][0] for i in range(3)), F(0))
            C3 = trh2 / 2 - trh * trh / 4
            Ck = [casimir2(h, (k + 1) % 3, (k + 2) % 3) for k in range(3)]
            assert sum(Ck, F(0)) - C3 == sum((h[i][i][0] ** 2 for i in range(3)), F(0)) / 4
            n2 = sum((ab2(b) for b in beta), F(0))
            for k in range(3):
                # unknowns a, b, al1..al4 of a conj(beta)beta^T + b|beta|^2 + al1 conj(h)^2 + al2 trh conj(h)
                # + al3 tr(h^2) + al4 (trh)^2 ; target 2|beta_k|^2 + (Lambda/3) C_k
                rows.append([ab2(beta[k]), n2, h2[k][k][0], trh * h[k][k][0], trh2, trh * trh,
                             2 * ab2(beta[k]) + Lam3 * Ck[k]])
    A = [r[:-1] for r in rows]
    assert rank_q(A) == 6 and rank_q(rows) == 7                             # inconsistent
    # at Lambda = 0 the same system is solved by a = 2 and nothing else
    rows0 = []
    for Zs in CONFIGS:
        B, beta, h = face_data(Zs, F(0))
        n2 = sum((ab2(b) for b in beta), F(0))
        trh = sum((h[i][i][0] for i in range(3)), F(0)); h2 = mat(h, h)
        trh2 = sum((h2[i][i][0] for i in range(3)), F(0))
        for k in range(3):
            rows0.append([ab2(beta[k]), n2, h2[k][k][0], trh * h[k][k][0], trh2, trh * trh, 2 * ab2(beta[k])])
    assert rank_q([r[:-1] for r in rows0]) == rank_q(rows0) == 6
    return True

synthesis.standard-model-currents-of-the:
"""synthesis.standard-model-currents-of-the-sixteen-channels-levels-and-window-sugawara-split: exact checks.

Five modes 0, 1 (slots) and 2, 3, 4 (pairs); V = Lambda C^5 in the occupation (bitmask) basis, V_+ the sixteen
states of even mode number (the halving (-1)^(n + k) with the empty state as neutral singlet), ordered by degree.
rho(X) is the action of X in gl(5) by the number-conserving bilinears sum X_ab a*_a a_b, restricted to V_+.
A window of L levels k = 0..L-1 carries 16 channels x; mode (x, k) is bit x L + k; c*, c act by the Jordan-Wigner
signs of lib/fock.py (checked against the Clifford relations of the tower planes, e = c* + c, f = c* - c).
J(M)_m = sum_{x,y} M_xy sum_k c*_{x,k} c_{y,k+m}. The sea Omega_s fills levels 0..s-1 of every channel.
H = sum_{x,k} (k + 1/2) n_{x,k}. For a factor with basis M_A and trace-dual basis M^A (tr_16 form),
H_f = (2 + lam_f)^{-1} (2 sum_{q >= 1} J(M^A)_{-q} J(M_A)_q + J(M^A)_0 J(M_A)_0), lam_f the adjoint Casimir.
(1) rho maps the gauge algebra into traceless 16 x 16 matrices, preserves V_+, is a homomorphism, commutes with
    transposition; the compact generators (unit J of a tower level, GA element of square -1) give anti-Hermitian
    channel matrices; the hypercharges on V_+ are the stored list.
(2) tr_16(rho X rho Y) = 4 tr_5(XY) on the whole gauge algebra; tr Y^2 = 10/3; distinct factors and the number
    current are trace-orthogonal; the window commutator of two gauge currents on edge-clean vectors has central
    term 4 m tr_5.
(3) Adjoint Casimirs lam = 3/2 (su(3)), 1 (su(2)), 2n on su(n); c = 2 dim / (2 + lam).
(4) On localised window vectors [H_f, J(X)_m] = -m J(X)_m for X in the factor, 0 for X in another factor;
    [H - sum H_f, J(X)_m] = 0; the relation fails on a vector at the window edge.
(5) ||L^f_{-2} Omega||^2 = dim f / (2 + lam_f): 16/7, 1, 1/2, 1/2; total 8; parts orthogonal; remainder 26/7.
"""
import itertools
from fractions import Fraction as F

import GA
import fock
from tp_premise import premise

# ------------------------------------------------------------------ the five-mode module and its even half
NM = 5
CH = sorted([S for S in range(1 << NM) if fock.popcount(S) % 2 == 0], key=lambda S: (fock.popcount(S), S))
ODD = [S for S in range(1 << NM) if fock.popcount(S) % 2 == 1]
POS = {S: i for i, S in enumerate(CH)}
NC = len(CH)


def _zero(n):
    return [[F(0)] * n for _ in range(n)]


def _one(n):
    return [[F(int(i == j)) for j in range(n)] for i in range(n)]


def _e5(a, b):
    M = _zero(NM)
    M[a][b] = F(1)
    return M


def _lin(*pairs):
    n = len(pairs[0][1])
    out = _zero(n)
    for c, X in pairs:
        for i in range(n):
            for j in range(n):
                out[i][j] += F(c) * X[i][j]
    return out


def _mm(A, B):
    return [[sum((A[i][l] * B[l][j] for l in range(len(B))), F(0)) for j in range(len(B[0]))] for i in range(len(A))]


def _tr(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def _comm(A, B):
    return _lin((1, _mm(A, B)), (-1, _mm(B, A)))


def _T(A):
    return [[A[j][i] for j in range(len(A))] for i in range(len(A[0]))]


def _bil_on(kind, a, b, v):
    if kind == "ab":
        return fock.cre_on(a, fock.ann_on(b, v))
    if kind == "cc":
        return fock.cre_on(a, fock.cre_on(b, v))
    return fock.ann_on(a, fock.ann_on(b, v))


def _rep_bil(kind, a, b, rows=CH, cols=CH):
    pos = {S: i for i, S in enumerate(rows)}
    M = [[F(0)] * len(cols) for _ in rows]
    for j, S in enumerate(cols):
        for T, c in _bil_on(kind, a, b, {S: F(1)}).items():
            if T not in pos:
                return None
            M[pos[T]][j] += c
    return M


def _rep(X):
    M = _zero(NC)
    for a in range(NM):
        for b in range(NM):
            if X[a][b]:
                R = _rep_bil("ab", a, b)
                M = _lin((1, M), (X[a][b], R))
    return M


SU2 = [_e5(0, 1), _e5(1, 0), _lin((1, _e5(0, 0)), (-1, _e5(1, 1)))]
SU3 = [_e5(a, b) for a in (2, 3, 4) for b in (2, 3, 4) if a != b] + \
      [_lin((1, _e5(2, 2)), (-1, _e5(3, 3))), _lin((1, _e5(3, 3)), (-1, _e5(4, 4)))]
Y5 = _lin((F(1, 2), _e5(0, 0)), (F(1, 2), _e5(1, 1)), (F(-1, 3), _e5(2, 2)), (F(-1, 3), _e5(3, 3)),
          (F(-1, 3), _e5(4, 4)))
FACTORS = (("su3", SU3), ("su2", SU2), ("Y", [Y5]))


def _inv(G):
    k = len(G)
    A = [list(row) + [F(int(i == j)) for j in range(k)] for i, row in enumerate(G)]
    for c in range(k):
        p = next(r for r in range(c, k) if A[r][c] != 0)
        A[c], A[p] = A[p], A[c]
        pv = A[c][c]
        A[c] = [x / pv for x in A[c]]
        for r in range(k):
            if r != c and A[r][c] != 0:
                f = A[r][c]
                A[r] = [x - f * y for x, y in zip(A[r], A[c])]
    return [row[k:] for row in A]


def _dual(B16):
    """trace-dual basis (tr_16 form) of a list of 16 x 16 matrices"""
    Gi = _inv([[_tr(_mm(A, B)) for B in B16] for A in B16])
    return [_lin(*[(Gi[a][b], B16[b]) for b in range(len(B16)) if Gi[a][b]] or [(0, B16[0])]) for a in range(len(B16))]


def _lam(B, D, X):
    """adjoint Casimir sum_A [M^A, [M_A, X]] = lam X: returns lam"""
    acc = _zero(len(X))
    for M, Md in zip(B, D):
        acc = _lin((1, acc), (1, _comm(Md, _comm(M, X))))
    vals = {acc[i][j] / X[i][j] for i in range(len(X)) for j in range(len(X)) if X[i][j]}
    zero_ok = all(acc[i][j] == 0 for i in range(len(X)) for j in range(len(X)) if X[i][j] == 0)
    return vals.pop() if len(vals) == 1 and zero_ok else None


# ------------------------------------------------------------------ windows
class _Win(object):
    def __init__(self, n, L):
        self.n, self.L = n, L

    def idx(self, x, k):
        return x * self.L + k

    def sea(self, s):
        return {sum(1 << self.idx(x, k) for x in range(self.n) for k in range(s)): F(1)}

    def cur(self, M, m, v):
        out = {}
        for x in range(self.n):
            for y in range(self.n):
                a = M[x][y]
                if not a:
                    continue
                for k in range(self.L):
                    if 0 <= k + m < self.L:
                        for s, c in fock.cre_on(self.idx(x, k), fock.ann_on(self.idx(y, k + m), v)).items():
                            out[s] = out.get(s, 0) + a * c
        return {s: c for s, c in out.items() if c}

    def energy(self, v):
        out = {}
        for S, c in v.items():
            e = sum((F(2 * k + 1, 2) for x in range(self.n) for k in range(self.L) if S >> self.idx(x, k) & 1), F(0))
            if e:
                out[S] = e * c
        return out

    def sug(self, B, D, v, maxq=None):
        """2 sum_{q>=1} J(D_A)_{-q} J(B_A)_q v + J(D_A)_0 J(B_A)_0 v"""
        out = {}
        for q in range(0, self.L if maxq is None else maxq + 1):
            for M, Md in zip(B, D):
                inner = self.cur(M, q, v)
                if inner:
                    out = _vadd(out, _vsc(2 if q else 1, self.cur(Md, -q, inner)))
        return out


def _vadd(*vs):
    out = {}
    for v in vs:
        for s, c in v.items():
            out[s] = out.get(s, 0) + c
    return {s: c for s, c in out.items() if c}


def _vsc(a, v):
    return {s: a * c for s, c in v.items() if a * c}


def _norm2(v):
    return sum((c * c for c in v.values()), F(0))


def _ip(u, v):
    return sum((c * v.get(s, 0) for s, c in u.items()), F(0))


def _E(n, x, y):
    M = _zero(n)
    M[x][y] = F(1)
    return M


def _factor_data():
    out = []
    for name, B5 in FACTORS:
        B = [_rep(X) for X in B5]
        D = _dual(B)
        lam = _lam(B, D, B[0]) if len(B) > 1 else F(0)
        out.append((name, B, D, lam))
    out.append(("N", [_one(NC)], [_vsc_m(F(1, NC), _one(NC))], F(0)))
    return out


def _vsc_m(a, M):
    return [[a * x for x in row] for row in M]


# ------------------------------------------------------------------ helpers for the checks
def _gauge_reps():
    return [_rep(X) for X in SU3 + SU2 + [Y5]]


def _preserves_v_plus(B5):
    for X in B5:
        for a in range(NM):
            for b in range(NM):
                if X[a][b] and _rep_bil("ab", a, b) is None:
                    return False
    return True


def _hypercharges():
    R = _rep(Y5)
    diag = all(R[i][j] == 0 for i in range(NC) for j in range(NC) if i != j)
    return sorted(R[i][i] for i in range(NC)) if diag else None


def _compact_generator_is_anti_hermitian():
    sq = (-1, -1)
    J = GA.mul(GA.gen(0), GA.gen(1), sq)
    H1 = _lin((1, _rep(SU2[0])), (1, _rep(SU2[1])))
    Tm = [[GA.scal(H1[i][j], J) for j in range(NC)] for i in range(NC)]
    unit = GA.eq(GA.mul(J, J, sq), GA.sc(-1)) and GA.eq(GA.reverse(J), GA.neg(J))
    anti = all(GA.eq(GA.reverse(Tm[j][i]), GA.neg(Tm[i][j])) for i in range(NC) for j in range(NC))
    nonzero = any(Tm[i][j] for i in range(NC) for j in range(NC))
    return unit and anti and nonzero


def _common_phase(num, den):
    """the pair-current phase z_x conj(z_y) when all channels carry the same weight z = (num + den J)/5"""
    sq = (-1, -1)
    J = GA.mul(GA.gen(0), GA.gen(1), sq)
    z = GA.add(GA.sc(F(num, 5)), GA.scal(F(den, 5), J))
    return GA.mul(z, GA.reverse(z), sq)


def _edge_clean_vectors(W):
    base = sum(1 << W.idx(x, 0) for x in range(W.n))
    return [base, base + sum(1 << W.idx(x, 1) for x in range(0, W.n, 3)),
            base + sum(1 << W.idx(x, 1) for x in range(W.n) if x % 2)]


def _window_central_values(R, pairs):
    """[J(X)_1, J(Y*)_-1] - J([X, Y*])_0 on edge-clean vectors: returns the scalar, or None if not scalar"""
    W = _Win(NC, 3)
    out = []
    for i, j in pairs:
        X, Yy = R[i], _T(R[j])
        C = _comm(X, Yy)
        vals = set()
        for S in _edge_clean_vectors(W):
            v = {S: F(1)}
            lhs = _vadd(W.cur(X, 1, W.cur(Yy, -1, v)), _vsc(-1, W.cur(Yy, -1, W.cur(X, 1, v))))
            d = _vadd(lhs, _vsc(-1, W.cur(C, 0, v)))
            if d and set(d) != {S}:
                return None
            vals.add(d.get(S, F(0)))
        if len(vals) != 1:
            return None
        out.append(vals.pop())
    return out


def _gl_casimir_value(n):
    X = _E(n, 0, 3)
    acc = _zero(n)
    for x in range(n):
        for y in range(n):
            acc = _lin((1, acc), (1, _comm(_E(n, y, x), _comm(_E(n, x, y), X))))
    vals = {acc[i][j] / X[i][j] for i in range(n) for j in range(n) if X[i][j]}
    zero_ok = all(acc[i][j] == 0 for i in range(n) for j in range(n) if X[i][j] == 0)
    return vals.pop() if len(vals) == 1 and zero_ok else None


def _split_relations(data):
    """on localised vectors of the window WIN_LOCAL: [H_f, J(X)_m] + m J(X)_m (own factor), [H_f, J(X)_m]
    (other factors), [H_c, J(X)_m]; returns the three booleans 'all zero'"""
    L, s = WIN_LOCAL
    W = _Win(NC, L)
    Om = W.sea(s)
    psis = [Om, W.cur(_E(NC, SAMPLE_PAIRS[0][0], SAMPLE_PAIRS[0][1]), -1, Om)]

    def Hf(d, v):
        return _vsc(1 / (2 + d[3]), W.sug(d[1], d[2], v))

    def Hc(v):
        out = W.energy(v)
        for d in data:
            out = _vadd(out, _vsc(-1, Hf(d, v)))
        return out
    ok_own = ok_other = ok_coset = True
    for psi in psis:
        hc = Hc(psi)
        hf = [Hf(d, psi) for d in data]
        for i, d in enumerate(data):
            Xm = d[1][0]
            for m in (1, -1):
                Xp = W.cur(Xm, m, psi)
                for j, d2 in enumerate(data):
                    lhs = _vadd(Hf(d2, Xp), _vsc(-1, W.cur(Xm, m, hf[j])))
                    if i == j:
                        ok_own = ok_own and lhs == _vsc(-m, Xp)
                    else:
                        ok_other = ok_other and lhs == {}
                ok_coset = ok_coset and _vadd(Hc(Xp), _vsc(-1, W.cur(Xm, m, hc))) == {}
    return ok_own, ok_other, ok_coset


def _edge_vector_breaks(data, channel, top, low):
    L, s = WIN_SMALL
    W = _Win(NC, L)
    psi = fock.cre_on(W.idx(channel, top), fock.ann_on(W.idx(channel, low), W.sea(s)))
    d = data[0]
    Xm = d[1][0]
    Xp = W.cur(Xm, -1, psi)
    lhs = _vadd(_vsc(1 / (2 + d[3]), W.sug(d[1], d[2], Xp)),
                _vsc(-1, W.cur(Xm, -1, _vsc(1 / (2 + d[3]), W.sug(d[1], d[2], psi)))))
    return Xp != {} and lhs != Xp


def _level_two_vectors(data):
    L, s = WIN_SMALL
    W = _Win(NC, L)
    Om = W.sea(s)
    parts = {}
    for name, B, D, lam in data:
        v = {}
        for M, Md in zip(B, D):
            v = _vadd(v, W.cur(Md, -1, W.cur(M, -1, Om)))
        parts[name] = _vsc(1 / (2 + lam), v)
    tot = {}
    for x in range(NC):
        for y in range(NC):
            tot = _vadd(tot, W.cur(_E(NC, y, x), -1, W.cur(_E(NC, x, y), -1, Om)))
    one = _one(NC)
    nn = W.cur(one, -1, W.cur(one, -1, Om))
    tot = _vsc(F(1, 2 * (NC + 1)), _vadd(tot, nn))
    return parts, tot, nn, W, Om


def _sp(M):
    return {(i, j): c for i, row in enumerate(M) for j, c in enumerate(row) if c}


def _spmm(A, B):
    rows = {}
    for (k, j), c in B.items():
        rows.setdefault(k, []).append((j, c))
    out = {}
    for (i, k), a in A.items():
        for j, c in rows.get(k, ()):
            out[(i, j)] = out.get((i, j), 0) + a * c
    return {k: v for k, v in out.items() if v}


def _spadd(*Ms):
    out = {}
    for M in Ms:
        for k, v in M.items():
            out[k] = out.get(k, 0) + v
    return {k: v for k, v in out.items() if v}


def _spsc(a, M):
    return {k: a * v for k, v in M.items() if a * v}


def _gl5_trace_identity():
    """tr_16(rho E_ab rho E_cd) - 4 tr_5(E_ab E_cd) - 4 tr E_ab tr E_cd over all 625 pairs, and tr rho E_ab - 8 tr E_ab"""
    E = [_e5(a, b) for a in range(NM) for b in range(NM)]
    R = [_rep(X) for X in E]
    bad2 = {_tr(_mm(R[i], R[j])) - 4 * _tr(_mm(E[i], E[j])) - 4 * _tr(E[i]) * _tr(E[j])
            for i in range(len(E)) for j in range(len(E))}
    bad1 = {_tr(R[i]) - 8 * _tr(E[i]) for i in range(len(E))}
    return bad2, bad1


def _tower_planes_ok(m):
    def e(w, j):
        return _vadd(fock.cre_on(j, w), fock.ann_on(j, w))

    def f(w, j):
        return _vadd(fock.cre_on(j, w), _vsc(-1, fock.ann_on(j, w)))
    for S in range(1 << m):
        v = {S: F(1)}
        for k in range(m):
            for l in range(m):
                ee = _vadd(e(e(v, k), l), e(e(v, l), k))
                ff = _vadd(f(f(v, k), l), f(f(v, l), k))
                ef = _vadd(e(f(v, k), l), f(e(v, l), k))
                if ee != (_vsc(2, v) if k == l else {}) or ff != (_vsc(-2, v) if k == l else {}) or ef != {}:
                    return False
    return True



