synthesis.tractor-transport-weak-null-cr:
"""synthesis.tractor-transport-weak-null-crossing: exact checks.

Polynomials over Fractions in the symbols S (the singular Schouten coefficient), f (the gauge function),
and, for the explicit null and timelike frames, the regular components. The transport equation along
gamma in a parallel frame, store convention of interior.imported-tractor-connection:
    sigma' = mu(X),  mu_b' = -X_b rho + P(X)_b sigma,  rho' = -eta^{bc} P(X)_c mu_b,
i.e. A = E_X + N_{P(X)} with E_X the soldering part and N_v the nilpotent map
    N_v : sigma -> (mu += v sigma),  mu -> (rho -= eta^{-1}(v, mu)).
The gauge is G = 1 + f N_n with n null (N_n^2 = 0), and Ahat = G^-1 A G - G^-1 G'.

  check_general_removal:   for fixed rational data (eta = diag(-1,1,1,1), causal X, null n with
                           nu = n(X) != 0, regular covector R), with P(X) = S nu n + R and the Riccati
                           f' = nu (S - f^2): Ahat = E_X + N_R + f [E_X, N_n] exactly; also
                           N_n E_X N_n = nu N_n, N_n N_R N_n = 0, N_n^2 = 0, and A preserves the
                           tractor metric.
  check_null_and_radial_frames: the two explicit frames of the proof (null generator with dilation,
                           radial timelike crossing with the null gauge): the gauged connection is free
                           of S and at most linear in f.
  check_model_profile:     the model y = 1 + t, t = (s_c - s)^(1/2): S = y''/(nu^2 y) is exact in t,
                           |S| ~ t^-3 (not integrable in s, ds = 2t dt) while |s - s_c||S| ~ t^-1
                           (integrable), and f = y'/(nu y) ~ t^-1 is integrable but unbounded.
"""
from fractions import Fraction as F
from itertools import product
import GA  # noqa: F401  (house rule; the computation is polynomial algebra over Fractions)
from tp_premise import premise
import gtg


class Det:
    """Deterministic integer sequence (linear congruential, exact integers only) supplying fixed
    rational test points; replaces pseudo-random sampling so the check is reproducible and exact."""

    def __init__(self, seed):
        self.x = seed

    def _next(self):
        self.x = (self.x * 1103515245 + 12345) % 2147483648
        return self.x // 65536

    def randint(self, lo, hi):
        return lo + self._next() % (hi - lo + 1)

    def choice(self, seq):
        return seq[self._next() % len(seq)]

    def sample(self, seq, k):
        pool = list(seq)
        out = []
        for _ in range(k):
            out.append(pool.pop(self._next() % len(pool)))
        return out

VARS = ("S", "f")


class P:
    def __init__(self, d=None):
        self.d = {k: F(v) for k, v in (d or {}).items() if v != 0}

    @staticmethod
    def c(x):
        return P({(0, 0): x})

    def __add__(s, o):
        o = o if isinstance(o, P) else P.c(o)
        d = dict(s.d)
        for k, v in o.d.items():
            d[k] = d.get(k, F(0)) + v
        return P(d)
    __radd__ = __add__

    def __neg__(s):
        return P({k: -v for k, v in s.d.items()})

    def __sub__(s, o):
        return s + (-(o if isinstance(o, P) else P.c(o)))

    def __mul__(s, o):
        o = o if isinstance(o, P) else P.c(o)
        d = {}
        for (k1, v1), (k2, v2) in product(s.d.items(), o.d.items()):
            k = (k1[0] + k2[0], k1[1] + k2[1])
            d[k] = d.get(k, F(0)) + v1 * v2
        return P(d)
    __rmul__ = __mul__

    def __eq__(s, o):
        return (s - o).d == {}

    def deg(s, i):
        return max((k[i] for k in s.d), default=0)

    def ddl(s, fprime):
        out = P()
        for k, c in s.d.items():
            assert k[0] == 0, "gauge must not depend on S"
            if k[1]:
                out = out + P({(0, k[1] - 1): c * k[1]}) * fprime
        return out


Sy, fy = P({(1, 0): 1}), P({(0, 1): 1})
DIM = 6           # (sigma, mu_0..mu_3, rho)
SIG, RHO = 0, 5
ETA = [F(-1), F(1), F(1), F(1)]


def zeros():
    return [[P() for _ in range(DIM)] for _ in range(DIM)]


def eye():
    M = zeros()
    for i in range(DIM):
        M[i][i] = P.c(1)
    return M


def mm(A, B):
    C = zeros()
    for i in range(DIM):
        for j in range(DIM):
            s = P()
            for k in range(DIM):
                if A[i][k].d and B[k][j].d:
                    s = s + A[i][k] * B[k][j]
            C[i][j] = s
    return C


def add(A, B, cb=1):
    return [[A[i][j] + B[i][j] * cb for j in range(DIM)] for i in range(DIM)]


def scale(A, p):
    return [[A[i][j] * p for j in range(DIM)] for i in range(DIM)]


def N(v):
    """v: covector (4 entries, may be P)."""
    M = zeros()
    for b in range(4):
        M[1 + b][SIG] = v[b] if isinstance(v[b], P) else P.c(v[b])
        M[RHO][1 + b] = -(v[b] if isinstance(v[b], P) else P.c(v[b])) * ETA[b]
    return M


def E(X):
    M = zeros()
    for a in range(4):
        M[SIG][1 + a] = P.c(X[a])
        M[1 + a][RHO] = P.c(-ETA[a] * X[a])
    return M


def eta_t():
    M = zeros()
    M[SIG][RHO] = M[RHO][SIG] = P.c(1)
    for a in range(4):
        M[1 + a][1 + a] = P.c(ETA[a])     # eta^{ab} on lower-index mu (diagonal, eta^-1 = eta)
    return M


def tr(A):
    return [[A[j][i] for j in range(DIM)] for i in range(DIM)]


def same(A, B):
    return all(A[i][j] == B[i][j] for i in range(DIM) for j in range(DIM))


NULLS = [(5, 3, 4, 0), (13, 5, 12, 0), (3, 1, 2, 2), (9, 1, 4, 8), (7, 2, 3, 6)]


def check_general_removal():
    premise("interior.imported-tractor-connection")
    # explicit instance: n = (5, 3, 4, 0) null, X = (2, 1, 1, 0) timelike, nu = n(X) = 17. The commutator
    # [E_X, N_n] is the g_0 element: nu on sigma, -nu on rho, and the Lorentz generator
    # mu -> X^flat <n, mu> - n <X^flat, mu>-type block on mu.
    n0 = [F(5), F(3), F(4), F(0)]
    X0 = [F(2), F(1), F(1), F(0)]
    assert sum(ETA[a] * n0[a] * n0[a] for a in range(4)) == 0
    assert sum(ETA[a] * X0[a] * X0[a] for a in range(4)) == -2
    nu0 = sum(n0[a] * X0[a] for a in range(4))
    assert nu0 == 17
    cm0 = add(mm(E(X0), N(n0)), mm(N(n0), E(X0)), -1)
    expect = {(0, 0): 17, (5, 5): -17, (1, 2): -11, (1, 3): -13, (2, 1): -11, (2, 3): 1,
              (3, 1): -13, (3, 2): -1}
    for i in range(DIM):
        for j in range(DIM):
            assert cm0[i][j] == P.c(expect.get((i, j), 0)), (i, j)
    assert same(mm(mm(N(n0), E(X0)), N(n0)), scale(N(n0), P.c(17)))
    rng = Det(1022)
    for _ in range(25):
        nv = list(map(F, rng.choice(NULLS)))
        sgn = [rng.choice((1, -1)) for _ in range(3)]
        perm = rng.sample([1, 2, 3], 3)
        n = [nv[0]] + [sgn[i] * nv[perm[i]] for i in range(3)]          # null covector
        assert sum(ETA[a] * n[a] * n[a] for a in range(4)) == 0
        while True:
            X = [F(rng.randint(-6, 6), rng.randint(1, 3)) for _ in range(4)]
            if sum(ETA[a] * X[a] * X[a] for a in range(4)) <= 0 and sum(n[a] * X[a] for a in range(4)) != 0:
                break
        if rng.randint(0, 9) < 4:                                         # a null tangent
            X = [x for x in map(F, rng.choice(NULLS))]
            if sum(n[a] * X[a] for a in range(4)) == 0:
                continue
        nu = sum(n[a] * X[a] for a in range(4))
        R = [F(rng.randint(-5, 5), rng.randint(1, 4)) for _ in range(4)]
        PX = [Sy * (nu * n[b]) + R[b] for b in range(4)]
        A = add(E(X), N(PX))
        # A preserves the tractor metric
        H = eta_t()
        Z = add(mm(H, A), mm(tr(A), H))
        assert all(not Z[i][j].d for i in range(DIM) for j in range(DIM))
        Nn = N(n)
        assert all(not x.d for row in mm(Nn, Nn) for x in row)                # N_n^2 = 0
        assert same(mm(mm(Nn, E(X)), Nn), scale(Nn, P.c(nu)))               # N E N = nu N
        assert all(not x.d for row in mm(mm(Nn, N(R)), Nn) for x in row)      # N N_R N = 0
        G = add(eye(), scale(Nn, fy))
        Gi = add(eye(), scale(Nn, -fy))
        assert same(mm(G, Gi), eye())
        fprime = (Sy - fy * fy) * nu
        Gp = [[G[i][j].ddl(fprime) for j in range(DIM)] for i in range(DIM)]
        Ah = add(mm(mm(Gi, A), G), mm(Gi, Gp), -1)
        comm = add(mm(E(X), Nn), mm(Nn, E(X)), -1)
        target = add(add(E(X), N(R)), scale(comm, fy))
        assert same(Ah, target)
        for row in Ah:
            for x in row:
                assert x.deg(0) == 0 and x.deg(1) <= 1
    return True


def check_null_and_radial_frames():
    premise("interior.imported-tractor-connection")
    # n = (1, 1, 0, 0) is a null covector (the conormal of the crossed null hypersurface); the
    # transverse null generator k^a = (1, 1, 0, 0) has nu = n(k) = 2; X_t is a radial unit timelike vector.
    n = [F(1), F(1), F(0), F(0)]
    k = [F(1), F(1), F(0), F(0)]
    assert sum(ETA[a] * n[a] * n[a] for a in range(4)) == 0
    nu = sum(n[a] * k[a] for a in range(4))
    assert nu == 2 and sum(ETA[a] * k[a] * k[a] for a in range(4)) == 0
    X_t = [F(5, 4), F(3, 4), F(0), F(0)]             # radial timelike, eta(X,X) = -1
    assert sum(ETA[a] * X_t[a] * X_t[a] for a in range(4)) == -1
    for X in (k, X_t):
        nuX = sum(n[a] * X[a] for a in range(4))
        R = [F(1, 3), F(-2, 5), F(0), F(0)]          # radial regular part (no angular flux)
        PX = [Sy * (nuX * n[b]) + R[b] for b in range(4)]
        A = add(E(X), N(PX))
        G = add(eye(), scale(N(n), fy))
        Gi = add(eye(), scale(N(n), -fy))
        Gp = [[G[i][j].ddl((Sy - fy * fy) * nuX) for j in range(DIM)] for i in range(DIM)]
        Ah = add(mm(mm(Gi, A), G), mm(Gi, Gp), -1)
        for row in Ah:
            for x in row:
                assert x.deg(0) == 0 and x.deg(1) <= 1
    return True


def check_model_profile():
    premise("interior.imported-tractor-connection")
    # y(s) = 1 + t with t = sqrt(s_c - s): dy/ds = -1/(2t), d2y/ds2 = -1/(4 t^3).
    # With nu = 1: S = y''/y = -1/(4 t^3 (1 + t)); f = y'/y = -1/(2 t (1 + t)).
    # Verify the Riccati f' = S - f^2 exactly at rational t (d/ds = -(1/(2t)) d/dt).
    for t in (F(1, 2), F(1, 3), F(2, 7), F(1, 10), F(5, 9), F(1, 1000)):
        y = 1 + t
        f = -1 / (2 * t * (1 + t))
        S = -1 / (4 * t ** 3 * (1 + t))
        dfdt = (2 * (1 + t) + 2 * t) / (2 * t * (1 + t)) ** 2          # d/dt of -1/(2t(1+t))
        fprime = -dfdt / (2 * t)
        assert fprime == S - f * f
        assert S * y == -1 / (4 * t ** 3)                               # y'' = S y
        # measures in s: ds = 2t dt. |S| ds = |S| 2t dt ~ t^-2 dt (divergent);
        # |s - s_c||S| ds = t^2 |S| 2t dt = 1/(2(1+t)) dt (bounded integrand); |f| ds = 1/(1+t) dt.
        assert abs(S) * 2 * t * t * t * (1 + t) * 2 == 1                 # |S| 2t = 1/(2 t^2 (1+t))
        assert t * t * abs(S) * 2 * t == 1 / (2 * (1 + t))
        assert abs(f) * 2 * t == 1 / (1 + t)
    return True


# ---- (GTG) the same algebra in Cl(2,4): tractors V = sigma ninf + mu + rho n0, bivectors acting by x ----
SQC = gtg.S24
N0C, NIC = gtg.null_pair(SQC)


def _v(c):
    return {(i,): F(x) for i, x in enumerate(c) if x}


GTG_DATA = [  # (gamma' (timelike or null), n (null), R, test tractors (sigma, mu, rho))
    (_v([2, 1, 0, 0]), _v([1, 1, 0, 0]), _v([F(1, 3), -1, 2, F(1, 2)]),
     [(F(1), _v([F(1, 2), 3, -1, 2]), F(-2)), (F(-3, 4), _v([0, 1, F(2, 5), -1]), F(5))]),
    (_v([1, 0, 1, 0]), _v([3, 0, F(-9, 5), F(12, 5)]), _v([0, 2, F(-1, 7), 1]),
     [(F(2), _v([1, 1, 1, 1]), F(1, 3)), (F(0), _v([F(-1, 2), 0, 3, 1]), F(-1))]),
]


def _tr(sig, mu, rho):
    return GA.add(GA.scal(sig, NIC), mu, GA.scal(rho, N0C))


def _E(gp, V):
    return gtg.comm(gtg.wedge(NIC, gp, SQC), V, SQC)


def _N(v, V):
    return GA.neg(gtg.comm(gtg.wedge(N0C, v, SQC), V, SQC))


def check_gtg_tractor_transport_in_cl24():
    """The proof's GTG steps in Cl(2,4): in a D-parallel frame the transport generator -Omega_T(x') . V
    (Omega_T = -ninf ^ gamma' + n0 ^ p there) is E V + N_p V with E = (ninf ^ gamma') . and N_v = -(n0 ^ v) .,
    giving sigma' = gamma' . mu, mu' = -rho gamma' + sigma p, rho' = -p . mu; (a) N_v N_w V = -sigma (v . w) n0,
    N_n^2 = 0; (b) N_n E N_n = nu N_n; (c) N_n N_R N_n = 0; A preserves the tractor metric; the gauge identity
    (1 - f N_n) A (1 + f N_n) - f' N_n = E + N_R + f [E, N_n] for f' = nu (S - f^2); (4) Einstein sides have
    P = (Lambda/6) id."""
    premise("synthesis.imported-gtg-dictionary")
    premise("synthesis.gtg-tractor-gauge-field-reproduces-tractor-connection")
    premise("interior.imported-tractor-connection")
    ok = True
    for gp, n, R, tests in GTG_DATA:
        nu = gtg.vdot(n, gp, SQC)
        ok = ok and gtg.vdot(n, n, SQC) == 0 and nu != 0
        for S, f in ((F(2), F(1, 3)), (F(-5, 2), F(3))):
            p = GA.add(GA.scal(S * nu, n), R)
            fp = nu * (S - f * f)
            OmT = GA.add(GA.neg(gtg.wedge(NIC, gp, SQC)), gtg.wedge(N0C, p, SQC))

            def A(V):
                return GA.add(_E(gp, V), _N(p, V))
            for sig, mu, rho in tests:
                V = _tr(sig, mu, rho)
                ok = ok and GA.eq(GA.neg(gtg.comm(OmT, V, SQC)), A(V))
                slots = _tr(gtg.vdot(gp, mu, SQC), GA.add(GA.scal(-rho, gp), GA.scal(sig, p)), -gtg.vdot(p, mu, SQC))
                ok = ok and GA.eq(A(V), slots)
                ok = ok and GA.eq(_N(R, _N(n, V)), GA.scal(-sig * gtg.vdot(R, n, SQC), N0C))
                ok = ok and _N(n, _N(n, V)) == {} and _N(n, _N(R, _N(n, V))) == {}
                ok = ok and GA.eq(_N(n, _E(gp, _N(n, V))), GA.scal(nu, _N(n, V)))
                for s2, m2, r2 in tests:
                    W = _tr(s2, m2, r2)
                    ok = ok and gtg.vdot(A(V), W, SQC) + gtg.vdot(V, A(W), SQC) == 0
                lhs = GA.add(A(GA.add(V, GA.scal(f, _N(n, V)))))
                lhs = GA.sub(lhs, GA.scal(f, _N(n, lhs)))
                lhs = GA.sub(lhs, GA.scal(fp, _N(n, V)))
                rhs = GA.add(_E(gp, V), _N(R, V), GA.scal(f, GA.sub(_E(gp, _N(n, V)), _N(n, _E(gp, V)))))
                ok = ok and GA.eq(lhs, rhs)
    for lam in (F(3), F(-6, 5)):
        P = gtg.schouten(gtg.op_const(lam / 3))
        ok = ok and all(GA.eq(P(GA.gen(m)), GA.scal(lam / 6, GA.gen(m))) for m in range(4))
    _tp_rv = (ok); assert _tp_rv is not False, "check_gtg_tractor_transport_in_cl24"; return _tp_rv

synthesis.twistor-form-states-only-off-t:
"""synthesis.twistor-form-states-only-off-the-real-slice: exact checks on the store's own Sigma.

The twistor form is rebuilt as the stored construction defines it (correspondence.fock-model-
complexified-ascended-algebra, correspondence.chevalley-pairing, correspondence.reality-conjugation-
twistor-form-factor): the Fock model on Lambda W with the wedge-plus-contraction operator C(v)
(c = sqrt(2) C, a positive rescaling that never changes a sign), the Chevalley pairing B, the real
orthonormal basis a1, a2, b1, ..., b4 with w3 = b3 + i b4, kappa = Gamma C(b4) J, and
Sigma(Z1, Z2) = mu B(kappa Z1, Z2) on CS in the t-basis, with the phase mu of the stored clause (2)
(here lambda = 1, mu = 2 > 0). The chart is the stored one: the graph line {A pi + pi} with the stored
bases pi1, pi2, e1, e2 and m(A) read through the spinor identification Psi. The Minkowski complement
of the Witt pair is e0 = a2, e1 = b2, e2 = b3, e3 = b4.
check_store_sigma_and_real_lines: Sigma Hermitian, rank four, both halves null, lambda = 1; the lines of
real points are Sigma-null.
check_restricted_form_is_imaginary_part: the Gram matrix of Sigma on the line of x + i y does not depend on
x, has determinant 4 Q(y) and trace 4 y^0 in the stored line basis (definite iff Q(y) > 0, positive iff
moreover y^0 > 0; split iff Q(y) < 0; rank one iff y null and nonzero).
check_imaginary_boost_half_strip: x(theta) = rho cos(theta) e1 + i rho sin(theta) e0 gives Gram 2 rho sin(theta)
times the identity: positive on 0 < theta < pi, negative on pi < theta < 2 pi, null at 0 and pi.
"""
from fractions import Fraction
from fractions import Fraction as F
from itertools import combinations
import GA as g
from tp_premise import premise

ZERO, ONE, I = g.QI(0), g.QI(1), g.QI(0, 1)


def zeros(n, m):
    return [[g.QI(0) for _ in range(m)] for _ in range(n)]


def madd(A, B):
    return [[A[i][j] + B[i][j] for j in range(len(A[0]))] for i in range(len(A))]


def mscal(c, A):
    c = g.QI(c) if not isinstance(c, g.QI) else c
    return [[c * x for x in row] for row in A]


mmul = g.field_mat_mul


def pc(m):
    return bin(m).count("1")


def sgn_below(mask, i):
    return g.QI(-1) if pc(mask & ((1 << i) - 1)) % 2 else g.QI(1)


def wedge_op(i):
    M = zeros(8, 8)
    for m in range(8):
        if not (m >> i) & 1:
            M[m | (1 << i)][m] = sgn_below(m, i)
    return M


def contract_op(i):
    M = zeros(8, 8)
    for m in range(8):
        if (m >> i) & 1:
            M[m & ~(1 << i)][m] = sgn_below(m, i)
    return M


AOPS = [wedge_op(i) for i in range(3)]
BOPS = [contract_op(i) for i in range(3)]


def C_of(v):
    M = zeros(8, 8)
    for i in range(3):
        if v[i]:
            M = madd(M, mscal(v[i], AOPS[i]))
        if v[3 + i]:
            M = madd(M, mscal(v[3 + i], BOPS[i]))
    return M


def ip6(u, v):
    return sum((u[i] * v[3 + i] + u[3 + i] * v[i] for i in range(3)), g.QI(0))


def basis6(k):
    v = [g.QI(0)] * 6
    v[k] = g.QI(1)
    return v


EPSK = {0: 1, 1: 1, 2: -1, 3: -1}


def wedge_sign(S, T):
    vals = [x for x in range(3) if (S >> x) & 1] + [x for x in range(3) if (T >> x) & 1]
    inv = sum(1 for i in range(len(vals)) for j in range(i + 1, len(vals)) if vals[i] > vals[j])
    return g.QI(-1) if inv % 2 else g.QI(1)


def B_mono(S, T):
    if (S | T) != 7 or (S & T):
        return g.QI(0)
    return g.QI(EPSK[pc(S)]) * wedge_sign(S, T)


def B_pair(x, y):
    out = g.QI(0)
    for S in range(8):
        if x[S]:
            for T in range(8):
                if y[T]:
                    out = out + x[S] * y[T] * B_mono(S, T)
    return out


def e8(mask):
    v = [g.QI(0)] * 8
    v[mask] = g.QI(1)
    return v


def apply_op(M, x):
    return [sum((M[i][j] * x[j] for j in range(8)), g.QI(0)) for i in range(8)]


H = g.QI(Fraction(1, 2))
REAL = [[H, 0, 0, 1, 0, 0], [0, H, 0, 0, 1, 0], [H, 0, 0, -1, 0, 0], [0, H, 0, 0, -1, 0],
        [0, 0, H, 0, 0, -1], [0, 0, g.QI(0, Fraction(-1, 2)), 0, 0, g.QI(0, -1)]]
REAL = [[g.QI(x) if not isinstance(x, g.QI) else x for x in v] for v in REAL]   # a1 a2 b1 b2 b3 b4
GAMMA = zeros(8, 8)
for m_ in range(8):
    GAMMA[m_][m_] = g.QI(-1) if pc(m_) % 2 else g.QI(1)
KMAT = mmul(GAMMA, C_of(REAL[5]))


def kappa(x):
    return apply_op(KMAT, [xi.conj() for xi in x])


t2 = [g.QI(0)] * 8
t2[5] = g.QI(-1)
T_VECS = [e8(0), e8(6), t2, e8(3)]
TP = [1, 2, 4, 7]
SIG = [[B_pair(kappa(T_VECS[i]), T_VECS[j]) for j in range(4)] for i in range(4)]
lam = None
for S in range(8):
    for T in range(8):
        b = B_mono(S, T)
        if b:
            lam = B_pair(kappa(e8(S)), kappa(e8(T))).conj() / b
            break
    if lam is not None:
        break
LAM = (lam * g.QI(2)).conj()
MU = g.QI(0, 1) if LAM == g.QI(-1) else ONE + LAM.conj()
HH = [[MU * SIG[i][j] for j in range(4)] for i in range(4)]

Bst = [[B_pair(e8(TP[i]), T_VECS[j]) for j in range(4)] for i in range(4)]
Binv = [g.field_solve([r[:] for r in Bst], [ONE if r == j else ZERO for r in range(4)]) for j in range(4)]
Binv = [[Binv[j][i] for j in range(4)] for i in range(4)]


def Psi(v):
    Cv = C_of(v)
    G = [[B_pair(e8(TP[i]), apply_op(Cv, e8(TP[j]))) for j in range(4)] for i in range(4)]
    P = zeros(4, 4)
    for k in range(4):
        for l in range(4):
            P[k][l] = sum((Binv[k][i] * G[i][j] * Binv[l][j] for i in range(4) for j in range(4)), g.QI(0))
    return P


PSI = [Psi(basis6(k)) for k in range(6)]
PSIMAT_T = [[[PSI[k][0][1], PSI[k][0][2], PSI[k][0][3], PSI[k][1][2], PSI[k][1][3], PSI[k][2][3]][c]
             for k in range(6)] for c in range(6)]
N0, NINF = PSI[0], PSI[3]
PI1 = [g.QI(0), g.QI(0), g.QI(-1), g.QI(0)]
PI2 = [g.QI(0), g.QI(0), g.QI(0), g.QI(1)]
E1 = [g.QI(1), g.QI(0), g.QI(0), g.QI(0)]
E2 = [g.QI(0), g.QI(1), g.QI(0), g.QI(0)]


def wedge4(u, v):
    return [[u[k] * v[l] - u[l] * v[k] for l in range(4)] for k in range(4)]


def line(A):
    u = [PI1[k] + A[0][0] * E1[k] + A[1][0] * E2[k] for k in range(4)]
    v = [PI2[k] + A[0][1] * E1[k] + A[1][1] * E2[k] for k in range(4)]
    return u, v


def m_of(A):
    u, v = line(A)
    P = wedge4(u, v)
    d = A[0][0] * A[1][1] - A[0][1] * A[1][0]
    ph = [[P[i][j] - N0[i][j] - d * NINF[i][j] for j in range(4)] for i in range(4)]
    return g.field_solve([r[:] for r in PSIMAT_T], [ph[0][1], ph[0][2], ph[0][3], ph[1][2], ph[1][3], ph[2][3]])


RMAT = [[REAL[k][r] for k in range(6)] for r in range(6)]


def real_coords(v):
    return g.field_solve([r[:] for r in RMAT], list(v))


def herm(Z1, Z2):
    return sum((Z1[a].conj() * HH[a][b] * Z2[b] for a in range(4) for b in range(4)), g.QI(0))


def gram_on_line(A):
    u, v = line(A)
    return [[herm(x, y) for y in (u, v)] for x in (u, v)]


def A_for_real(target):
    """The 2x2 A (complex linear chart) with m(A) = the given real-basis vector."""
    units = [[[ONE if (i, j) == (p, q) else ZERO for j in range(2)] for i in range(2)] for p in range(2) for q in range(2)]
    cols = [real_coords(m_of(U)) for U in units]   # m is linear in A
    M = [[cols[c][r] for c in range(4)] for r in range(6)]
    for pick in combinations(range(6), 4):
        sub = [M[r][:] for r in pick]
        if g.field_rank([s[:] for s in sub]) == 4:
            x = g.field_solve(sub, [target[r] for r in pick])
            ok = all(sum((M[r][c] * x[c] for c in range(4)), g.QI(0)) == target[r] for r in range(6))
            assert ok
            return [[x[0], x[1]], [x[2], x[3]]]
    raise ValueError


def coords_of(xc):
    return [g.QI(0), g.QI(xc[0]), g.QI(0), g.QI(xc[1]), g.QI(xc[2]), g.QI(xc[3])]


BASE = {}


def A_of(xc, yc):
    """Chart A of the complex point x + i y, x, y given in (e0, e1, e2, e3); the chart is complex linear."""
    if not BASE:
        for j, k in enumerate((1, 3, 4, 5)):
            BASE[j] = A_for_real([g.QI(1 if r == k else 0) for r in range(6)])
    return [[sum((BASE[k][i][j] * (g.QI(xc[k]) + I * g.QI(yc[k])) for k in range(4)), g.QI(0))
             for j in range(2)] for i in range(2)]


def det2(G):
    return G[0][0] * G[1][1] - G[0][1] * G[1][0]


def check_store_sigma_and_real_lines():
    premise("correspondence.reality-conjugation-twistor-form-factor")
    premise("correspondence.incidence-relation-chart")
    assert LAM == ONE and MU == g.QI(2)
    assert all(HH[j][i] == HH[i][j].conj() for i in range(4) for j in range(4))
    assert g.field_rank([r[:] for r in HH]) == 4
    assert all(not HH[i][j] for i in (0, 1) for j in (0, 1)) and all(not HH[i][j] for i in (2, 3) for j in (2, 3))
    assert all(kappa(kappa(e8(S))) == [x * g.QI(Fraction(-1, 2)) for x in e8(S)] for S in range(8))
    # the chart reproduces the real basis vectors
    for j, k in enumerate((1, 3, 4, 5)):
        A = A_of([1 if r == j else 0 for r in range(4)], [0, 0, 0, 0])
        assert real_coords(m_of(A)) == [g.QI(1 if r == k else 0) for r in range(6)]
    for x in [(1, 0, 0, 0), (0, 1, 0, 0), (2, -1, 3, 1), (0, 0, 5, -2)]:
        G = gram_on_line(A_of(x, [0, 0, 0, 0]))
        assert G == [[ZERO, ZERO], [ZERO, ZERO]]
    return True


def check_restricted_form_is_imaginary_part():
    premise("correspondence.reality-conjugation-twistor-form-factor")
    premise("synthesis.incidence-vacua-thermofield-real-capacity")
    cases = [((1, 0, 0, 0), (4, 4)), ((2, 1, 0, 1), (8, 8)), ((-3, 0, 2, 0), (20, -12)),
             ((1, 2, 0, 0), (-12, 4)), ((0, 0, 0, 1), (-4, 0)), ((1, 1, 0, 0), (0, 4))]
    for y, (de, te) in cases:
        G = gram_on_line(A_of((0, 0, 0, 0), y))
        for x in [(1, 2, 3, -1), (F(1, 2), 0, -2, 7)]:
            assert gram_on_line(A_of(x, y)) == G                     # depends on Im only
        qy = y[0] ** 2 - y[1] ** 2 - y[2] ** 2 - y[3] ** 2
        d, t = det2(G), G[0][0] + G[1][1]
        assert (d, t) == (g.QI(de), g.QI(te))
        assert d == g.QI(4 * qy) and t == g.QI(4 * y[0])
        if qy > 0:
            assert (t.re > 0) == (y[0] > 0)                           # positive iff future along e0
    return True


def check_imaginary_boost_half_strip():
    premise("correspondence.incidence-relation-chart")
    premise("one-relation.two-capacities-three-consequences")
    rho = F(3, 2)
    seen = []
    for c, s in [(F(3, 5), F(4, 5)), (F(-3, 5), F(4, 5)), (F(-3, 5), F(-4, 5)), (F(3, 5), F(-4, 5)),
                 (F(1), F(0)), (F(-1), F(0))]:
        assert c * c + s * s == 1
        G = gram_on_line(A_of((0, rho * c, 0, 0), (rho * s, 0, 0, 0)))
        assert G == [[g.QI(2 * rho * s), ZERO], [ZERO, g.QI(2 * rho * s)]]
        seen.append((G[0][0].re > 0, G[0][0].re < 0))
    assert seen == [(True, False)] * 2 + [(False, True)] * 2 + [(False, False)] * 2
    return True

synthesis.two-loop-qed-in-the-spacetime-:
"""Two-loop electrodynamics in the spacetime algebra continued in dimension: exact checks.

The Dirac algebra is the Clifford algebra of the (Wick-rotated) spacetime vectors; in d dimensions it is
handled symbolically by the contraction rule gamma_a X b gamma_a = -(gamma_a X gamma_a) b + 2 b X with
gamma_a gamma_a = d, checked against the Clifford algebras Cl(D,0) and Cl(1,D-1) for integer D. Traces are
4 <.>_0 (tr 1 = 4). The two-loop vacuum polarisation of one massless Dirac fermion (three diagrams, covariant
gauge with parameter xi) is reduced exactly: scalar products to the five denominators, integration by parts
(the triangle rule) and Gamma-function bubbles, to two masters M1 = G(1,1)^2 and M2 = G(1,1) G(1, 3 - d/2),
with coefficients rational functions of d (GA.RF). Laurent expansion in eps (d = 4 - 2 eps) is exact, zeta_3
kept symbolic. Results: one loop beta0 = 4/3; two loops: transverse, xi independent, a simple pole only,
beta1 = 4 (a = alpha/(4 pi), mu^2 da/dmu^2 = beta0 a^2 + beta1 a^3); MS-bar finite part 16 zeta_3 - 55/3.
The Ward-Takahashi identity at two loops at integrand level (Z1 = Z2) in Cl(1,3) with massive lines and the
unit outside the product. Exact arithmetic only.
"""
from fractions import Fraction as Fr
from functools import lru_cache

import GA
from tp_premise import premise


def factorial(n):
    out = 1
    for i in range(2, n + 1):
        out *= i
    return out


def comb(n, r):
    return factorial(n) // (factorial(r) * factorial(n - r))

RF = GA.RF
D = RF.var()                     # the dimension d


def rfc(c):
    return RF.const(Fr(c))


def lin(c0, c1):
    """c0 + c1 d as an RF."""
    return RF([Fr(c0), Fr(c1)])


# ---------------------------------------------------------------------------
# 1. polynomials in d (coefficient lists) and in the scalar products
# ---------------------------------------------------------------------------
# scalar-product symbols: index 0 kk, 1 ll, 2 qq, 3 kl, 4 kq, 5 lq
SYM = {(0, 0): 0, (1, 1): 1, (2, 2): 2, (0, 1): 3, (0, 2): 4, (1, 2): 5}


def padd(p, q):
    out = dict(p)
    for m, c in q.items():
        out[m] = out.get(m, Fr(0)) + c
        if out[m] == 0:
            del out[m]
    return out


def pscale(p, c):
    if c == 0:
        return {}
    return {m: v * c for m, v in p.items()}


def pmulmono(p, mono):
    """multiply polynomial (keys: (dpow, e0..e5)) by monomial key."""
    out = {}
    for m, c in p.items():
        k = tuple(a + b for a, b in zip(m, mono))
        out[k] = out.get(k, Fr(0)) + c
    return {m: c for m, c in out.items() if c != 0}


def pmul(p, q):
    out = {}
    for m1, c1 in p.items():
        for m2, c2 in q.items():
            k = tuple(a + b for a, b in zip(m1, m2))
            out[k] = out.get(k, Fr(0)) + c1 * c2
    return {m: c for m, c in out.items() if c != 0}


ONE = {(0, 0, 0, 0, 0, 0, 0): Fr(1)}
DPOLY = {(1, 0, 0, 0, 0, 0, 0): Fr(1)}


def dot(a, b):
    """scalar product of momentum vectors a, b (3-tuples over k, l, q) as polynomial."""
    out = {}
    for i in range(3):
        for j in range(3):
            c = a[i] * b[j]
            if c == 0:
                continue
            s = SYM[(min(i, j), max(i, j))]
            key = [0] * 7
            key[1 + s] = 1
            key = tuple(key)
            out[key] = out.get(key, Fr(0)) + c
    return {m: c for m, c in out.items() if c != 0}


# ---------------------------------------------------------------------------
# 2. d-dimensional Clifford algebra: contraction of a repeated index, traces
# ---------------------------------------------------------------------------
# A word is a tuple of symbols: ('v', (ck, cl, cq)) a momentum vector, ('i', label) a basis vector
# gamma_label. Linear combinations of words: dict word -> polynomial.

@lru_cache(maxsize=None)
def contract(X):
    """gamma_a X gamma_a (a not in X) as a tuple of (dpoly-key-coefficient, word) pairs.
    gamma_a gamma_a = d; gamma_a X' b gamma_a = -(gamma_a X' gamma_a) b + 2 b X'."""
    if len(X) == 0:
        return (((1, 0, 0, 0, 0, 0, 0), Fr(1), ()),)
    Xp, b = X[:-1], X[-1]
    out = {}
    for mono, c, w in contract(Xp):
        key = (mono, w + (b,))
        out[key] = out.get(key, Fr(0)) - c
    key = ((0, 0, 0, 0, 0, 0, 0), (b,) + Xp)
    out[key] = out.get(key, Fr(0)) + 2
    return tuple((m, c, w) for (m, w), c in out.items() if c != 0)


def eliminate_indices(word):
    """Return dict word -> poly in d with all repeated labels contracted (trace context, cyclic)."""
    todo = {word: ONE}
    done = {}
    while todo:
        w, p = todo.popitem()
        labels = [s[1] for s in w if s[0] == 'i']
        rep = None
        for lab in labels:
            if labels.count(lab) == 2:
                rep = lab
                break
        if rep is None:
            done[w] = padd(done.get(w, {}), p)
            continue
        i = next(j for j, s in enumerate(w) if s == ('i', rep))
        w = w[i:] + w[:i]                      # cyclic rotation
        j = next(t for t in range(1, len(w)) if w[t] == ('i', rep))
        X, Y = w[1:j], w[j + 1:]
        for mono, c, wx in contract(X):
            nw = wx + Y
            todo[nw] = padd(todo.get(nw, {}), pmulmono(pscale(p, c), mono))
    return done


@lru_cache(maxsize=None)
def trace_vectors(w):
    """tr(a1 ... an) / 1 with tr 1 = 4, for momentum vectors only (polynomial as frozen items)."""
    if len(w) == 0:
        return tuple({(0, 0, 0, 0, 0, 0, 0): Fr(4)}.items())
    if len(w) % 2 == 1:
        return ()
    a1 = w[0][1]
    out = {}
    for j in range(1, len(w)):
        aj = w[j][1]
        rest = w[1:j] + w[j + 1:]
        t = dict(trace_vectors(rest))
        if not t:
            continue
        sgn = 1 if j % 2 == 1 else -1
        out = padd(out, pscale(pmul(dot(a1, aj), t), Fr(sgn)))
    return tuple(out.items())


def trace(word):
    total = {}
    for w, p in eliminate_indices(word).items():
        if any(s[0] == 'i' for s in w):
            raise ValueError("unpaired index left in trace")
        total = padd(total, pmul(p, dict(trace_vectors(w))))
    return total


def V(ck, cl, cq):
    return ('v', (Fr(ck), Fr(cl), Fr(cq)))


def G_(lab):
    return ('i', lab)


# ---------------------------------------------------------------------------
# 3. scalar products to denominators (q^2 = 1), then to integrals
# ---------------------------------------------------------------------------
# D-polynomials: dict (n1..n5) -> RF-free poly in d stored as dict dpow -> Fraction

def sp_to_D():
    """each scalar product as dict (n1..n5) -> Fraction (q^2 = 1)."""
    z = (0, 0, 0, 0, 0)
    e = lambda i: tuple(1 if t == i else 0 for t in range(5))
    h = Fr(1, 2)
    return {
        0: {e(0): Fr(1)},                                  # kk = D1
        1: {e(2): Fr(1)},                                  # ll = D3
        2: {z: Fr(1)},                                     # qq = 1
        3: {e(0): h, e(2): h, e(4): -h},                   # kl = (D1 + D3 - D5)/2
        4: {e(0): h, e(1): -h, z: h},                      # kq = (D1 - D2 + 1)/2
        5: {e(2): h, e(3): -h, z: h},                      # lq = (D3 - D4 + 1)/2
    }


SP = sp_to_D()


def dmul(p, q):
    out = {}
    for m1, c1 in p.items():
        for m2, c2 in q.items():
            k = tuple(a + b for a, b in zip(m1, m2))
            out[k] = out.get(k, Fr(0)) + c1 * c2
    return {m: c for m, c in out.items() if c != 0}


def dpow(p, n):
    out = {(0, 0, 0, 0, 0): Fr(1)}
    for _ in range(n):
        out = dmul(out, p)
    return out


def to_D(poly):
    """polynomial in scalar products and d -> dict (n1..n5) -> RF(d)."""
    out = {}
    for mono, c in poly.items():
        dp, ex = mono[0], mono[1:]
        term = {(0, 0, 0, 0, 0): Fr(1)}
        for s, e in enumerate(ex):
            if e:
                term = dmul(term, dpow(SP[s], e))
        coef_d = RF([Fr(0)] * dp + [Fr(1)])
        for m, v in term.items():
            out[m] = out.get(m, GA.RF0) + coef_d * rfc(v * c)
    return {m: v for m, v in out.items() if not v.is_zero()}


# ---------------------------------------------------------------------------
# 4. Gamma bookkeeping: Gamma(n + c d/2) keyed (n, c); ratios to the masters are RF(d)
# ---------------------------------------------------------------------------

def gamma_shift(n, c):
    """Gamma(n + c d/2) / Gamma(c d/2) as RF (c != 0)."""
    out = GA.RF1
    if n > 0:
        for i in range(n):
            out = out * lin(i, Fr(c, 2))
    elif n < 0:
        for i in range(1, -n + 1):
            out = out / lin(-i, Fr(c, 2))
    return out


def gfact(n):
    return Fr(factorial(n - 1))


def to_master(gp, master):
    """gp, master: dict (n, c) -> exponent. Returns RF ratio gp/master, or None if zero."""
    groups = {}
    for (n, c), e in gp.items():
        groups.setdefault(c, []).append((n, e))
    for (n, c), e in master.items():
        groups.setdefault(c, []).append((n, -e))
    out = GA.RF1
    for c, lst in groups.items():
        if c == 0:
            for n, e in lst:
                if n <= 0:
                    if e < 0:
                        return None
                    raise ValueError("Gamma pole in numerator")
                out = out * rfc(gfact(n) ** e)
            continue
        if sum(e for _, e in lst) != 0:
            raise ValueError("not a rational multiple of the master (group c=%s)" % c)
        for n, e in lst:
            g = gamma_shift(n, c)
            for _ in range(abs(e)):
                out = out * g if e > 0 else out / g
    return out


def gp_add(gp, key, e):
    gp[key] = gp.get(key, 0) + e
    if gp[key] == 0:
        del gp[key]


def gp_merge(a, b):
    out = dict(a)
    for k, e in b.items():
        gp_add(out, k, e)
    return out


M1 = {(2, -1): 2, (-1, 1): 4, (-2, 2): -2}


def bubble_gp(al, be):
    """G(al, be), al and be as (n, c) meaning n + c d/2; returns gp dict or None if zero."""
    (n1, c1), (n2, c2) = al, be
    if (c1 == 0 and n1 <= 0) or (c2 == 0 and n2 <= 0):
        return None
    gp = {}
    gp_add(gp, (n1 + n2, c1 + c2 - 1), 1)
    gp_add(gp, (-n1, 1 - c1), 1)
    gp_add(gp, (-n2, 1 - c2), 1)
    gp_add(gp, (n1, c1), -1)
    gp_add(gp, (n2, c2), -1)
    gp_add(gp, (-n1 - n2, 2 - c1 - c2), -1)
    return gp


# M2 = G(1,1) G(1, 3 - d/2): the inner bubble raises a line's power to 1 + eps
M2 = gp_merge(bubble_gp((1, 0), (1, 0)), bubble_gp((1, 0), (3, -1)))


def dfact2(n):
    out = 1
    while n > 1:
        out *= n
        n -= 2
    return out


def tensor_bubble_terms(j, A, B):
    """int d^dk/pi^(d/2) (k.v)^j / ((k^2)^A ((k-P)^2)^B)
       = sum_r coef_r (v^2)^r (v.P)^(j-2r) (P^2)^(d/2 + r - A - B) * Gamma-product_r.
    Returns list of (r, Fraction coef, gp) ; empty if A <= 0 or B <= 0 (scaleless)."""
    if A <= 0 or B <= 0:
        return []
    out = []
    for r in range(j // 2 + 1):
        coef = Fr(comb(j, 2 * r) * dfact2(2 * r - 1), 2 ** r)
        gp = {}
        gp_add(gp, (A + B - r, -1), 1)
        gp_add(gp, (j - r - A, 1), 1)
        gp_add(gp, (r - B, 1), 1)
        gp_add(gp, (j - A - B, 2), -1)
        gp_add(gp, (A, 0), -1)
        gp_add(gp, (B, 0), -1)
        out.append((r, coef, gp))
    return out


def add_res(res, which, rf):
    res[which] = res[which] + rf


def lin_expand(coeffs, n):
    """(c_x X + c_y Y + c_1)^n as dict (i, j) -> Fraction (powers of X, Y)."""
    cx, cy, c1 = coeffs
    out = {}
    for i in range(n + 1):
        for j in range(n - i + 1):
            m = n - i - j
            v = Fr(factorial(n), factorial(i) * factorial(j) * factorial(m)) * cx ** i * cy ** j * c1 ** m
            if v != 0:
                out[(i, j)] = out.get((i, j), Fr(0)) + v
    return out


@lru_cache(maxsize=None)
def I(a1, a2, a3, a4, a5):
    """returns (RF coefficient of M1, RF coefficient of M2)."""
    res = [GA.RF0, GA.RF0]
    if a5 <= 0:
        # factorised: D5^n = (D1 + D3 - 2 k.l)^n
        n = -a5
        for i in range(n + 1):
            for m in range(n - i + 1):
                j = n - i - m
                mult = Fr(factorial(n), factorial(i) * factorial(m) * factorial(j)) * (-2) ** j
                for r, coef, gpk in tensor_bubble_terms(j, a1 - i, a2):
                    # (l^2)^r (l.q)^(j-2r), l.q = (D3 - D4 + 1)/2, l^2 = D3
                    for (s, t), cst in lin_expand((Fr(1, 2), Fr(-1, 2), Fr(1, 2)), j - 2 * r).items():
                        gpl = bubble_gp((a3 - m - r - s, 0), (a4 - t, 0))
                        if gpl is None:
                            continue
                        rat = to_master(gp_merge(gpk, gpl), M1)
                        if rat is None:
                            continue
                        res[0] = res[0] + rat * rfc(mult * coef * cst)
        return tuple(res)
    if (a1 > 0 and a2 > 0) and (a3 <= 0 or a4 <= 0):
        return I(a3, a4, a1, a2, a5)                   # k <-> l
    if a1 <= 0 or a2 <= 0:
        if a1 <= 0 and a2 <= 0:
            return (GA.RF0, GA.RF0)
        if a1 <= 0:
            # k = k' + q: D1 = k'^2 + 2 k'.q + 1, D2 = k'^2, D5 = (k' - P)^2, P = l - q
            n = -a1
            for al in range(n + 1):
                for be in range(n - al + 1):
                    mult = Fr(factorial(n), factorial(al) * factorial(be) * factorial(n - al - be)) * 2 ** be
                    for r, coef, gpk in tensor_bubble_terms(be, a2 - al, a5):
                        A, B = a2 - al, a5
                        # (q^2)^r = 1, (q.P)^(be-2r), q.P = (D3 - D4 - 1)/2, P^2 = D4
                        for (s, t), cst in lin_expand((Fr(1, 2), Fr(-1, 2), Fr(-1, 2)), be - 2 * r).items():
                            gpl = bubble_gp((a3 - s, 0), (a4 - t + A + B - r, -1))
                            if gpl is None:
                                continue
                            rat = to_master(gp_merge(gpk, gpl), M2)
                            if rat is None:
                                continue
                            res[1] = res[1] + rat * rfc(mult * coef * cst)
            return tuple(res)
        # a2 <= 0: D2 = k^2 - 2 k.q + 1, D1 = k^2, D5 = (k - l)^2, P = l
        n = -a2
        for al in range(n + 1):
            for be in range(n - al + 1):
                mult = Fr(factorial(n), factorial(al) * factorial(be) * factorial(n - al - be)) * (-2) ** be
                for r, coef, gpk in tensor_bubble_terms(be, a1 - al, a5):
                    A, B = a1 - al, a5
                    # (q.l)^(be-2r), q.l = (D3 - D4 + 1)/2, P^2 = D3
                    for (s, t), cst in lin_expand((Fr(1, 2), Fr(-1, 2), Fr(1, 2)), be - 2 * r).items():
                        gpl = bubble_gp((a3 - s + A + B - r, -1), (a4 - t, 0))
                        if gpl is None:
                            continue
                        rat = to_master(gp_merge(gpk, gpl), M2)
                        if rat is None:
                            continue
                        res[1] = res[1] + rat * rfc(mult * coef * cst)
        return tuple(res)
    # all positive: triangle rule on the k-loop (lines 1, 2, 5)
    pre = GA.RF1 / lin(-a1 - a2 - 2 * a5, 1)
    terms = [
        (Fr(a1), (a1 + 1, a2, a3, a4, a5 - 1)),
        (Fr(-a1), (a1 + 1, a2, a3 - 1, a4, a5)),
        (Fr(a2), (a1, a2 + 1, a3, a4, a5 - 1)),
        (Fr(-a2), (a1, a2 + 1, a3, a4 - 1, a5)),
    ]
    for c, idx in terms:
        x = I(*idx)
        res[0] = res[0] + x[0] * rfc(c)
        res[1] = res[1] + x[1] * rfc(c)
    return (res[0] * pre, res[1] * pre)


def integrate(dpoly, denom):
    """dpoly: dict (n1..n5) -> RF ; denom: (a1..a5). Returns (RF on M1, RF on M2)."""
    r1, r2 = GA.RF0, GA.RF0
    for m, c in dpoly.items():
        x = I(*[a - n for a, n in zip(denom, m)])
        r1 = r1 + c * x[0]
        r2 = r2 + c * x[1]
    return r1, r2


