def cmulv(xs, sq):
    out = xs[0]
    for x in xs[1:]:
        out = GA.mul(out, x, sq)
    return out


def gvec(comps):
    return GA.add(*[GA.scal(Fr(c), GA.gen(i)) for i, c in enumerate(comps)])


def word_to_mv(word, vecs, sq):
    return cmulv([vecs[s] for s in word], sq) if word else GA.sc(1)


