def check_subdivergences_cancel_between_vertex_and_self_energy():
    """(5) in the Feynman gauge the self-energy insertions and the vertex correction each have a
    1/eps^2 pole, equal and opposite: the one-loop counterterms cancel in pairs (Z1 = Z2)."""
    premise(P_QED)
    premise(P_DR)
    se = GA.RF0, GA.RF0
    for name in ('se1', 'se2'):
        x = project_two_loop('delta', name)['feyn']
        se = (se[0] + x[0], se[1] + x[1])
    vx = project_two_loop('delta', 'vx')['feyn']
    Sse = sum_series(*pi2_coefficients(se))
    Svx = sum_series(*pi2_coefficients(vx))
    a = Sse.coef(0).get((0, 0, 0), Fr(0))
    b = Svx.coef(0).get((0, 0, 0), Fr(0))
    ok = a != 0 and a + b == 0 and Sse.coef(-1) == {} and Svx.coef(-1) == {}
    ok = ok and a == Fr(4, 3) and b == Fr(-4, 3)
    GA.check("subdivergences: self-energy 1/eps^2 = 4/3 a^2, vertex -4/3 a^2, sum 0", ok)
    return ok


# ---- the Ward-Takahashi identity at two loops in Cl(1,3) (massive, unit outside) ----

S13 = (1, -1, -1, -1)
FP_WARD = Fr(16462924192730412, 55021266940681015)   # sum of coefficients of the insertion sums (computed)


def v13(c):
    return gvec(c)


def Q13(v):
    return GA.mul(v, v, S13).get((), Fr(0))


def prop13(k, m):
    """S(k) = (k - m)^(-1) = (k + m)/(Q(k) - m^2), the unit and the i of the Feynman rule outside."""
    return GA.scal(Fr(1) / (Q13(k) - m * m), GA.add(k, GA.sc(m)))


def chain(verts, moms, m):
    """V0 S(p1) V1 S(p2) ... S(pn) Vn."""
    out = verts[0]
    for p, vv in zip(moms, verts[1:]):
        out = cmulv([out, prop13(p, m), vv], S13)
    return out


def insertion_sum(verts, moms, h, m):
    """sum_j V0 S(p1+h) ... S(pj+h) h S(pj) ... S(pn) Vn."""
    tot = {}
    n = len(moms)
    for j in range(n):
        out = verts[0]
        for i in range(n):
            if i < j:
                out = cmulv([out, prop13(GA.add(moms[i], h), m), verts[i + 1]], S13)
            elif i == j:
                out = cmulv([out, prop13(GA.add(moms[i], h), m), h, prop13(moms[i], m), verts[i + 1]], S13)
            else:
                out = cmulv([out, prop13(moms[i], m), verts[i + 1]], S13)
        tot = GA.add(tot, out)
    return tot


def check_ward_identity_at_two_loops_integrand_by_integrand():
    """(6) Cl(1,3), massive lines, unit outside the product: for the open fermion line of the rainbow, the
    crossed and the polarisation-insertion self-energies, the sum of insertions of h (vertex h) equals
    -(chain(p + h) - chain(p)); for the closed loop the insertions telescope to a difference of the same
    integrand at loop momenta l + h and l (zero after the shift). Derivative: dS(k + t h)/dt = -S h S."""
    premise(P_QED)
    premise(P_TREE)
    premise(P_DR)
    m = Fr(3, 2)
    p, k, l, h = v13([2, 1, 0, 1]), v13([1, -1, 2, 0]), v13([3, 0, 1, -1]), v13([1, 2, -1, 1])
    g = [GA.gen(i) for i in range(4)]
    vt = [g[0], g[2], g[2], g[0]]
    pk, pkl, pl = GA.sub(p, k), GA.sub(GA.sub(p, k), l), GA.sub(p, l)
    ok, fp = True, Fr(0)
    cases = [(vt, [pk, pkl, pk]),                       # rainbow
             ([g[0], g[2], g[0], g[2]], [pk, pkl, pl]),  # crossed
             ([g[1], g[3]], [pk])]                       # open line of the polarisation insertion
    for verts, moms in cases:
        lhs = insertion_sum(verts, moms, h, m)
        shifted = chain(verts, [GA.add(x, h) for x in moms], m)
        ok = ok and GA.eq(lhs, GA.neg(GA.sub(shifted, chain(verts, moms, m))))
        fp += sum(lhs.values(), Fr(0))
    # closed loop tr[g_a S(l) g_b S(l - k)] with insertions on both propagators
    lk = GA.sub(l, k)
    loop_ins = GA.add(cmulv([g[1], prop13(GA.add(l, h), m), h, prop13(l, m), g[3], prop13(lk, m)], S13),
                      cmulv([g[1], prop13(GA.add(l, h), m), g[3], prop13(GA.add(lk, h), m), h,
                             prop13(lk, m)], S13))
    loop_diff = GA.sub(cmulv([g[1], prop13(GA.add(l, h), m), g[3], prop13(GA.add(lk, h), m)], S13),
                       cmulv([g[1], prop13(l, m), g[3], prop13(lk, m)], S13))
    ok = ok and loop_ins.get((), Fr(0)) == -loop_diff.get((), Fr(0))
    ok = ok and GA.eq(loop_ins, GA.neg(loop_diff))
    fp += loop_ins.get((), Fr(0))
    ok = ok and fp == FP_WARD
    # derivative of one propagator along h at t = 0
    den = Q13(k) - m * m
    kh = GA.mul(k, h, S13).get((), Fr(0))
    dS = GA.sub(GA.scal(Fr(1) / den, h), GA.scal(2 * kh / (den * den), GA.add(k, GA.sc(m))))
    ok = ok and GA.eq(dS, GA.neg(cmulv([prop13(k, m), h, prop13(k, m)], S13)))
    # controls: the insertion sum without the middle insertion fails; with the vertex g0 in place of h fails
    verts, moms = cases[0]
    full = insertion_sum(verts, moms, h, m)
    middle = cmulv([verts[0], prop13(GA.add(moms[0], h), m), verts[1], prop13(GA.add(moms[1], h), m), h,
                    prop13(moms[1], m), verts[2], prop13(moms[2], m), verts[3]], S13)
    shifted = chain(verts, [GA.add(x, h) for x in moms], m)
    target = GA.neg(GA.sub(shifted, chain(verts, moms, m)))
    ok = ok and not GA.eq(GA.sub(full, middle), target)
    wrongv = {}
    for jj in range(3):
        fac = [verts[0]]
        for ii in range(3):
            if ii == jj:
                fac += [prop13(GA.add(moms[ii], h), m), g[0], prop13(moms[ii], m), verts[ii + 1]]
            else:
                fac += [prop13(GA.add(moms[ii], h) if ii < jj else moms[ii], m), verts[ii + 1]]
        wrongv = GA.add(wrongv, cmulv(fac, S13))
    ok = ok and not GA.eq(wrongv, target)
    GA.check("two-loop Ward-Takahashi identity integrand by integrand (open lines, closed loop, derivative)", ok)
    return ok

synthesis.two-species-floor-pairing-has-:
"""Exact checks: the two-species pairing element on a floor and its doublet pair mode.

Floor of Om blocks; block b holds three tower modes, psi_1 = mode 3b, psi_2 = mode 3b + 1 (an isospin doublet)
and chi = mode 3b + 2 (a singlet). The tower planes generate the CAR (field-theory.imported-tower-limit); the
Fock states are GA's exterior model (creation v = wedge, annihilation w = contraction), as in the stored pairing
checks; the block algebra is also checked in the Clifford algebra of the tower planes themselves (GA.mul).
  S = sum_b w_1 w_2 (singlet pair), B_a = sum_b w_a w_chi (doublet pair), S* = sum v_2 v_1, B_a* = sum v_chi v_a,
  H = Kp N_psi + Kc N_chi - GS S*S - GD (B_1*B_1 + B_2*B_2),
  doublet quanta Z_2* = sum w_1 v_chi, Z_1* = sum v_chi w_2 (each turns a singlet pair into a doublet pair),
  isospin t_+ = sum v_1 w_2, t_- = sum v_2 w_1, t_3 = (N_1 - N_2)/2,
  W = S*S + B_1*B_1 + B_2*B_2 (the pair sum with equal couplings).
Every number is a Fraction; spectra are certified by exact inertia (congruence diagonalisation of a rational
symmetric matrix, checked against GA.congruence_signature on the small cases).
"""
from fractions import Fraction as F
from itertools import combinations, permutations

import GA
from tp_premise import premise

# (Kp, Kc, GS, GD): rational samples, singlet-condensed (GS > GD), degenerate (GS = GD), doublet-condensed
COUPLINGS = [(F(1, 3), F(2), F(3), F(1)), (F(0), F(0), F(5, 2), F(1, 2)), (F(-1, 2), F(1, 4), F(2), F(2)),
             (F(1), F(1, 2), F(1), F(3))]
FLOORS = (1, 2, 3, 4)
W_FLOORS = (2, 3, 4, 5, 6)
H_FLOORS = (2, 3, 4, 5)
# clause (x): (n_b, P, GD) at K = 0, GS = 1 with omega_D > 0 where the sector (2, 2, 2) has a level below E(P, 0);
# and doublet-condensed (n_b, P) at K = 0, GS = 1, GD = 3 with isospin-one levels below the pair-breaking threshold
BELOW_BAND = [(5, 3, F(1, 2)), (6, 3, F(4, 5)), (7, 3, F(9, 10))]
CONDENSED = [(4, 2), (5, 2)]
H_SAMPLES = [(F(3), F(1)), (F(3), F(29, 10)), (F(7, 2), F(1, 3))]   # (GS, GD), GS > GD > 0


# ---------------------------------------------------------------- exterior model of the CAR
def _ann(i, st, m):
    return GA.ext_contract([F(1) if j == i else F(0) for j in range(m)], st)


def _cre(i, st, m):
    return GA.ext_wedge(i, st)


def _acc(out, x, c=F(1)):
    for k, v in x.items():
        out[k] = out.get(k, F(0)) + c * v
    return out


def _clean(x):
    return {k: v for k, v in x.items() if v != 0}


def _lin(*terms):
    out = {}
    for c, x in terms:
        _acc(out, x, F(c))
    return _clean(out)


def _vac():
    return {frozenset(): F(1)}


def _bil(om, ops, st):
    """sum_b of a product of single-block operators, ops = [(kind, flavour)] applied right to left."""
    m = 3 * om
    out = {}
    for b in range(om):
        y = st
        for kind, f in reversed(ops):
            y = (_cre if kind == 'v' else _ann)(3 * b + f, y, m)
            if not y:
                break
        _acc(out, y)
    return _clean(out)


def S(om, st):
    return _bil(om, [('w', 0), ('w', 1)], st)


def Ss(om, st):
    return _bil(om, [('v', 1), ('v', 0)], st)


def B(om, a, st):
    return _bil(om, [('w', a), ('w', 2)], st)


def Bs(om, a, st):
    return _bil(om, [('v', 2), ('v', a)], st)


def Z2s(om, st):
    return _bil(om, [('w', 0), ('v', 2)], st)


def Z2(om, st):
    return _bil(om, [('w', 2), ('v', 0)], st)


def Z1s(om, st):
    return _bil(om, [('v', 2), ('w', 1)], st)


def tp(om, st):
    return _bil(om, [('v', 0), ('w', 1)], st)


def tm(om, st):
    return _bil(om, [('v', 1), ('w', 0)], st)


def num(om, f, st):
    return _bil(om, [('v', f), ('w', f)], st)


def Hop(om, cp, st):
    Kp, Kc, GS, GD = cp
    out = {}
    _acc(out, num(om, 0, st), Kp)
    _acc(out, num(om, 1, st), Kp)
    _acc(out, num(om, 2, st), Kc)
    _acc(out, Ss(om, S(om, st)), -GS)
    for a in (0, 1):
        _acc(out, Bs(om, a, B(om, a, st)), -GD)
    return _clean(out)


def Wop(om, st):
    out = dict(Ss(om, S(om, st)))
    for a in (0, 1):
        _acc(out, Bs(om, a, B(om, a, st)))
    return _clean(out)


def band_state(om, nS, n1, n2):
    x = _vac()
    for _ in range(n2):
        x = Bs(om, 1, x)
    for _ in range(n1):
        x = Bs(om, 0, x)
    for _ in range(nS):
        x = Ss(om, x)
    return x


def isospin_casimir(om, st):
    t3 = _lin((F(1, 2), num(om, 0, st)), (F(-1, 2), num(om, 1, st)))
    t3t3 = _lin((F(1, 2), num(om, 0, t3)), (F(-1, 2), num(om, 1, t3)))
    return _lin((1, t3t3), (F(1, 2), tp(om, tm(om, st))), (F(1, 2), tm(om, tp(om, st))))


def eq(x, y):
    return GA.ext_state_eq(x, y)


def sector(om, nums):
    m = 3 * om
    return [frozenset(Sx) for k in range(m + 1) for Sx in combinations(range(m), k)
            if tuple(sum(1 for j in Sx if j % 3 == f) for f in range(3)) == nums]


def sector_matrix(om, nums, op):
    basis = sector(om, nums)
    idx = {Sx: i for i, Sx in enumerate(basis)}
    rows = [dict() for _ in basis]
    for j, Sx in enumerate(basis):
        for T, v in op({Sx: F(1)}).items():
            rows[idx[T]][j] = rows[idx[T]].get(j, F(0)) + v
    return [{k: v for k, v in r.items() if v != 0} for r in rows]


def shifted(rows, a, sign):
    """sign * rows - a * 1 as sparse rows (a symmetric rational matrix)."""
    out = []
    for i, r in enumerate(rows):
        d = {k: sign * v for k, v in r.items()}
        d[i] = d.get(i, F(0)) - a
        out.append({k: v for k, v in d.items() if v != 0})
    return out


def inertia(rows):
    """(n_plus, n_minus, n_zero) of a sparse rational symmetric matrix by congruence diagonalisation
    (symmetric elimination; a zero diagonal is repaired by adding a row and column, as GA.congruence_signature)."""
    A = [dict(r) for r in rows]
    alive = set(range(len(A)))
    pos = neg = zer = 0
    while alive:
        piv = next((i for i in sorted(alive) if A[i].get(i, 0) != 0), None)
        if piv is None:
            found = None
            for i in sorted(alive):
                j = next((j for j in sorted(A[i]) if j != i and j in alive), None)
                if j is not None:
                    found = (i, j)
                    break
            if found is None:
                zer += len(alive)
                break
            i, j = found
            for k, x in list(A[j].items()):
                A[i][k] = A[i].get(k, F(0)) + x
            for k in alive:
                if j in A[k]:
                    A[k][i] = A[k].get(i, F(0)) + A[k][j]
            for k in list(A[i]):
                if A[i][k] == 0:
                    del A[i][k]
            continue
        d = A[piv][piv]
        if d > 0:
            pos += 1
        else:
            neg += 1
        alive.discard(piv)
        rp = {k: x for k, x in A[piv].items() if k in alive}
        for i, xi in rp.items():
            f = xi / d
            Ai = A[i]
            for k, xk in rp.items():
                v = Ai.get(k, F(0)) - f * xk
                if v != 0:
                    Ai[k] = v
                else:
                    Ai.pop(k, None)
    return pos, neg, zer


def dense(rows):
    n = len(rows)
    return [[rows[i].get(j, F(0)) for j in range(n)] for i in range(n)]


def count_above(rows, a):
    """number of eigenvalues > a, and the multiplicity of a."""
    p, n, z = inertia(shifted(rows, a, 1))
    return p, z


# ---------------------------------------------------------------- sectors and block permutations
def sector_basis(om, nums):
    out = []
    for c1 in combinations(range(om), nums[0]):
        for c2 in combinations(range(om), nums[1]):
            for c3 in combinations(range(om), nums[2]):
                out.append(frozenset([3 * b for b in c1] + [3 * b + 1 for b in c2] + [3 * b + 2 for b in c3]))
    return out


def permuted(pi, Sx):
    """the Fock basis vector of Sx with block b relabelled pi[b], and the sign of reordering its creators."""
    seq = [3 * pi[k // 3] + k % 3 for k in sorted(Sx)]
    inv = sum(1 for i in range(len(seq)) for j in range(i + 1, len(seq)) if seq[i] > seq[j])
    return frozenset(seq), (F(-1) if inv % 2 else F(1))


def fixed_block_inertia(om, nums, cp, E):
    """inertia of H - E on the vectors of the sector invariant under the permutations of blocks 1, ..., om - 1
    (Gram form <s_i, (H - E) s_j> on the orbit sums s_i, which are orthogonal and nonzero)."""
    perms = [tuple([0] + list(q)) for q in permutations(range(1, om))]
    seen, vecs = set(), []
    for Sx in sector_basis(om, nums):
        if Sx in seen:
            continue
        v = {}
        for pi in perms:
            T, sg = permuted(pi, Sx)
            seen.add(T)
            v[T] = v.get(T, F(0)) + sg
        v = _clean(v)
        if v:
            vecs.append(v)
    hv = [Hop(om, cp, v) for v in vecs]
    ip = lambda a, b: sum((c * b.get(k, F(0)) for k, c in a.items()), F(0))
    rows = []
    for i in range(len(vecs)):
        r = {j: ip(vecs[i], hv[j]) - E * ip(vecs[i], vecs[j]) for j in range(len(vecs))}
        rows.append({j: x for j, x in r.items() if x != 0})
    return len(vecs), inertia(rows)


# ---------------------------------------------------------------- Clifford algebra of one block
def _block_cl():
    # kernel g1, g2 (square -1), then three tower planes (e, f): squares +1, -1
    s = tuple([-1, -1] + [1, -1] * 3)
    mul = lambda x, y: GA.mul(x, y, s)
    v = [GA.add(GA.scal(F(1, 2), GA.gen(2 + 2 * j)), GA.scal(F(1, 2), GA.gen(3 + 2 * j))) for j in range(3)]
    w = [GA.add(GA.scal(F(1, 2), GA.gen(2 + 2 * j)), GA.scal(F(-1, 2), GA.gen(3 + 2 * j))) for j in range(3)]
    J = mul(GA.gen(0), GA.gen(1))
    gam = GA.sc(1)
    for j in range(3):
        gam = mul(gam, mul(GA.gen(2 + 2 * j), GA.gen(3 + 2 * j)))
    return s, mul, v, w, J, gam


# ================================================================ checks
def check_block_algebra_in_the_tower_planes():
    premise("field-theory.imported-tower-limit")
    premise("synthesis.kernel-bivector-is-the-unit-of-hermitian-boson-fields-on-the-tower")
    s, mul, v, w, J, gam = _block_cl()
    ok = True
    for i in range(3):
        for j in range(3):
            ok = ok and GA.eq(GA.add(mul(w[i], v[j]), mul(v[j], w[i])), GA.sc(int(i == j)))
            ok = ok and GA.is_zero(GA.add(mul(v[i], v[j]), mul(v[j], v[i])))
